local config = {
  str_homestory_800601001_0_dialog_content = "Carleen...",
  str_homestory_800601001_1_dialog_content = "Olá, PlayerName.",
  str_homestory_800601001_2_dialog_content = "O que você está fazendo, Carleen?",
  str_homestory_800601001_3_dialog_content = "Estou murmurando para mim mesmo.",
  str_homestory_800601001_4_dialog_content = "Você quer dizer \"orar\"?",
  str_homestory_800601001_5_dialog_content = "...",
  str_homestory_800601001_6_dialog_content = "Sim. Por favor, não ria de mim.",
  str_homestory_800601001_7_dialog_content = "Por que eu deveria? É perfeitamente normal orar.",
  str_homestory_800601001_8_dialog_content = "As crianças que não conseguem segurar uma lâmina rezam para os adultos por proteção.",
  str_homestory_800601001_9_dialog_content = "Um paciente moribundo ora aos deuses por recuperação.",
  str_homestory_800601001_10_dialog_content = "Mas por que uma pessoa capaz seria dependente de \"orações\"?",
  str_homestory_800601001_11_dialog_content = "(Aceita)",
  str_homestory_800601001_12_dialog_content = "Isso é um pouco duro, mas você tem um ponto...",
  str_homestory_800601001_13_dialog_content = "Se alguém pudesse controlar seu próprio destino, não teria motivos para depender de mais ninguém.",
  str_homestory_800601001_14_dialog_content = "No entanto, muitas coisas neste mundo estão além do nosso controle. Sua afirmação está correta, PlayerName.",
  str_homestory_800601001_15_dialog_content = "Destino.",
  str_homestory_800601001_16_dialog_content = "Consideramos todas as coisas irreversíveis como \"destino\" e isso nos faz sentir melhor.",
  str_homestory_800601001_17_dialog_content = "Mas para mim, o destino pode ser mudado.",
  str_homestory_800601001_18_dialog_content = "(Discordo)",
  str_homestory_800601001_19_dialog_content = "Não é prática comum em Lumopolis rezar ao Deus da Luz?",
  str_homestory_800601001_20_dialog_content = "Achei que todo mundo fazia isso, inclusive você.",
  str_homestory_800601001_21_dialog_content = "Sim, muitas vezes compartilhamos nossos pensamentos e desejos com o Deus da Luz.",
  str_homestory_800601001_22_dialog_content = "Mas para mim, é apenas uma maneira de buscar conforto e alívio espiritual.",
  str_homestory_800601001_23_dialog_content = "Depois que as orações terminam, as dificuldades à minha frente ainda estão esperando para serem superadas. Isso nunca muda.",
  str_homestory_800601001_24_dialog_content = "...",
  str_homestory_800601001_25_dialog_content = "Hmm... Quando penso nisso, sinto-me bastante afortunado.",
  str_homestory_800601001_26_dialog_content = "Afortunado? Por que é que?",
  str_homestory_800601001_27_dialog_content = "Porque não estou sozinho diante do inimigo.",
  str_homestory_800601001_28_dialog_content = "Sou super grata por ter todos esses amigos.",
  str_homestory_800601001_29_dialog_content = "Não posso concordar mais! É nossa sorte termos um ao outro nesta jornada.",
  str_homestory_800601001_30_dialog_content = "Sim.",
  str_homestory_800601001_31_dialog_content = "Você parece um pouco sentimental hoje?",
  str_homestory_800601001_32_dialog_content = "Acho que é este lugar... É perfeito para refletir.",
  str_homestory_800601001_33_dialog_content = "Nenhuma guerra. Nada de príncipes e nobres ruins. Tudo é tão calmo e tranquilo.",
  str_homestory_800601001_34_dialog_content = "Eu vou deixar você com isso. Aproveite a solidão.",
  str_homestory_800601001_35_dialog_content = "Obrigada, PlayerName.",
  str_homestory_800601001_36_dialog_content = "De nada, Carleen.",
  str_homestory_800201001_0_dialog_content = "Saudações, Comandante Hiiro.",
  str_homestory_800201001_1_dialog_content = "O que te trouxe aqui?",
  str_homestory_800201001_2_dialog_content = "Também tem um desejo a fazer?",
  str_homestory_800201001_3_dialog_content = "Ah, sim.",
  str_homestory_800201001_4_dialog_content = "Eu vi você aqui, então vim dizer oi.",
  str_homestory_800201001_5_dialog_content = "Ótimo.",
  str_homestory_800201001_6_dialog_content = "Você está... Meditando?",
  str_homestory_800201001_7_dialog_content = "Estou rezando.<sprite=emo_mojing size=60 />",
  str_homestory_800201001_8_dialog_content = "...!",
  str_homestory_800201001_9_dialog_content = "Você parece surpreso.",
  str_homestory_800201001_10_option_content = "Admitem",
  str_homestory_800201001_11_dialog_content = "Eu... eu não pensei que você iria orar.",
  str_homestory_800201001_12_option_content = "Negar",
  str_homestory_800201001_13_dialog_content = "É mais um choque do que uma surpresa...",
  str_homestory_800201001_14_dialog_content = "Você é tão poderoso... Não pensei que assuntos triviais o incomodariam.",
  str_homestory_800201001_15_dialog_content = "Vou levar isso como um elogio.",
  str_homestory_800201001_16_dialog_content = "Estou orando para mim mesmo, não para qualquer deus.",
  str_homestory_800201001_17_dialog_content = "Orar para si mesmo?",
  str_homestory_800201001_18_dialog_content = "Estou um pouco confuso...",
  str_homestory_800201001_19_dialog_content = "Ouvi dizer que muitas pessoas viriam aqui para orar.",
  str_homestory_800201001_20_dialog_content = "Acho que uma oração pode tornar mais claro em nossos corações o que realmente queremos.",
  str_homestory_800201001_21_dialog_content = "Em outras palavras, orar aqui pode nos ajudar a descobrir nossos desejos.",
  str_homestory_800201001_22_dialog_content = "Ah... Entendi.",
  str_homestory_800201001_23_dialog_content = "É como encontrar \"a missão que realmente queremos completar\"?",
  str_homestory_800201001_24_dialog_content = "Isso mesmo.",
  str_homestory_800201001_25_dialog_content = "Então... Já o encontrou?",
  str_homestory_800201001_26_dialog_content = "Sim.",
  str_homestory_800201001_27_dialog_content = "A \"oração\" não deixou tão claro quanto esperava... Mas encontrei meu caminho.",
  str_homestory_800201001_28_dialog_content = "Você não sabia qual caminho seguir antes?",
  str_homestory_800201001_29_dialog_content = "Sempre foi claro qual caminho eu deveria seguir.",
  str_homestory_800201001_30_dialog_content = "Mas eu não tinha certeza de qual caminho meu coração queria ou desejava.",
  str_homestory_800201001_31_dialog_content = "Agora eu posso entender totalmente por que as pessoas estão tão ansiosas para orar.",
  str_homestory_800201001_32_dialog_content = "Sim...",
  str_homestory_800201001_33_dialog_content = "Para uma figura poderosa como o Comandante Hiiro, orar pode ajudá-lo a entender as coisas que seu coração realmente deseja...",
  str_homestory_800201001_34_dialog_content = "Para aqueles que lutam para ganhar a vida, as orações são seu sustento devoto.",
  str_homestory_800201001_35_dialog_content = "Então, é por isso que a Fonte da Esperança é essencial.",
  str_homestory_800201001_36_dialog_content = "Você e Vice trabalhou duro para este lugar.",
  str_homestory_800201001_37_dialog_content = "(A conversa de repente se transformou em uma conversa de advertência para um subalterno...)",
  str_homestory_800201001_38_dialog_content = "Não vou perder mais do seu precioso tempo. Vá e ore, PlayerName.",
  str_homestory_800201001_39_dialog_content = "Tchau!",
  str_homestory_800201001_40_dialog_content = "Ah... Sim, Comandante Hiiro!",
  str_homestory_802501001_0_dialog_content = "Ele está recitando um poema?",
  str_homestory_802501001_1_dialog_content = "Nada mal...",
  str_homestory_802501001_2_dialog_content = "Nada mal?",
  str_homestory_802501001_3_dialog_content = "Hum. Tenho que dizer...",
  str_homestory_802501001_4_dialog_content = "Nada mal! Essa fase não é nada ruim!<sprite=emo_yinfu size=60 />",
  str_homestory_802501001_5_dialog_content = "Palco?",
  str_homestory_802501001_6_dialog_content = "Ei, PlayerName. No momento ideal.",
  str_homestory_802501001_7_dialog_content = "Olhar! Uma pequena praça do lado de fora da Hyacinth Tower...",
  str_homestory_802501001_8_dialog_content = "Isso não é perfeito para uma peça de teatro em movimento?",
  str_homestory_802501001_9_dialog_content = "PlayerName, não desperdice esta luz e espaço.",
  str_homestory_802501001_10_dialog_content = "Por favor, permita-me esta oportunidade de fazer um show lendário aqui!",
  str_homestory_802501001_11_option_content = "Concordo",
  str_homestory_802501001_12_dialog_content = "Claro... Só não faça muito barulho...",
  str_homestory_802501001_13_dialog_content = "Não é possivel!",
  str_homestory_802501001_14_dialog_content = "Trens! Chamas! Canecas manchadas de sangue! Metal pesado! Vinil! E alto-falantes!",
  str_homestory_802501001_15_dialog_content = "Vou garantir que meu jogo chegue a todos os cantos da ilha!",
  str_homestory_802501001_16_dialog_content = "... Isso não incomodaria os moradores?",
  str_homestory_802501001_17_dialog_content = "Perturbar os moradores? Eles não sabem apreciar a arte?",
  str_homestory_802501001_18_dialog_content = "Ah-há-há! Esse não é o caso!",
  str_homestory_802501001_19_dialog_content = "Uma peça indie é frequentemente apreciada por apenas algumas pessoas com um interesse especial!",
  str_homestory_802501001_20_dialog_content = "No entanto, acredito que seu show será melhor na calada da noite.",
  str_homestory_802501001_21_dialog_content = "Ouço, Charon...",
  str_homestory_802501001_22_option_content = "Rejeitar",
  str_homestory_802501001_23_dialog_content = "O que devo fazer?",
  str_homestory_802501001_24_dialog_content = "Sua rejeição fria apenas acendeu novas ideias na minha cabeça!",
  str_homestory_802501001_25_dialog_content = "As idéias entrelaçadas estão gritando e rasgando no fundo da minha alma como cavalos selvagens!",
  str_homestory_802501001_26_dialog_content = "O que é rosnar? Arte! Um desempenho fora de controle...",
  str_homestory_802501001_27_dialog_content = "Agora é a hora! Deixe este show ecoar por todo Eraveil!",
  str_homestory_802501001_28_dialog_content = "(Minha rejeição não pareceu funcionar...)",
  str_homestory_802501001_29_dialog_content = "Que tal outro dia?",
  str_homestory_802501001_30_dialog_content = "... Outro dia?",
  str_homestory_802501001_31_dialog_content = "Ah... Uma explosão de tristeza de repente encheu meu coração.",
  str_homestory_802501001_32_dialog_content = "PlayerName, você aprendeu a ignorar os outros.",
  str_homestory_802501001_33_dialog_content = "Ok, eu vou considerar dar a você um \"papel frio e distante\" no meu show.",
  str_homestory_802501001_34_dialog_content = "...",
  str_homestory_810501001_0_dialog_content = "Você está tão ocupado, Eve!",
  str_homestory_810501001_1_dialog_content = "Que bom te ver, Navegador!<sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "Eu estarei com você em breve. Agora tenho que pensar no que mais preciso...",
  str_homestory_810501001_3_dialog_content = "Ah... Não se preocupe comigo!",
  str_homestory_810501001_4_dialog_content = "Se você está procurando algo, talvez eu possa ajudar.",
  str_homestory_810501001_5_dialog_content = "Aww... Você se preparou tanto para nós!",
  str_homestory_810501001_6_dialog_content = "Eu quero fazer alguns presentes.",
  str_homestory_810501001_7_dialog_content = "Eu estava pensando em qual cor é melhor para uma flor bordada ou um porta-copos.",
  str_homestory_810501001_8_dialog_content = "Flor bordada? Suporte de copo?",
  str_homestory_810501001_9_dialog_content = "Sim.",
  str_homestory_810501001_10_dialog_content = "fiz um top para Dawn<sprite=emo_qunzi size=60 />. Eu gostaria de adicionar algumas flores do amanhecer nele...",
  str_homestory_810501001_11_dialog_content = "Hmm... O porta-copos... Você sabe que meu irmão sempre carrega uma garrafa de água para eu beber...",
  str_homestory_810501001_12_dialog_content = "Um porta-copos fofo seria um belo presente para ele.",
  str_homestory_810501001_13_dialog_content = "Heheh. Navegador, o que você acha?",
  str_homestory_810501001_14_dialog_content = "Formidável!",
  str_homestory_810501001_15_dialog_content = "Estes são presentes muito atenciosos. Tenho certeza Dawn e seu irmão ficaria muito feliz.",
  str_homestory_810501001_16_dialog_content = "Sim! Tão feliz em ouvir...",
  str_homestory_810501001_17_dialog_content = "Então... Qual cor devo escolher?",
  str_homestory_810501001_18_dialog_content = "Dawn as flores geralmente são brancas, mas pode ser divertido usar uma cor diferente...",
  str_homestory_810501001_19_dialog_content = "Para o porta-copos, não consigo decidir entre vermelho e preto. Qual irmão gostaria mais?",
  str_homestory_810501001_20_dialog_content = "Ahh... É uma decisão difícil.",
  str_homestory_810501001_21_dialog_content = "Hmm...",
  str_homestory_810501001_22_dialog_content = "Qual é a cor do top que você fez Dawn?",
  str_homestory_810501001_23_dialog_content = "Preto!",
  str_homestory_810501001_24_dialog_content = "Acho que as flores brancas do amanhecer ficariam muito bem nele.",
  str_homestory_810501001_25_dialog_content = "Tente fazer o padrão levantado acima do tecido para Dawn pode sentir as flores do amanhecer com as mãos.",
  str_homestory_810501001_26_dialog_content = "Erguidas flores brancas do amanhecer...",
  str_homestory_810501001_27_dialog_content = "Ah... É uma ideia fantástica!",
  str_homestory_810501001_28_dialog_content = "Que bom que pude ser útil.",
  str_homestory_810501001_29_dialog_content = "Que tal o porta-copos para meu irmão? Navegador, alguma ideia sobre isso?",
  str_homestory_810501001_30_option_content = "Sim",
  str_homestory_810501001_31_dialog_content = "Se você não consegue decidir entre as duas cores, por que não fazer um xadrez preto e vermelho?",
  str_homestory_810501001_32_dialog_content = "No entanto, Eve...",
  str_homestory_810501001_33_option_content = "Na verdade, não",
  str_homestory_810501001_34_dialog_content = "Para ser honesto, Eve...",
  str_homestory_810501001_35_dialog_content = "Sinsa ficará fora de si de alegria por qualquer coisa que você presentear a ele.",
  str_homestory_810501001_36_dialog_content = "Mesmo uma folha aleatória ou um punhado de areia sua vale a pena se gabar como os tesouros mais raros.",
  str_homestory_810501001_37_dialog_content = "Hmm...",
  str_homestory_810501001_38_dialog_content = "Sim, eu concordo com você...",
  str_homestory_810501001_39_dialog_content = "Neste caso, vou escolher a minha cor favorita. Heheh.",
  str_homestory_810501001_40_dialog_content = "Hmm... Acho que vai ficar tudo bem.",
  str_homestory_810501001_41_dialog_content = "Eve... Você está trabalhando tão duro para Dawn e Sinsapresentes. Qualquer coisa para você?",
  str_homestory_810501001_42_dialog_content = "Hum? Desculpe, Navegador. Não entendo...",
  str_homestory_810501001_43_dialog_content = "O que devo preparar para mim?",
  str_homestory_810501001_44_dialog_content = "Ah... quero dizer...",
  str_homestory_810501001_45_dialog_content = "Olhar. Você me pediu solo nutritivo e sementes de flores do amanhecer há algum tempo. Aqueles eram para Dawn, certo?",
  str_homestory_810501001_46_dialog_content = "Para que ela possa cultivar flores aqui alegremente.",
  str_homestory_810501001_47_dialog_content = "E você tem alguns lanches Rediesel Wrench de Vice porque você estava preocupado Sinsa pode não ter nada a ver com suas bebidas.",
  str_homestory_810501001_48_dialog_content = "Ah... Navegador, você sabe tudo...",
  str_homestory_810501001_49_dialog_content = "Você está certo.",
  str_homestory_810501001_50_dialog_content = "Mas...",
  str_homestory_810501001_51_dialog_content = "Por que não preparar algo para você?",
  str_homestory_810501001_52_dialog_content = "Hmm... Eu preparei isso para Dawn e meu irmão para que fossem mais felizes aqui.",
  str_homestory_810501001_53_dialog_content = "Eu já estou na lua por estar perto deles o tempo todo.",
  str_homestory_810501001_54_dialog_content = "Ah... e você e Vice!",
  str_homestory_810501001_55_dialog_content = "Sua presença me deixa feliz!",
  str_homestory_810501001_56_dialog_content = "Não preciso preparar nada para mim.",
  str_homestory_810501001_57_dialog_content = "É assim mesmo?.",
  str_homestory_810501001_58_dialog_content = "Você é tão atencioso e doce...",
  str_homestory_810501001_59_dialog_content = "Você também, Navegador!",
  str_homestory_810501001_60_dialog_content = "Tadinha...",
  str_homestory_810501001_61_dialog_content = "O que foi?",
  str_homestory_810501001_62_dialog_content = "Navegador, por que de repente você está derramando lágrimas?",
  str_homestory_810501001_63_dialog_content = "*Sob* Eu gostaria de ter uma irmã como Eve...<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "Smokey?",
  str_homestory_811201001_1_dialog_content = "O que aconteceu, Smokey?",
  str_homestory_811201001_2_dialog_content = "Você parece realmente louco.",
  str_homestory_811201001_3_dialog_content = "E aí, Navegador?",
  str_homestory_811201001_4_dialog_content = "Você não acha que esta loja tem uma seleção muito pequena de produtos para oferecer?<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "Ah! Você está bravo com isso?",
  str_homestory_811201001_6_dialog_content = "Existe algo em particular que você não consegue encontrar aqui? Apenas deixe-me saber.",
  str_homestory_811201001_7_dialog_content = "Tem certeza que quer ouvir?",
  str_homestory_811201001_8_dialog_content = "Sim. Vá em frente.",
  str_homestory_811201001_9_dialog_content = "Então eu vou direto ao assunto.",
  str_homestory_811201001_10_dialog_content = "Em primeiro lugar, não há nenhum detergente acessório.",
  str_homestory_811201001_11_dialog_content = "Então, os botões disponíveis na loja são absolutamente terríveis!",
  str_homestory_811201001_12_dialog_content = "Confie em mim. Ninguém iria querer colocar nada disso em suas roupas.",
  str_homestory_811201001_13_dialog_content = "Perdoe-me. Esses caras Illumina podem gostar disso na verdade.",
  str_homestory_811201001_14_dialog_content = "Botões... Desde que funcione...",
  str_homestory_811201001_15_dialog_content = "Não posso culpá-lo. Afinal, a maioria de vocês não sabe muito sobre moda.",
  str_homestory_811201001_16_dialog_content = "Não olhe para si mesmo. Você me pegou aqui.",
  str_homestory_811201001_17_dialog_content = "Valeu...",
  str_homestory_811201001_18_dialog_content = "Além disso, este lugar é muito mais quente e ensolarado do que Umbraton.",
  str_homestory_811201001_19_dialog_content = "Eu vejo guarda-sóis aqui, mas onde estão as sombras e protetores solares? Você não tem nenhum!",
  str_homestory_811201001_20_dialog_content = "Pois tens razão...",
  str_homestory_811201001_21_dialog_content = "(Smokey não pode ser o único auroriano que luta para encontrar o que precisa aqui.)",
  str_homestory_811201001_22_dialog_content = "(O que devo fazer? Levará séculos para falar com eles um por um...)",
  str_homestory_811201001_23_dialog_content = "Ei, o que você está murmurando?",
  str_homestory_811201001_24_dialog_content = "Eu sou demais para você? Você está preocupado que possa haver outros compradores exigentes como eu?",
  str_homestory_811201001_25_option_content = "Aceno com a cabeça",
  str_homestory_811201001_26_dialog_content = "Bom. Honestidade é ouro.",
  str_homestory_811201001_27_dialog_content = "Estou mais preocupado do que preocupado...",
  str_homestory_811201001_28_option_content = "Agite a cabeça",
  str_homestory_811201001_29_dialog_content = "Não, Smokey, não me incomoda em nada...",
  str_homestory_811201001_30_dialog_content = "Na verdade, problema ou não não é o ponto aqui.",
  str_homestory_811201001_31_dialog_content = "Pode haver outras pessoas enfrentando um problema semelhante ao seu, mas não sei como resolver isso ...",
  str_homestory_811201001_32_dialog_content = "... Você precisa desenvolver um sistema de pedidos Eraveil.",
  str_homestory_811201001_33_dialog_content = "Todos podem registrar os produtos de que precisam no sistema regularmente. As encomendas são então colocadas em Astra em conformidade.",
  str_homestory_811201001_34_dialog_content = "Entrega... Aposto que você pode descobrir alguma tecnologia especial, certo?",
  str_homestory_811201001_35_dialog_content = "A União dos Correios<sprite=emo_gezitou size=60 />, vaga-lumes e tal.",
  str_homestory_811201001_36_dialog_content = "Ah... Boa ideia...",
  str_homestory_811201001_37_dialog_content = "Assim você não precisa falar com a gente um por um. E você não receberá outra reclamação como a minha.",
  str_homestory_811201001_38_dialog_content = "Você sabe que alguns Aurorianos são muito especiais.",
  str_homestory_811201001_39_dialog_content = "Eles podem gostar de caixões, pincéis de todos os tipos ou insetos bizarros...",
  str_homestory_811201001_40_dialog_content = "E alguns deles não podem viver sem gin.",
  str_homestory_811201001_41_dialog_content = "Espere... Você disse gim?",
  str_homestory_811201001_42_dialog_content = "Você está falando sobre... Genevieve?",
  str_homestory_811201001_43_dialog_content = "Ela é a única que gosta de tomar uma bebida?",
  str_homestory_811201001_44_dialog_content = "... Eu não entendo como seu cérebro funciona!",
  str_homestory_811201001_45_dialog_content = "Ok... Então você não está falando sobre ela. Aí está mais um grande fã de gin!",
  str_homestory_811201001_46_dialog_content = "Isso mesmo! Muitas pessoas por aí apreciam uma bebida ou duas, ok?<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "Claro... Não fique bravo! E não coloque fogo em nada...",
  str_homestory_811201001_48_dialog_content = "Hunf.",
  str_homestory_811201001_49_dialog_content = "Obrigada, Smokey!",
  str_homestory_811201001_50_dialog_content = "Sua dica é muito útil!",
  str_homestory_811201001_51_dialog_content = "Tenho que ir. Vê você.",
  str_homestory_811201001_52_dialog_content = "Até mais!",
  str_homestory_807101001_0_dialog_content = "Takia pipa...",
  str_homestory_807101001_1_dialog_content = "Aham... Taki...",
  str_homestory_807101001_2_dialog_content = "Huh? PlayerName?",
  str_homestory_807101001_3_dialog_content = "Hum... eu vi sua pipa...",
  str_homestory_807101001_4_dialog_content = "Foi no chão.",
  str_homestory_807101001_5_dialog_content = "... Oh.",
  str_homestory_807101001_6_dialog_content = "Mas eu peguei rapidamente.",
  str_homestory_807101001_7_dialog_content = "...<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "(Essa não é a questão...)",
  str_homestory_807101001_9_dialog_content = "OK. Com base nisso, acho que sua habilidade de empinar pipa é...",
  str_homestory_807101001_10_option_content = "Muito bom!",
  str_homestory_807101001_11_dialog_content = "Garoto, tentando dar consolo?",
  str_homestory_807101001_12_dialog_content = "Aham... Eu só queria ser solidário...",
  str_homestory_807101001_13_dialog_content = "Entendido, mas elogios falsos são o mínimo que preciso.",
  str_homestory_807101001_14_dialog_content = "Eu vejo. Desde que você não perca seu coração...",
  str_homestory_807101001_15_option_content = "Inexistente!",
  str_homestory_807101001_16_dialog_content = "Estou feliz em te ensinar.",
  str_homestory_807101001_17_dialog_content = "OK. Ensine-me então.",
  str_homestory_807101001_18_dialog_content = "Huh? Essa foi fácil.",
  str_homestory_807101001_19_dialog_content = "É claro.",
  str_homestory_807101001_20_dialog_content = "Não é uma vergonha aprender com o melhor.",
  str_homestory_807101001_21_dialog_content = "Admita o que não entendemos e a comunicação será mais eficaz. É particularmente verdade para qualquer empresário.",
  str_homestory_807101001_22_dialog_content = "O proprietário da Odd Jobs nunca deixa de me impressionar!",
  str_homestory_807101001_23_dialog_content = "Então, qual é o truque para empinar pipa? Diga-me.",
  str_homestory_807101001_24_dialog_content = "Primeiro, você precisa ter certeza de que está de costas para o vento.",
  str_homestory_807101001_25_dialog_content = "A pipa pegará o vento dessa maneira.",
  str_homestory_807101001_26_dialog_content = "Então você começa a soltar alguma linha para ajudar a pipa a subir mais alto no ar. Se não houver vento suficiente, você deve puxar a linha rapidamente.",
  str_homestory_807101001_27_dialog_content = "Corra devagar enquanto empina a pipa. Fique de olho sempre.",
  str_homestory_807101001_28_dialog_content = "Se sua pipa está voando alto no ar...",
  str_homestory_807101001_29_dialog_content = "Você pode amarrá-lo a uma árvore ou a um poste de sinalização e encontrar um local confortável para vê-lo voar.",
  str_homestory_807101001_30_dialog_content = "Ok... A direção do vento... A força do vento... Corrida lenta... E interação com a pipa...<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "Ah? Você está recitando?",
  str_homestory_807101001_32_dialog_content = "Posso repetir tudo o que acabei de dizer se você quiser...",
  str_homestory_807101001_33_dialog_content = "Não há necessidade. Eu memorizei tudo.",
  str_homestory_807101001_34_dialog_content = "Hum? Por que você ainda está murmurando para si mesmo então?",
  str_homestory_807101001_35_dialog_content = "Umm... quero dizer... Por que não tentar?",
  str_homestory_807101001_36_dialog_content = "Estou planejando como imprimir este livro \"Como empinar pipa\" para melhores vendas.",
  str_homestory_807101001_37_dialog_content = "...Hã?",
  str_homestory_807101001_38_dialog_content = "Imagina isto. Se o Odd Jobs começasse a vender pipas e realmente aumentasse a propaganda...",
  str_homestory_807101001_39_dialog_content = "Compre uma pipa e ganhe uma sessão de coaching gratuita por tempo limitado.",
  str_homestory_807101001_40_dialog_content = "O que acontece se não conseguir empinar pipa após a sessão de coaching? Compre o livro \"Como empinar pipa\".",
  str_homestory_807101001_41_dialog_content = "Podemos ter todos os tipos de pipas. Talvez até com um tiro na cabeça do Shadowlord...",
  str_homestory_807101001_42_dialog_content = "Pare aí mesmo!",
  str_homestory_807101001_43_dialog_content = "Então você está aqui empinando pipa e aprendendo habilidades de pipa comigo...",
  str_homestory_807101001_44_dialog_content = "Fazer dinheiro?",
  str_homestory_807101001_45_dialog_content = "Uhum.",
  str_homestory_807101001_46_dialog_content = "Garoto, eu sou um homem de negócios.",
  str_homestory_807101001_47_dialog_content = "Você tem um problema?",
  str_homestory_807101001_48_dialog_content = "Não. De jeito nenhum...",
  str_homestory_807101001_49_dialog_content = "Admiro seu forte senso de negócios!",
  str_homestory_807101001_50_dialog_content = "Eu não ultrapassaria o orçamento todos os dias se soubesse ganhar dinheiro com as coisas ao meu redor...",
  str_homestory_807101001_51_dialog_content = "Hmm... Você está preocupado com dinheiro.",
  str_homestory_807101001_52_dialog_content = "Ouço. Já que me inspirei em você para esse negócio...",
  str_homestory_807101001_53_dialog_content = "Metade do lucro será seu quando estiver realmente acontecendo nas Odds Jobs.",
  str_homestory_807101001_54_dialog_content = "?!",
  str_homestory_807101001_55_dialog_content = "Você está falando sério?",
  str_homestory_807101001_56_dialog_content = "Sim, mas não fique muito animado ainda.",
  str_homestory_807101001_57_dialog_content = "Este negócio pode ser um desastre total.",
  str_homestory_807101001_58_dialog_content = "Sem problemas. Taki, Eu tenho fé em você!",
  str_homestory_807101001_59_dialog_content = "OK. Devo praticar minhas habilidades de empinar pipa agora.",
  str_homestory_807101001_60_dialog_content = "Garoto, você deve estar ocupado. Siga em frente com o seu dia.",
  str_homestory_807101001_61_dialog_content = "Você tem isso! Taki!",
  str_homestory_807101001_62_dialog_content = "(... Sim! Eu decidi!)",
  str_homestory_807101001_63_dialog_content = "(Pela minha metade do lucro... vou me certificar Taki pratica e melhora a cada dia!)<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "Vice?",
  str_homestory_803301001_1_dialog_content = "Inalar... Vice, você consegue fazer isso!",
  str_homestory_803301001_2_dialog_content = "Respire profundamente... expire...<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "Expire?",
  str_homestory_803301001_4_dialog_content = "Vice, você... Você está praticando a respiração?",
  str_homestory_803301001_5_dialog_content = "Ahh! PlayerName?",
  str_homestory_803301001_6_dialog_content = "... Praticar a respiração?",
  str_homestory_803301001_7_dialog_content = "Não estou...",
  str_homestory_803301001_8_dialog_content = "O que você está fazendo então?",
  str_homestory_803301001_9_dialog_content = "Estou fazendo contas.",
  str_homestory_803301001_10_dialog_content = "Ah... A conta de despesas está me dando dor de cabeça.",
  str_homestory_803301001_11_dialog_content = "Eu gostaria que fosse apenas um exercício de respiração...",
  str_homestory_803301001_12_dialog_content = "Pelo menos respirar não custa nada.",
  str_homestory_803301001_13_option_content = "Perguntar Vice",
  str_homestory_803301001_14_dialog_content = "Posso ajudar?",
  str_homestory_803301001_15_dialog_content = "Eu revisei nosso livro de contas ontem à noite.",
  str_homestory_803301001_16_dialog_content = "Não sou muito bom em contabilidade, mas estou disposto a ajudar.",
  str_homestory_803301001_17_option_content = "Fica em silêncio",
  str_homestory_803301001_18_dialog_content = "Porque você está tão quieto?",
  str_homestory_803301001_19_dialog_content = "Ahh... eu não queria te culpar...",
  str_homestory_803301001_20_dialog_content = "Eu sei. Estou apenas pensando em como posso ser de alguma ajuda.",
  str_homestory_803301001_21_dialog_content = "Eu revisei nosso livro de contas ontem à noite. Ultrapassamos um pouco...",
  str_homestory_803301001_22_dialog_content = "Ah... Vice... Obrigado por tudo que você fez!",
  str_homestory_803301001_23_dialog_content = "Deixe-me pensar no que vi no livro de contas ontem à noite...",
  str_homestory_803301001_24_dialog_content = "\"Apenas os componentes para a Fonte da Esperança, a praça e o jardim ornamental custarão uma fortuna.\"",
  str_homestory_803301001_25_dialog_content = "\"Muito menos abastecer os dormitórios e o museu\"...",
  str_homestory_803301001_26_dialog_content = "\"Devemos levar em consideração a preferência de cada um de nossos amigos...\"",
  str_homestory_803301001_27_dialog_content = "\"Como um cavalo de balanço, uma cadeira suspensa e esculturas...\"",
  str_homestory_803301001_28_dialog_content = "\"Essas coisas sozinhas não são muito caras, mas os números aumentam rapidamente.\"",
  str_homestory_803301001_29_dialog_content = "\"Há muito o que aprender sobre como se comunicar com os artesãos. A instalação pode ser um desafio.\"",
  str_homestory_803301001_30_dialog_content = "\"No entanto... eu acho que todos os esforços de PlayerName e eu não sou à toa se nossos hóspedes puderem ter uma estadia confortável.\"",
  str_homestory_803301001_31_dialog_content = "Ah... Você viu tudo.",
  str_homestory_803301001_32_dialog_content = "Sim... Não consigo me livrar desse velho hábito de escrever meus pensamentos... Hahah.",
  str_homestory_803301001_33_dialog_content = "Vice, honestamente, você é fabuloso!",
  str_homestory_803301001_34_dialog_content = "Navegador, por que de repente você é tão generoso com seus elogios?",
  str_homestory_803301001_35_dialog_content = "Quero dizer!",
  str_homestory_803301001_36_dialog_content = "Olhar. Você desenha planos de construção, organiza cronogramas de projetos e faz planejamento regional...",
  str_homestory_803301001_37_dialog_content = "Eu não sou nenhuma ajuda. Eu não posso desenhar. Nem sou bom em planejar ou organizar.",
  str_homestory_803301001_38_dialog_content = "A Cloud Gardens deve tudo a você.",
  str_homestory_803301001_39_dialog_content = "... ah... é verdade...",
  str_homestory_803301001_40_dialog_content = "Mas não há necessidade de agradecimentos!",
  str_homestory_803301001_41_dialog_content = "Eu só quero te animar.",
  str_homestory_803301001_42_dialog_content = "Vamos trabalhar juntos para nos manter fora do vermelho.",
  str_homestory_803301001_43_dialog_content = "Sim! Você está absolutamente correto!",
  str_homestory_803301001_44_dialog_content = "Ah... Já que é bem difícil comprar coisas no Cloud Gardens...",
  str_homestory_803301001_45_dialog_content = "Que tal aumentarmos nossos preços para tudo em dez vezes?<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "... Err... Eu não acho que isso seja necessário...",
  str_homestory_803301001_47_dialog_content = "Heheh. Navegador, isso foi uma piada!",
  str_homestory_803301001_48_dialog_content = "Sério, como podemos ganhar algum dinheiro? Deixe-me pensar...",
  str_homestory_804101001_0_dialog_content = "Senhora Blanc...",
  str_homestory_804101001_1_dialog_content = "Ei, PlayerName.",
  str_homestory_804101001_2_dialog_content = "É um bom dia<sprite=emo_pugongying size=60 />, Sra. Blanc.",
  str_homestory_804101001_3_dialog_content = "Sim.",
  str_homestory_804101001_4_dialog_content = "Você está dando um passeio ou a caminho de algum lugar?",
  str_homestory_804101001_5_option_content = "Apenas andando",
  str_homestory_804101001_6_dialog_content = "Uma boa escolha.",
  str_homestory_804101001_7_dialog_content = "É lindo aqui, com muitas instalações de lazer...",
  str_homestory_804101001_8_dialog_content = "E muitas pessoas que eu nunca conheci antes.",
  str_homestory_804101001_9_option_content = "Ir pescar",
  str_homestory_804101001_10_dialog_content = "Ah. Você é bom em pescar?",
  str_homestory_804101001_11_option_content = "Muito bom",
  str_homestory_804101001_12_dialog_content = "Sério?",
  str_homestory_804101001_13_dialog_content = "Eu vou verificar.",
  str_homestory_804101001_14_dialog_content = "Bem-vindo!",
  str_homestory_804101001_15_dialog_content = "Heheh. Um jovem muito confiante!",
  str_homestory_804101001_16_option_content = "Só assim...",
  str_homestory_804101001_17_dialog_content = "A pesca exige muita paciência.",
  str_homestory_804101001_18_dialog_content = "Achei que você era um pouco jovem demais para isso.",
  str_homestory_804101001_19_dialog_content = "Hmm... Acho que ajuda na minha concentração.",
  str_homestory_804101001_20_dialog_content = "Hum...",
  str_homestory_804101001_21_dialog_content = "Somente aqueles que \"têm dificuldade em se concentrar\" precisam fazer coisas que ajudem a melhorar a concentração.",
  str_homestory_804101001_22_dialog_content = "Mas você vai se beneficiar disso ao longo do tempo.",
  str_homestory_804101001_23_dialog_content = "Sim...",
  str_homestory_804101001_24_dialog_content = "Sra. Blanc, por que você está parada sob esta placa de madeira?",
  str_homestory_804101001_25_dialog_content = "Estou observando.",
  str_homestory_804101001_26_dialog_content = "Observando?",
  str_homestory_804101001_27_dialog_content = "Não posso ajudar com isso.",
  str_homestory_804101001_28_dialog_content = "Todos estes novos edifícios e estradas... quero gravá-los todos na minha cabeça.",
  str_homestory_804101001_29_dialog_content = "Entendi.",
  str_homestory_804101001_30_dialog_content = "As estradas aqui não são complicadas. Talvez a Sra. Blanc possa relaxar um pouco.",
  str_homestory_804101001_31_dialog_content = "Relaxar?",
  str_homestory_804101001_32_dialog_content = "Isso sim é um luxo...",
  str_homestory_804101001_33_dialog_content = "Mas devo seguir seu conselho.",
  str_homestory_804101001_34_dialog_content = "PlayerName, tenha um bom descanso você mesmo.",
  str_homestory_804101001_35_dialog_content = "O excesso de trabalho acelera o envelhecimento.<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "Tá bom...",
  str_homestory_804101001_37_dialog_content = "Eu desejo! Senhora Blanca!",
  str_homestory_813801001_0_dialog_content = "Siobhan!",
  str_homestory_813801001_1_dialog_content = "PlayerName?",
  str_homestory_813801001_2_dialog_content = "Ah... Graças a Deus você está aqui...<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "E aí, Siobhan? Você parece cansado.",
  str_homestory_813801001_4_dialog_content = "Porque... Fiquei acordado a noite toda para ver todos os itens coletados no museu.",
  str_homestory_813801001_5_dialog_content = "Esses colecionáveis são um registro perfeito do passado de Eraveil e de todas as tecnologias que a Caelestites desenvolveu...",
  str_homestory_813801001_6_dialog_content = "Tenho que admitir minha admiração por suas proezas científicas.",
  str_homestory_813801001_7_dialog_content = "Obrigada. A Illumina está indo muito bem em ciência e tecnologia.",
  str_homestory_813801001_8_dialog_content = "Não sei porque, mas não consigo me livrar desse sentimento...",
  str_homestory_813801001_9_dialog_content = "A tecnologia dos Caelestites não é nada parecida com a da Illumina.",
  str_homestory_813801001_10_dialog_content = "A alta tecnologia da Illumina é baseada em elaboradas redes mecânicas desenvolvidas com sólido conhecimento e precisão...",
  str_homestory_813801001_11_dialog_content = "Mas os Caelestites... Tudo parece tão fresco e diferente.",
  str_homestory_813801001_12_dialog_content = "Semelhante a essas tecnologias antigas de alguma forma.",
  str_homestory_813801001_13_dialog_content = "Bom, eu não sei nada sobre isso...",
  str_homestory_813801001_14_dialog_content = "Ho-hum...",
  str_homestory_813801001_15_dialog_content = "Sentindo sono de repente...<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "O que você está esperando? Volte e durma.",
  str_homestory_813801001_17_dialog_content = "Estou tentando combinar esses colecionáveis com os documentos que li antes. Felizmente, haverá descobertas intrigantes.",
  str_homestory_813801001_18_dialog_content = "Pode haver celestitas em algum outro lugar deste continente muito antes do nosso tempo...",
  str_homestory_813801001_19_dialog_content = "As pessoas não tinham ideia de que eram realmente celestitas e, portanto, confundiram sua tecnologia com as antigas.",
  str_homestory_813801001_20_dialog_content = "... Hahaha. Deixa para lá.",
  str_homestory_813801001_21_dialog_content = "Estou ficando um pouco irreal aqui. Eu provavelmente deveria ir para a cama.",
  str_homestory_813801001_22_dialog_content = "Siobhan, Estou preocupado com você.",
  str_homestory_813801001_23_dialog_content = "Por que você tem que terminar agora?",
  str_homestory_813801001_24_dialog_content = "Eu não acho que você pode trabalhar bem neste estado...",
  str_homestory_813801001_25_dialog_content = "Você não está hospedando alguns cidadãos de Lumopolis aqui?",
  str_homestory_813801001_26_dialog_content = "Embora você seja um celestita, eu não acho que eles iriam sabotar o museu...",
  str_homestory_813801001_27_dialog_content = "Eu... só estou preocupado!",
  str_homestory_813801001_28_dialog_content = "Sinto que preciso registrar e analisar tudo o mais rápido possível.",
  str_homestory_813801001_29_dialog_content = "Quem sabe como esses odiadores de tecnologia realmente pensam sobre esse lugar?",
  str_homestory_813801001_30_dialog_content = "Entendo...",
  str_homestory_813801001_31_dialog_content = "Não se preocupe. Até onde eu sei, existem muitos museus em Lumopolis.",
  str_homestory_813801001_32_dialog_content = "Eles são meus convidados aqui. O que quer que você esteja preocupado, não vai acontecer.",
  str_homestory_813801001_33_dialog_content = "Estou pensando demais?",
  str_homestory_813801001_34_dialog_content = "O excesso de trabalho está me deixando preocupado demais?<sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "Acho que você está apenas cansado.",
  str_homestory_813801001_36_dialog_content = "Que tal fazermos uma pausa e voltarmos a isso mais tarde?",
  str_homestory_813801001_37_dialog_content = "Tudo bem. É o que vou fazer... PlayerName.",
  str_homestory_813801001_38_dialog_content = "Eu estou indo para a cama. E você?",
  str_homestory_813801001_39_dialog_content = "Aposto que você pode descansar um pouco?",
  str_homestory_813801001_40_option_content = "Concordo",
  str_homestory_813801001_41_dialog_content = "Sim, também estou cansado.",
  str_homestory_813801001_42_dialog_content = "Mas...",
  str_homestory_813801001_43_option_content = "Objeto",
  str_homestory_813801001_44_dialog_content = "Meu corpo pode estar cansado, mas meu espírito se sente realizado!",
  str_homestory_813801001_45_dialog_content = "Eu não me importo com todo esse trabalho, desde que todos possam se divertir aqui.",
  str_homestory_813801001_46_dialog_content = "Você pode ser jovem, mas seu senso de liderança é forte.",
  str_homestory_813801001_47_dialog_content = "Valeu...",
  str_homestory_813801001_48_dialog_content = "Não sei por que continuo querendo ir ao rio, mas estou com muito sono para fazer isso.",
  str_homestory_813801001_49_dialog_content = "Falaremos mais sobre a tecnologia Caelestite depois da minha soneca, PlayerName.",
  str_homestory_813801001_50_dialog_content = "Descanse bem, Siobhan.",
  str_homestory_814501001_0_dialog_content = "O que ela está olhando?",
  str_homestory_814501001_1_dialog_content = "Amemori?",
  str_homestory_814501001_2_dialog_content = "Silêncio.<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "?",
  str_homestory_814501001_4_dialog_content = "O que está fazendo?",
  str_homestory_814501001_5_dialog_content = "Observando.",
  str_homestory_814501001_6_dialog_content = "Estou examinando este lugar com muito cuidado e atenção.",
  str_homestory_814501001_7_dialog_content = "Há algo de incomum nisso?",
  str_homestory_814501001_8_dialog_content = "Você não acha que o design do Cloud Gardens é primorosamente intrincado?",
  str_homestory_814501001_9_dialog_content = "Eu fantasiava em construir um lugar assim quando era jovem.",
  str_homestory_814501001_10_dialog_content = "Um que seja fácil de atacar, fácil de defender e um grande conclave para indivíduos com ideias semelhantes.",
  str_homestory_814501001_11_dialog_content = "Oh!",
  str_homestory_814501001_12_dialog_content = "Você tem feito um plano de longo prazo desde a infância, Amemori?",
  str_homestory_814501001_13_dialog_content = "Bem, o sonho para mim naquela época era provavelmente apenas um ímpeto para \"continuar vivendo\".",
  str_homestory_814501001_14_dialog_content = "Mas não é ruim que eu possa viver aqui agora.",
  str_homestory_814501001_15_dialog_content = "Desculpe.",
  str_homestory_814501001_16_dialog_content = "Quer que eu te mostre por aí?",
  str_homestory_814501001_17_dialog_content = "Não se preocupe.",
  str_homestory_814501001_18_dialog_content = "Eu já descobri a configuração do terreno no meu primeiro dia.",
  str_homestory_814501001_19_dialog_content = "Nossa, que perceptivo!",
  str_homestory_814501001_20_dialog_content = "Isso é o que um ninja faz.",
  str_homestory_814501001_21_dialog_content = "Na verdade, gostaria de saber quem projetou este lugar?",
  str_homestory_814501001_22_dialog_content = "Navegador, por acaso você conhece?",
  str_homestory_814501001_23_option_content = "Sim",
  str_homestory_814501001_24_dialog_content = "Vice, das minhas sugestões e das dos artesãos.",
  str_homestory_814501001_25_option_content = "Não",
  str_homestory_814501001_26_dialog_content = "Posso perguntar a ela se você quiser.",
  str_homestory_814501001_27_dialog_content = "Eu me envolvi no plano real, mas ela sabe disso melhor.",
  str_homestory_814501001_28_dialog_content = "Amemori, por que você quer tanto saber?",
  str_homestory_814501001_29_dialog_content = "Você está interessado em construir outro Cloud Gardens na Cloud Island?",
  str_homestory_814501001_30_dialog_content = "Esse pensamento passou pela minha cabeça.",
  str_homestory_814501001_31_dialog_content = "Imagine, uma vez que Cloud Island tenha habitações neste nível, as pessoas desfrutariam de uma vida muito melhor.",
  str_homestory_814501001_32_dialog_content = "Claro, isso é só o começo...",
  str_homestory_814501001_33_dialog_content = "Se realmente aprendêssemos essa tecnologia avançada, seria mais fácil nos defendermos dos inimigos.",
  str_homestory_814501001_34_dialog_content = "Tecnologia Caelestite com conceito e planejamento tão maravilhosos... Vale a pena dar uma olhada.",
  str_homestory_814501001_35_dialog_content = "Entendi.",
  str_homestory_814501001_36_dialog_content = "Eu vou obter a resposta para você!",
  str_homestory_814501001_37_dialog_content = "Agradeço, Navegador!",
  str_homestory_814601001_0_dialog_content = "Cabeça balançando...",
  str_homestory_814601001_1_dialog_content = "Todos os aurorianos...",
  str_homestory_814601001_2_dialog_content = "Passando pelos Jardins da Nuvem.",
  str_homestory_814601001_3_dialog_content = "?",
  str_homestory_814601001_4_dialog_content = "O arco se eleva do terreno plano...",
  str_homestory_814601001_5_dialog_content = "Com um pãozinho recheado na mão!<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "...",
  str_homestory_814601001_7_dialog_content = "Yao, você está recitando um poema?",
  str_homestory_814601001_8_dialog_content = "Aí, Navegador!",
  str_homestory_814601001_9_dialog_content = "Eu não estou recitando.",
  str_homestory_814601001_10_dialog_content = "Mas compondo! O que você acha?",
  str_homestory_814601001_11_option_content = "Bom!",
  str_homestory_814601001_12_dialog_content = "Muito bom!",
  str_homestory_814601001_13_dialog_content = "Yao, você é um poeta talentoso!",
  str_homestory_814601001_14_option_content = "Nada mal",
  str_homestory_814601001_15_dialog_content = "Eu diria que este poema está em algum lugar entre Charon e Viceas obras de.",
  str_homestory_814601001_16_dialog_content = "Nem muito exagerado nem muito realista, revela o verdadeiro desejo do Poeta...",
  str_homestory_814601001_17_dialog_content = "Aham... Mas o que o arco tem a ver com pãezinhos recheados?",
  str_homestory_814601001_18_dialog_content = "Basta olhar para este arqueiro. Você não vê minha futura loja de pães recheados?",
  str_homestory_814601001_19_dialog_content = "Ainda pensando em abrir uma loja de pães recheados?",
  str_homestory_814601001_20_dialog_content = "Cansado de defender a justiça e ajudar os fracos?",
  str_homestory_814601001_21_dialog_content = "Eu quero fazer os dois.",
  str_homestory_814601001_22_dialog_content = "Não é bom me aposentar da vida marcial para uma loja de pães de pelúcia quando estou grisalho?",
  str_homestory_814601001_23_dialog_content = "Você sabe. Guerreiros lendários geralmente optam por se aposentar em algum lugar de um mercado movimentado...",
  str_homestory_814601001_24_dialog_content = "Eles podem continuar a ouvir a lenda que deixaram para trás!",
  str_homestory_814601001_25_dialog_content = "Esses guerreiros não têm coisas melhores para fazer?",
  str_homestory_814601001_26_dialog_content = "Esqueça-os. Venha conhecer meu plano!",
  str_homestory_814601001_27_dialog_content = "Vá em frente. Sou todo ouvidos.",
  str_homestory_814601001_28_dialog_content = "Em primeiro lugar, a loja de pães recheados deve ter três andares.",
  str_homestory_814601001_29_dialog_content = "Metade do primeiro andar é para Anzu e Momo venderem sua comida saborosa. A outra metade é para os meus pratos deliciosos!",
  str_homestory_814601001_30_dialog_content = "O segundo andar é mais como uma taverna, então meus amigos não precisam se preocupar com acomodação quando conversamos até tarde da noite!",
  str_homestory_814601001_31_dialog_content = "O terceiro andar é onde eu moro!",
  str_homestory_814601001_32_dialog_content = "Haverá quartos para mim, Amemori, e Rinne. Navegador e Vice também...",
  str_homestory_814601001_33_dialog_content = "E Kayano. E meus amigos do clã Lin, minha irmã jurada e meus pais...",
  str_homestory_814601001_34_dialog_content = "Devo manter um quarto para Taki? Ele pode não gostar de estar cercado por tantas garotas.<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "E Dayna e Robyn?",
  str_homestory_814601001_36_dialog_content = "Espere... Yao, eu não acho que você pode ganhar dinheiro assim...",
  str_homestory_814601001_37_dialog_content = "Vai custar-lhe uma fortuna preparar todos estes quartos para os seus amigos.",
  str_homestory_814601001_38_dialog_content = "Algumas pessoas preferem a solidão. Este tipo de vida comunitária não é para todos...",
  str_homestory_814601001_39_dialog_content = "Dinheiro não é problema!",
  str_homestory_814601001_40_dialog_content = "Hmm... Mas a preferência pessoal é um problema...",
  str_homestory_814601001_41_dialog_content = "De qualquer forma, eles são meus amigos e vou preparar seus quartos.",
  str_homestory_814601001_42_dialog_content = "Mas é completamente com eles se eles querem vir ou não.",
  str_homestory_814601001_43_dialog_content = "Heheh. Todo mundo está feliz. Sem relutância ou compromisso.",
  str_homestory_814601001_44_dialog_content = "Sim, você está certo...",
  str_homestory_814601001_45_dialog_content = "Esta é uma solução exclusiva para os super ricos...",
  str_homestory_816301001_0_dialog_content = "Você está desenhando?",
  str_homestory_816301001_1_dialog_content = "Uau! <sprite=emo_wuzui size=60 />O chefe do dirigívelPlayerName!",
  str_homestory_816301001_2_dialog_content = "Finalmente! Eu estive procurando por você em todos os lugares...",
  str_homestory_816301001_3_dialog_content = "Err... Como posso ajudar?",
  str_homestory_816301001_4_dialog_content = "Eu estava viajando para fazer acordos com as pessoas para suas contribuições quando descobri esta prancheta...",
  str_homestory_816301001_5_dialog_content = "Senhorita Vice disse que você comprou isso contra todas as vozes dissidentes.",
  str_homestory_816301001_6_dialog_content = "Posso tomar como...",
  str_homestory_816301001_7_dialog_content = "Você finalmente concordou em criar arte para Al***my St**s?<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "Confirmar",
  str_homestory_816301001_9_dialog_content = "Sim, eu tenho brincado com essa ideia.",
  str_homestory_816301001_10_dialog_content = "Uau! Finalmente você está disposto a encarar seu presente!",
  str_homestory_816301001_11_dialog_content = "Err... Eu preciso fazer algo para ajudar com a crise financeira.",
  str_homestory_816301001_12_dialog_content = "Minhas habilidades não estão melhorando tão cedo.",
  str_homestory_816301001_13_dialog_content = "Prefiro deixar isso para alguém que realmente gosta de desenhar, como você...",
  str_homestory_816301001_14_option_content = "Negar",
  str_homestory_816301001_15_dialog_content = "Aham... eu conheço minhas habilidades...",
  str_homestory_816301001_16_dialog_content = "Esta placa é para qualquer pessoa apaixonada por desenho.",
  str_homestory_816301001_17_dialog_content = "Chefe do dirigível, por favor, coloque a mão no peito.",
  str_homestory_816301001_18_dialog_content = "Sinta esse coração batendo de amor pelo desenho.",
  str_homestory_816301001_19_dialog_content = "Falando em amor pelo desenho, você é incomparável.",
  str_homestory_816301001_20_dialog_content = "Senhor. Tourdog.",
  str_homestory_816301001_21_dialog_content = "...!",
  str_homestory_816301001_22_dialog_content = "Dia e noite você aborda as pessoas por suas contribuições para o seu jogo. Quando foi a última vez que você dormiu bem?",
  str_homestory_816301001_23_dialog_content = "Para o meu jogo, não preciso dormir ou jantar.",
  str_homestory_816301001_24_dialog_content = "Então há quanto tempo você não desenha livremente?",
  str_homestory_816301001_25_dialog_content = "Nossa...",
  str_homestory_816301001_26_dialog_content = "Você realmente quer que eu desenhe no seu quadro?<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "Se o Sr. Tourdog, a celebridade do Astra, desenharia algo aqui...",
  str_homestory_816301001_28_dialog_content = "Seria perfeito!",
  str_homestory_816301001_29_dialog_content = "Primeiro, encontre o ponto fraco do alvo e tenha uma conversa estimulante. Então, elogie o alvo antes de fazer seu pedido.<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "É assim que você joga o jogo mental?",
  str_homestory_816301001_31_dialog_content = "Depois de pedir tantas contribuições, quase caí na sua armadilha. Interessante!",
  str_homestory_816301001_32_dialog_content = "O protagonista escolhido pelos investidores é realmente impressionante!",
  str_homestory_816301001_33_dialog_content = "O enredo do jogo não será chato enquanto você ainda estiver aqui.",
  str_homestory_816301001_34_option_content = "Pergunte sobre os investidores",
  str_homestory_816301001_35_dialog_content = "Investidores?",
  str_homestory_816301001_36_dialog_content = "Um grupo de chefes capazes que compartilham uma forte fé em você.",
  str_homestory_816301001_37_dialog_content = "Você não precisa saber quem eles são.",
  str_homestory_816301001_38_option_content = "Pergunte sobre o protagonista",
  str_homestory_816301001_39_dialog_content = "Protagonista?",
  str_homestory_816301001_40_dialog_content = "A figura central deste jogo, a estrela absoluta amada por todos.",
  str_homestory_816301001_41_dialog_content = "Esta posição não é para todos.",
  str_homestory_816301001_42_dialog_content = "Você está me perdendo.",
  str_homestory_816301001_43_dialog_content = "Em suma, chefe do dirigível.",
  str_homestory_816301001_44_dialog_content = "Vou desenhar para você uma pintura de pergaminho de Cloud Gardens de graça!",
  str_homestory_816301001_45_dialog_content = "Como minha taxa de matrícula para o seu jogo mental exclusivo para solicitar contribuições.",
  str_homestory_816301001_46_dialog_content = "Aguardo ansiosamente para trabalhar com você.<sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "Hum... Da mesma forma...",
  str_homestory_816301001_48_dialog_content = "Excelente. Preciso planejar a composição desse desenho.",
  str_homestory_816301001_49_dialog_content = "Normalmente, um desenho não leva mais de 3 segundos, mas devo dar o meu melhor para o Airship Boss.",
  str_homestory_816301001_50_dialog_content = "Hmm...",
  str_homestory_816301001_51_dialog_content = "Como devo começar?",
  str_homestory_816301001_52_dialog_content = "vou te deixar com isso...",
  str_homestory_816301001_53_dialog_content = "(Acho que ele não pode me ouvir.)",
  str_homestory_816301001_54_dialog_content = "(Estou fora daqui...)",
  str_homestory_814801001_0_dialog_content = "Ela está aqui?",
  str_homestory_814801001_1_dialog_content = "Azure...",
  str_homestory_814801001_2_dialog_content = "Hã?",
  str_homestory_814801001_3_dialog_content = "De quem é essa cara fofa? Absolutamente adoravel.",
  str_homestory_814801001_4_dialog_content = "Venha aqui. Deixe-me sentir se é macio.",
  str_homestory_814801001_5_dialog_content = "Ah<sprite=emo_yundao size=60 />... Espere!",
  str_homestory_814801001_6_dialog_content = "Sou eu... PlayerName.",
  str_homestory_814801001_7_dialog_content = "PlayerName? Soa familiar.",
  str_homestory_814801001_8_dialog_content = "Ah! Hahahah. Eu me lembro agora!",
  str_homestory_814801001_9_dialog_content = "Esse é o meu namoradinho celestita!",
  str_homestory_814801001_10_option_content = "Admitem",
  str_homestory_814801001_11_dialog_content = "... Sim. Sou eu.",
  str_homestory_814801001_12_dialog_content = "Uau! Você admite?",
  str_homestory_814801001_13_dialog_content = "Então é melhor você assumir a responsabilidade.",
  str_homestory_814801001_14_option_content = "Negar",
  str_homestory_814801001_15_dialog_content = "Azure, por favor, não brinque assim...",
  str_homestory_814801001_16_dialog_content = "Outras pessoas podem entender mal...",
  str_homestory_814801001_17_dialog_content = "Oh? De que você tem tanto medo?",
  str_homestory_814801001_18_dialog_content = "Você não quer que aquela garota Illumina com cauda de dragão ouça?",
  str_homestory_814801001_19_dialog_content = "Ou você está pensando naquela princesa distante de Lumopolis?",
  str_homestory_814801001_20_dialog_content = "...",
  str_homestory_814801001_21_dialog_content = "Ainda mais fofo quando você cora. Hahahah.",
  str_homestory_814801001_22_dialog_content = "Eu... eu tenho que ir...<sprite=emo_hanshui size=60 />",
  str_homestory_814801001_23_dialog_content = "Pronto pronto. Eu paro agora.",
  str_homestory_814801001_24_dialog_content = "Você estava me procurando antes?",
  str_homestory_814801001_25_dialog_content = "Eu só quero perguntar como você está se saindo aqui...",
  str_homestory_814801001_26_dialog_content = "Aww... Minha pequena Caelestite é tão carinhosa. Estou realmente tocado.",
  str_homestory_814801001_27_dialog_content = "Graças a você, estou me divertindo muito aqui.",
  str_homestory_814801001_28_dialog_content = "Bem diferente daquele deserto escaldante e árido, este lugar é tão verde.",
  str_homestory_814801001_29_dialog_content = "Não está quente. Não seco. Até o vento é muito suave.",
  str_homestory_814801001_30_dialog_content = "Muito menos escória irritante.",
  str_homestory_814801001_31_dialog_content = "Um salão de beleza natural...",
  str_homestory_814801001_32_dialog_content = "Você não acha que estou mais bonita agora?",
  str_homestory_814801001_33_option_content = "Confirmar",
  str_homestory_814801001_34_dialog_content = "Sim, sua beleza chegou ao clímax...",
  str_homestory_814801001_35_option_content = "Negar",
  str_homestory_814801001_36_dialog_content = "Você não pode ficar mais bonita porque você já é perfeita.",
  str_homestory_814801001_37_dialog_content = "Onde você aprendeu todas essas palavras doces?",
  str_homestory_814801001_38_dialog_content = "Acho que devo ficar mais tempo para desfrutar de sua calorosa hospitalidade?",
  str_homestory_814801001_39_dialog_content = "Pequena celestita, você quer que eu fique?",
  str_homestory_814801001_40_option_content = "Confirmar",
  str_homestory_814801001_41_dialog_content = "Claro... Você pode ficar o tempo que quiser.",
  str_homestory_814801001_42_dialog_content = "A porta está sempre aberta para você.",
  str_homestory_814801001_43_option_content = "Negar",
  str_homestory_814801001_44_dialog_content = "Eu... eu não tenho nenhuma expectativa...",
  str_homestory_814801001_45_dialog_content = "Você e todos os outros são livres para ir e vir...",
  str_homestory_814801001_46_dialog_content = "Bem, vou me sentir em casa então.",
  str_homestory_814801001_47_dialog_content = "Diga à sua loja para pedir um vinho decente.",
  str_homestory_814801001_48_dialog_content = "Eu não posso esperar mais. Ok?",
  str_homestory_814801001_49_dialog_content = "Sim...",
  str_homestory_814801001_50_dialog_content = "O que você está esperando?<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "Eu estou trabalhando nisso!",
  str_homestory_815001001_0_dialog_content = "Completamente ainda...",
  str_homestory_815001001_1_dialog_content = "Olá, PlayerName.<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "Lenoreestá muito feliz em vê-lo.",
  str_homestory_815001001_3_dialog_content = "Lenore, por que você está parado aqui como uma estátua?",
  str_homestory_815001001_4_dialog_content = "Você não quer dar uma volta?",
  str_homestory_815001001_5_dialog_content = "Dar uma volta?",
  str_homestory_815001001_6_dialog_content = "Este é um novo pedido de PlayerName?",
  str_homestory_815001001_7_dialog_content = "Onde exatamente devo ir?",
  str_homestory_815001001_8_dialog_content = "Lenore, isso não é uma ordem. Se for preciso, tome-o como um conselho.",
  str_homestory_815001001_9_dialog_content = "Qual é a diferença entre uma ordem e um conselho?",
  str_homestory_815001001_10_dialog_content = "Hum… Vejamos.",
  str_homestory_815001001_11_dialog_content = "Uma ordem é algo que você deve fazer.",
  str_homestory_815001001_12_dialog_content = "Um conselho é apenas uma sugestão que você não precisa aceitar.",
  str_homestory_815001001_13_dialog_content = "Entendi.",
  str_homestory_815001001_14_dialog_content = "PlayerName aconselhado Lenore para dar uma volta. É um conselho.",
  str_homestory_815001001_15_dialog_content = "Lenore pode optar por passear ou não.",
  str_homestory_815001001_16_dialog_content = "Muito esperto! Você entendeu completamente!",
  str_homestory_815001001_17_dialog_content = "Agradeço pelo elogio, PlayerName.",
  str_homestory_815001001_18_dialog_content = "De nada.",
  str_homestory_815001001_19_dialog_content = "...",
  str_homestory_815001001_20_dialog_content = "...",
  str_homestory_815001001_21_dialog_content = "...",
  str_homestory_815001001_22_dialog_content = "Errar... Lenore?",
  str_homestory_815001001_23_dialog_content = "Então você não quer andar por aí?",
  str_homestory_815001001_24_dialog_content = "Não é apenas um conselho?",
  str_homestory_815001001_25_dialog_content = "Lenore não tem que fazer.",
  str_homestory_815001001_26_dialog_content = "Ahh!",
  str_homestory_815001001_27_dialog_content = "Plantei muitas flores e árvores lindas. E algumas novas instalações de recreação foram instaladas!",
  str_homestory_815001001_28_dialog_content = "Você não quer vê-los?",
  str_homestory_815001001_29_dialog_content = "Deve Lenore quero ver eles?",
  str_homestory_815001001_30_option_content = "Comando",
  str_homestory_815001001_31_dialog_content = "Bem... Não há outro jeito. OK. eu ordeno Lenore para dar uma olhada ao redor.",
  str_homestory_815001001_32_dialog_content = "Sim. Lenore vai completar a missão.",
  str_homestory_815001001_33_option_content = "Sugerir",
  str_homestory_815001001_34_dialog_content = "Eu sei que soa como se gabar, mas eu realmente acho que fiz um bom trabalho.",
  str_homestory_815001001_35_dialog_content = "Então... acho que você deveria dar uma olhada neles.",
  str_homestory_815001001_36_dialog_content = "Desde PlayerName disse assim, Lenore Irá.",
  str_homestory_815001001_37_dialog_content = "Sim. Vá e aproveite.",
  str_homestory_815001001_38_dialog_content = "Mas onde deve Lenore vai?",
  str_homestory_815001001_39_dialog_content = "PlayerName, você tem alguma dica para Lenore?",
  str_homestory_815001001_40_dialog_content = "Ah!",
  str_homestory_815001001_41_dialog_content = "O que foi, PlayerName?",
  str_homestory_815001001_42_dialog_content = "Nada...",
  str_homestory_815001001_43_dialog_content = "Lenore realmente aprendeu sobre a palavra \"conselho\".",
  str_homestory_815001001_44_dialog_content = "Estou um pouco emocionado...",
  str_homestory_801901001_0_dialog_content = "Victoria...",
  str_homestory_801901001_1_dialog_content = "Oi, PlayerName.",
  str_homestory_801901001_2_dialog_content = "Victoria, bom te ver.",
  str_homestory_801901001_3_dialog_content = "Estou admirando esses fluxos alegres. Você gostaria de se juntar a mim?",
  str_homestory_801901001_4_dialog_content = "Admirando streams?",
  str_homestory_801901001_5_dialog_content = "Com licença... O que há de tão especial nesse riacho descendo o rochedo?",
  str_homestory_801901001_6_dialog_content = "A água entrou em um ciclo sem fim sem saber.",
  str_homestory_801901001_7_dialog_content = "Você não acha que é bem parecido com nós, aurorianos?",
  str_homestory_801901001_8_option_content = "Aceno com a cabeça",
  str_homestory_801901001_9_dialog_content = "Sim, é um pouco...",
  str_homestory_801901001_10_dialog_content = "Ainda assim, não entendi completamente suas palavras...",
  str_homestory_801901001_11_option_content = "Agite a cabeça",
  str_homestory_801901001_12_dialog_content = "Sinto muito, Victoria...",
  str_homestory_801901001_13_dialog_content = "Estou um pouco perdido.",
  str_homestory_801901001_14_dialog_content = "Não se preocupe com isso. Apenas uma observação insignificante.",
  str_homestory_801901001_15_dialog_content = "O que é Victoriaestá pensando sobre isso?",
  str_homestory_801901001_16_dialog_content = "A água não tem ideia de que está seguindo um ciclo.",
  str_homestory_801901001_17_dialog_content = "Porque flui sem rumo.",
  str_homestory_801901001_18_dialog_content = "Não sabe por que está fluindo, como escapar deste ciclo ou onde está o fim.",
  str_homestory_801901001_19_dialog_content = "A maioria de nós vive nossas vidas assim, você não acha?",
  str_homestory_801901001_20_dialog_content = "Não estou criticando ou tendo pena de forma alguma.",
  str_homestory_801901001_21_dialog_content = "Como alguém vive sua vida não faz diferença para mim.",
  str_homestory_801901001_22_dialog_content = "Estou apenas tentando pensar.",
  str_homestory_801901001_23_dialog_content = "... Tentando pensar?",
  str_homestory_801901001_24_dialog_content = "Sim.",
  str_homestory_801901001_25_dialog_content = "Devemos respeitar nossos pensamentos. Qualquer coisa que o leve a pensar está além de sua compreensão atual.",
  str_homestory_801901001_26_dialog_content = "... Quer dizer... que precisamos respeitar o desconhecido?",
  str_homestory_801901001_27_dialog_content = "Mais ou menos querida.",
  str_homestory_801901001_28_dialog_content = "Esses fluxos podem estar se divertindo. Eles não precisam da nossa voz em seu fluxo.",
  str_homestory_801901001_29_dialog_content = "É uma coisa boa estar feliz e contente neste ciclo.",
  str_homestory_801901001_30_dialog_content = "Então... Eles não vão exclamar sobre assuntos como este como você fez?",
  str_homestory_801901001_31_dialog_content = "Heheh. Quem sabe?",
  str_homestory_801901001_32_dialog_content = "A propósito... O sol está muito forte aqui<sprite=emo_taiyang size=60 />.",
  str_homestory_801901001_33_dialog_content = "Err... Temos guarda-sóis ali. Victoria, você gostaria de se mudar?",
  str_homestory_801901001_34_dialog_content = "Obrigado por sua preocupação, PlayerName. Acho que posso descansar um pouco.",
  str_homestory_801901001_35_dialog_content = "Que a Verdade te abençoe!",
  str_homestory_800901001_0_dialog_content = "Senhor. Faust?",
  str_homestory_800901001_1_dialog_content = "Caro Navegador, bom vê-lo novamente.",
  str_homestory_800901001_2_dialog_content = "Da mesma maneira.",
  str_homestory_800901001_3_dialog_content = "Na verdade, eu não esperava ver você durante o dia.",
  str_homestory_800901001_4_dialog_content = "Por favor, não me leve a mal. Eu pessoalmente prefiro a noite, mas não sou contra a energia do dia.",
  str_homestory_800901001_5_dialog_content = "Wispy parece gostar daqui.",
  str_homestory_800901001_6_dialog_content = "... Espere. Wispy gosta aqui?",
  str_homestory_800901001_7_dialog_content = "Temos muita tristeza e desespero aqui?",
  str_homestory_800901001_8_dialog_content = "Ainda me lembro de como esse caso especial babava por minha impotência...",
  str_homestory_800901001_9_dialog_content = "Wispy pode encontrar conforto em muitas coisas.",
  str_homestory_800901001_10_dialog_content = "Memórias tristes, pesadelos, crenças desesperadas ou água fria...",
  str_homestory_800901001_11_dialog_content = "Hã?!",
  str_homestory_800901001_12_dialog_content = "(Lembrando o tempo gasto cuidando de Wispy...<sprite=emo_sikao size=60 />)",
  str_homestory_800901001_13_dialog_content = "(Então as pessoas estão tristes e tendo pesadelos aqui?)",
  str_homestory_800901001_14_dialog_content = "Caro Navegador, por favor, não pense demais.",
  str_homestory_800901001_15_dialog_content = "O conforto do Wispy...",
  str_homestory_800901001_16_dialog_content = "Pode vir do passado dos aurorianos, não de seus sentimentos presentes.",
  str_homestory_800901001_17_dialog_content = "Tanto quanto sei, muitos de nós tivemos um passado amargo e doloroso.",
  str_homestory_800901001_18_dialog_content = "Se você colocar assim...",
  str_homestory_800901001_19_dialog_content = "Sim muito verdadeiro.",
  str_homestory_800901001_20_dialog_content = "Espero que todos sejam felizes aqui.",
  str_homestory_800901001_21_dialog_content = "Às vezes, memórias e emoções estão além do controle, caro Navegador.",
  str_homestory_800901001_22_dialog_content = "É um bom hábito não se preocupar excessivamente com os outros.",
  str_homestory_800901001_23_dialog_content = "A natureza segue seu curso.",
  str_homestory_800901001_24_dialog_content = "... Tá bem.",
  str_homestory_800901001_25_dialog_content = "Então você está aqui para?",
  str_homestory_800901001_26_option_content = "Divulgar a verdade?",
  str_homestory_800901001_27_dialog_content = "Não, meu caro Navegador.",
  str_homestory_800901001_28_option_content = "Alimentando Wispy?",
  str_homestory_800901001_29_dialog_content = "Sim, meu caro Navegador.",
  str_homestory_800901001_30_dialog_content = "Este é o local perfeito para alimentar Wispy...",
  str_homestory_800901001_31_dialog_content = "Wispy pode sentir livremente os transeuntes.",
  str_homestory_800901001_32_dialog_content = "Deixe Wispy sentir livremente...",
  str_homestory_800901001_33_dialog_content = "Err... Há tanta dor indescritível em seus corações?",
  str_homestory_800901001_34_dialog_content = "Seu palpite é tão bom quanto o meu, caro Navegador.",
  str_homestory_800901001_35_dialog_content = "No entanto, aqui está uma coisa que eu sei com certeza.",
  str_homestory_800901001_36_dialog_content = "Sim?",
  str_homestory_800901001_37_dialog_content = "Wispy bebeu uma tonelada de água fria antes de sairmos de casa.",
  str_homestory_800901001_38_dialog_content = "?",
  str_homestory_800901001_39_dialog_content = "Então o conforto de Wispy pode ser resultado de toda a água gelada que acabou de beber?",
  str_homestory_800901001_40_dialog_content = "Isso significa que pode não haver muita tristeza, dor ou outros sentimentos negativos, afinal.",
  str_homestory_800901001_41_dialog_content = "Você me enganou!",
  str_homestory_800901001_42_dialog_content = "Receio que sim, meu caro Navegador.",
  str_homestory_800901001_43_dialog_content = "Mas fiz isso para distraí-lo de todo o trabalho e estresse.",
  str_homestory_800901001_44_dialog_content = "As coisas não precisam ser perfeitas, certo?",
  str_homestory_800901001_45_dialog_content = "Que a Verdade te abençoe!",
  str_homestory_800901001_46_dialog_content = "Por que você...!<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "Esta canção de ninar...",
  str_homestory_815101001_1_dialog_content = "Há um cordeiro preto chamado Isaac. O velo assustador pode queimar seu braço!",
  str_homestory_815101001_2_dialog_content = "Oi, Giles!",
  str_homestory_815101001_3_dialog_content = "Ah. Caro Navegador.",
  str_homestory_815101001_4_dialog_content = "Eu quase esqueci. Você já ouviu essa rima infantil.",
  str_homestory_815101001_5_dialog_content = "É hora de algo novo?",
  str_homestory_815101001_6_dialog_content = "Um trabalho novo, um tanto profético, centrado no intrigante celestita...<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "Err...",
  str_homestory_815101001_8_dialog_content = "Você parece relutante, Navegador?",
  str_homestory_815101001_9_dialog_content = "Isso parte meu coração...",
  str_homestory_815101001_10_dialog_content = "Você disse que minhas canções de ninar eram suas favoritas...",
  str_homestory_815101001_11_dialog_content = "(... Eu realmente?)",
  str_homestory_815101001_12_option_content = "Você terminou de criar o trabalho?",
  str_homestory_815101001_13_dialog_content = "Não demora muito quando há inspiração.",
  str_homestory_815101001_14_dialog_content = "Perfeito. A fonte de inspiração está bem na minha frente...",
  str_homestory_815101001_15_option_content = "Você poderia, por favor, esperar?",
  str_homestory_815101001_16_dialog_content = "Você nem se deu ao trabalho de inventar alguma desculpa.",
  str_homestory_815101001_17_dialog_content = "Esta é uma clara rejeição para mim.",
  str_homestory_815101001_18_dialog_content = "Charmosa e ágil, a Caelestita pode facilmente roubar seu coração...",
  str_homestory_815101001_19_dialog_content = "... Já começou?",
  str_homestory_815101001_20_dialog_content = "La la la! La la la! Uma casa charmosa cheia de flores.",
  str_homestory_815101001_21_dialog_content = "Peixes e camarões também o chamam de lar.",
  str_homestory_815101001_22_dialog_content = "Ela mora aqui com isso. Juntos, eles abraçam um destemido celestita.",
  str_homestory_815101001_23_dialog_content = "Pitpat... Pitpat... A chuva do tempo chuvisca.",
  str_homestory_815101001_24_dialog_content = "Construa torres altas. Fortaleça-os com tijolos e telhas. Procure maneiras de se tornar mais forte.",
  str_homestory_815101001_25_dialog_content = "La la la! La la la! Onde está o celestita agora?",
  str_homestory_815101001_26_dialog_content = "A casa agora é grande e alta. Olhe para o celestita acima das nuvens, sem piscar.",
  str_homestory_815101001_27_dialog_content = "La la la! La la la! Uma casa charmosa cheia de flores...",
  str_homestory_815101001_28_dialog_content = "... Esta é a sua profecia?",
  str_homestory_815101001_29_dialog_content = "Apenas uma simples canção de ninar, Navigator.",
  str_homestory_815101001_30_dialog_content = "Você está assustado? É só um trabalho meu...",
  str_homestory_815101001_31_dialog_content = "Sim eu sei.",
  str_homestory_815101001_32_dialog_content = "Muitas vezes acho suas canções de ninar simples, mas obscuras.",
  str_homestory_815101001_33_dialog_content = "Uma canção de ninar nada mais é do que uma canção de ninar.",
  str_homestory_815101001_34_dialog_content = "Navegador, por favor, não pense muito sobre isso.",
  str_homestory_815101001_35_dialog_content = "Multar. Vamos voltar à vida real...",
  str_homestory_815101001_36_dialog_content = "Como você está se sentindo aqui?",
  str_homestory_815101001_37_dialog_content = "Isaac e eu adoramos.",
  str_homestory_815101001_38_dialog_content = "Tenho uma forte vontade de escrever mais... Hahah!",
  str_homestory_815101001_39_dialog_content = "Sejam os transeuntes aleatórios ou o Navigator, todos eles são fontes de inspiração para mim.<sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "Bom de se ouvir...",
  str_homestory_815101001_41_dialog_content = "Baa baa...",
  str_homestory_815101001_42_dialog_content = "Preciso de um momento a sós com Isaac. Com licença, Navegador.",
  str_homestory_815101001_43_dialog_content = "Vejo você na próxima vez?",
  str_homestory_815101001_44_dialog_content = "Certo... Até mais.",
  str_homestory_815301001_0_dialog_content = "O Grande Marechal?",
  str_homestory_815301001_1_dialog_content = "Você fez um ótimo trabalho com a infraestrutura.<sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "Obrigado por suas amáveis palavras, Grande Marechal!",
  str_homestory_815301001_3_dialog_content = "Estou tão acostumado com os quadrados arrumados e uniformes na Illumina. Este é diferente e refrescante.",
  str_homestory_815301001_4_dialog_content = "As pessoas desprezam a Illumina por nosso mau gosto em arte e baixo padrão de beleza.",
  str_homestory_815301001_5_dialog_content = "Infelizmente, muitos desses lugares que buscam a perfeição na arte estão lutando para alimentar seu povo.",
  str_homestory_815301001_6_dialog_content = "Coisas bem estruturadas custam menos e funcionam com mais eficiência. Isso é bastante simples de entender.",
  str_homestory_815301001_7_dialog_content = "Mas tenho que dizer que é lindo aqui.",
  str_homestory_815301001_8_dialog_content = "Bonito e maré. Vice e você deve ter trabalhado duro para isso.",
  str_homestory_815301001_9_option_content = "Aceno com a cabeça",
  str_homestory_815301001_10_dialog_content = "Foi principalmente Vice... Eu não sei muito sobre isso.",
  str_homestory_815301001_11_dialog_content = "Bem, é um mérito reconhecer suas falhas.",
  str_homestory_815301001_12_option_content = "Agite a cabeça",
  str_homestory_815301001_13_dialog_content = "Não é tão ruim. Os vaga-lumes ajudaram muito. E nossos amigos do Sindicato dos Correios.",
  str_homestory_815301001_14_dialog_content = "É um prazer, desde que todos estejam se divertindo aqui.",
  str_homestory_815301001_15_dialog_content = "Não é esta a qualidade mais preciosa que vocês dois têm?",
  str_homestory_815301001_16_dialog_content = "Na minha opinião, ter prazer em servir aos outros é um dom especial.",
  str_homestory_815301001_17_dialog_content = "Como você planejou cuidadosamente...",
  str_homestory_815301001_18_dialog_content = "Eu estou ficando em um quarto como Vice's. E comemos a mesma comida todos os dias.",
  str_homestory_815301001_19_dialog_content = "Você está me tratando muito melhor do que a maioria das pessoas.",
  str_homestory_815301001_20_dialog_content = "É difícil tratar todos igualmente, independentemente de seu status e posição.",
  str_homestory_815301001_21_dialog_content = "(Não esperava que o Grande Marechal visse as coisas deste ângulo...)",
  str_homestory_815301001_22_dialog_content = "(Devo dizer a verdade?)",
  str_homestory_815301001_23_dialog_content = "(Ok... é melhor eu ser honesto...)",
  str_homestory_815301001_24_dialog_content = "Na verdade, Grande Marechal...",
  str_homestory_815301001_25_dialog_content = "Não podemos ter quartos melhores...",
  str_homestory_815301001_26_dialog_content = "Sei disso.",
  str_homestory_815301001_27_dialog_content = "Não é sobre o tamanho do seu orçamento, mas como você planeja gastar o dinheiro em primeiro lugar.",
  str_homestory_815301001_28_dialog_content = "acho que consegui...",
  str_homestory_815301001_29_dialog_content = "Ótimo.",
  str_homestory_815301001_30_dialog_content = "Vou visitar meus camaradas Illumina.",
  str_homestory_815301001_31_dialog_content = "Tchau, PlayerName.",
  str_homestory_815301001_32_dialog_content = "Foi uma honra falar com você, Grande Marechal!",
  str_homestory_803801001_0_dialog_content = "Jogando de novo?",
  str_homestory_803801001_1_dialog_content = "Oi, PlayerName!",
  str_homestory_803801001_2_dialog_content = "Heheh... Quer jogar?",
  str_homestory_803801001_3_dialog_content = "Não.",
  str_homestory_803801001_4_dialog_content = "Eu só quero perguntar como você está se instalando aqui.",
  str_homestory_803801001_5_dialog_content = "Hum...",
  str_homestory_803801001_6_dialog_content = "Nada mal. Poderia usar mais algumas instalações de recreação.",
  str_homestory_803801001_7_dialog_content = "Hum. Eu entendi! O super doce PlayerName deve estar aqui para ajudar a aliviar o tédio. Estou certo?",
  str_homestory_803801001_8_dialog_content = "Er... eu...",
  str_homestory_803801001_9_dialog_content = "Heheh. Vamos jogar um jogo simples...",
  str_homestory_803801001_10_dialog_content = "É muito fácil. Não precisamos de nenhum dispositivo!",
  str_homestory_803801001_11_dialog_content = "Quer dizer... Pedra Papel Tesoura?",
  str_homestory_803801001_12_dialog_content = "Não! Questionário!",
  str_homestory_803801001_13_dialog_content = "Preparar? O jogo está prestes a começar!",
  str_homestory_803801001_14_dialog_content = "Tudo bem... Só porque você está tão interessado nisso.",
  str_homestory_803801001_15_dialog_content = "Questão 1! Por favor, responda verdadeiro ou falso!",
  str_homestory_803801001_16_dialog_content = "Divulgação do Diretor de Tecnologia da Illumina GronruA origem misteriosa de... Ela é na verdade um andróide!",
  str_homestory_803801001_17_option_content = "Verdadeiro",
  str_homestory_803801001_18_dialog_content = "Que diabos? Eu não sou um andróide!",
  str_homestory_803801001_19_option_content = "Falso",
  str_homestory_803801001_20_dialog_content = "Bingo! Correto!<sprite=emo_dianzan size=60 />",
  str_homestory_803801001_21_dialog_content = "Questão 2!",
  str_homestory_803801001_22_dialog_content = "Raphael uma vez venceu Gronru na Taça do Imperador!",
  str_homestory_803801001_23_option_content = "Verdadeiro",
  str_homestory_803801001_24_dialog_content = "Ei! Ninguém pode me vencer, certo?",
  str_homestory_803801001_25_dialog_content = "Eu até a ajudei a melhorar esses aparelhos.",
  str_homestory_803801001_26_option_content = "Falso",
  str_homestory_803801001_27_dialog_content = "Correto! Bom trabalho!",
  str_homestory_803801001_28_dialog_content = "Questão 3!",
  str_homestory_803801001_29_dialog_content = "PlayerName transferirá as permissões do sistema operacional para este local para Gronru!",
  str_homestory_803801001_30_dialog_content = "Verdadeiro...",
  str_homestory_803801001_31_dialog_content = "Aguentar! Esta pergunta não deveria ser permitida em nenhum quiz!",
  str_homestory_803801001_32_dialog_content = "Ah... Não?",
  str_homestory_803801001_33_dialog_content = "Err... Claro que não, Gronru!",
  str_homestory_803801001_34_dialog_content = "Hum! Você me rejeitou?",
  str_homestory_803801001_35_dialog_content = "Você deve estar possuído pelo chefe final!",
  str_homestory_803801001_36_dialog_content = "Possuído? O que te fez dizer isso?",
  str_homestory_803801001_37_dialog_content = "Um verdadeiro celestita nunca pode me dizer não!",
  str_homestory_803801001_38_dialog_content = "O super amável Caelestite nunca recusou um único pedido meu no passado!",
  str_homestory_803801001_39_dialog_content = "Affe…",
  str_homestory_803801001_40_dialog_content = "Eu provavelmente desistiria de qualquer coisa por você, exceto as permissões para o Colosso e este lugar, Gronru.",
  str_homestory_803801001_41_dialog_content = "Ahhh... que chato...",
  str_homestory_803801001_42_dialog_content = "No entanto...",
  str_homestory_803801001_43_dialog_content = "Já que você negou meu pedido de pesquisa, vou ter que fazer isso secretamente!",
  str_homestory_803801001_44_dialog_content = "Um dia... hehe. Um dia! Vou descobrir como este sistema está operando!",
  str_homestory_803801001_45_dialog_content = "Tá bom.",
  str_homestory_803801001_46_dialog_content = "Boa sorte.",
  str_homestory_803801001_47_dialog_content = "Um novo jogo está no ar! Muito exitante...<sprite=emo_yaosu size=60 />",
  str_homestory_802601001_0_dialog_content = "Uriel...",
  str_homestory_802601001_1_dialog_content = "...",
  str_homestory_802601001_2_dialog_content = "...",
  str_homestory_802601001_3_dialog_content = "O-o que você quer?",
  str_homestory_802601001_4_dialog_content = "Ah... Nada. Eu só queria ver você.",
  str_homestory_802601001_5_dialog_content = "Estou preocupado se você está indo bem aqui. Lembro que você passou muitas noites sem dormir no Colosso.",
  str_homestory_802601001_6_dialog_content = "Não há nada que não esteja bem...",
  str_homestory_802601001_7_dialog_content = "Afinal, as únicas duas coisas que realmente me importam são o meu Anel de Fogo e o Casaco da Fênix...",
  str_homestory_802601001_8_dialog_content = "Umm... Existe alguma coisa que eu possa conseguir para você então?",
  str_homestory_802601001_9_dialog_content = "Comida, brinquedos, qualquer coisa?",
  str_homestory_802601001_10_dialog_content = "Você pode me dizer qualquer coisa!",
  str_homestory_802601001_11_dialog_content = "não quero nada...",
  str_homestory_802601001_12_dialog_content = "eu vou queimar<sprite=emo_nuhuo size=60 /> todos no chão...",
  str_homestory_802601001_13_dialog_content = "De jeito nenhum, Uriel.",
  str_homestory_802601001_14_dialog_content = "Instalei instalações de prevenção de incêndio aqui. Você não precisa se preocupar com nada!",
  str_homestory_802601001_15_dialog_content = "Entendo...",
  str_homestory_802601001_16_dialog_content = "Sim!",
  str_homestory_802601001_17_dialog_content = "Nada?",
  str_homestory_802601001_18_dialog_content = "...",
  str_homestory_802601001_19_dialog_content = "... Não.",
  str_homestory_802601001_20_dialog_content = "Brinquedos e instalações recreativas não podem proporcionar alegria duradoura...",
  str_homestory_802601001_21_dialog_content = "É breve e barato...",
  str_homestory_802601001_22_dialog_content = "Na verdade, essa alegria passageira é muitas vezes seguida por uma dor sem fim...",
  str_homestory_802601001_23_dialog_content = "Basta pensar na tortura que você sofrerá pegando fogo por essa felicidade momentânea...",
  str_homestory_802601001_24_dialog_content = "Prefiro não ter nada disso...",
  str_homestory_802601001_25_dialog_content = "Além disso... Nem sempre há alegria depois da dor...",
  str_homestory_802601001_26_dialog_content = "Muito pelo contrário, a alegria momentânea pode ser enganosa, criando a ilusão de que seu sofrimento sempre compensa...",
  str_homestory_802601001_27_dialog_content = "Mas isso não é verdade, pois o sofrimento é infinito e a \"alegria\" é finita...<sprite=emo_xinsui size=60 />",
  str_homestory_802601001_28_dialog_content = "... Você não concorda, PlayerName?",
  str_homestory_802601001_29_dialog_content = "(Tudo parece razoável, mas não consigo seguir a lógica dela...)",
  str_homestory_802601001_30_option_content = "Sim",
  str_homestory_802601001_31_dialog_content = "Você provavelmente está certo em algum sentido, Uriel.",
  str_homestory_802601001_32_option_content = "Não",
  str_homestory_802601001_33_dialog_content = "Eu entendo de onde você vem, mas não posso concordar com você...",
  str_homestory_802601001_34_dialog_content = "(O mais importante agora é acalmá-la...)",
  str_homestory_802601001_35_dialog_content = "Uriel acredita que a alegria depois da dor é barata e momentânea...",
  str_homestory_802601001_36_dialog_content = "Mas muitas pessoas estão vivendo para essa alegria transitória.",
  str_homestory_802601001_37_dialog_content = "Às vezes, essa pequena felicidade depois do sofrimento é esperança.",
  str_homestory_802601001_38_dialog_content = "E essa esperança nos mantém em busca da próxima rodada de alegria...",
  str_homestory_802601001_39_dialog_content = "Por mais curta e pequena que seja a alegria toda vez, é um momento de conforto.",
  str_homestory_802601001_40_dialog_content = "A felicidade não é uma recompensa pela dor que você sofreu.",
  str_homestory_802601001_41_dialog_content = "Pelo contrário, é a nutrição que precisamos desesperadamente para continuar suportando a dor.",
  str_homestory_802601001_42_dialog_content = "...",
  str_homestory_802601001_43_dialog_content = "... Nutrição ...",
  str_homestory_802601001_44_dialog_content = "... Pode ser...",
  str_homestory_802601001_45_dialog_content = "(Acho que ela não está convencida...)",
  str_homestory_802601001_46_dialog_content = "Ah... De qualquer forma, Uriel, por favor, não trate a felicidade como um fardo!",
  str_homestory_802601001_47_dialog_content = "... Ok...",
  str_homestory_802601001_48_dialog_content = "... Eu entendi, PlayerName...",
  str_homestory_802601001_49_dialog_content = "... Obrigado por sua preocupação...",
  str_homestory_802601001_50_dialog_content = "Não mencione isso...",
  str_homestory_802601001_51_dialog_content = "Ahh... Falando em felicidade...",
  str_homestory_802601001_52_dialog_content = "(Lembro que ela gosta muito de ler, especialmente aquelas obras literárias populares em Umbraton...)",
  str_homestory_802601001_53_dialog_content = "Uriel, que tal eu emprestar alguns livros para você?",
  str_homestory_802601001_54_dialog_content = "Você pode ler se estiver entediado.",
  str_homestory_802601001_55_dialog_content = "Não se preocupe. Muitos de nós estão vivendo aqui agora. Tenho alguns exemplares de cada livro...",
  str_homestory_802601001_56_dialog_content = "... Livros ...",
  str_homestory_802601001_57_dialog_content = "...",
  str_homestory_802601001_58_dialog_content = "... Soa bem...",
  str_homestory_802601001_59_dialog_content = "vou ler...",
  str_homestory_802601001_60_dialog_content = "Ufa... Isso é maravilhoso.",
  str_homestory_804401001_0_dialog_content = "Vivian?",
  str_homestory_804401001_1_dialog_content = "O balanço é muito divertido, PlayerName!",
  str_homestory_804401001_2_dialog_content = "Sim! Concordo.",
  str_homestory_804401001_3_dialog_content = "O vento sopra suavemente no meu rosto. Não há uma preocupação em minha mente...<sprite=emo_pugongying size=60 />",
  str_homestory_804401001_4_dialog_content = "O balanço lentamente me empurra para os braços do vento...",
  str_homestory_804401001_5_dialog_content = "Todo o meu estresse se foi como um milagre.",
  str_homestory_804401001_6_dialog_content = "Estou feliz que você se sinta tão relaxado no balanço.",
  str_homestory_804401001_7_dialog_content = "Hmm... O único inconveniente desta atividade recreativa é...",
  str_homestory_804401001_8_dialog_content = "Meu cabelo fica meio bagunçado depois. Hahah.",
  str_homestory_804401001_9_dialog_content = "Exatamente!",
  str_homestory_804401001_10_dialog_content = "Não admira Vice insiste em arrumar o cabelo toda vez que sai do balanço!",
  str_homestory_804401001_11_dialog_content = "Então... Quem teve a ideia de construir um balanço, você ou Vice?",
  str_homestory_804401001_12_option_content = "Fui eu.",
  str_homestory_804401001_13_dialog_content = "Para ser honesto, eu realmente não joguei em um balanço enquanto crescia...",
  str_homestory_804401001_14_dialog_content = "Achei que seria bom ter um aqui.",
  str_homestory_804401001_15_option_content = "Era Vice.",
  str_homestory_804401001_16_dialog_content = "Vice fortemente exigiu um aqui!",
  str_homestory_804401001_17_dialog_content = "Eu não tinha certeza sobre isso no início, mas ela seguiu em frente com confiança com o desenho da construção, apesar da minha hesitação. Eu pensei...",
  str_homestory_804401001_18_dialog_content = "Não foi grande coisa colocar um balanço aqui. Alguns de vocês podem gostar.",
  str_homestory_804401001_19_dialog_content = "Ahh!",
  str_homestory_804401001_20_dialog_content = "Esta é uma decisão fabulosa!",
  str_homestory_804401001_21_dialog_content = "Heheh... Obrigado por suas amáveis palavras, Vivian.",
  str_homestory_804401001_22_dialog_content = "Falando em balanços...",
  str_homestory_804401001_23_dialog_content = "Não há muitos na Illumina.",
  str_homestory_804401001_24_dialog_content = "Hum... É mesmo?",
  str_homestory_804401001_25_dialog_content = "Provavelmente é por isso Vice e Vivian ambos amam tanto esse balanço.",
  str_homestory_804401001_26_dialog_content = "Sim. Coisas raramente vistas são mais atraentes.",
  str_homestory_804401001_27_dialog_content = "Hmm, certo...",
  str_homestory_804401001_28_dialog_content = "Hum? O que está em sua mente?",
  str_homestory_804401001_29_dialog_content = "Ahhh... Nada.",
  str_homestory_804401001_30_dialog_content = "Eu estava calculando o quão necessária essa despesa <sprite=emo_baiyebi size=60 />é.",
  str_homestory_804401001_31_dialog_content = "Despesa?",
  str_homestory_804401001_32_dialog_content = "Que despesa?",
  str_homestory_804401001_33_dialog_content = "Gostaria de saber quanto vai custar para construir um balanço...",
  str_homestory_804401001_34_dialog_content = "Em cada orfanato, escola e base em Illumina.",
  str_homestory_804401001_35_dialog_content = "Ah... Entendi.",
  str_homestory_804401001_36_dialog_content = "Acho que nosso orçamento não dá para esse projeto...",
  str_homestory_804401001_37_dialog_content = "A menos que outros projetos nossos possam cortar alguns custos.",
  str_homestory_804401001_38_dialog_content = "Hmm... Isso é complicado.",
  str_homestory_804401001_39_dialog_content = "Que tal alguns balanços a menos?",
  str_homestory_804401001_40_dialog_content = "Menos balanços, mas em locais melhores?",
  str_homestory_804401001_41_dialog_content = "Tal como...",
  str_homestory_804401001_42_dialog_content = "Em algum lugar todo mundo iria passar!",
  str_homestory_804401001_43_dialog_content = "Como as junções entre as cidades subterrâneas e o meio de vários orfanatos ou escolas...",
  str_homestory_804401001_44_dialog_content = "Você é um gênio, pequeno PlayerName!",
  str_homestory_804401001_45_dialog_content = "Feliz por ajudar.",
  str_homestory_804401001_46_dialog_content = "No entanto...",
  str_homestory_804401001_47_dialog_content = "Por que você estava tão nervoso quando mencionei o orçamento antes?",
  str_homestory_804401001_48_dialog_content = "Há... ah...",
  str_homestory_804401001_49_dialog_content = "Você soou como Vice quando ela verifica o livro de contas...",
  str_homestory_804401001_50_dialog_content = "Provavelmente foi uma resposta condicionada!",
  str_homestory_804401001_51_dialog_content = "Ah... pouco Vice e pouco PlayerName estão tão perto...<sprite=emo_guilian size=60 />",
  str_homestory_808501001_0_dialog_content = "Jane?",
  str_homestory_808501001_1_dialog_content = "Olá, PlayerName.",
  str_homestory_808501001_2_dialog_content = "Ah, Jane!",
  str_homestory_808501001_3_dialog_content = "Você está... Tomando notas de Cloud Gardens?",
  str_homestory_808501001_4_dialog_content = "Sim, vou anotar tudo o que acontece aqui.",
  str_homestory_808501001_5_dialog_content = "Mas agora não estou gravando. Este é um momento para deixar ir completamente.<sprite=emo_pugongying size=60 />",
  str_homestory_808501001_6_dialog_content = "Solte?",
  str_homestory_808501001_7_dialog_content = "O que aconteceu? Algo está incomodando você?",
  str_homestory_808501001_8_dialog_content = "Ou há muita pressão?",
  str_homestory_808501001_9_dialog_content = "Acho que ambos.",
  str_homestory_808501001_10_dialog_content = "PlayerName, como Testemunha profissional, não posso intervir em certas coisas.",
  str_homestory_808501001_11_dialog_content = "Sim, eu ouvi sobre isso.",
  str_homestory_808501001_12_dialog_content = "Bom...",
  str_homestory_808501001_13_dialog_content = "Se você fosse uma Testemunha, ajudaria uma vítima de uma briga de gangues?",
  str_homestory_808501001_14_option_content = "É claro.",
  str_homestory_808501001_15_dialog_content = "Ser testemunha é apenas um trabalho...",
  str_homestory_808501001_16_option_content = "Não.",
  str_homestory_808501001_17_dialog_content = "Para mim, não importa tanto permanecer absolutamente objetivo...",
  str_homestory_808501001_18_dialog_content = "Eu poderia chamar alguém para ajudar imediatamente.",
  str_homestory_808501001_19_dialog_content = "Então você tentaria ajudar, mas não se envolveria?",
  str_homestory_808501001_20_dialog_content = "Isso mesmo.",
  str_homestory_808501001_21_dialog_content = "O que seria Jane Faz?",
  str_homestory_808501001_22_dialog_content = "Foi uma pergunta muito específica que você acabou de fazer. Você se incomoda com algo assim na vida real?",
  str_homestory_808501001_23_dialog_content = "Sim. Recentemente, ajudei uma garotinha.",
  str_homestory_808501001_24_dialog_content = "Ainda estou preocupado com a decisão que tomei na época.",
  str_homestory_808501001_25_dialog_content = "Quais são suas preocupações?",
  str_homestory_808501001_26_dialog_content = "E se minha interferência mudasse como as coisas teriam se desenrolado?",
  str_homestory_808501001_27_dialog_content = "Quando uma testemunha vacila, seu testemunho não é mais neutro.",
  str_homestory_808501001_28_dialog_content = "Pode ser o destino daquela garotinha desaparecer deste mundo. E isso deveria ser a consequência dessa briga de gangues.",
  str_homestory_808501001_29_dialog_content = "Agora eu a salvei...",
  str_homestory_808501001_30_dialog_content = "... Meu testemunho tendencioso é inútil.",
  str_homestory_808501001_31_dialog_content = "Em primeiro lugar, você é uma pessoa real com sentimentos. Então, você é uma testemunha que tenta ao máximo permanecer neutra.",
  str_homestory_808501001_32_dialog_content = "Isso eu entendo.",
  str_homestory_808501001_33_dialog_content = "...",
  str_homestory_808501001_34_dialog_content = "... Entendo.",
  str_homestory_808501001_35_dialog_content = "Que tal se incluir neste testemunho?",
  str_homestory_808501001_36_dialog_content = "Incluindo me a mim?",
  str_homestory_808501001_37_dialog_content = "Sim, escreva toda a história fielmente.",
  str_homestory_808501001_38_dialog_content = "Uma testemunha desencadeada pela cena interveio no processo após esta briga de gangues... Pode ter um impacto.",
  str_homestory_808501001_39_dialog_content = "... Algo parecido.",
  str_homestory_808501001_40_dialog_content = "...",
  str_homestory_808501001_41_dialog_content = "Você tem razão.",
  str_homestory_808501001_42_dialog_content = "Vou tentar registrar o incidente dessa maneira.",
  str_homestory_808501001_43_dialog_content = "Eu agradeço.",
  str_homestory_808801001_0_dialog_content = "Maggie!",
  str_homestory_808801001_1_dialog_content = "Navigator... Você também está aqui pela história?<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "História? Que história?",
  str_homestory_808801001_3_dialog_content = "Achei que podíamos bater um papo. Agora estou muito interessado nesta história.",
  str_homestory_808801001_4_dialog_content = "Ah oh... Desapareceu...",
  str_homestory_808801001_5_dialog_content = "Hum? Maggie não quer que eu saiba?",
  str_homestory_808801001_6_dialog_content = "Não assim...",
  str_homestory_808801001_7_dialog_content = "Tudo bem... Já não é mais segredo...",
  str_homestory_808801001_8_dialog_content = "O que foi?",
  str_homestory_808801001_9_dialog_content = "Hmm... Alguns dias atrás, eu estava explorando o deserto...",
  str_homestory_808801001_10_dialog_content = "Quando me deparei com algumas crianças.",
  str_homestory_808801001_11_dialog_content = "Eles obviamente fugiram de casa e se perderam no vasto deserto...",
  str_homestory_808801001_12_dialog_content = "Eu os vi andando em círculos, então me ofereci para ajudar.",
  str_homestory_808801001_13_dialog_content = "Depois de escoltá-los para um local seguro, eles perguntaram meu nome e quiseram vir me agradecer um dia.",
  str_homestory_808801001_14_dialog_content = "Antes que eu pudesse me apresentar, eles viram meu rabo... Eles...",
  str_homestory_808801001_15_option_content = "Eles riram de você?",
  str_homestory_808801001_16_dialog_content = "Não...",
  str_homestory_808801001_17_dialog_content = "Disseram que meu rabo era muito fofo!",
  str_homestory_808801001_18_dialog_content = "Isso é bom, né?",
  str_homestory_808801001_19_option_content = "Eles te reconheceram?",
  str_homestory_808801001_20_dialog_content = "Não...",
  str_homestory_808801001_21_dialog_content = "Eu não sou popular como Fleur...",
  str_homestory_808801001_22_dialog_content = "Mas eles...",
  str_homestory_808801001_23_dialog_content = "Eles me confundiram com um dragão!",
  str_homestory_808801001_24_dialog_content = "?",
  str_homestory_808801001_25_dialog_content = "Eu estava tão chocado quanto...",
  str_homestory_808801001_26_dialog_content = "Achei ultrajante!",
  str_homestory_808801001_27_dialog_content = "Eles me disseram que nunca tinham visto um dragão com uma cauda fofa antes...",
  str_homestory_808801001_28_dialog_content = "Eles perguntaram se podiam tocar meu rabo...",
  str_homestory_808801001_29_dialog_content = "Eu fiquei muito louco!<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "Por quê? Você não poderia simplesmente explicar a situação para eles?",
  str_homestory_808801001_31_dialog_content = "Eu não me importei que eles me confundissem com outra coisa, mas a atitude deles era irritante!",
  str_homestory_808801001_32_dialog_content = "\"Podemos sentir sua cauda?\"",
  str_homestory_808801001_33_dialog_content = "Que tipo de pedido é esse?",
  str_homestory_808801001_34_dialog_content = "Para quem você diria uma coisa dessas além do seu animal de estimação?",
  str_homestory_808801001_35_dialog_content = "Eu... estou tão bravo...",
  str_homestory_808801001_36_dialog_content = "Eu quero incendiar tudo<sprite=emo_nuhuo size=60 />! Agora mesmo!",
  str_homestory_808801001_37_dialog_content = "(De novo não!)",
  str_homestory_808801001_38_dialog_content = "Acalmar, Maggie!",
  str_homestory_808801001_39_dialog_content = "E se eles simplesmente achassem seu rabo extremamente fofo?",
  str_homestory_808801001_40_dialog_content = "E-é assim que me sinto sobre isso todo esse tempo!",
  str_homestory_808801001_41_dialog_content = "... Para ser honesto, não consigo imaginar como Maggie seria sem esta linda cauda.",
  str_homestory_808801001_42_dialog_content = "...",
  str_homestory_808801001_43_dialog_content = "...É mesmo?",
  str_homestory_808801001_44_dialog_content = "(Ufa... Ela parece menos brava agora...)",
  str_homestory_808801001_45_dialog_content = "Sim, Maggie! Juro!",
  str_homestory_808801001_46_dialog_content = "... Está bem então...",
  str_homestory_808801001_47_dialog_content = "Ah! A propósito...",
  str_homestory_808801001_48_dialog_content = "Mais cedo você disse que não era mais um segredo?",
  str_homestory_808801001_49_dialog_content = "Acho que muitas pessoas não estão cientes deste incidente...",
  str_homestory_808801001_50_dialog_content = "Porque…",
  str_homestory_808801001_51_dialog_content = "Jomu incluiu isso em sua última coleção de contos...",
  str_homestory_808801001_52_dialog_content = "... Hmm... Eu deveria ter pensado nisso...",
  str_homestory_800801001_0_dialog_content = "Brock?",
  str_homestory_800801001_1_dialog_content = "Hahah! Bom te ver.<sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "Você viu isso? Bem legal, certo?",
  str_homestory_800801001_3_dialog_content = "Err... Do que você está falando, Brock?",
  str_homestory_800801001_4_dialog_content = "Meus socos! Organizado! Bonito!",
  str_homestory_800801001_5_dialog_content = "Umm... Não muito pobre...",
  str_homestory_800801001_6_dialog_content = "Não muito pobre? Isso é tudo o que eu tenho?",
  str_homestory_800801001_7_dialog_content = "Deixa para lá. Você não sabe nada sobre boxe. Aposto que você está cheio de ciúmes agora.",
  str_homestory_800801001_8_dialog_content = "?",
  str_homestory_800801001_9_dialog_content = "Não se preocupe, PlayerName! Embora agora eu seja a inveja de você, ainda serei legal com você!",
  str_homestory_800801001_10_dialog_content = "Mas eu não tenho ciúmes de você...",
  str_homestory_800801001_11_dialog_content = "Shush... entendi.",
  str_homestory_800801001_12_dialog_content = "Quando eu tinha mais ou menos a sua idade, ansiava por me tornar um homem de verdade como sou agora!<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "Ouça, PlayerName! Nada é impossível para um coração disposto!",
  str_homestory_800801001_14_dialog_content = "... Multar. Brock.",
  str_homestory_800801001_15_dialog_content = "Você é muito bem-vindo. É minha responsabilidade abastecer Cloud Gardens.",
  str_homestory_800801001_16_dialog_content = "Quando se trata de cuidar dos mais novos, ninguém faz isso melhor do que eu.",
  str_homestory_800801001_17_dialog_content = "Espere um segundo... Que responsabilidade? Que combustível?",
  str_homestory_800801001_18_dialog_content = "Você não está ciente do meu sacrifício por você?",
  str_homestory_800801001_19_dialog_content = "... Me esclareça.",
  str_homestory_800801001_20_dialog_content = "Nós iremos. eu visitei Odi vários dias atrás para repintar meu Brock com as cores do arco-íris.",
  str_homestory_800801001_21_dialog_content = "Ela parecia extremamente preocupada e me implorou para fazer esse favor.",
  str_homestory_800801001_22_dialog_content = "Que favor?",
  str_homestory_800801001_23_dialog_content = "Odi me disse...",
  str_homestory_800801001_24_dialog_content = "Este seu manequim vacilante tem um motor térmico instalado dentro.",
  str_homestory_800801001_25_dialog_content = "?",
  str_homestory_800801001_26_dialog_content = "Este motor é a fonte de energia de todo o Cloud Gardens!",
  str_homestory_800801001_27_dialog_content = "Resumindo, são meus milhares de socos diários que mantêm o Cloud Gardens funcionando.",
  str_homestory_800801001_28_dialog_content = "Hahah! Pra que essa cara? O prazer é meu!",
  str_homestory_800801001_29_dialog_content = "Fico feliz em ajudar!",
  str_homestory_800801001_30_dialog_content = "... Er... Brock... Eu penso...",
  str_homestory_800801001_31_option_content = "Você foi enganado.",
  str_homestory_800801001_32_dialog_content = "Este boneco cambaleante não tem nada além de um pouco de enchimento dentro...",
  str_homestory_800801001_33_dialog_content = "Basicamente não tem nada a ver com o funcionamento do Cloud Gardens.",
  str_homestory_800801001_34_dialog_content = "No entanto!",
  str_homestory_800801001_35_dialog_content = "Sua prática diária de boxe é ótima para sua saúde física e mental.",
  str_homestory_800801001_36_option_content = "Eu aprecio!",
  str_homestory_800801001_37_dialog_content = "No entanto...",
  str_homestory_800801001_38_dialog_content = "eu não acho Odi está muito familiarizado com a estrutura do Cloud Gardens.",
  str_homestory_800801001_39_dialog_content = "Quer dizer...",
  str_homestory_800801001_40_dialog_content = "Este boneco cambaleante não tem nada além de um pouco de enchimento dentro...",
  str_homestory_800801001_41_dialog_content = "Oh! É assim mesmo?",
  str_homestory_800801001_42_dialog_content = "Hahah. Eu acho Odi nem sempre está certo!",
  str_homestory_800801001_43_dialog_content = "Hum... Brock...",
  str_homestory_800801001_44_dialog_content = "Você pode ter sido enganado.",
  str_homestory_800801001_45_dialog_content = "Eu acho. Não seria a primeira vez.",
  str_homestory_800801001_46_dialog_content = "Você não está chateado?",
  str_homestory_800801001_47_dialog_content = "Porque eu estaria?",
  str_homestory_800801001_48_dialog_content = "Eles adoram brincar comigo porque gostam muito de mim!",
  str_homestory_800801001_49_dialog_content = "... Hmm ... Você provavelmente está certo.",
  str_homestory_800801001_50_dialog_content = "Pelo menos...",
  str_homestory_800801001_51_dialog_content = "Provocar-me é uma maneira de mostrar sua admiração e confiança por mim.",
  str_homestory_800801001_52_dialog_content = "... Admiração? Você tem certeza disso?",
  str_homestory_800801001_53_dialog_content = "Por que você acha que eles nunca tiram sarro Sinsa?",
  str_homestory_800801001_54_dialog_content = "Meu toque comum é inigualável! Hahahaha!<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "Tweety?",
  str_homestory_806501001_1_dialog_content = "Uau! Navegador! Gwad para vê-lo.",
  str_homestory_806501001_2_dialog_content = "Tweety, qual é o problema? Por que você está tão nervoso para me ver?",
  str_homestory_806501001_3_dialog_content = "Ah... eu?",
  str_homestory_806501001_4_dialog_content = "Olhar. Você deixou cair coisas em todos os lugares.",
  str_homestory_806501001_5_dialog_content = "Ah! Onde?",
  str_homestory_806501001_6_dialog_content = "Aquela penugem branca ao lado dos seus pés...",
  str_homestory_806501001_7_dialog_content = "Ahh... deixe-me conquistar...",
  str_homestory_806501001_8_dialog_content = "Uau! São penas fwom Tweety!",
  str_homestory_806501001_9_dialog_content = "Boohoo... Nunca deveria fazer coisas ruins.",
  str_homestory_806501001_10_dialog_content = "Coisas ruins?",
  str_homestory_806501001_11_dialog_content = "Não é à toa que seu rabo está abaixado hoje.",
  str_homestory_806501001_12_dialog_content = "Hmm...",
  str_homestory_806501001_13_dialog_content = "O que aconteceu? Você poderia me dizer?",
  str_homestory_806501001_14_dialog_content = "É melhor eu dizer ao Navigator...",
  str_homestory_806501001_15_dialog_content = "Tweety veio entregar uma carta hoje.",
  str_homestory_806501001_16_dialog_content = "OK. Já está no posto? daqui a pouco vou lá!",
  str_homestory_806501001_17_dialog_content = "Mas... Por favor, espere!",
  str_homestory_806501001_18_dialog_content = "A carta... não enviei ao correio.",
  str_homestory_806501001_19_dialog_content = "Tweety notei que o Cloud Gardens mudou muito!",
  str_homestory_806501001_20_dialog_content = "Fui aqui e ali e esqueci-me da carta...",
  str_homestory_806501001_21_dialog_content = "Essa é a \"coisa ruim\" que você fez?",
  str_homestory_806501001_22_option_content = "Ficar com raiva",
  str_homestory_806501001_23_dialog_content = "Negligenciar seus deveres pode ser um grande problema.",
  str_homestory_806501001_24_dialog_content = "Como proprietário do Cloud Gardens, devo puni-lo?",
  str_homestory_806501001_25_dialog_content = "Uau! Punir-me?",
  str_homestory_806501001_26_dialog_content = "Mais penas vão cair do meu rabo...",
  str_homestory_806501001_27_dialog_content = "Ok... eu vou te punir...",
  str_homestory_806501001_28_option_content = "Conforto",
  str_homestory_806501001_29_dialog_content = "Não se preocupe. Não é urgente.",
  str_homestory_806501001_30_dialog_content = "Fico muito feliz que tenha gostado das mudanças que fiz aqui.",
  str_homestory_806501001_31_dialog_content = "Obrigado, Navegador. Você é muito gentil!",
  str_homestory_806501001_32_dialog_content = "Então, quem enviou a carta?",
  str_homestory_806501001_33_dialog_content = "Mostre-me.",
  str_homestory_806501001_34_dialog_content = "Ok! A União Couwier sempre entlega!",
  str_homestory_806501001_35_dialog_content = "Uau! Onde está a carta?",
  str_homestory_806501001_36_dialog_content = "Não na minha bolsa...",
  str_homestory_806501001_37_dialog_content = "Não no meu chapéu!",
  str_homestory_806501001_38_dialog_content = "Acalmar. Você deixou cair em algum lugar?",
  str_homestory_806501001_39_dialog_content = "Onde você foi antes, Tweety?",
  str_homestory_806501001_40_dialog_content = "Em todos os lugares... eu fui em todo lugar.",
  str_homestory_806501001_41_dialog_content = "... Vai ser difícil pesquisar então.",
  str_homestory_806501001_42_dialog_content = "Tweety não quer se tornar o próximo Dove...",
  str_homestory_806501001_43_dialog_content = "Hum? Alguma coisa caiu do seu rabo...",
  str_homestory_806501001_44_dialog_content = "Mais penas caíram da minha cauda? Tweety será careca em nenhum momento!",
  str_homestory_806501001_45_dialog_content = "Não, não parece uma pena...",
  str_homestory_806501001_46_dialog_content = "Err...",
  str_homestory_806501001_47_dialog_content = "Ah! Esta é a letra!",
  str_homestory_806501001_48_dialog_content = "Estava escondido no meu rabo!",
  str_homestory_805501001_0_dialog_content = "Aquilo é...",
  str_homestory_805501001_1_dialog_content = "Pittman?",
  str_homestory_805501001_2_dialog_content = "...!",
  str_homestory_805501001_3_dialog_content = "Pittman?",
  str_homestory_805501001_4_dialog_content = "Ahem... Você deve estar enganado.",
  str_homestory_805501001_5_dialog_content = "Huh? Mas esse terno sério... e as olheiras no seu rosto!",
  str_homestory_805501001_6_dialog_content = "Você está definitivamente Pittman.",
  str_homestory_805501001_7_dialog_content = "Shh…",
  str_homestory_805501001_8_dialog_content = "Controle-se. Não deixe que os outros te ouçam...",
  str_homestory_805501001_9_option_content = "Faça um inquérito",
  str_homestory_805501001_10_dialog_content = "Hum? O juiz de Lumopolis tem medo de ser reconhecido?",
  str_homestory_805501001_11_option_content = "Mostrar compreensão",
  str_homestory_805501001_12_dialog_content = "OK.",
  str_homestory_805501001_13_dialog_content = "Você não quer expor seu paradeiro!",
  str_homestory_805501001_14_dialog_content = "Você é procurado em Lumopolis?",
  str_homestory_805501001_15_dialog_content = "Eu sou justo e honrado, justo e honesto, um devoto seguidor do Deus da Luz e um servo leal de Lumopolis.",
  str_homestory_805501001_16_dialog_content = "Por que eu seria desejado?",
  str_homestory_805501001_17_dialog_content = "Pode ser...",
  str_homestory_805501001_18_dialog_content = "Você montou um cavalo de balanço para se divertir secretamente!",
  str_homestory_805501001_19_dialog_content = "Você... você viu?<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "Ah ha! Você montou o cavalo de balanço!",
  str_homestory_805501001_21_dialog_content = "Aham. Queria ter certeza de que estava em boas condições.",
  str_homestory_805501001_22_dialog_content = "Muitos falsos no mercado hoje em dia.",
  str_homestory_805501001_23_dialog_content = "Nós, juízes, devemos combater esses vendedores sem escrúpulos.",
  str_homestory_805501001_24_dialog_content = "Mas não se preocupe. Seu cavalo de balanço é sólido com excelente acabamento. Pode suportar pelo menos 84 kg.",
  str_homestory_805501001_25_dialog_content = "Você pode arrasar com tranquilidade.",
  str_homestory_805501001_26_dialog_content = "Er... Obrigado...",
  str_homestory_805501001_27_dialog_content = "Eu instalei este cavalo de balanço aqui para que todos possam se divertir.",
  str_homestory_805501001_28_dialog_content = "Não há necessidade de ser sorrateiro sobre isso!",
  str_homestory_805501001_29_dialog_content = "De onde vem isso?",
  str_homestory_805501001_30_dialog_content = "Está tudo escrito em seu rosto.",
  str_homestory_805501001_31_dialog_content = "Você não é um bom mentiroso. Hahahah.",
  str_homestory_805501001_32_dialog_content = "... Tá bem.",
  str_homestory_805501001_33_dialog_content = "Por favor, mantenha isso entre nós.",
  str_homestory_805501001_34_dialog_content = "Por quê? Não precisa ser segredo...",
  str_homestory_805501001_35_dialog_content = "Eu adoro montar eu mesmo.",
  str_homestory_805501001_36_dialog_content = "Para defender a justiça, os juízes sempre querem ser persuasivos e tranquilizadores.",
  str_homestory_805501001_37_dialog_content = "Se as pessoas descobrirem esse meu lado infantil...",
  str_homestory_805501001_38_dialog_content = "Eles não serão capazes de confiar no meu julgamento no tribunal.",
  str_homestory_805501001_39_dialog_content = "Isso está certo?",
  str_homestory_805501001_40_dialog_content = "Então PlayerName, meu segredo está seguro com você?",
  str_homestory_805501001_41_dialog_content = "Multar. Embora eu ainda não veja nenhuma conexão entre andar em um cavalo de balanço e tentar um caso...",
  str_homestory_805501001_42_dialog_content = "Eu prometo que não vou contar a ninguém!",
  str_homestory_805501001_43_dialog_content = "Obrigado pela sua compreensão!",
  str_homestory_805501001_44_dialog_content = "Mais uma coisa...",
  str_homestory_805501001_45_dialog_content = "Se você for vítima de mercadorias falsas, eu defenderei a justiça para você!<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "Parece uma espada sendo embainhada?",
  str_homestory_815501001_1_dialog_content = "Eraveil é realmente maravilhoso, PlayerName!",
  str_homestory_815501001_2_dialog_content = "Não é ruim... eu acho...",
  str_homestory_815501001_3_dialog_content = "Quantos segredos mais nos são guardados por este celestita?",
  str_homestory_815501001_4_dialog_content = "... Mal posso esperar para descobrir.",
  str_homestory_815501001_5_dialog_content = "Hmm... Que lugar lindo você tem, garoto.",
  str_homestory_815501001_6_dialog_content = "Muito bem equipado, estrategicamente situado e de difícil acesso.",
  str_homestory_815501001_7_dialog_content = "Em tempos de guerra, isso pode ser uma boa base de combate sem problemas!",
  str_homestory_815501001_8_dialog_content = "Uau... Você está pelo menos dez passos à minha frente, Barton.",
  str_homestory_815501001_9_dialog_content = "Claro que não!",
  str_homestory_815501001_10_dialog_content = "A busca constante pelo poder e o planejamento racional do que você tem são igualmente importantes.",
  str_homestory_815501001_11_dialog_content = "(Barton soa diferente hoje...)",
  str_homestory_815501001_12_dialog_content = "Infelizmente... eu gostaria de ter descoberto isso antes...",
  str_homestory_815501001_13_dialog_content = "... Garoto, o que você acha?",
  str_homestory_815501001_14_dialog_content = "O que é mais importante na sua opinião, crescer mais forte ou planejar racionalmente seus recursos?<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "Ficar mais forte",
  str_homestory_815501001_16_dialog_content = "Se 10 Nightium fosse tudo o que eu tivesse, não faria sentido planejar...",
  str_homestory_815501001_17_dialog_content = "Eu devo me tornar mais forte primeiro. Em outras palavras, eu preciso aumentar minha riqueza primeiro.",
  str_homestory_815501001_18_option_content = "Planejar racionalmente",
  str_homestory_815501001_19_dialog_content = "Se 10 Nightium era tudo que eu tinha, eu deveria encontrar uma maneira de viver antes que eu pudesse pensar em ganhar mais dinheiro...",
  str_homestory_815501001_20_dialog_content = "Huh? Você não pode estar falando sério?",
  str_homestory_815501001_21_dialog_content = "10 Nightium é tudo que você tem?",
  str_homestory_815501001_22_dialog_content = "... Foi só um exemplo!",
  str_homestory_815501001_23_dialog_content = "Está bem.",
  str_homestory_815501001_24_dialog_content = "Eu estava prestes a lhe oferecer um empréstimo se você estivesse tão falido.",
  str_homestory_815501001_25_dialog_content = "Nesse aspecto, a Illumina é muito boa. Pelo menos muitas coisas não custam um centavo.",
  str_homestory_815501001_26_dialog_content = "?",
  str_homestory_815501001_27_dialog_content = "Desculpe. eu discordo...",
  str_homestory_815501001_28_dialog_content = "Cheguei a um ponto em que acredito que buscar poder e recursos de planejamento podem ser conduzidos simultaneamente.",
  str_homestory_815501001_29_dialog_content = "Não precisa ser uma situação de ou-ou.",
  str_homestory_815501001_30_dialog_content = "Eu costumava dar toda a minha atenção ao crescimento do meu poder. Muitos assuntos importantes foram negligenciados ao longo do caminho.",
  str_homestory_815501001_31_dialog_content = "Planejar o que você já tem lhe dá uma ideia melhor do futuro!",
  str_homestory_815501001_32_dialog_content = "Uma compreensão completa de si mesmo permite que você avance suavemente nesta jornada e se torne mais forte.",
  str_homestory_815501001_33_dialog_content = "Mais poder lhe dá uma palavra melhor.",
  str_homestory_815501001_34_dialog_content = "Hmm... Eu concordo com você até certo ponto.",
  str_homestory_815501001_35_dialog_content = "Então você concorda em me emprestar este lugar como minha base de combate?",
  str_homestory_815501001_36_dialog_content = "?!",
  str_homestory_815501001_37_dialog_content = "Eu nunca disse isso!",
  str_homestory_815501001_38_dialog_content = "O conceito de uma base de combate não soa bem para os Cloud Gardens!",
  str_homestory_815501001_39_dialog_content = "Hahah. Quem sabe? Ninguém pode garantir-lhe uma paz duradoura!",
  str_homestory_815501001_40_dialog_content = "Ei! Por favor, não diga isso!<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "Não faz diferença. Devemos estar preparados para riscos potenciais!",
  str_homestory_815501001_42_dialog_content = "Sim. Precisamos de mais algumas rodadas de jogos de guerra sem mais atrasos.",
  str_homestory_815501001_43_dialog_content = "E todas essas ideias na minha cabeça... vou compartilhá-las com Vivian amanhã.",
  str_homestory_815501001_44_dialog_content = "Hmm... Eu não tenho tempo para procurar documentos para um relatório escrito!",
  str_homestory_815501001_45_dialog_content = "(Decido retirar o que acabei de dizer...)",
  str_homestory_815501001_46_dialog_content = "(Barton não mudou um pouco.)",
  str_homestory_801101001_0_dialog_content = "Sharona!",
  str_homestory_801101001_1_dialog_content = "Senhor...",
  str_homestory_801101001_2_dialog_content = "Você está praticando novos movimentos?",
  str_homestory_801101001_3_dialog_content = "Sim.",
  str_homestory_801101001_4_dialog_content = "Muito diligente<sprite=emo_yaling size=60 />. Não é à toa que a principal força de combate da Illumina, a 1ª Legião, está sob seu comando...",
  str_homestory_801101001_5_dialog_content = "Acho que há algum mal-entendido, PlayerName.",
  str_homestory_801101001_6_dialog_content = "Não tenho intenção de introduzir este novo conjunto de movimentos em nosso treinamento militar.",
  str_homestory_801101001_7_dialog_content = "Na verdade, essas são habilidades que adquiri recentemente de um romance.",
  str_homestory_801101001_8_dialog_content = "Você... Você leu um romance?",
  str_homestory_801101001_9_dialog_content = "Espere... Você está praticando movimentos de um romance?",
  str_homestory_801101001_10_dialog_content = "Isso... Isso não soa como o oficial Sharona Eu sei!",
  str_homestory_801101001_11_dialog_content = "Você está chocado?",
  str_homestory_801101001_12_option_content = "Aceno com a cabeça",
  str_homestory_801101001_13_dialog_content = "Pensei que estivesse sempre ocupado com grandes negócios. Lendo romances...",
  str_homestory_801101001_14_dialog_content = "Não me leve a mal. Não tenho nada contra a leitura!",
  str_homestory_801101001_15_option_content = "Agite a cabeça",
  str_homestory_801101001_16_dialog_content = "Pensando bem, não devemos limitar nossa compreensão de uma pessoa à primeira impressão...",
  str_homestory_801101001_17_dialog_content = "Para mim, oficial Sharona parece ocupado o tempo todo. Achei que você não teria tempo para ler um romance.",
  str_homestory_801101001_18_dialog_content = "Você tem razão. Eu não sou um grande leitor por qualquer medida.",
  str_homestory_801101001_19_dialog_content = "Mas o nome do livro me chamou a atenção: The Millennia Entanglement of Two Rebellious Dragons.",
  str_homestory_801101001_20_dialog_content = "...",
  str_homestory_801101001_21_dialog_content = "Onde você por acaso encontrou este livro?",
  str_homestory_801101001_22_dialog_content = "Não me diga que você comprou de um certo auroriano!",
  str_homestory_801101001_23_dialog_content = "Sim, um comerciante em Umbraton vendeu para mim.",
  str_homestory_801101001_24_dialog_content = "Você parece calmo...",
  str_homestory_801101001_25_dialog_content = "Acho que a história não está muito fora de linha.",
  str_homestory_801101001_26_dialog_content = "Ele me disse que o truque deste livro era...",
  str_homestory_801101001_27_dialog_content = "As habilidades secretas há muito perdidas de Dragon e uma história de amor de uma antiga linhagem...",
  str_homestory_801101001_28_dialog_content = "O que? Você não está bravo?",
  str_homestory_801101001_29_dialog_content = "Não muito.",
  str_homestory_801101001_30_dialog_content = "Não há muito que eu possa fazer de qualquer maneira.",
  str_homestory_801101001_31_dialog_content = "A impressão e as vendas deste livro ocorrem em Umbraton, além da minha jurisdição.",
  str_homestory_801101001_32_dialog_content = "Para mim, o conteúdo de um livro pouco importa.",
  str_homestory_801101001_33_dialog_content = "Mas para esses escritores, um livro pode ser a única coisa em que vivem.",
  str_homestory_801101001_34_dialog_content = "... Sim, isso é tão verdade ...",
  str_homestory_801101001_35_dialog_content = "Sharona... Você é um excelente oficial!",
  str_homestory_801101001_36_dialog_content = "Bem, as habilidades secretas do Dragão mencionadas neste livro são bastante ridículas...",
  str_homestory_801101001_37_dialog_content = "Mas pode apimentar um pouco minha rotina de exercícios.",
  str_homestory_801101001_38_dialog_content = "Quer tentar?",
  str_homestory_801101001_39_dialog_content = "Conforme registrado no livro, começaremos com 200 agachamentos fáceis antes de passar para...",
  str_homestory_801101001_40_dialog_content = "Não, não...",
  str_homestory_801101001_41_dialog_content = "Acho que realmente preciso me concentrar nas habilidades celestitas, oficial Sharona.",
  str_homestory_801101001_42_dialog_content = "Vou deixá-lo para o seu exercício... Tchau!",
  str_homestory_801101001_43_dialog_content = "Tchau!",
  str_homestory_810301001_0_dialog_content = "Eicy?",
  str_homestory_810301001_1_dialog_content = "Eicy, quer dar uma olhada por dentro?",
  str_homestory_810301001_2_dialog_content = "Lembro que você adora fazer compras.",
  str_homestory_810301001_3_dialog_content = "PlayerName, já que você conhece meu hobby...",
  str_homestory_810301001_4_dialog_content = "Como você pode ser tão mesquinho construindo apenas uma loja?",
  str_homestory_810301001_5_dialog_content = "Err... eu tenho muitas razões...",
  str_homestory_810301001_6_dialog_content = "Continue.",
  str_homestory_810301001_7_dialog_content = "Se sua memória falhar de repente, posso remover meu tapa-olho...",
  str_homestory_810301001_8_dialog_content = "Meu olhar vazio <sprite=emo_baimao size=60 />Ajudará você.",
  str_homestory_810301001_9_option_content = "Explique",
  str_homestory_810301001_10_dialog_content = "Tudo bem. Me dê um minuto!",
  str_homestory_810301001_11_dialog_content = "A principal razão é o nosso orçamento muito apertado...",
  str_homestory_810301001_12_dialog_content = "Temos tantas coisas para construir. Não é possível fazer tudo perfeito desde o início.",
  str_homestory_810301001_13_option_content = "Responda vagamente",
  str_homestory_810301001_14_dialog_content = "O interrogatório não pode fazer diferença aqui...",
  str_homestory_810301001_15_dialog_content = "Nosso orçamento é muito apertado. Nós simplesmente não podemos pagar outra loja...",
  str_homestory_810301001_16_dialog_content = "Eu acho... Um é melhor do que nenhum!",
  str_homestory_810301001_17_dialog_content = "Isso é muito ousado e direto de sua parte.",
  str_homestory_810301001_18_dialog_content = "Nossa única loja cobre todas as suas necessidades!",
  str_homestory_810301001_19_dialog_content = "Eu tenho trabalhado duro para cooperar com diferentes Guildas em Umbraton...",
  str_homestory_810301001_20_dialog_content = "Os suprimentos estão chegando de forma irregular através do Sindicato dos Correios.",
  str_homestory_810301001_21_dialog_content = "Que tal você entrar e dar uma olhada primeiro? Deixe-me saber se há algo que você quer que eu peça.",
  str_homestory_810301001_22_dialog_content = "Isso não será necessário. Eu já estive lá.",
  str_homestory_810301001_23_dialog_content = "Na verdade, limpei seu estoque para mostrar meu apoio.",
  str_homestory_810301001_24_dialog_content = "Tudo?",
  str_homestory_810301001_25_dialog_content = "Sim.",
  str_homestory_810301001_26_dialog_content = "Incluindo o peixe que acabamos de pegar hoje no rio?",
  str_homestory_810301001_27_dialog_content = "Aqueles coloridos? Sim, eles são adoráveis.",
  str_homestory_810301001_28_dialog_content = "Não consegui encontrar um tanque para mantê-los, então os libertei em um rio próximo.",
  str_homestory_810301001_29_dialog_content = "Até aquele sapato de couro esfarrapado indesejado?",
  str_homestory_810301001_30_dialog_content = "Sapato esfarrapado? Sim. Não é um vaso de flores da última moda?",
  str_homestory_810301001_31_dialog_content = "Entrei em contato com o Sindicato dos Correios para enviá-lo de volta à Verdadeira Ordem.",
  str_homestory_810301001_32_dialog_content = "Que tal... meu mapa de Eraveil desenhado à mão?",
  str_homestory_810301001_33_dialog_content = "Você quer dizer a imagem de um labirinto torto?",
  str_homestory_810301001_34_dialog_content = "Você desenhou? Preciso emoldurar e pendurar na parede.",
  str_homestory_810301001_35_dialog_content = "Obrigada, Eicy... Você é o cliente mais generoso que eu já vi!",
  str_homestory_810301001_36_dialog_content = "Não mencione isso. Compras é tudo sobre espirrar para fora!",
  str_homestory_810301001_37_dialog_content = "Irrita-me que não haja mais loja para comprar mais.",
  str_homestory_810301001_38_dialog_content = "Eicy, você pode dar uma volta.",
  str_homestory_810301001_39_dialog_content = "Temos um museu ali, e a Fonte da Esperança...",
  str_homestory_810301001_40_dialog_content = "Posso dar-lhe a minha palavra. Você não será capaz de vê-los em nenhum outro lugar!",
  str_homestory_810301001_41_dialog_content = "Claro. Soa interessante.",
  str_homestory_810301001_42_dialog_content = "Eu tenho uma ideia. decido comprar <sprite=emo_baiyebi size=60 />vocês.",
  str_homestory_810301001_43_dialog_content = "Huh? Me compre?",
  str_homestory_810301001_44_dialog_content = "Apenas por um dia. Você pode me mostrar ao redor.",
  str_homestory_810301001_45_dialog_content = "Diga-me um preço justo pelo seu tempo.",
  str_homestory_810301001_46_dialog_content = "Combinado! Estou muito feliz em atendê-lo!",
  str_homestory_802301001_0_dialog_content = "Connolly...",
  str_homestory_802301001_1_dialog_content = "A luz suave...",
  str_homestory_802301001_2_dialog_content = "Connolly, o que você disse?",
  str_homestory_802301001_3_dialog_content = "Na-Navegador! <sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "Eu estava apenas murmurando. Por favor, não preste atenção em mim...",
  str_homestory_802301001_5_dialog_content = "... Não, não é só isso!",
  str_homestory_802301001_6_dialog_content = "Você também pode me dar um pouco de atenção... eu... estou no meio de um treinamento de dessensibilização...",
  str_homestory_802301001_7_dialog_content = "Treinamento de dessensibilização?",
  str_homestory_802301001_8_dialog_content = "Sim... Vice me falou sobre isso...",
  str_homestory_802301001_9_dialog_content = "Eu estava tendo dificuldade em me adaptar à luz aqui...",
  str_homestory_802301001_10_dialog_content = "Vice me encontrou escondido em um canto...",
  str_homestory_802301001_11_dialog_content = "Ela percebeu que você precisava de ajuda?",
  str_homestory_802301001_12_dialog_content = "Sim...",
  str_homestory_802301001_13_dialog_content = "Ela me disse para tentar fazer coisas que eu gosto e ignorar outras pessoas...",
  str_homestory_802301001_14_dialog_content = "Ou finja que este é o Holiday Cafe e todos vocês são clientes...",
  str_homestory_802301001_15_dialog_content = "Estou realmente tentando...",
  str_homestory_802301001_16_option_content = "Como você está se sentindo?",
  str_homestory_802301001_17_dialog_content = "Um pouco melhor...",
  str_homestory_802301001_18_dialog_content = "Havia muitas pessoas no Colosso também...",
  str_homestory_802301001_19_option_content = "Não se force.",
  str_homestory_802301001_20_dialog_content = "Você não é obrigado a sair se ficar no seu quarto for mais confortável.",
  str_homestory_802301001_21_dialog_content = "Na verdade, tenho algo para lhe dizer, Navegador...",
  str_homestory_802301001_22_dialog_content = "Hum? O que é isso?",
  str_homestory_802301001_23_dialog_content = "eu prestei atenção Viceconselho de e tocou uma música com Anton aqui<sprite=emo_yinfu size=60 />...",
  str_homestory_802301001_24_dialog_content = "Nunca esperei... uma senhora vestida com uma roupa de Lumopolis me elogiou...",
  str_homestory_802301001_25_dialog_content = "Eu...",
  str_homestory_802301001_26_dialog_content = "Ah... De repente, esse lugar brilhante não parece mais tão ruim, certo?",
  str_homestory_802301001_27_dialog_content = "Às vezes, um elogio é muito encorajador.",
  str_homestory_802301001_28_dialog_content = "Connolly, eu acho que você é fenomenal!",
  str_homestory_802301001_29_dialog_content = "Você faz o café mais saboroso e é um lutador doce e poderoso...",
  str_homestory_802301001_30_dialog_content = "Obrigado por suas amáveis palavras, Navegador. Eu... eu não sei o que dizer...",
  str_homestory_802301001_31_dialog_content = "Mas o elogio daquela senhora... foi diferente do seu!",
  str_homestory_802301001_32_dialog_content = "Navegador e Vice são bons amigos de Connolly...",
  str_homestory_802301001_33_dialog_content = "Você sempre me apoiou, me confortando e me elogiando...",
  str_homestory_802301001_34_dialog_content = "Mas aquela senhora era uma total estranha!",
  str_homestory_802301001_35_dialog_content = "Sua aprovação era pura e mais tranquilizadora para Connolly.",
  str_homestory_802301001_36_dialog_content = "Sim... É exatamente assim que me sinto...",
  str_homestory_802301001_37_dialog_content = "Navegador, você poderia dizer Vice Eu realmente aprecio a ajuda dela?",
  str_homestory_802301001_38_dialog_content = "Eu provavelmente estaria me escondendo no meu quarto agora se não fosse por ela...",
  str_homestory_802301001_39_dialog_content = "Considere isso feito!",
  str_homestory_802301001_40_dialog_content = "Agradeço, Navegador!",
  str_homestory_802301001_41_dialog_content = "Eu pretendo praticar essa música novamente com Anton...",
  str_homestory_802301001_42_dialog_content = "Você também pode tentar algo novo.",
  str_homestory_802301001_43_dialog_content = "Tenho certeza que aquela senhora misteriosa adoraria ouvir.",
  str_homestory_802301001_44_dialog_content = "Ah! Você tem razão...",
  str_homestory_802301001_45_dialog_content = "Ok! Navegador, vou praticar!",
  str_homestory_802301001_46_dialog_content = "Você tem isso!",
  str_homestory_803001001_0_dialog_content = "Sinsa...",
  str_homestory_803001001_1_dialog_content = "Olá, Sinsa!",
  str_homestory_803001001_2_dialog_content = "Uh-huh<sprite=emo_yaosu size=60 />! Bom te ver, PlayerName, o último celestita!",
  str_homestory_803001001_3_dialog_content = "Como está tudo?",
  str_homestory_803001001_4_dialog_content = "Tudo está bem. E você? Passando bem aqui?",
  str_homestory_803001001_5_dialog_content = "Legal.",
  str_homestory_803001001_6_dialog_content = "Não demorou muito para você transformar completamente essa merda...",
  str_homestory_803001001_7_dialog_content = "Você está vivendo até Sinsaexpectativas. Ahahahah.",
  str_homestory_803001001_8_dialog_content = "Então, você decidiu?",
  str_homestory_803001001_9_dialog_content = "Quando você vai se juntar ao Rediesel Wrench?",
  str_homestory_803001001_10_dialog_content = "Hum... Err...",
  str_homestory_803001001_11_dialog_content = "Pelo padrão da Chave Rediesel...",
  str_homestory_803001001_12_dialog_content = "Este lugar precisa desesperadamente de uma área para lutas e corridas de arrancada!",
  str_homestory_803001001_13_option_content = "Rejeitar",
  str_homestory_803001001_14_dialog_content = "Prefiro não ter nenhum conflito aqui...",
  str_homestory_803001001_15_dialog_content = "Não há espaço para violência.",
  str_homestory_803001001_16_dialog_content = "Infelizmente... perdi a conta da sua fria rejeição.",
  str_homestory_803001001_17_dialog_content = "No entanto, PlayerName, sua ideia soa bastante infantil lá atrás.",
  str_homestory_803001001_18_dialog_content = "Acredite em mim. O proibido está definitivamente para acontecer.",
  str_homestory_803001001_19_dialog_content = "Não pergunte como eu sei...",
  str_homestory_803001001_20_dialog_content = "...",
  str_homestory_803001001_21_option_content = "Concordo",
  str_homestory_803001001_22_dialog_content = "Hmm... Não faz parte do nosso plano original...",
  str_homestory_803001001_23_dialog_content = "Mas lutas aleatórias e corridas de arrancada podem resultar em danos às casas pelas quais trabalhei duro.",
  str_homestory_803001001_24_dialog_content = "É melhor ter uma zona especial...",
  str_homestory_803001001_25_dialog_content = "Hahahah. Você cresceu, garoto.",
  str_homestory_803001001_26_dialog_content = "Agora você sabe quando ouvir!",
  str_homestory_803001001_27_dialog_content = "Você poderia me mostrar os dormitórios femininos de Cloud Gardens?",
  str_homestory_803001001_28_dialog_content = "Hã?!",
  str_homestory_803001001_29_dialog_content = "Por que há terror em seus olhos?",
  str_homestory_803001001_30_dialog_content = "Eu acho que você vai lá por uma razão?",
  str_homestory_803001001_31_dialog_content = "É hora de fazer uma visita.",
  str_homestory_803001001_32_dialog_content = "Uma visita?",
  str_homestory_803001001_33_dialog_content = "Sim<sprite=emo_qingsong size=60 />, preciso ter certeza se é bom o suficiente para o meu Eve.",
  str_homestory_803001001_34_dialog_content = "Ufa... entendi.",
  str_homestory_803001001_35_dialog_content = "Preciso verificar se o colchão é macio o suficiente...",
  str_homestory_803001001_36_dialog_content = "Se a lâmpada de cabeceira é boa para os olhos...",
  str_homestory_803001001_37_dialog_content = "Se a folha tiver EveO padrão favorito de...",
  str_homestory_803001001_38_dialog_content = "Se houver um guarda-roupa adequado para Evesão lindos vestidos...",
  str_homestory_803001001_39_dialog_content = "Ah! E o mais importante! Se houver um copo térmico no quarto!",
  str_homestory_803001001_40_option_content = "Concordo",
  str_homestory_803001001_41_dialog_content = "Mandarei Vice para checar tudo...",
  str_homestory_803001001_42_dialog_content = "Hahaha! Este é meu irmão!",
  str_homestory_803001001_43_option_content = "Não Concordo",
  str_homestory_803001001_44_dialog_content = "Sinsa, acho que é hora de você aprender a respeitar Eveo espaço.",
  str_homestory_803001001_45_dialog_content = "O que você disse?",
  str_homestory_803001001_46_dialog_content = "Deixa para lá! Mandarei Vice para checar tudo...",
  str_homestory_811601001_0_dialog_content = "Estes zumbidos e haws!",
  str_homestory_811601001_1_dialog_content = "Navegador, você tem algo para consertar?",
  str_homestory_811601001_2_dialog_content = "No momento ideal! Não recebi nenhum trabalho hoje!",
  str_homestory_811601001_3_dialog_content = "Reparar?",
  str_homestory_811601001_4_dialog_content = "Você está recebendo pedidos... no depósito de carga?",
  str_homestory_811601001_5_dialog_content = "Sim, eu recebo clientes aqui. Então eu arrumo as coisas deles no meu quarto.",
  str_homestory_811601001_6_dialog_content = "Ah, não se preocupe. Nenhum dinheiro está envolvido.",
  str_homestory_811601001_7_dialog_content = "Então por que você...",
  str_homestory_811601001_8_dialog_content = "Por que ofereço serviço de reparo gratuito?",
  str_homestory_811601001_9_dialog_content = "Sim. Normalmente você está ocupado com seus próprios hobbies...",
  str_homestory_811601001_10_dialog_content = "Peças e componentes de pesquisa e tal.",
  str_homestory_811601001_11_dialog_content = "Porque as pessoas aqui são de todos os lugares.<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "As coisas que eles querem consertar são tão diferentes e fascinantes.",
  str_homestory_811601001_13_dialog_content = "Mais cedo Charon me pediu para fazer seu fonógrafo<sprite=emo_yinfu size=60 /> mais alto...",
  str_homestory_811601001_14_dialog_content = "Achei que era apenas um fonógrafo da Illumina e não prestei muita atenção.",
  str_homestory_811601001_15_dialog_content = "Você sabe o que? Acabou sendo um modelo vintage de origem desconhecida!",
  str_homestory_811601001_16_dialog_content = "Hahah. Estudei o fonógrafo várias vezes!",
  str_homestory_811601001_17_dialog_content = "Err... você realmente ajudou Charon torná-lo mais alto?",
  str_homestory_811601001_18_dialog_content = "Bem, só um pouco. Foi meu pagamento por essa rara oportunidade de estudar um novo aparelho...",
  str_homestory_811601001_19_dialog_content = "Mas! Eu também sou uma vítima de sua música alta. Juro que só fiz um pouco mais alto!",
  str_homestory_811601001_20_dialog_content = "Tudo bem... Você parece se divertir aqui.",
  str_homestory_811601001_21_dialog_content = "Muito mesmo!",
  str_homestory_811601001_22_dialog_content = "Tantas tecnologias diferentes, novas peças e dispositivos para estudar... Isso é o paraíso!<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "Ok, contanto que você esteja confortável aqui.",
  str_homestory_811601001_24_dialog_content = "Muito bom. Em breve poderei fazer um novo mecha!",
  str_homestory_811601001_25_dialog_content = "... Aqui vamos nós novamente!",
  str_homestory_811601001_26_dialog_content = "Não seja assim! Eu me importo muito com você! Eu inspecionei a estrutura deste depósito de carga para você agora.",
  str_homestory_811601001_27_dialog_content = "Minha chave de fenda e chave de fenda provaram que este pavilhão é muito estável e não precisa do meu serviço.",
  str_homestory_811601001_28_dialog_content = "Foi construído com materiais da Eraveil.",
  str_homestory_811601001_29_dialog_content = "Ver? Aqui até tenho acesso a materiais do Eraveil. Fabuloso!",
  str_homestory_811601001_30_dialog_content = "Tudo bem então, acho que vou deixar você aqui... para receber ordens?",
  str_homestory_811601001_31_dialog_content = "Você não está me incomodando em nada. Na verdade, você pode ficar e receber ordens comigo.",
  str_homestory_811601001_32_option_content = "Concordo",
  str_homestory_811601001_33_dialog_content = "Tudo bem... Estou curioso para saber quais são as necessidades de reparo por aí.",
  str_homestory_811601001_34_dialog_content = "Excelente!",
  str_homestory_811601001_35_dialog_content = "... Estou tendo um dia muito lento hoje.",
  str_homestory_811601001_36_dialog_content = "... E se ninguém vier até você para reparos?",
  str_homestory_811601001_37_option_content = "Rejeitar",
  str_homestory_811601001_38_dialog_content = "Hoje nao. Tem coisas para fazer...",
  str_homestory_811601001_39_dialog_content = "Ah! A propósito...",
  str_homestory_811601001_40_dialog_content = "E se ninguém vier até você para reparo?",
  str_homestory_811601001_41_dialog_content = "Você vai continuar andando por aqui?",
  str_homestory_811601001_42_dialog_content = "Isso mesmo.",
  str_homestory_811601001_43_dialog_content = "No entanto, navegador, aqui está uma coisa que devo corrigir.",
  str_homestory_811601001_44_dialog_content = "Eu não estou vagando por aqui. Uma intensa guerra mecha está constantemente lutando na minha cabeça.",
  str_homestory_811601001_45_dialog_content = "Antes de você chegar, eu estava pensando em quem ganharia se Mecha PlayerName e Mecha Odi teve uma briga.",
  str_homestory_811601001_46_dialog_content = "Mecha PlayerName é conhecido por seus ataques rápidos e leves, enquanto Mecha Odi está muito mais bem equipado...",
  str_homestory_811601001_47_dialog_content = "Foi uma luta feroz!",
  str_homestory_811601001_48_dialog_content = "Ok... terminei aqui...",
  str_homestory_811701001_0_dialog_content = "Gram?",
  str_homestory_811701001_1_dialog_content = "Gram, o que você está fazendo na loja?",
  str_homestory_811701001_2_dialog_content = "Err... Você está pensando?",
  str_homestory_811701001_3_dialog_content = "Ou há algo que você não pode encontrar aqui?",
  str_homestory_811701001_4_dialog_content = "Garoto.",
  str_homestory_811701001_5_dialog_content = "Preciso de alguns ingredientes para fazer espetos com carne racionada vencida.",
  str_homestory_811701001_6_dialog_content = "Carne vencida<sprite=emo_rou size=60 />...",
  str_homestory_811701001_7_dialog_content = "Expirando, não expirado. Está perfeitamente bem.",
  str_homestory_811701001_8_dialog_content = "Além disso, a qualidade do prato depende apenas da habilidade do chef e não tem nada a ver com a qualidade dos ingredientes.",
  str_homestory_811701001_9_dialog_content = "Gram, você está correto!",
  str_homestory_811701001_10_dialog_content = "Aliás, nunca provei seus espetos...",
  str_homestory_811701001_11_dialog_content = "Você vai.",
  str_homestory_811701001_12_dialog_content = "Os espetos são tão fáceis de fazer.",
  str_homestory_811701001_13_dialog_content = "... Fácil?",
  str_homestory_811701001_14_dialog_content = "Eu sabia. Gram, você é realmente talentoso ...",
  str_homestory_811701001_15_dialog_content = "Um cozinheiro talentoso? Não existe tal coisa.",
  str_homestory_811701001_16_dialog_content = "Hum! A geração jovem tem tudo a ver com dotes!",
  str_homestory_811701001_17_dialog_content = "Muitas conquistas são alcançadas através de trabalho árduo e estudo diligente. Talento sozinho não leva a lugar nenhum!",
  str_homestory_811701001_18_dialog_content = "Cozinho bem porque trabalhei muitos anos na cozinha.",
  str_homestory_811701001_19_dialog_content = "Cozinhar como uma habilidade tem muito pouco a ver com talento.",
  str_homestory_811701001_20_option_content = "Eu não entendo muito bem.",
  str_homestory_811701001_21_dialog_content = "Tentei cozinhar e segui de perto uma receita...",
  str_homestory_811701001_22_dialog_content = "Não deu certo.",
  str_homestory_811701001_23_option_content = "Está começando a fazer sentido",
  str_homestory_811701001_24_dialog_content = "As habilidades culinárias podem ser melhoradas através da prática?",
  str_homestory_811701001_25_dialog_content = "Qualquer coisa pode ser melhorada com bastante prática.",
  str_homestory_811701001_26_dialog_content = "Para cozinhar uma refeição saborosa, você deve senti-la em seu coração.",
  str_homestory_811701001_27_dialog_content = "Sinta?",
  str_homestory_811701001_28_dialog_content = "Então Viceos pratos...",
  str_homestory_811701001_29_dialog_content = "Você não teve nenhum sentimento ou muito sentimento?",
  str_homestory_811701001_30_dialog_content = "Obviamente, ela perdeu seus sentimentos para as instruções.",
  str_homestory_811701001_31_dialog_content = "Digamos que ela seja prejudicada por seus ganhos e perdas pessoais.",
  str_homestory_811701001_32_dialog_content = "Hmm... Você provavelmente pode dizer isso sobre mim também.",
  str_homestory_811701001_33_dialog_content = "Estou com medo de estragar as coisas, mas também muito ansioso para fazer algo incrível. Isso me deixa confuso e estressado...",
  str_homestory_811701001_34_dialog_content = "Vou te dar um exemplo muito simples.",
  str_homestory_811701001_35_dialog_content = "Quando eu estava na unidade de logística, ansiava por ir para a frente, mas ainda assim conseguia entregar comida saborosa todos os dias. Só havia uma razão.",
  str_homestory_811701001_36_dialog_content = "Queria que todos os meus irmãos de armas se alimentassem bem para terem forças para lutar.",
  str_homestory_811701001_37_dialog_content = "Agora estou cozinhando aqui pelo mesmo motivo.",
  str_homestory_811701001_38_dialog_content = "Quero que vocês, jovens, comam bem para terem energia para lutar!",
  str_homestory_811701001_39_dialog_content = "Cozinhar uma refeição saborosa é muito fácil.",
  str_homestory_811701001_40_dialog_content = "Siga as instruções e deixe de lado todos os seus pensamentos aleatórios.",
  str_homestory_811701001_41_dialog_content = "Quanto mais você pensar, mais erros cometerá. Entendido?",
  str_homestory_811701001_42_dialog_content = "Sim! Desta vez consegui!",
  str_homestory_811701001_43_dialog_content = "Você está absolutamente correto, Gram!",
  str_homestory_811701001_44_dialog_content = "Para ser honesto, acho que você deveria escrever um livro sobre técnicas culinárias.",
  str_homestory_811701001_45_dialog_content = "Até os membros do Deserto Rediesel estão publicando livros... Você pode fazer isso!",
  str_homestory_811701001_46_dialog_content = "Posso apresentá-lo a uma imprensa em Umbraton.",
  str_homestory_811701001_47_dialog_content = "Agora não. Vou pensar sobre isso.",
  str_homestory_811701001_48_dialog_content = "Você vem buscar meus espetos quando estiverem prontos, garoto?",
  str_homestory_811701001_49_dialog_content = "Com certeza!",
  str_homestory_807701001_0_dialog_content = "Sua Majestade?",
  str_homestory_807701001_1_dialog_content = "Vossa Majestade...",
  str_homestory_807701001_2_dialog_content = "Olá, aquele que detém o futuro.",
  str_homestory_807701001_3_option_content = "Bem-vindo.",
  str_homestory_807701001_4_dialog_content = "É uma honra tê-lo aqui.",
  str_homestory_807701001_5_dialog_content = "PlayerName, não fique na cerimônia.",
  str_homestory_807701001_6_dialog_content = "Estive olhando para esta Torre Hyacinth.",
  str_homestory_807701001_7_option_content = "Eu estou atrapalhando?",
  str_homestory_807701001_8_dialog_content = "Você parece muito focado...",
  str_homestory_807701001_9_dialog_content = "Sim, estou olhando para esta Torre Hyacinth.",
  str_homestory_807701001_10_dialog_content = "A Torre Jacinto? O que dizer disso?",
  str_homestory_807701001_11_dialog_content = "Hmm... Esta Torre Jacinto significa muito para os celestitas.",
  str_homestory_807701001_12_dialog_content = "Sim! Esta é uma estrutura maciça.",
  str_homestory_807701001_13_dialog_content = "Você pode não ser capaz de vê-lo claramente daqui, mas na verdade é muito grande. Bastante espaçoso por dentro também!",
  str_homestory_807701001_14_dialog_content = "Ele pode produzir e reparar o Colosso.",
  str_homestory_807701001_15_dialog_content = "De acordo com as informações disponíveis, muitos celestitas foram treinados aqui.",
  str_homestory_807701001_16_dialog_content = "É praticamente um berço para navegadores.",
  str_homestory_807701001_17_dialog_content = "Um berço?",
  str_homestory_807701001_18_dialog_content = "Veja como é excepcionalmente brilhante e radiante sob o céu.",
  str_homestory_807701001_19_dialog_content = "É mais como... um totem espiritual de celestitas.",
  str_homestory_807701001_20_dialog_content = "PlayerName, você sabe como as pessoas se unem?",
  str_homestory_807701001_21_dialog_content = "Ah, você me pegou...",
  str_homestory_807701001_22_dialog_content = "Eu nunca pensei sobre isso. Desculpe.",
  str_homestory_807701001_23_dialog_content = "Não se preocupe. Esta pergunta não importava para você antes.",
  str_homestory_807701001_24_dialog_content = "Mas as coisas sao diferentes agora. Você precisa observar este continente de uma nova perspectiva.",
  str_homestory_807701001_25_dialog_content = "Todos aqui, altos ou baixos, fortes ou fracos, idosos ou jovens...",
  str_homestory_807701001_26_dialog_content = "Desde que compartilhem uma fé e uma crença comuns...",
  str_homestory_807701001_27_dialog_content = "Eles estão juntos.",
  str_homestory_807701001_28_dialog_content = "Não podemos conquistar a natureza sozinhos.",
  str_homestory_807701001_29_dialog_content = "Não temos garras ou presas afiadas. Nossas peles não são duras como rochas e nossos braços não podem nos levar para o céu.",
  str_homestory_807701001_30_dialog_content = "Mas se lutarmos juntos como um só, nosso poder está além da imaginação...",
  str_homestory_807701001_31_dialog_content = "Se você colocar assim...",
  str_homestory_807701001_32_dialog_content = "Vossa Majestade, você é o nosso totem espiritual.",
  str_homestory_807701001_33_dialog_content = "...",
  str_homestory_807701001_34_dialog_content = "Hum... Isso mesmo.",
  str_homestory_807701001_35_dialog_content = "A confiança, a admiração ou a busca de proteção as trazem até mim.",
  str_homestory_807701001_36_dialog_content = "Isso não é uma coisa ruim...",
  str_homestory_807701001_37_dialog_content = "Um grupo unido é sempre mais forte que um monte de areia solta.",
  str_homestory_807701001_38_dialog_content = "Tanto a Illumina quanto a Lumopolis estão mantendo essa unidade à sua maneira.",
  str_homestory_807701001_39_dialog_content = "Sim... Eu aprendi sobre isso.",
  str_homestory_807701001_40_dialog_content = "Você cresceu, o celestita que detém o futuro.",
  str_homestory_807701001_41_dialog_content = "Esta Torre Branca, o totem dos celestitas, é como você...",
  str_homestory_807701001_42_dialog_content = "Vocês dois têm o poder da unidade.",
  str_homestory_807701001_43_dialog_content = "Eu tenho o poder de unir as pessoas e defender o Eraveil...? Oh, Sua Majestade, posso fazer uma pergunta?",
  str_homestory_807701001_44_dialog_content = "Fale.",
  str_homestory_807701001_45_dialog_content = "Você viu o Eraveil de hoje no futuro que você previu?",
  str_homestory_807701001_46_dialog_content = "... É claro. E há mais.",
  str_homestory_804201001_0_dialog_content = "Barton!",
  str_homestory_804201001_1_dialog_content = "Aí, Navegador!",
  str_homestory_804201001_2_dialog_content = "Barton...",
  str_homestory_804201001_3_dialog_content = "Shh... Assista comigo.<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "...Hã?",
  str_homestory_804201001_5_dialog_content = "O que você está assistindo?",
  str_homestory_804201001_6_dialog_content = "Você tem alguns homens talentosos aqui! Navegador!",
  str_homestory_804201001_7_dialog_content = "Como eu perdi todos eles no Colossus?",
  str_homestory_804201001_8_dialog_content = "Hmm... Eu acho que eles não tinham espaço suficiente para abrir completamente suas asas no Colosso!",
  str_homestory_804201001_9_dialog_content = "... Homens talentosos?",
  str_homestory_804201001_10_dialog_content = "Você está recrutando para a Illumina?",
  str_homestory_804201001_11_dialog_content = "Recrutar? Não, eles não precisam aderir.",
  str_homestory_804201001_12_dialog_content = "PlayerName, você sabe qual legião eu comando?",
  str_homestory_804201001_13_option_content = "A 2ª Legião",
  str_homestory_804201001_14_dialog_content = "Exatamente!",
  str_homestory_804201001_15_option_content = "A 4ª Legião",
  str_homestory_804201001_16_dialog_content = "Seriamente? <sprite=emo_shengqi size=60 />Pirralho, minhas tropas são muito maiores que as daquela garota!",
  str_homestory_804201001_17_dialog_content = "Hum! WrathAs reservas de elite de não podem resistir a um único golpe nosso!",
  str_homestory_804201001_18_dialog_content = "Estou no comando da maior 2ª Legião. Lembre-se disso.",
  str_homestory_804201001_19_dialog_content = "Sim...",
  str_homestory_804201001_20_dialog_content = "Você conhece minha responsabilidade especialmente designada pelo Grande Marechal!?",
  str_homestory_804201001_21_option_content = "Suporte rápido?",
  str_homestory_804201001_22_dialog_content = "... Isso é para Hiiro e Vice.",
  str_homestory_804201001_23_dialog_content = "Ei! Você esqueceu seu cérebro em casa?",
  str_homestory_804201001_24_dialog_content = "Eu lidero as tropas da guarnição!",
  str_homestory_804201001_25_dialog_content = "... Agora você vê?",
  str_homestory_804201001_26_dialog_content = "Sim...",
  str_homestory_804201001_27_option_content = "Defesa e segurança.",
  str_homestory_804201001_28_dialog_content = "Correto! Você tem aprendido!",
  str_homestory_804201001_29_dialog_content = "Com esse conhecimento, você deve entender o que estou fazendo aqui.",
  str_homestory_804201001_30_dialog_content = "Você reuniu tantos talentosos com habilidades únicas aqui...",
  str_homestory_804201001_31_dialog_content = "De vez em quando uma briga surgia entre eles...",
  str_homestory_804201001_32_dialog_content = "Ataques furtivos! Armas escondidas! Ataques de Taijutsu!",
  str_homestory_804201001_33_dialog_content = "Tsk... Esplêndido.",
  str_homestory_804201001_34_dialog_content = "Eu não preciso deles para se juntar à Illumina. Você entendeu?",
  str_homestory_804201001_35_dialog_content = "Observar seu ataque e defesa é suficiente.",
  str_homestory_804201001_36_dialog_content = "Estou aprendendo técnicas diferentes de pessoas diferentes. Depois, passarei tudo isso para meus soldados!",
  str_homestory_804201001_37_dialog_content = "Esta é uma lição valiosa!",
  str_homestory_804201001_38_dialog_content = "Entendo...",
  str_homestory_804201001_39_dialog_content = "Aguentar. Por que eles estão lutando?",
  str_homestory_804201001_40_dialog_content = "Não é bastante comum os Aurorianos não gostarem uns dos outros?",
  str_homestory_804201001_41_dialog_content = "Achei que você já estivesse acostumado com isso no Colossus.",
  str_homestory_804201001_42_dialog_content = "Mas...",
  str_homestory_804201001_43_dialog_content = "Apenas finja que eles estão treinando um com o outro!",
  str_homestory_804201001_44_dialog_content = "Agora preciso trabalhar no movimento que vi ontem...",
  str_homestory_804201001_45_dialog_content = "Como ele levou aquele chute dela?",
  str_homestory_804201001_46_dialog_content = "Hmm... Uma vez que eu dominar isso, ouse Wrath para me provocar de novo!",
  str_homestory_804201001_47_dialog_content = "Ei! Huh!<sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "... Tudo bem. Boa sorte, Barton...",
  str_homestory_807601001_0_dialog_content = "Kleken...",
  str_homestory_807601001_1_dialog_content = "Ah! O herói viajante finalmente desembarcou.",
  str_homestory_807601001_2_dialog_content = "Oi, Kleken.",
  str_homestory_807601001_3_dialog_content = "Você realmente gosta dessa Pedra da Cachoeira? Muitas vezes vejo você aqui vagando por aí...",
  str_homestory_807601001_4_dialog_content = "Quão precioso é este fluxo!",
  str_homestory_807601001_5_dialog_content = "Todos esses rios e nascentes estão me levando às lágrimas<sprite=emo_hanshui size=60 />.",
  str_homestory_807601001_6_dialog_content = "Você está sendo sarcástico?",
  str_homestory_807601001_7_dialog_content = "Tudo o que temos aqui são alguns riachos ornamentais...",
  str_homestory_807601001_8_dialog_content = "Não é nada comparado ao \"oceano\" e \"afogamento\" que você gosta de dizer.",
  str_homestory_807601001_9_dialog_content = "Eu quero agradecer-te.",
  str_homestory_807601001_10_dialog_content = "... Para que?",
  str_homestory_807601001_11_dialog_content = "Em breve você testemunhará minha Técnica do Olhar alcançando a perfeição.",
  str_homestory_807601001_12_dialog_content = "Poderei dizer com o que sua cabecinha anda ocupada ultimamente...",
  str_homestory_807601001_13_dialog_content = "Um olhar em seus lindos olhos é o suficiente para encontrar a resposta.",
  str_homestory_807601001_14_dialog_content = "Obrigado por ser minha primeira testemunha.",
  str_homestory_807601001_15_dialog_content = "Err...",
  str_homestory_807601001_16_option_content = "Técnica do olhar?",
  str_homestory_807601001_17_dialog_content = "Você está curioso, pequenino...",
  str_homestory_807601001_18_option_content = "Posso recusar?",
  str_homestory_807601001_19_dialog_content = "Claro.",
  str_homestory_807601001_20_dialog_content = "Mas essas pequenas criaturas rápidas atrás de mim não vão deixar você.",
  str_homestory_807601001_21_dialog_content = "Eles adoram ver você dormir, PlayerName...",
  str_homestory_807601001_22_dialog_content = "(... Que diabos?)",
  str_homestory_807601001_23_dialog_content = "Tudo bem... Não demore muito. Tenho coisas para fazer.",
  str_homestory_807601001_24_dialog_content = "Então, o que é essa Técnica do Olhar?",
  str_homestory_807601001_25_dialog_content = "Deixe-me explicar, guerreiro.",
  str_homestory_807601001_26_dialog_content = "Acredito que você visitou Umbraton recentemente...",
  str_homestory_807601001_27_dialog_content = "Devagar, você estava andando pela rua quando viu uma menininha lamentável.",
  str_homestory_807601001_28_dialog_content = "Ela te pediu ajuda para saber os preços daqueles restaurantes naquela rua...",
  str_homestory_807601001_29_dialog_content = "Ela tinha muito pouco para apenas andar em um restaurante aleatório.",
  str_homestory_807601001_30_dialog_content = "Ela não podia suportar a ideia de receber olhares de reprovação dos garçons se ela pedisse apenas uma fatia de pão...",
  str_homestory_807601001_31_dialog_content = "Um restaurante após o outro você foi com ela e descobriu os preços para ela.",
  str_homestory_807601001_32_dialog_content = "Toda vez, ela balançou a cabeça.",
  str_homestory_807601001_33_dialog_content = "No final, você decidiu comprar uma boa refeição para ela...",
  str_homestory_807601001_34_dialog_content = "Após a refeição, ela saiu depois de um rápido agradecimento, deixando dinheiro na mesa o suficiente para cobrir a conta.",
  str_homestory_807601001_35_dialog_content = "... Como você sabe?",
  str_homestory_807601001_36_dialog_content = "(Como essa Técnica do Olhar pode ser tão mágica?)",
  str_homestory_807601001_37_dialog_content = "... De qualquer forma, foi difícil para mim processar.",
  str_homestory_807601001_38_dialog_content = "Se ela tinha o dinheiro o tempo todo, por que ela simplesmente não entrou em um restaurante e saboreou a comida?",
  str_homestory_807601001_39_dialog_content = "Como você disse... ela conferiu o preço de cada prato em todos os restaurantes de Umbraton!",
  str_homestory_807601001_40_dialog_content = "Haha... Hahaha<sprite=emo_guilian size=60 />.",
  str_homestory_807601001_41_dialog_content = "Porque eu pedi para ela fazer isso.",
  str_homestory_807601001_42_dialog_content = "Foi uma tarefa atribuída pelo Senhor Istvan...",
  str_homestory_807601001_43_dialog_content = "Para estudar os preços dos alimentos em Umbraton.",
  str_homestory_807601001_44_dialog_content = "Eu tenho ajudado essa garota. Dar a ela esta oportunidade de me fazer um pequeno favor poderia fazê-la se sentir útil...",
  str_homestory_807601001_45_dialog_content = "De qualquer forma, o celestita não tinha nada melhor para fazer então. Então por que não ir em frente?",
  str_homestory_807601001_46_dialog_content = "Andar é muito exigente fisicamente para mim nos dias de hoje.",
  str_homestory_807601001_47_dialog_content = "...",
  str_homestory_807601001_48_dialog_content = "Você vê. Esta é a verdade da Técnica do Olhar, PlayerName.",
  str_homestory_807601001_49_dialog_content = "Você parece desapontado... Que interessante!",
  str_homestory_804601001_0_dialog_content = "É ele.",
  str_homestory_804601001_1_dialog_content = "Navigator vem e Navigator vai ♪",
  str_homestory_804601001_2_dialog_content = "Navigator sorri para Pierre, mas Pierre só quer causar problemas.",
  str_homestory_804601001_3_dialog_content = "Você está comprando?",
  str_homestory_804601001_4_dialog_content = "Compras. Navigator pensa que estou comprando<sprite=emo_yinfu size=60 />",
  str_homestory_804601001_5_dialog_content = "Dian diria não e Kara diria: \"Isso mesmo!\" Niel diria, \"mais ou menos...\", mas Pierre apenas ria.<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "Então, o que você acha que estou tentando dizer?",
  str_homestory_804601001_7_dialog_content = "...%^&",
  str_homestory_804601001_8_dialog_content = "Esqueça. Não estou com disposição para um enigma.",
  str_homestory_804601001_9_dialog_content = "Queria perguntar como a vida está te tratando aqui...",
  str_homestory_804601001_10_dialog_content = "É um alívio ver você inteligente e travesso como sempre.",
  str_homestory_804601001_11_dialog_content = "O navegador se preocupa Keating. Pierre é homenageado ♪",
  str_homestory_804601001_12_dialog_content = "Navegador, você não está curioso sobre quem eu conheci recentemente?",
  str_homestory_804601001_13_dialog_content = "... Estou com um mau pressentimento...<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "Então, quem você conheceu?",
  str_homestory_804601001_15_dialog_content = "Seus pequeninos devem ter mais cuidado aqui. Não é bom zombar dos outros...",
  str_homestory_804601001_16_dialog_content = "Você não está em Lumopolis. Alguns Aurorianos são mal-humorados!",
  str_homestory_804601001_17_dialog_content = "Há também aurorianos muito sensíveis. Suas palavras maldosas provavelmente os levariam às lágrimas...",
  str_homestory_804601001_18_dialog_content = "Navigator está preocupado conosco. Navigator se preocupa com seus amigos ♪",
  str_homestory_804601001_19_dialog_content = "Conhecemos um cara de conserto de cauda longa e ele nos fez um braço robótico para pegar galinhas.",
  str_homestory_804601001_20_dialog_content = "Conhecemos uma ave gordinha e ela nos presenteou com muitas bolas de neve.",
  str_homestory_804601001_21_dialog_content = "Conhecemos um cachorro de terno, chateado porque ninguém estava interessado em suas pinturas falsas.",
  str_homestory_804601001_22_dialog_content = "Pierre encontrou um navegador baixo e atarracado, parado na minha frente preocupado com seus amigos.",
  str_homestory_804601001_23_dialog_content = "... Ufa... Melhor do que eu pensava.",
  str_homestory_804601001_24_dialog_content = "Para ser honesto, estas são possivelmente as palavras mais gentis que você já disse.",
  str_homestory_804601001_25_dialog_content = "As pessoas se tornam gentis por uma razão.",
  str_homestory_804601001_26_dialog_content = "Na estante, há livros que Dian gosta.",
  str_homestory_804601001_27_dialog_content = "Na sala, há um pano de lente que Niel precisa.",
  str_homestory_804601001_28_dialog_content = "Na sala de jantar, há um cabideiro para Kara.",
  str_homestory_804601001_29_dialog_content = "Na grama, os petiscos favoritos de Gege e Pierre♪",
  str_homestory_804601001_30_dialog_content = "O atencioso Navegador é nosso amigo do peito.",
  str_homestory_804601001_31_dialog_content = "O Navigator é a estrela de amanhã.",
  str_homestory_804601001_32_dialog_content = "A estrela que vai crescer mais ♪",
  str_homestory_804601001_33_dialog_content = "... Foi tudo bem até a última linha.",
  str_homestory_804601001_34_dialog_content = "Navegador, qual é o seu plano?",
  str_homestory_804601001_35_option_content = "Volte para descansar",
  str_homestory_804601001_36_dialog_content = "Eu vou tirar um cochilo.",
  str_homestory_804601001_37_option_content = "Andar por aí",
  str_homestory_804601001_38_dialog_content = "Vou verificar o que outras pessoas estão fazendo.",
  str_homestory_804601001_39_dialog_content = "Entendi. Pierre entendeu.",
  str_homestory_804601001_40_dialog_content = "Embora Pierre realmente não se importe. Aqui está uma linha para o mestre.",
  str_homestory_804601001_41_dialog_content = "Gege está fertilizando perto do jardim. Fertilizando ♪",
  str_homestory_804601001_42_dialog_content = "?!",
  str_homestory_804601001_43_dialog_content = "Fertilizando?",
  str_homestory_804601001_44_dialog_content = "Pierre é muito gentil. Confira quando puder ♪",
  str_homestory_804601001_45_dialog_content = "... Obrigado por sua preocupação!",
  str_homestory_805701001_0_dialog_content = "Isto é... Pelo de gato?",
  str_homestory_805701001_1_dialog_content = "Bocejar-",
  str_homestory_805701001_2_dialog_content = "Hum? Philyshy?",
  str_homestory_805701001_3_dialog_content = "Ahn... ah...<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "... Philyshy?",
  str_homestory_805701001_5_dialog_content = "Ufa... Miau!",
  str_homestory_805701001_6_dialog_content = "Que diabos! Isso é PlayerName, Miau.",
  str_homestory_805701001_7_dialog_content = "Você não vê que eu estou dormindo, miau?",
  str_homestory_805701001_8_dialog_content = "Volte depois da minha soneca, miau.",
  str_homestory_805701001_9_dialog_content = "Eu vou ter um doce sonho neste palheiro confortável, miau...",
  str_homestory_805701001_10_dialog_content = "Espere, Philyshy! Eu tenho algo para te dizer!",
  str_homestory_805701001_11_dialog_content = "Huh... Huh... Miau!",
  str_homestory_805701001_12_dialog_content = "Hmm... O que você deve me dizer, miau?",
  str_homestory_805701001_13_dialog_content = "É melhor ser muito importante, miau!",
  str_homestory_805701001_14_dialog_content = "Umm... Alguns Aurorianos vieram até mim...",
  str_homestory_805701001_15_dialog_content = "Philyshy, Você esteve...",
  str_homestory_805701001_16_option_content = "Sentindo mal?",
  str_homestory_805701001_17_dialog_content = "Alguma coceira?",
  str_homestory_805701001_18_dialog_content = "Perda de apetite?",
  str_homestory_805701001_19_dialog_content = "Do que você está falando, miau?",
  str_homestory_805701001_20_dialog_content = "Philyshy não entende.",
  str_homestory_805701001_21_option_content = "Temporada de derramamento?",
  str_homestory_805701001_22_dialog_content = "Derramando o que... miau?",
  str_homestory_805701001_23_dialog_content = "O que foi?",
  str_homestory_805701001_24_dialog_content = "(Que atuação ruim!)",
  str_homestory_805701001_25_dialog_content = "De qualquer forma, Philyshy não sente nada!",
  str_homestory_805701001_26_dialog_content = "(Acariciando Philyshycauda)",
  str_homestory_805701001_27_dialog_content = "Miau!",
  str_homestory_805701001_28_dialog_content = "PlayerName, como você pode tocar o rabo de uma dama?",
  str_homestory_805701001_29_dialog_content = "Foi uma sensação agradável. Não, miau!",
  str_homestory_805701001_30_dialog_content = "Philyshy, tanto cabelo saiu quando você balançou!",
  str_homestory_805701001_31_dialog_content = "I-isso não é verdade...!",
  str_homestory_805701001_32_dialog_content = "Booo... Miau. Eu não posso pará-lo!",
  str_homestory_805701001_33_dialog_content = "É a época do derramamento... Não, miau!",
  str_homestory_805701001_34_dialog_content = "Meu cabelo está absorvendo sol suficiente para uma evolução, miau!",
  str_homestory_805701001_35_dialog_content = "Uma vez feito... eu me tornarei Super Philyshy, Miau!",
  str_homestory_805701001_36_dialog_content = "Mas... Se o seu cabelo voa para todo o lado...",
  str_homestory_805701001_37_dialog_content = "Alguns aurorianos podem sofrer de alergias.",
  str_homestory_805701001_38_dialog_content = "Hmm... O que devo fazer então?",
  str_homestory_805701001_39_dialog_content = "Não é Philyshyescolha de.<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "Você está certo... Deixe-me pensar...",
  str_homestory_805701001_41_dialog_content = "Que tal... Deixe-me cuidar de você!",
  str_homestory_805701001_42_dialog_content = "Seu cabelo ficará mais macio e sedoso. Chega de voar.",
  str_homestory_805701001_43_dialog_content = "Istvan me ensinou isso.",
  str_homestory_805701001_44_dialog_content = "Ok... Só porque você preparou este palheiro confortável em Eraveil.",
  str_homestory_805701001_45_dialog_content = "Pedido de tosa atendido, miau!",
  str_homestory_803601001_0_dialog_content = "Hydrad?",
  str_homestory_803601001_1_dialog_content = "O que está fazendo?",
  str_homestory_803601001_2_dialog_content = "Você não pode ver?",
  str_homestory_803601001_3_dialog_content = "estou de pé.",
  str_homestory_803601001_4_dialog_content = "... Que eu saiba.",
  str_homestory_803601001_5_dialog_content = "...",
  str_homestory_803601001_6_dialog_content = "...",
  str_homestory_803601001_7_dialog_content = "Ei.",
  str_homestory_803601001_8_dialog_content = "Sim?",
  str_homestory_803601001_9_dialog_content = "Eu me machuquei ontem.",
  str_homestory_803601001_10_dialog_content = "?!",
  str_homestory_803601001_11_option_content = "Você está bem?",
  str_homestory_803601001_12_dialog_content = "Ainda chutando.",
  str_homestory_803601001_13_option_content = "Onde você foi?",
  str_homestory_803601001_14_dialog_content = "Eu sei o que te preocupa.",
  str_homestory_803601001_15_dialog_content = "Não aconteceu aqui.",
  str_homestory_803601001_16_dialog_content = "Eu... só estou preocupado com sua saúde.",
  str_homestory_803601001_17_dialog_content = "Como você está se sentindo? Melhor?",
  str_homestory_803601001_18_dialog_content = "Mais ou menos.",
  str_homestory_803601001_19_dialog_content = "Minha rápida recuperação é tudo graças a Shadow Wolves.",
  str_homestory_803601001_20_dialog_content = "Multar. Você poderia me dizer o que aconteceu?",
  str_homestory_803601001_21_dialog_content = "Não me diga que você gosta disso.",
  str_homestory_803601001_22_dialog_content = "Eu estava lutando por algo.",
  str_homestory_803601001_23_dialog_content = "No mercado negro em Umbraton.",
  str_homestory_803601001_24_dialog_content = "O que era tão importante?",
  str_homestory_803601001_25_dialog_content = "Alegadamente um produto de civilização antiga.",
  str_homestory_803601001_26_dialog_content = "Alegadamente?",
  str_homestory_803601001_27_dialog_content = "Você não tem certeza sobre isso?",
  str_homestory_803601001_28_dialog_content = "Você nunca saberia até tentar.",
  str_homestory_803601001_29_dialog_content = "... O que foi isso?",
  str_homestory_803601001_30_dialog_content = "Um tipo de console que pode deixar a ilusão ou a magia das Sombras se tornarem realidade.",
  str_homestory_803601001_31_dialog_content = "Err... Mas seus Shadow Wolves sempre estiveram ao seu lado.",
  str_homestory_803601001_32_dialog_content = "Zumbir. Mas eu quero acariciar seus pelos macios todos os dias.",
  str_homestory_803601001_33_dialog_content = "A pele real cresce a partir de sua pele, não os pêlos dispersos que caem durante o período de muda.",
  str_homestory_803601001_34_dialog_content = "Entendo...",
  str_homestory_803601001_35_dialog_content = "(Hydrad... provavelmente é bastante solitário?)",
  str_homestory_803601001_36_dialog_content = "Acho que é uma farsa.",
  str_homestory_803601001_37_dialog_content = "O dispositivo?",
  str_homestory_803601001_38_dialog_content = "Sim.",
  str_homestory_803601001_39_dialog_content = "Eu nunca ouvi falar de algo assim.",
  str_homestory_803601001_40_dialog_content = "(Será que ele se sentiria melhor se fosse uma farsa?)",
  str_homestory_803601001_41_dialog_content = "Concordo com você.",
  str_homestory_803601001_42_dialog_content = "Algo assim seria uma herança inestimável...",
  str_homestory_803601001_43_dialog_content = "Não vai acabar no mercado negro.",
  str_homestory_803601001_44_dialog_content = "... Isso é verdade.",
  str_homestory_803601001_45_dialog_content = "Já que você também pensa assim.",
  str_homestory_803601001_46_dialog_content = "Eu tenho que ir.",
  str_homestory_803601001_47_dialog_content = "Até mais!",
  str_homestory_803601001_48_dialog_content = "(Se fosse real, o que eu faria com isso?)",
  str_homestory_811401001_0_dialog_content = "Este cavalo...",
  str_homestory_811401001_1_dialog_content = "Ah, caro Navegador.",
  str_homestory_811401001_2_dialog_content = "Anna está no seu caminho?",
  str_homestory_811401001_3_dialog_content = "Ou você está aqui para me ver?",
  str_homestory_811401001_4_dialog_content = "Desculpe por ficar aqui por tanto tempo. Essas flores são tão perfumadas...",
  str_homestory_811401001_5_dialog_content = "Não se preocupe com isso. Aproveite as flores.",
  str_homestory_811401001_6_dialog_content = "Isso foi rápido. Essas flores...",
  str_homestory_811401001_7_dialog_content = "Muito mais flores do que eu imaginava.",
  str_homestory_811401001_8_dialog_content = "Hum? O que foi isso, Navegador?",
  str_homestory_811401001_9_dialog_content = "Ah... eu estava murmurando sobre essas flores.",
  str_homestory_811401001_10_dialog_content = "Acabei de fazer o pedido pelo Courier Union<sprite=emo_gezitou size=60 /> alguns dias atrás.",
  str_homestory_811401001_11_dialog_content = "Algumas pessoas sugeriram que deveríamos adicionar algumas flores a todas as rochas e árvores.",
  str_homestory_811401001_12_dialog_content = "Oh? Eu pensei na mesma coisa!",
  str_homestory_811401001_13_dialog_content = "Disse a Anna outro dia que precisávamos de mais flores aqui.",
  str_homestory_811401001_14_dialog_content = "Sim. É por isso que entrei em contato com o Sindicato dos Correios.",
  str_homestory_811401001_15_dialog_content = "No entanto, é um pouco mais do que eu esperava...",
  str_homestory_811401001_16_dialog_content = "Eu também comprei alguns depois da minha última missão.",
  str_homestory_811401001_17_dialog_content = "Isso explica tudo...",
  str_homestory_811401001_18_dialog_content = "Navigator, você tem um bom lugar.",
  str_homestory_811401001_19_dialog_content = "Dei uma olhada na loja e encontrei meu gin favorito...",
  str_homestory_811401001_20_dialog_content = "Também aquelas ervas, xaropes e especiarias essenciais para um belo coquetel.",
  str_homestory_811401001_21_dialog_content = "Hahah. Estou bem surpreso!",
  str_homestory_811401001_22_dialog_content = "Você ficou mais pensativo.",
  str_homestory_811401001_23_dialog_content = "Considerado...",
  str_homestory_811401001_24_dialog_content = "Que experiências tornaram aquele garoto ignorante tão doce e considerável?",
  str_homestory_811401001_25_dialog_content = "Genevieve ainda está falando sobre estocar gin na loja?",
  str_homestory_811401001_26_dialog_content = "Não apenas isso. Você também encomendou flores para as senhoras.",
  str_homestory_811401001_27_dialog_content = "Bem, na verdade...",
  str_homestory_811401001_28_dialog_content = "A pessoa que me disse para estocar gin e pedir flores é...",
  str_homestory_811401001_29_dialog_content = "... Smokey.",
  str_homestory_811401001_30_dialog_content = "... Oh?",
  str_homestory_811401001_31_dialog_content = "Ela tinha muito mais pedidos, então eu não acho que ela fez isso por você...",
  str_homestory_811401001_32_dialog_content = "Agora que você mencionou... Naquele dia, quando eu estava conversando com Anna, senti um ar quente ao meu redor.",
  str_homestory_811401001_33_dialog_content = "Eu nem pensei nela, considerando o grande número de pessoas aqui que usam fogo<sprite=emo_nuhuo size=60 />.",
  str_homestory_811401001_34_dialog_content = "... Esse cara...",
  str_homestory_811401001_35_dialog_content = "Ela provavelmente não quer que eu descubra sobre isso.",
  str_homestory_811401001_36_dialog_content = "Hum... eu acho...",
  str_homestory_811401001_37_option_content = "Ela espera que sim.",
  str_homestory_811401001_38_dialog_content = "Caso contrário, ela poderia facilmente conseguir um pouco de gim e flores...",
  str_homestory_811401001_39_dialog_content = "Quero dizer... Ela realmente não precisava que eu pegasse isso.",
  str_homestory_811401001_40_option_content = "Ela espera que não.",
  str_homestory_811401001_41_dialog_content = "Na verdade, perguntei se o gin era para você. E ela negou...",
  str_homestory_811401001_42_dialog_content = "É mesmo?",
  str_homestory_811401001_43_dialog_content = "Isso é um pouco estranho.",
  str_homestory_811401001_44_dialog_content = "De qualquer forma, Navegador, por favor, mantenha a conversa de hoje entre nós.",
  str_homestory_811401001_45_dialog_content = "Embora eu tenha aprendido sobre sua bondade, ninguém quer que isso seja exposto em seu rosto...",
  str_homestory_811401001_46_dialog_content = "Para esconder seu embaraço, ela atirava fogo ou fazia uma cena.",
  str_homestory_811401001_47_dialog_content = "Entendi...",
  str_homestory_811401001_48_dialog_content = "Você a conhece bem!",
  str_homestory_811401001_49_dialog_content = "Você acha? Eu não sei sobre isso.",
  str_homestory_801801001_0_dialog_content = "Esta aura selvagem...",
  str_homestory_801801001_1_dialog_content = "Não se importe!",
  str_homestory_801801001_2_dialog_content = "E... sem perder o fôlego!",
  str_homestory_801801001_3_dialog_content = "Muitos tolos neste mundo! Chama! Chamuscar!<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "(Ela está completamente fora de si!)",
  str_homestory_801801001_5_dialog_content = "Ei, Regina!",
  str_homestory_801801001_6_dialog_content = "Navigator, o que você acha da minha nova demo?",
  str_homestory_801801001_7_dialog_content = "Achei que você estava xingando...",
  str_homestory_801801001_8_dialog_content = "Você ouviu isso?",
  str_homestory_801801001_9_dialog_content = "Sim!",
  str_homestory_801801001_10_dialog_content = "Oh... Eu tentei ser implícito!",
  str_homestory_801801001_11_dialog_content = "Mas você ainda pode ouvi-lo?",
  str_homestory_801801001_12_dialog_content = "Você aprendeu com as crianças más!",
  str_homestory_801801001_13_dialog_content = "?",
  str_homestory_801801001_14_dialog_content = "Aham... Nunca...",
  str_homestory_801801001_15_dialog_content = "Qualquer que seja. Quem se importa!",
  str_homestory_801801001_16_dialog_content = "Minha nova música ainda não está completa. Qualquer pensamento? Bata em mim!",
  str_homestory_801801001_17_dialog_content = "Tema? Letra da música? Melodia?",
  str_homestory_801801001_18_dialog_content = "Eu sou péssimo em música.",
  str_homestory_801801001_19_dialog_content = "E daí? Não odeio ninguém mais do que aqueles velhos idiotas que insistem em estabelecer limites para a música!",
  str_homestory_801801001_20_dialog_content = "Apenas diga alguma coisa, qualquer coisa!",
  str_homestory_801801001_21_dialog_content = "...",
  str_homestory_801801001_22_option_content = "Barbara é o melhor",
  str_homestory_801801001_23_dialog_content = "Huh? O que diabos você disse?",
  str_homestory_801801001_24_dialog_content = "Eu entendi. Sarcasmo.",
  str_homestory_801801001_25_option_content = "Metal sempre!",
  str_homestory_801801001_26_dialog_content = "Exatamente!",
  str_homestory_801801001_27_dialog_content = "vou anotar!",
  str_homestory_801801001_28_dialog_content = "Ah! Uma nova música composta com a ajuda do Caelestite será demais!",
  str_homestory_801801001_29_dialog_content = "Ah. Você está competindo com Barbara em todos os campos, bem como com seus pares de metal?",
  str_homestory_801801001_30_dialog_content = "Vamos. Qual músico genuinamente respeita o outro?<sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "Principalmente aqueles do meu gênero. A maioria deles são ignorantes e falsos!",
  str_homestory_801801001_32_dialog_content = "Sentindo-se o último que entende de rock e tem uma antiguidade considerável... Na verdade, eles provavelmente nunca escrevem uma música sozinhos!",
  str_homestory_801801001_33_dialog_content = "Hum! Se depender de mim, eu colocaria fogo em todos eles...",
  str_homestory_801801001_34_dialog_content = "Falar com eles sobre metal é pior do que ouvir Barbaranovo single de!",
  str_homestory_801801001_35_dialog_content = "... Eu pensei que você não gostasse muito Barbara?",
  str_homestory_801801001_36_dialog_content = "Dois segundos.",
  str_homestory_801801001_37_dialog_content = "?",
  str_homestory_801801001_38_dialog_content = "Eu aguento Barbaranova música de 2 segundos.",
  str_homestory_801801001_39_dialog_content = "Ahh!",
  str_homestory_809201001_0_dialog_content = "Aquilo é...",
  str_homestory_809201001_1_dialog_content = "Ei, Pact.",
  str_homestory_809201001_2_dialog_content = "Quem mais poderia ser?<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "Aham. Este balanço é bastante popular...",
  str_homestory_809201001_4_dialog_content = "Então... Você gosta de brincar no balanço?",
  str_homestory_809201001_5_dialog_content = "Sua pergunta não está muito bem estruturada.",
  str_homestory_809201001_6_dialog_content = "Primeiro, qual é a sua definição de \"como\"?",
  str_homestory_809201001_7_option_content = "Definir",
  str_homestory_809201001_8_dialog_content = "Eu acho que se você gosta de algo, você gostaria de fazê-lo com frequência.",
  str_homestory_809201001_9_dialog_content = "Então, qual é a medida de \"frequentemente\"? Isso não está claro.",
  str_homestory_809201001_10_dialog_content = "Como constantemente?",
  str_homestory_809201001_11_dialog_content = "Ou só quando tenho tempo?",
  str_homestory_809201001_12_dialog_content = "Ou talvez eu não pense nisso com frequência, mas quando o fizer, irei em frente e agirei?",
  str_homestory_809201001_13_dialog_content = "(Querido céu! Estou apenas tentando ter uma conversa casual com Pact...)",
  str_homestory_809201001_14_dialog_content = "Eu acho que a medida de \"frequentemente\" é fazer isso quando você tiver tempo.",
  str_homestory_809201001_15_option_content = "Recusar-se a definir",
  str_homestory_809201001_16_dialog_content = "Quem precisa de uma definição de \"like\"?",
  str_homestory_809201001_17_dialog_content = "Quando tenho tempo, gosto de passear.",
  str_homestory_809201001_18_dialog_content = "Algo que eu quero fazer quando tiver tempo?",
  str_homestory_809201001_19_dialog_content = "Entendi.",
  str_homestory_809201001_20_dialog_content = "Neste caso, eu gosto de sentar neste balanço.",
  str_homestory_809201001_21_dialog_content = "Este tipo de cadeira suspensa oferece uma sensação muito sutil de gravidade zero...",
  str_homestory_809201001_22_dialog_content = "Isso me dá uma alegria que não pode ser colocada em palavras.",
  str_homestory_809201001_23_dialog_content = "Sério? Que ótimo!",
  str_homestory_809201001_24_dialog_content = "No começo, eu não tinha certeza se um balanço era uma boa ideia.",
  str_homestory_809201001_25_dialog_content = "Estou tão feliz que você está gostando!",
  str_homestory_809201001_26_dialog_content = "No entanto, também há problemas.",
  str_homestory_809201001_27_dialog_content = "Hunting Stone tem dificuldade em encontrar a quantidade certa de força para me empurrar.",
  str_homestory_809201001_28_dialog_content = "Na verdade, eu caí uma vez!",
  str_homestory_809201001_29_dialog_content = "Hahaha...",
  str_homestory_809201001_30_dialog_content = "Você acabou de rir de mim?<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "Negar",
  str_homestory_809201001_32_dialog_content = "Nunca...",
  str_homestory_809201001_33_dialog_content = "Tem certeza? Por que os cantos dos seus lábios subiram então?",
  str_homestory_809201001_34_option_content = "Admitem",
  str_homestory_809201001_35_dialog_content = "Sinto muito...",
  str_homestory_809201001_36_dialog_content = "Eu quase podia ver isso na minha cabeça...",
  str_homestory_809201001_37_dialog_content = "Ahem... Você se machucou?",
  str_homestory_809201001_38_dialog_content = "Você acha que eu sou tão vulnerável?",
  str_homestory_809201001_39_dialog_content = "Isso é um alívio! Já que você ama tanto o balanço...",
  str_homestory_809201001_40_dialog_content = "Posso te dar um empurrão?",
  str_homestory_809201001_41_dialog_content = "Hum? Você se importa?",
  str_homestory_809201001_42_dialog_content = "Bem, se você não se importa. Minha força não é nada comparada à de Hunting Stone.",
  str_homestory_809201001_43_dialog_content = "Isso depende de como você define \"mente\".",
  str_homestory_809201001_44_dialog_content = "Err...",
  str_homestory_809201001_45_dialog_content = "Vamos. É hora do balanço!",
  str_homestory_809201001_46_dialog_content = "Ok... Já que você é tão sincero... Vamos.",
  str_homestory_809901001_0_dialog_content = "Areia...",
  str_homestory_809901001_1_dialog_content = "Ah, PlayerName...",
  str_homestory_809901001_2_dialog_content = "Obrigado por me convidar aqui. Estou muito feliz!",
  str_homestory_809901001_3_dialog_content = "Não há de quê!",
  str_homestory_809901001_4_dialog_content = "Eu acho que você ainda não está familiarizado com esta área. Você precisa de um guia turístico?",
  str_homestory_809901001_5_dialog_content = "PlayerName, você realmente tem tempo para isso?",
  str_homestory_809901001_6_dialog_content = "É claro. Ninguém conhece este lugar melhor do que eu.",
  str_homestory_809901001_7_dialog_content = "Mas...",
  str_homestory_809901001_8_dialog_content = "Eu... prefiro voltar para o meu quarto.",
  str_homestory_809901001_9_dialog_content = "Huh? Areia, você não gosta da paisagem lá fora?",
  str_homestory_809901001_10_dialog_content = "Muito pelo contrário. Adoro a paisagem daqui!",
  str_homestory_809901001_11_dialog_content = "Eu nunca estive em um lugar isolado e confortável como este antes.",
  str_homestory_809901001_12_option_content = "Mostrar gratidão",
  str_homestory_809901001_13_dialog_content = "Fico muito feliz que goste daqui!",
  str_homestory_809901001_14_dialog_content = "Temos paz e reclusão, bem como hilaridade e júbilo aqui.",
  str_homestory_809901001_15_dialog_content = "Eu vou te mostrar ao redor.",
  str_homestory_809901001_16_dialog_content = "Mas estou com medo...",
  str_homestory_809901001_17_option_content = "Faça um inquérito",
  str_homestory_809901001_18_dialog_content = "Qual é a pressa de voltar para o quarto?",
  str_homestory_809901001_19_dialog_content = "Eu estou assustado...",
  str_homestory_809901001_20_dialog_content = "E se a maldição e os espinhos escuros em mim arruinassem a beleza?",
  str_homestory_809901001_21_dialog_content = "Isso causaria tantos problemas para PlayerName...",
  str_homestory_809901001_22_dialog_content = "Areia, isso é muito atencioso da sua parte.",
  str_homestory_809901001_23_dialog_content = "Mas eu não acho que você iria estragar a beleza aqui.",
  str_homestory_809901001_24_dialog_content = "Hum?",
  str_homestory_809901001_25_dialog_content = "Já nos conhecemos há algum tempo. Sua maldição não me afeta em nada.",
  str_homestory_809901001_26_dialog_content = "Mas meus espinhos escuros...",
  str_homestory_809901001_27_dialog_content = "Eles não são seus amigos que protegem seu corpo da maldição?",
  str_homestory_809901001_28_dialog_content = "Sim...",
  str_homestory_809901001_29_dialog_content = "AreiaOs amigos de são meus amigos!",
  str_homestory_809901001_30_dialog_content = "Além do mais...",
  str_homestory_809901001_31_dialog_content = "Eu lembro que você tem procurado maneiras de remover a maldição.",
  str_homestory_809901001_32_dialog_content = "Dê uma volta e você pode encontrar algo.",
  str_homestory_809901001_33_dialog_content = "Huh... eu acho muito difícil de acreditar, mesmo que tenha saído de PlayerName.",
  str_homestory_809901001_34_dialog_content = "Tantos anos se passaram. Qual é a chance de encontrar uma solução aqui?",
  str_homestory_809901001_35_dialog_content = "Acho que você não sai muito além do trabalho?",
  str_homestory_809901001_36_dialog_content = "Sim...",
  str_homestory_809901001_37_dialog_content = "Quando você passa um tempo na natureza, seu humor melhora.",
  str_homestory_809901001_38_dialog_content = "Nunca se sabe. Um bom humor pode enfraquecer a maldição!",
  str_homestory_809901001_39_dialog_content = "...",
  str_homestory_809901001_40_dialog_content = "Hahaha...",
  str_homestory_809901001_41_dialog_content = "Obrigada. Estou me sentindo muito bem agora.<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "Bem, então... posso visitar a mina?",
  str_homestory_809901001_43_dialog_content = "Hum?",
  str_homestory_801601001_0_dialog_content = "Kafka?",
  str_homestory_801601001_1_dialog_content = "Espere, Kafka... O que é essa mancha de água<sprite=emo_hanshui size=60 /> no chão?",
  str_homestory_801601001_2_dialog_content = "Ah... eu sinto muito. Franz<sprite=emo_goutou size=60 /> babou. Acabei de limpar.",
  str_homestory_801601001_3_dialog_content = "Ele parece babar muito quando se sente feliz. Trabalhei duro para resolver esse novo problema.",
  str_homestory_801601001_4_dialog_content = "Err... Pelo menos ele não molha minha cama com tanta frequência.",
  str_homestory_801601001_5_dialog_content = "Isso vale um mimo... Franz sempre foi um bom menino, certo?",
  str_homestory_801601001_6_dialog_content = "Seu elogio o fará enlouquecer de alegria.",
  str_homestory_801601001_7_dialog_content = "Eu sei que ele está muito feliz aqui.",
  str_homestory_801601001_8_dialog_content = "Hum? Porque ele tem mais espaço aqui do que no Colosso?",
  str_homestory_801601001_9_dialog_content = "Ou porque ele continua encontrando pessoas estranhas...",
  str_homestory_801601001_10_dialog_content = "Como você sabe, ele adora coisas estranhas.",
  str_homestory_801601001_11_dialog_content = "Como qual?",
  str_homestory_801601001_12_dialog_content = "Eu deveria dizer \"criaturas estranhas\".",
  str_homestory_801601001_13_dialog_content = "Criaturas estranhas...",
  str_homestory_801601001_14_dialog_content = "Entendi! Você deve estar falando sobre... Ele...",
  str_homestory_801601001_15_option_content = "Tourdog?",
  str_homestory_801601001_16_dialog_content = "Hmm... Isso parece certo. Eu nunca falei muito com ele.",
  str_homestory_801601001_17_dialog_content = "Mas o rabo de Franz balança como um louco quando ele vê Tourdog. Ele até tentou morder Tourdogorelha de uma vez.",
  str_homestory_801601001_18_dialog_content = "Ah? O que Tourdog Faz?",
  str_homestory_801601001_19_dialog_content = "Nada de mais. Ele olhou para Franz por um tempo, segurando uma panela na mão. Senti que ele tinha algo a dizer.",
  str_homestory_801601001_20_dialog_content = "(... Ele pode pedir a Franz para desenhar algumas fotos para ele!)",
  str_homestory_801601001_21_dialog_content = "Por fim, ele olhou para as patas de Franz e se afastou balançando a cabeça.",
  str_homestory_801601001_22_dialog_content = "Ufa... Isso é um alívio...",
  str_homestory_801601001_23_dialog_content = "A propósito, suas orelhas parecem muito macias.",
  str_homestory_801601001_24_dialog_content = "Eu deveria apenas tocá-los da próxima vez...",
  str_homestory_801601001_25_option_content = "Hachi e Gin?",
  str_homestory_801601001_26_dialog_content = "Dois pirralhos fofos que tentam parecer maduros.",
  str_homestory_801601001_27_dialog_content = "Toda vez que veem Franz, gritam: \"Uau! Um cachorrinho de verdade!\"",
  str_homestory_801601001_28_dialog_content = "Franz parece gostar deles também e continua correndo atrás deles.",
  str_homestory_801601001_29_dialog_content = "Isso soa estranho...",
  str_homestory_801601001_30_dialog_content = "Não sei porque, mas quero muito ver por mim mesmo...",
  str_homestory_801601001_31_dialog_content = "Ao todo, Franz está vivendo uma boa vida aqui.",
  str_homestory_801601001_32_dialog_content = "No entanto... você tem passado muito tempo com Franz ultimamente?",
  str_homestory_801601001_33_dialog_content = "Hum? Não consigo me lembrar disso.",
  str_homestory_801601001_34_dialog_content = "Mas eu posso sentir seu cheiro em Franz!",
  str_homestory_801601001_35_dialog_content = "Ele pode ter entrado no seu quarto.",
  str_homestory_801601001_36_dialog_content = "Hmm... Não é totalmente impossível.",
  str_homestory_801601001_37_dialog_content = "Espere...",
  str_homestory_801601001_38_dialog_content = "O que você disse para mim?",
  str_homestory_801601001_39_dialog_content = "Franz não molha sua cama<sprite=emo_hanshui size=60 /> com tanta frequência?",
  str_homestory_801601001_40_dialog_content = "Err... Não me diga...",
  str_homestory_801601001_41_dialog_content = "... Não é à toa que minhas roupas de cama estão úmidas recentemente!",
  str_homestory_801601001_42_dialog_content = "Isso explica muita coisa...",
  str_homestory_801601001_43_dialog_content = "Acho que Franz realmente gosta de você.",
  str_homestory_801601001_44_dialog_content = "... Devo me sentir feliz agora?",
  str_homestory_801601001_45_dialog_content = "Você está procurando conselhos de mim?",
  str_homestory_801601001_46_dialog_content = "Bem... Se eu fosse você, correria para casa para lavar os lençóis agora mesmo.",
  str_homestory_804501001_0_dialog_content = "Que som é esse?",
  str_homestory_804501001_1_dialog_content = "Nails?",
  str_homestory_804501001_2_dialog_content = "Shush... Por favor, espere...",
  str_homestory_804501001_3_dialog_content = "Ah! Seu rosto está brilhante e limpo como um prato de porcelana, refletindo o corpo imundo do meu...",
  str_homestory_804501001_4_dialog_content = "Seus olhos são profundos como o céu noturno, perfurando a parte insuportável do meu coração...",
  str_homestory_804501001_5_dialog_content = "Por favor, perdoe-me pelo meu pecado...",
  str_homestory_804501001_6_dialog_content = "Ou me perdoar seria sua desgraça?",
  str_homestory_804501001_7_dialog_content = "...",
  str_homestory_804501001_8_dialog_content = "Desculpe a espera, PlayerName!",
  str_homestory_804501001_9_dialog_content = "Eu te atrapalhei?",
  str_homestory_804501001_10_dialog_content = "Minhas mais sinceras desculpas! Minha voz é intolerável para qualquer ouvido, cheia de pecados...",
  str_homestory_804501001_11_dialog_content = "Por favor, não seja tão duro consigo mesmo. Eu não estou perturbado em tudo!",
  str_homestory_804501001_12_dialog_content = "Mas estou muito curioso... Com quem você estava falando?",
  str_homestory_804501001_13_dialog_content = "Deve haver algum mal-entendido... Não havia ninguém. Eu estava confessando meus pecados.",
  str_homestory_804501001_14_dialog_content = "É tudo graças a você!",
  str_homestory_804501001_15_dialog_content = "Obrigado por fornecer este lugar perfeito para a minha confissão.",
  str_homestory_804501001_16_dialog_content = "Finalmente, sou capaz de confessar sem incomodar Lady Victoria.",
  str_homestory_804501001_17_option_content = "Negar",
  str_homestory_804501001_18_dialog_content = "Não me lembro de ter construído um lugar para confissão...",
  str_homestory_804501001_19_dialog_content = "Tão humilde. Tenho certeza de que esta magnífica fonte exigiu muito tempo e esforço.",
  str_homestory_804501001_20_dialog_content = "Mas esta é a Fonte da Esperança.",
  str_homestory_804501001_21_option_content = "Admitem",
  str_homestory_804501001_22_dialog_content = "Você é muito bem-vindo. Estou feliz por ter gostado...",
  str_homestory_804501001_23_dialog_content = "Espere... Você disse confissão?",
  str_homestory_804501001_24_dialog_content = "Você não está falando sobre esta Fonte da Esperança, está?",
  str_homestory_804501001_25_dialog_content = "A Fonte da Esperança. Que nome delicado!",
  str_homestory_804501001_26_dialog_content = "Eu vi pessoas aqui juntando as palmas das mãos devotamente e confessando. Agora eu sei o nome dele!",
  str_homestory_804501001_27_dialog_content = "Eu sou culpado. Eu devo confessar...",
  str_homestory_804501001_28_dialog_content = "Eu acho que essa é uma maneira de ver isso... Eu creio que as pessoas estão aqui orando.",
  str_homestory_804501001_29_dialog_content = "Também devo confessar em nome do PlayerName...",
  str_homestory_804501001_30_dialog_content = "Hã?!",
  str_homestory_804501001_31_dialog_content = "Uma confissão nunca deve ser interrompida...",
  str_homestory_804501001_32_dialog_content = "PlayerName, por favor, perdoe-me por não explicar isso antes.",
  str_homestory_804501001_33_dialog_content = "Ó Verdade que habita na Fonte da Esperança...",
  str_homestory_804501001_34_dialog_content = "Por favor perdoe Nails por incomodá-lo mais uma vez!",
  str_homestory_804501001_35_dialog_content = "Eu sou culpado. Estou aqui para confessar. Por favor, me castigue...",
  str_homestory_804501001_36_option_content = "Punir",
  str_homestory_804501001_37_dialog_content = "Poxa! Senti a resposta da Fonte da Esperança!",
  str_homestory_804501001_38_dialog_content = "Resposta? A verdade finalmente chegou!",
  str_homestory_804501001_39_dialog_content = "Ahem, a Fonte da Esperança declarou...",
  str_homestory_804501001_40_option_content = "Conforto",
  str_homestory_804501001_41_dialog_content = "Nails, Eu realmente não acho que você precisa confessar tais assuntos.",
  str_homestory_804501001_42_dialog_content = "Em vez de confessar aqui, por que não fazer planos para o futuro?",
  str_homestory_804501001_43_dialog_content = "!",
  str_homestory_804501001_44_dialog_content = "Como não pensei nisso até agora?",
  str_homestory_804501001_45_dialog_content = "Eu sabia... sou um homem pecador...",
  str_homestory_804501001_46_dialog_content = "Err...",
  str_homestory_808601001_0_dialog_content = "Esta flor branca familiar...",
  str_homestory_808601001_1_dialog_content = "Navegador PlayerName.",
  str_homestory_808601001_2_dialog_content = "Eu não esperava que Eraveil fosse tão bonito.",
  str_homestory_808601001_3_dialog_content = "Esta pradaria sem fim... Você não pode encontrá-la em Lumopolis.",
  str_homestory_808601001_4_dialog_content = "Mesmo essas flores brancas<sprite=emo_huaduo size=60 /> como Eraveil...",
  str_homestory_808601001_5_dialog_content = "Sim. Estou tão espantado.",
  str_homestory_808601001_6_dialog_content = "Hum? Você não é um deles em Eraveil?",
  str_homestory_808601001_7_dialog_content = "Ah, certo...",
  str_homestory_808601001_8_dialog_content = "Eu me lembro agora... Você foi forçado a deixar Eraveil em tenra idade.",
  str_homestory_808601001_9_dialog_content = "Está correto. Eu aprendi sobre Eraveil com Soroz...",
  str_homestory_808601001_10_dialog_content = "Mas fiquei impressionado com sua beleza quando cheguei a Eraveil.<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "E esse espanto não desaparece com o tempo.",
  str_homestory_808601001_12_dialog_content = "Esta é provavelmente a sensação de estar em casa. Eu sei que Eraveil está conectado comigo.",
  str_homestory_808601001_13_dialog_content = "Sim... Tudo aqui é cheio de inteligência espiritual. A arquitetura Caelestita convive perfeitamente com a natureza.",
  str_homestory_808601001_14_dialog_content = "Costumo lidar com o passado. Eu posso sentir isso...",
  str_homestory_808601001_15_dialog_content = "Este lugar tem a beleza da fonte da vida.",
  str_homestory_808601001_16_dialog_content = "Qualquer coisa viva e qualquer um que cante os louvores da vida vai se apaixonar por Eraveil.",
  str_homestory_808601001_17_dialog_content = "A casa de PlayerName é realmente linda.",
  str_homestory_808601001_18_dialog_content = "Estou tão feliz que este é o lugar onde você escolhe se estabelecer.",
  str_homestory_808601001_19_dialog_content = "Obrigada, Uriah.",
  str_homestory_808601001_20_dialog_content = "Estou emocionado com sua alta avaliação de Eraveil.",
  str_homestory_808601001_21_option_content = "Peça um favor",
  str_homestory_808601001_22_dialog_content = "Na verdade... eu tenho um favor a pedir à Srta. Uriah.",
  str_homestory_808601001_23_dialog_content = "Hehehe... PlayerName, não seja um estranho.",
  str_homestory_808601001_24_dialog_content = "Parece bastante sério, mas um pouco ambíguo...",
  str_homestory_808601001_25_dialog_content = "É mais do que um encontro? Você está propondo?",
  str_homestory_808601001_26_dialog_content = "Licença?",
  str_homestory_808601001_27_dialog_content = "Isso não!",
  str_homestory_808601001_28_dialog_content = "Hehehe... Adorável!",
  str_homestory_808601001_29_dialog_content = "Por favor, não zombe de mim!",
  str_homestory_808601001_30_option_content = "Estenda suas boas-vindas",
  str_homestory_808601001_31_dialog_content = "Você é bem-vinda ao Eraveil a qualquer hora, senhorita Uriah. Espero vê-lo mais vezes.",
  str_homestory_808601001_32_dialog_content = "Claro.",
  str_homestory_808601001_33_dialog_content = "A bela paisagem aqui é fascinante. Além disso, esta é a sua casa.",
  str_homestory_808601001_34_dialog_content = "PlayerName, Aguardo com expectativa o seu futuro brilhante sob a sua liderança.",
  str_homestory_808601001_35_dialog_content = "Obrigada... Uriah, você é uma freira encarregada da oração pelos falecidos para que descansem em paz, certo?",
  str_homestory_808601001_36_dialog_content = "Sim, essa é minha responsabilidade em Lumopolis.",
  str_homestory_808601001_37_dialog_content = "... Acho que sei o que você precisa.",
  str_homestory_808601001_38_dialog_content = "Sim. Quero orar pelos meus falecidos membros do clã para que possam descansar em paz.",
  str_homestory_808601001_39_dialog_content = "Imaginei...",
  str_homestory_808601001_40_dialog_content = "Estou impressionado com o quão maduro você se tornou. Agora você é capaz de aceitar tanto a vida quanto a morte.",
  str_homestory_808601001_41_dialog_content = "Eu, oração fúnebre, Uriah a freira, vai rezar pelos espíritos de Eraveil.",
  str_homestory_808601001_42_dialog_content = "Que suas almas descansem em paz! Maio flores brancas tapete Eraveil.",
  str_homestory_808601001_43_dialog_content = "Eu agradeço.",
  str_homestory_810201001_0_dialog_content = "Essa corrente elétrica...",
  str_homestory_810201001_1_dialog_content = "Tessa?",
  str_homestory_810201001_2_dialog_content = "Se estiver cansado, descanse nos dormitórios do Cloud Gardens.",
  str_homestory_810201001_3_dialog_content = "*Bocejar*<sprite=emo_kun size=60 />",
  str_homestory_810201001_4_dialog_content = "Diga o quê? Ei você!",
  str_homestory_810201001_5_dialog_content = "O que você disse?",
  str_homestory_810201001_6_dialog_content = "Suspiro... Eu tenho que tirar esse pirulito pra você entender?",
  str_homestory_810201001_7_dialog_content = "Hmm... Eu só não quero que você pegue um resfriado dormindo lá fora.",
  str_homestory_810201001_8_dialog_content = "É uma regra aqui dormir dentro?",
  str_homestory_810201001_9_dialog_content = "Não é obrigatório...",
  str_homestory_810201001_10_dialog_content = "Eu realmente não me importo, mesmo que seja.",
  str_homestory_810201001_11_dialog_content = "Eu durmo onde eu quiser.",
  str_homestory_810201001_12_option_content = "Concordo",
  str_homestory_810201001_13_dialog_content = "Claro que não!",
  str_homestory_810201001_14_dialog_content = "Tenho inveja do seu estilo de vida.",
  str_homestory_810201001_15_dialog_content = "Eu só preciso de um pouco de paz. Não há nada para ter ciúmes.",
  str_homestory_810201001_16_option_content = "Não foi possível concordar",
  str_homestory_810201001_17_dialog_content = "eu entendo onde Tessa é de mas...",
  str_homestory_810201001_18_dialog_content = "Eu só preciso de um pouco de paz. A compreensão não é necessária.",
  str_homestory_810201001_19_dialog_content = "Multar...",
  str_homestory_810201001_20_dialog_content = "Há guarda-sóis e tendas na loja. Me avise sempre que precisar.",
  str_homestory_810201001_21_dialog_content = "Eu sou muito bom na sombra.",
  str_homestory_810201001_22_dialog_content = "A propósito, esta loja tem pirulitos?",
  str_homestory_810201001_23_dialog_content = "Estou acabando.",
  str_homestory_810201001_24_dialog_content = "Nós temos, mas...",
  str_homestory_810201001_25_dialog_content = "Você já esteve dentro de um dormitório Cloud Gardens?",
  str_homestory_810201001_26_dialog_content = "Como eu disse, não estou interessado em ficar dentro de casa.",
  str_homestory_810201001_27_dialog_content = "O que isso tem a ver com pirulitos?",
  str_homestory_810201001_28_dialog_content = "Dar as boas vindas Tessa...",
  str_homestory_810201001_29_dialog_content = "Eu preparei muitos pirulitos no dormitório...",
  str_homestory_810201001_30_dialog_content = "Pirulitos?",
  str_homestory_810201001_31_dialog_content = "Eu acabei de verificar. Nada sobrou.",
  str_homestory_810201001_32_dialog_content = "Eu pensei que era Tessa... Acho que alguém conseguiu antes de você.",
  str_homestory_810201001_33_dialog_content = "Seriamente? Por que você não me contou antes?",
  str_homestory_810201001_34_dialog_content = "Eu pensei que todos iriam para os dormitórios Cloud Gardens para descansar primeiro...",
  str_homestory_810201001_35_dialog_content = "Hmph! Qualquer que seja.",
  str_homestory_810201001_36_dialog_content = "Vou comprar mais.",
  str_homestory_810201001_37_dialog_content = "(Tessaé surpreendentemente razoável...)",
  str_homestory_810201001_38_dialog_content = "Existe algum trabalho remunerado disponível aqui?",
  str_homestory_810201001_39_dialog_content = "Hum? Eu pensei que você estava de folga... Por que você está procurando um emprego agora?",
  str_homestory_810201001_40_dialog_content = "Eu queria fazer compras, mas não tenho dinheiro sobrando.",
  str_homestory_810201001_41_dialog_content = "Vou ter que comprar a crédito se não houver nada disponível.",
  str_homestory_810201001_42_dialog_content = "...",
  str_homestory_810201001_43_dialog_content = "Você poderia inspecionar o circuito elétrico dos dormitórios do Cloud Gardens?",
  str_homestory_810201001_44_dialog_content = "Eu estou trabalhando nisso!",
  str_homestory_801501001_0_dialog_content = "Isso é um primeiro...",
  str_homestory_801501001_1_dialog_content = "Nunca te vi sem Gin antes.",
  str_homestory_801501001_2_dialog_content = "Ah! PlayerName, você pode sentir o cheiro?",
  str_homestory_801501001_3_dialog_content = "A fragrância de Nightium<sprite=emo_baiyebi size=60 />! Está em toda parte!",
  str_homestory_801501001_4_option_content = "Expresse suas dúvidas",
  str_homestory_801501001_5_dialog_content = "Como é que eu não posso sentir o cheiro?",
  str_homestory_801501001_6_dialog_content = "Qual é a fragrância de Nightium afinal?",
  str_homestory_801501001_7_dialog_content = "PlayerName, esta é uma arte da fala. O ponto é...",
  str_homestory_801501001_8_dialog_content = "Tenho alguns projetos para discutir com você. Qualquer um deles vale mais de 9 dígitos!",
  str_homestory_801501001_9_dialog_content = "9 dígitos?",
  str_homestory_801501001_10_option_content = "Pergunte sobre o cheiro",
  str_homestory_801501001_11_dialog_content = "Como é o cheiro de Nightium?",
  str_homestory_801501001_12_dialog_content = "30% de doçura enferrujada misturada com 40% de suor salgado...",
  str_homestory_801501001_13_dialog_content = "Mais 50%... *Cheirar*",
  str_homestory_801501001_14_dialog_content = "50% pura fragrância de árvores frutíferas!",
  str_homestory_801501001_15_dialog_content = "Isso é 120%.",
  str_homestory_801501001_16_dialog_content = "Tanto quanto minha sinceridade para fazer negócios com PlayerName.",
  str_homestory_801501001_17_dialog_content = "Só para ficar claro. É 120% e não 12%.",
  str_homestory_801501001_18_dialog_content = "O que você tem desta vez?",
  str_homestory_801501001_19_dialog_content = "Ouço. Meus desenhos não estão à venda. E você não pode pedir emprestado para fazer uma cópia...",
  str_homestory_801501001_20_dialog_content = "PlayerName, ter uma perspectiva mais longa.",
  str_homestory_801501001_21_dialog_content = "Agora você tem uma sala de exposições naturais. Não se apegue muito a alguns desenhos.",
  str_homestory_801501001_22_dialog_content = "Hall de exibição?",
  str_homestory_801501001_23_dialog_content = "Um exemplo perfeito de combinar um espaço natural aberto com ecologia cultural.",
  str_homestory_801501001_24_dialog_content = "Este é um excelente Salão de Exposições natural.",
  str_homestory_801501001_25_dialog_content = "PlayerName, nós amamos<sprite=emo_aixin size=60 /> muito este lugar.",
  str_homestory_801501001_26_dialog_content = "Acabei de tomar uma decisão difícil!",
  str_homestory_801501001_27_dialog_content = "Eu decido...",
  str_homestory_801501001_28_dialog_content = "Vou me tornar um planejador de exposições!",
  str_homestory_801501001_29_dialog_content = "O que exatamente faz um planejador de exposições?",
  str_homestory_801501001_30_dialog_content = "Tosse... Resumindo, sou responsável por avaliar, estudar, preservar e expor todo tipo de obras de arte...",
  str_homestory_801501001_31_dialog_content = "Serei um gestor profissional que planeja e organiza exposições de arte em locais específicos.",
  str_homestory_801501001_32_dialog_content = "Estou perdido, mas parece legítimo.",
  str_homestory_801501001_33_dialog_content = "Então você concorda?",
  str_homestory_801501001_34_dialog_content = "Você não precisa da minha permissão para mudar de carreira.",
  str_homestory_801501001_35_dialog_content = "Contanto que você não destrua nosso meio ambiente... Trabalhei duro para construir isso.",
  str_homestory_801501001_36_dialog_content = "Entendi.",
  str_homestory_801501001_37_dialog_content = "PlayerName não quer que eu mude a arquitetura e as plantas aqui.",
  str_homestory_801501001_38_dialog_content = "Isso mesmo.",
  str_homestory_801501001_39_dialog_content = "PlayerName não quer que eu desenhe ou organize exposições artísticas e festivais.",
  str_homestory_801501001_40_dialog_content = "Correto.",
  str_homestory_801501001_41_dialog_content = "PlayerName também não quer que minhas exposições e festivais de arte atraiam turistas.",
  str_homestory_801501001_42_dialog_content = "Sim...",
  str_homestory_801501001_43_dialog_content = "Nem é PlayerName interessados na receita significativa resultante.",
  str_homestory_801501001_44_dialog_content = "Hmm...",
  str_homestory_801501001_45_dialog_content = "PlayerName não deseja melhorar sua terrível situação financeira.",
  str_homestory_801501001_46_dialog_content = "Aham... Espere um minuto.",
  str_homestory_801501001_47_dialog_content = "Preciso pensar mais sobre isso.",
  str_homestory_801501001_48_dialog_content = "Hahah. PlayerName finalmente senti a fragrância de Nightium!",
  str_homestory_815401001_0_dialog_content = "De novo?",
  str_homestory_815401001_1_dialog_content = "Vice, você tem passado muito tempo no museu ultimamente.",
  str_homestory_815401001_2_dialog_content = "Existe uma maneira de ganhar dinheiro lá?",
  str_homestory_815401001_3_dialog_content = "Infelizmente...",
  str_homestory_815401001_4_dialog_content = "Nossa situação financeira não é boa, mas pensei que chegamos a um acordo?",
  str_homestory_815401001_5_dialog_content = "Este museu é um site de serviço público dedicado a mostrar a história do Eraveil e a tecnologia dos Caelestites.",
  str_homestory_815401001_6_dialog_content = "Entrada gratuita e sem fins lucrativos...",
  str_homestory_815401001_7_option_content = "Desculpar-se",
  str_homestory_815401001_8_dialog_content = "Eu sinto Muito, Vice.",
  str_homestory_815401001_9_dialog_content = "Tenho pensado nisso esses dias. Acho que estou obcecado agora.",
  str_homestory_815401001_10_dialog_content = "Hahahah. Está bem! Eu mesmo já estive lá.",
  str_homestory_815401001_11_dialog_content = "Acho que você precisa de uma pausa!",
  str_homestory_815401001_12_dialog_content = "Vice, diga isso para si mesmo.",
  str_homestory_815401001_13_dialog_content = "Você quase se mudou para o museu esses dias. Você parece ansioso e preocupado...",
  str_homestory_815401001_14_dialog_content = "Há quanto tempo você não descansa direito?",
  str_homestory_815401001_15_option_content = "Interesse",
  str_homestory_815401001_16_dialog_content = "Não se preocupe. Eu nunca vou mudar minha posição sobre isso!",
  str_homestory_815401001_17_dialog_content = "Como o último celestita, não posso deixar nossa civilização acabar em minhas mãos.",
  str_homestory_815401001_18_dialog_content = "Mas...",
  str_homestory_815401001_19_dialog_content = "O que você está fazendo tão cuidadosamente no museu?",
  str_homestory_815401001_20_dialog_content = "Infelizmente... eu não posso esconder nada de PlayerName.<sprite=emo_wuzui size=60 />",
  str_homestory_815401001_21_dialog_content = "Recentemente, estive investigando os itens expostos no museu.",
  str_homestory_815401001_22_dialog_content = "Investigar? Uma nova missão atribuída pela Illumina?",
  str_homestory_815401001_23_dialog_content = "Não, é para mim.",
  str_homestory_815401001_24_dialog_content = "Talvez eu não devesse chamar isso de investigação.",
  str_homestory_815401001_25_dialog_content = "Estou procurando inspiração.",
  str_homestory_815401001_26_dialog_content = "Sabe... Depois do que aconteceu com meu corpo...",
  str_homestory_815401001_27_dialog_content = "Recordei muitos fragmentos de memória.",
  str_homestory_815401001_28_dialog_content = "Mas é completamente em branco quando se trata da minha origem...",
  str_homestory_815401001_29_dialog_content = "Então... Você está procurando pistas para o seu passado?",
  str_homestory_815401001_30_dialog_content = "Heheheh. Estranho, certo?",
  str_homestory_815401001_31_dialog_content = "Eu sei. Como eu poderia encontrar alguma coisa em um museu Caelestita?",
  str_homestory_815401001_32_dialog_content = "Nunca se sabe.",
  str_homestory_815401001_33_dialog_content = "O mundo é grande, mas coincidências acontecem todos os dias.",
  str_homestory_815401001_34_dialog_content = "Hahahaha. Você está muito mais otimista agora.",
  str_homestory_815401001_35_dialog_content = "Vamos fazer outro tour pelo museu?",
  str_homestory_815401001_36_dialog_content = "Podemos encontrar algo desta vez, como uma carta de família ou algo assim?",
  str_homestory_815401001_37_dialog_content = "Claro!",
  str_homestory_815401001_38_dialog_content = "Mas e se eu for sua irmã mais velha...<sprite=emo_sikao size=60 />",
  str_homestory_815401001_39_dialog_content = "O que você faria?",
  str_homestory_815401001_40_dialog_content = "Minha irmã mais velha? De jeito nenhum!",
  str_homestory_815401001_41_dialog_content = "É possível que eu seja seu irmão mais velho!",
  str_homestory_815401001_42_dialog_content = "PlayerName...",
  str_homestory_815401001_43_dialog_content = "Hmm... Eu realmente não consigo ver isso.",
  str_homestory_815401001_44_dialog_content = "Ahem... Espero que não seja o caso!",
  str_homestory_805702001_0_dialog_content = "Está chovendo?",
  str_homestory_805702001_1_dialog_content = "Miau...",
  str_homestory_805702001_2_dialog_content = "Está chovendo, Philyshy. Devemos sair da chuva.",
  str_homestory_805702001_3_dialog_content = "Não, na verdade fui eu sacudindo a água de mim mesmo.",
  str_homestory_805702001_4_dialog_content = "Desculpe por ter pego em você, PlayerName...",
  str_homestory_805702001_5_dialog_content = "Eu vejo. Não é à toa que você estava balançando a cabeça para todos os lados...",
  str_homestory_805702001_6_dialog_content = "Pare de zombar de mim, PlayerName...",
  str_homestory_805702001_7_dialog_content = "Mas se não choveu, como você se molhou?",
  str_homestory_805702001_8_dialog_content = "Miau... Eu culpo o peixe seco e brilhante no rio!<sprite=emo_shengqi size=60 />",
  str_homestory_805702001_9_option_content = "Brilhante?",
  str_homestory_805702001_10_dialog_content = "Como isso é possível?",
  str_homestory_805702001_11_dialog_content = "Eu também quero saber. É por isso que eu tentei pegá-lo, miau.",
  str_homestory_805702001_12_option_content = "Peixe seco brilhante?",
  str_homestory_805702001_13_dialog_content = "Espere, como pode peixe seco estar no rio?",
  str_homestory_805702001_14_dialog_content = "Será depois que eu pegar e secar ao sol!",
  str_homestory_805702001_15_dialog_content = "Por mais que tente, não consegui pegá-lo e caí no rio.",
  str_homestory_805702001_16_dialog_content = "Achoo! O rio está muito frio, miau...",
  str_homestory_805702001_17_dialog_content = "Você deve voltar para casa e se aquecer antes de pegar um resfriado.",
  str_homestory_805702001_18_dialog_content = "Mas...",
  str_homestory_805702001_19_dialog_content = "Ei, já que você é o proprietário aqui, PlayerName...",
  str_homestory_805702001_20_dialog_content = "Pegue aquele peixe seco brilhante para mim!",
  str_homestory_805702001_21_dialog_content = "Hã?",
  str_homestory_805702001_22_dialog_content = "E lembre-se... Seque ao sol... Zzz...<sprite=emo_kun size=60 />",
  str_homestory_805702001_23_dialog_content = "Você vai pegar um resfriado dormindo aqui fora... Philyshy?",
  str_homestory_805702001_24_dialog_content = "Zzz... Zzz... <sprite=emo_kun size=60 />Peixe seco...",
  str_homestory_814101001_0_dialog_content = "Que legal...",
  str_homestory_814101001_1_dialog_content = "Oi, PlayerName, a explorar também?",
  str_homestory_814101001_2_option_content = "Sim.",
  str_homestory_814101001_3_dialog_content = "Há muitos lugares para explorar em meus Cloud Gardens com curadoria.",
  str_homestory_814101001_4_option_content = "Não.",
  str_homestory_814101001_5_dialog_content = "Estou apenas tomando um pouco de ar fresco.",
  str_homestory_814101001_6_dialog_content = "Com um esforço, Cloud Gardens se torna o que é hoje, então eu gostaria de ficar aqui quando puder.",
  str_homestory_814101001_7_dialog_content = "Você está absolutamente correto!",
  str_homestory_814101001_8_dialog_content = "Esta ilha que você construiu é tão emocionante. Eu amo isso!",
  str_homestory_814101001_9_dialog_content = "Estava a bisbilhotar aquele rio há pouco.",
  str_homestory_814101001_10_dialog_content = "Sim? Encontrou algo emocionante?",
  str_homestory_814101001_11_dialog_content = "Heh, sabia que você ia me perguntar isso!",
  str_homestory_814101001_12_dialog_content = "Assim que vi o rio, pulei para dentro!",
  str_homestory_814101001_13_dialog_content = "Separei os juncos e encontrei uma moeda que nunca tinha visto antes no fundo<sprite=emo_baiyebi size=60 />...",
  str_homestory_814101001_14_dialog_content = "Então eu peguei um grande peixe Betta...",
  str_homestory_814101001_15_dialog_content = "Alguns golpes depois, vi uma estranha relíquia!",
  str_homestory_814101001_16_dialog_content = "Então eu apenas peguei e levei para a praia. Adivinhe o que é.",
  str_homestory_814101001_17_dialog_content = "O-o que é?",
  str_homestory_814101001_18_dialog_content = "Um velho sapato esfarrapado cheio de juncos!",
  str_homestory_814101001_19_dialog_content = "Tentei vendê-lo para a loja, mas nem sequer valeu um Nightium! Tão engraçado!",
  str_homestory_814101001_20_dialog_content = "E o peixe e a moeda?",
  str_homestory_814101001_21_dialog_content = "Ah sim... eu sei que os coloquei no meu bolso...",
  str_homestory_814101001_22_dialog_content = "Hmm, eles provavelmente caíram quando eu peguei o sapato.",
  str_homestory_814101001_23_dialog_content = "Podemos ir buscá-lo se você estiver interessado!",
  str_homestory_814101001_24_dialog_content = "Embora o peixe já tenha nado para longe, com certeza.",
  str_homestory_814101001_25_dialog_content = "Ruby, um eterno otimista.",
  str_homestory_814101001_26_dialog_content = "Oh, não conte a Blossom sobre isso!",
  str_homestory_814101001_27_dialog_content = "Ou ela vai forçar um remédio amargo para febre na minha garganta!",
  str_homestory_801001001_0_dialog_content = "Ainda está dormindo?",
  str_homestory_801001001_1_dialog_content = "Você está bem, Louise? Você parece sonolento.",
  str_homestory_801001001_2_dialog_content = "Ah é você, PlayerName.",
  str_homestory_801001001_3_dialog_content = "Eu pensei que minha espera finalmente acabou...",
  str_homestory_801001001_4_dialog_content = "Você está esperando por alguem?",
  str_homestory_801001001_5_dialog_content = "Estou esperando o fae no rio.",
  str_homestory_801001001_6_dialog_content = "Fae?",
  str_homestory_801001001_7_dialog_content = "Você não ouviu falar daquele conto de fadas muito famoso, PlayerName?",
  str_homestory_801001001_8_dialog_content = "Em um rio remoto vivia uma fae muito bonita.",
  str_homestory_801001001_9_dialog_content = "O fae voaria quando alguém acidentalmente deixasse cair algo na água.",
  str_homestory_801001001_10_dialog_content = "Aqueles que respondessem honestamente à pergunta do fae seriam recompensados!",
  str_homestory_801001001_11_option_content = "Rio...",
  str_homestory_801001001_12_dialog_content = "Você acha que há um fae neste rio, Louise?",
  str_homestory_801001001_13_dialog_content = "Uh, todo rio não tem um fae?",
  str_homestory_801001001_14_dialog_content = "No rio de Northland vivia um fae de Northland, então no rio de Eraveil viveria um fae de Eraveil...",
  str_homestory_801001001_15_option_content = "Conto de fadas, você disse...",
  str_homestory_801001001_16_dialog_content = "Sabe, acho que já ouvi algo parecido.",
  str_homestory_801001001_17_dialog_content = "Alguém perdeu um machado de aço, mas ficou ganancioso e alegou que era um machado de ouro.",
  str_homestory_801001001_18_dialog_content = "Mas o ponto aqui é...",
  str_homestory_801001001_19_dialog_content = "Perdeu alguma coisa no rio?",
  str_homestory_801001001_20_dialog_content = "Sim! Mas não é meu.",
  str_homestory_801001001_21_dialog_content = "É uma moeda que peguei no banco com padrões muito intrincados.",
  str_homestory_801001001_22_dialog_content = "Mas tinha rolado na água antes que eu pudesse dar uma boa olhada.",
  str_homestory_801001001_23_dialog_content = "Esperei tanto tempo, mas ainda não fae.",
  str_homestory_801001001_24_dialog_content = "Eu acho que seu rio não tem fae, PlayerName...<sprite=emo_sikao size=60 />",
  str_homestory_801001001_25_dialog_content = "Deixa eu ver se consigo tirar.",
  str_homestory_801001001_26_dialog_content = "Então você é o fae, PlayerName?!",
  str_homestory_804102001_0_dialog_content = "Você não pode estar falando sério...",
  str_homestory_804102001_1_dialog_content = "Olá, Sra. Blanc.",
  str_homestory_804102001_2_dialog_content = "Olá querido PlayerName.",
  str_homestory_804102001_3_dialog_content = "Você ainda está inspecionando as estradas e edifícios em Cloud Gardens?",
  str_homestory_804102001_4_dialog_content = "Fico feliz que você ainda se lembre das minhas rotinas.",
  str_homestory_804102001_5_option_content = "Acho muito profissional.",
  str_homestory_804102001_6_dialog_content = "Mas...",
  str_homestory_804102001_7_option_content = "Desculpas!",
  str_homestory_804102001_8_dialog_content = "Por que diz isso?",
  str_homestory_804102001_9_dialog_content = "Estou expandindo Cloud Gardens, adicionando estruturas e estradas.",
  str_homestory_804102001_10_dialog_content = "Isso não vai facilitar o seu trabalho, vai?",
  str_homestory_804102001_11_dialog_content = "Nunca subestime as habilidades de uma mulher profissional, PlayerName.",
  str_homestory_804102001_12_dialog_content = "Contanto que eu tenha as coordenadas e localizações dos principais edifícios e estradas na minha cabeça...",
  str_homestory_804102001_13_dialog_content = "Não terei problemas em memorizar mais.",
  str_homestory_804102001_14_dialog_content = "Uma lembrança tão incrível!",
  str_homestory_804102001_15_dialog_content = "Mas eu vi você franzindo a testa. Existe um problema?",
  str_homestory_804102001_16_dialog_content = "Ops, você viu isso, PlayerName?",
  str_homestory_804102001_17_dialog_content = "Bem, algo está realmente me incomodando. Acho que não há problema em lhe dizer.",
  str_homestory_804102001_18_dialog_content = "Eu estava escrevendo o guia para Cloud Gardens...",
  str_homestory_804102001_19_dialog_content = "Quando cheguei ao rio aqui.",
  str_homestory_804102001_20_dialog_content = "Em cima de uma variedade de peixes, há algo brilhante.",
  str_homestory_804102001_21_dialog_content = "Para garantir a precisão da descrição, gostaria muito de saber o que é isso...",
  str_homestory_804102001_22_dialog_content = "Objeto brilhante, você disse...",
  str_homestory_804102001_23_dialog_content = "Já que você é o dono do Cloud Gardens, você se importaria de dar uma olhada nele?",
  str_homestory_804102001_24_dialog_content = "Sem problemas!",
  str_homestory_801502001_0_dialog_content = "Cheirando de novo?",
  str_homestory_801502001_1_dialog_content = "Ahem, o que você está fazendo agora, Hachi?",
  str_homestory_801502001_2_dialog_content = "Ei, não é nosso querido PlayerName!<sprite=emo_yaosu size=60 />",
  str_homestory_801502001_3_dialog_content = "Então, tomou sua decisão?",
  str_homestory_801502001_4_dialog_content = "Que decisão?",
  str_homestory_801502001_5_dialog_content = "Ah, Eu entendi. Você tem um monte de coisas no seu prato!",
  str_homestory_801502001_6_dialog_content = "Eu quis dizer... transformar Cloud Gardens em uma exposição natural.",
  str_homestory_801502001_7_option_content = "Está em consideração.",
  str_homestory_801502001_8_dialog_content = "Bom, ainda estou pensando nisso...",
  str_homestory_801502001_9_option_content = "Esquece...",
  str_homestory_801502001_10_dialog_content = "Um gol admirável, mas gosto de Cloud Gardens do jeito que está agora, limpo e tranquilo.",
  str_homestory_801502001_11_dialog_content = "Uh. Tudo bem.",
  str_homestory_801502001_12_dialog_content = "Mas você deve reconsiderar. As oportunidades não esperam por ninguém!",
  str_homestory_801502001_13_dialog_content = "Hmm...",
  str_homestory_801502001_14_dialog_content = "*Onomatopeia de cheirar*",
  str_homestory_801502001_15_dialog_content = "O que você está cheirando?",
  str_homestory_801502001_16_dialog_content = "Você não pode sentir o cheiro? Tem cheiro de moeda.",
  str_homestory_801502001_17_dialog_content = "Nightium <sprite=emo_baiyebi size=60 />novamente?",
  str_homestory_801502001_18_dialog_content = "Não, totalmente diferente!",
  str_homestory_801502001_19_dialog_content = "É novo e indescritivelmente único... *Sniff*",
  str_homestory_801502001_20_dialog_content = "É mais alegre e úmido que Nightium, mais antigo também...",
  str_homestory_801502001_21_dialog_content = "E os padrões são mais intrincados.",
  str_homestory_801502001_22_dialog_content = "Você pode sentir o cheiro dos padrões também?!",
  str_homestory_801502001_23_dialog_content = "Nunca subestime o nariz canino.",
  str_homestory_801502001_24_dialog_content = "Seja uma tendência de negócios ou o cheiro de uma moeda, posso apontar a direção certa.",
  str_homestory_801502001_25_dialog_content = "Desta vez, darei a você a chance de encontrar a moeda, querida PlayerName.",
  str_homestory_801502001_26_dialog_content = "Hã?",
  str_homestory_801502001_27_dialog_content = "Espero que você pense sobre nossa colaboração!",
  str_homestory_805602001_0_dialog_content = "Constantine?",
  str_homestory_805602001_1_dialog_content = "Olá, PlayerName.",
  str_homestory_805602001_2_dialog_content = "Onde você foi desta vez, Constantine?",
  str_homestory_805602001_3_dialog_content = "Acabei de voltar da pescaria.",
  str_homestory_805602001_4_dialog_content = "Ah, vejo que você tem feito isso nos últimos dias.",
  str_homestory_805602001_5_dialog_content = "Você é um profissional, então provavelmente pegou muitos peixes, certo?",
  str_homestory_805602001_6_dialog_content = "Nem mesmo um.",
  str_homestory_805602001_7_dialog_content = "O que? Mas você é um caçador experiente!",
  str_homestory_805602001_8_dialog_content = "Você pode considerar pescar o mesmo que caçar, mas há uma grande diferença entre os dois.<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "Você subjuga ativamente a presa ao caçar.",
  str_homestory_805602001_10_dialog_content = "Considerando que você minimiza a iniciativa e faz com que eles venham até você na hora da pesca.",
  str_homestory_805602001_11_option_content = "Entendido.",
  str_homestory_805602001_12_dialog_content = "Ao pescar, ninguém tem ideia do que vai pescar.",
  str_homestory_805602001_13_dialog_content = "Mas quando caçam, eles encontram o alvo primeiro, depois agem.",
  str_homestory_805602001_14_option_content = "Não.",
  str_homestory_805602001_15_dialog_content = "Mas você disse que caçar exigia paciência. Isso também é necessário para a pesca.",
  str_homestory_805602001_16_dialog_content = "Ninguém tem ideia de quando um peixe vai morder.",
  str_homestory_805602001_17_dialog_content = "Sim você está correto.",
  str_homestory_805602001_18_dialog_content = "Francamente, eu era contra as regras no começo...",
  str_homestory_805602001_19_dialog_content = "Eu sempre travava um alvo primeiro, depois tentava pegá-lo, mas isso nunca dava certo.",
  str_homestory_805602001_20_dialog_content = "Para me lembrar da lição aprendida, achatei o anzol.",
  str_homestory_805602001_21_dialog_content = "O que? Você pode pegar peixe assim?",
  str_homestory_805602001_22_dialog_content = "Não sei, não me importo. Eu só quero aprimorar minha paciência.",
  str_homestory_805602001_23_dialog_content = "Será que vai continuar?",
  str_homestory_805602001_24_dialog_content = "Eu estabeleci um prazo para mim.",
  str_homestory_805602001_25_dialog_content = "Quando a moeda do banco está atolada na lama ou lavada... ou alguém a recolhe.",
  str_homestory_805602001_26_dialog_content = "Até lá, vou ficar com o gancho reto.",
  str_homestory_805602001_27_dialog_content = "(Moeda...?)",
  str_homestory_805602001_28_dialog_content = "(Eu deveria ver se consigo pescar isso.)",
  str_homestory_808502001_0_dialog_content = "Uau, tão rápido...",
  str_homestory_808502001_1_dialog_content = "Você está fazendo um diário, Jane?",
  str_homestory_808502001_2_dialog_content = "Sim, estou gravando tudo que vejo em Cloud Gardens.",
  str_homestory_808502001_3_dialog_content = "Se eu não soubesse sua profissão, pensaria que você desenhava.",
  str_homestory_808502001_4_dialog_content = "Mas eu estava desenhando.",
  str_homestory_808502001_5_dialog_content = "Huh...?<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "Você precisa de mais do que texto para a descrição. Ilustrações também são necessárias.",
  str_homestory_808502001_7_dialog_content = "Quando as ilustrações são necessárias?",
  str_homestory_808502001_8_dialog_content = "É bem direto. Quando as palavras não são suficientes para descrever algo, você usa ilustrações.",
  str_homestory_808502001_9_dialog_content = "Por exemplo, eu estava apenas descrevendo tudo o que vi no rio.",
  str_homestory_808502001_10_dialog_content = "Eu poderia usar palavras para descrever Redfin Fish, mas os leitores apenas imaginariam uma imagem vaga em suas mentes.",
  str_homestory_808502001_11_dialog_content = "Mas se eu realmente desenhar a forma e a cor...",
  str_homestory_808502001_12_dialog_content = "Eles obterão imediatamente a aparência do peixe.",
  str_homestory_808502001_13_dialog_content = "Então é isso...",
  str_homestory_808502001_14_dialog_content = "Outro exemplo, quando eu estava escrevendo sobre \"Uma moeda ainda está no fundo do rio\"...",
  str_homestory_808502001_15_dialog_content = "Eles só podiam imaginar a moeda que usavam antes.",
  str_homestory_808502001_16_dialog_content = "Então eu teria que desenhar os padrões dessa moeda que ninguém viu antes.",
  str_homestory_808502001_17_dialog_content = "Isso permite que eles saibam claramente que tipo de moeda estava no fundo do rio em Cloud Gardens.",
  str_homestory_808502001_18_dialog_content = "Então, onde está a moeda agora?",
  str_homestory_808502001_19_dialog_content = "Ainda no rio.",
  str_homestory_808502001_20_dialog_content = "O que? Por que você não tirou?",
  str_homestory_808502001_21_dialog_content = "Eu apenas gravo. Eu não interfiro.",
  str_homestory_808502001_22_dialog_content = "Isso também significa que não vou impedi-lo de obter a moeda.",
  str_homestory_808502001_23_dialog_content = "Mas vou gravar assim que acontecer.",
  str_homestory_805502001_0_dialog_content = "De mau humor?",
  str_homestory_805502001_1_dialog_content = "O que aconteceu, Pittman? Você parece zangado.",
  str_homestory_805502001_2_dialog_content = "Na hora certa, PlayerName. Eu ia te procurar!",
  str_homestory_805502001_3_dialog_content = "Uh, isso tem alguma coisa a ver comigo?",
  str_homestory_805502001_4_dialog_content = "Ainda não tenho certeza, mas...",
  str_homestory_805502001_5_dialog_content = "Noite Branca nas alturas! Como Juiz de Lumopolis, venho por este meio abrir um inquérito...",
  str_homestory_805502001_6_dialog_content = "Você está cunhando Nightium aqui em Cloud Gardens?",
  str_homestory_805502001_7_option_content = "Não!",
  str_homestory_805502001_8_dialog_content = "É verdade que preciso de Nightium, mas não estou tão desesperada!",
  str_homestory_805502001_9_option_content = "Eu gostaria de.",
  str_homestory_805502001_10_dialog_content = "Mas é caro cunhar Nightium. Eu precisaria de um monte de dinheiro para ganhar dinheiro.",
  str_homestory_805502001_11_dialog_content = "Você sabe que eu não tenho muito!",
  str_homestory_805502001_12_dialog_content = "Você jura?",
  str_homestory_805502001_13_dialog_content = "EU, PlayerName, nunca cunharam Nightium, nunca.",
  str_homestory_805502001_14_dialog_content = "Ou... você pode fazer comigo o que quiser!",
  str_homestory_805502001_15_dialog_content = "Então, você notou algum suspeito ou sinal relacionado a isso em Cloud Gardens?",
  str_homestory_805502001_16_dialog_content = "Particularmente aqueles de Umbraton e do deserto?",
  str_homestory_805502001_17_dialog_content = "Eles são todos meus amigos, então eu realmente não quero duvidar deles...",
  str_homestory_805502001_18_dialog_content = "Todos são iguais perante a lei, independentemente de quem.",
  str_homestory_805502001_19_dialog_content = "Mas por que você suspeita deles?",
  str_homestory_805502001_20_dialog_content = "Já que você fez seu juramento, posso divulgar meu segredo.",
  str_homestory_805502001_21_dialog_content = "Encontrei uma moeda à beira do rio que lembrava Nightium em make!",
  str_homestory_805502001_22_dialog_content = "Se importa se eu ver?",
  str_homestory_805502001_23_dialog_content = "Fiquei muito bravo, perdi o controle e ele caiu no rio.",
  str_homestory_805502001_24_dialog_content = "É só um palpite... mas acho que provavelmente pertenceu a nós, celestitas.",
  str_homestory_805502001_25_dialog_content = "Ah... S-realmente?",
  str_homestory_805502001_26_dialog_content = "Bem, eu não dei uma boa olhada, afinal...",
  str_homestory_805502001_27_dialog_content = "Se isso for verdade, devo me desculpar por minha grosseria.",
  str_homestory_805502001_28_dialog_content = "Foi mal!",
  str_homestory_805502001_29_dialog_content = "Tudo bem, também não tenho certeza de qual é exatamente a história com isso.",
  str_homestory_805502001_30_dialog_content = "Eu vou mostrar para você quando eu encontrá-lo.",
  str_homestory_805502001_31_dialog_content = "Muito obrigado, PlayerName!",
  str_homestory_815701001_0_dialog_content = "Sanae...",
  str_homestory_815701001_1_dialog_content = "Ahhhhhhhhhh! Sr. Navegador...",
  str_homestory_815701001_2_dialog_content = "Eu estava apenas admirando as flores<sprite=emo_huaduo size=60 />!",
  str_homestory_815701001_3_dialog_content = "Eu definitivamente não caí por perto e acabei descansando aqui...",
  str_homestory_815701001_4_dialog_content = "Você caiu? Você está machucado?",
  str_homestory_815701001_5_dialog_content = "Estou acostumado com isso... Ah, eu me entreguei?",
  str_homestory_815701001_6_dialog_content = "Sanae... Você é muito fácil de ler.",
  str_homestory_815701001_7_dialog_content = "Por favor, não me demita por minha falta de jeito...",
  str_homestory_815701001_8_dialog_content = "Isso não vai acontecer, mas... o que estava em sua mente?",
  str_homestory_815701001_9_dialog_content = "Se você tiver alguma ideia sobre o desenvolvimento do Cloud Gardens, por favor me avise!",
  str_homestory_815701001_10_dialog_content = "eu não... realmente...",
  str_homestory_815701001_11_dialog_content = "Eu não estava me perguntando por que você decidiu cultivar flores neste local preciso!",
  str_homestory_815701001_12_dialog_content = "Bem, isso não é nada suspeito...",
  str_homestory_815701001_13_dialog_content = "Hã?",
  str_homestory_815701001_14_dialog_content = "Enterrando sua saudade aqui em forma de flores em memória de sua amada...",
  str_homestory_815701001_15_dialog_content = "Ah, eu não saberia nada sobre isso...",
  str_homestory_815701001_16_option_content = "Amado?",
  str_homestory_815701001_17_dialog_content = "Sim! Alguém que te conheceu por coincidência...",
  str_homestory_815701001_18_dialog_content = "Alguém que rompeu todas as restrições mundanas e veio para o seu lado...",
  str_homestory_815701001_19_dialog_content = "Alguém que ofereceu conselhos sobre sua jornada no Astra...",
  str_homestory_815701001_20_dialog_content = "Oh, ela deve ter sido uma menina muito boa!",
  str_homestory_815701001_21_dialog_content = "As flores deste jardim devem ser as favoritas dela, certo?",
  str_homestory_815701001_22_option_content = "Enterrando minha saudade?",
  str_homestory_815701001_23_dialog_content = "Alguém que deixou tudo para trás para vir até você...",
  str_homestory_815701001_24_dialog_content = "Alguém que olhou por cima de seus ombros na jornada...",
  str_homestory_815701001_25_dialog_content = "Mas agora é impossível para vocês dois se reunirem por causa de algumas restrições mundanas.",
  str_homestory_815701001_26_dialog_content = "Então, para mostrar o quanto você sente falta dela...",
  str_homestory_815701001_27_dialog_content = "Você plantou as flores favoritas dela no jardim!",
  str_homestory_815701001_28_dialog_content = "Não sei do que você tá falando...",
  str_homestory_815701001_29_dialog_content = "É assim mesmo...<sprite=emo_sikao size=60 />!",
  str_homestory_815701001_30_dialog_content = "Eu deveria saber. Esta informação não pode ser facilmente divulgada a um estranho como eu...",
  str_homestory_815701001_31_dialog_content = "Se você está se perguntando por que há canteiros de flores aqui...",
  str_homestory_815701001_32_dialog_content = "Minha resposta seria que eles estão lá como parte do projeto paisagístico.",
  str_homestory_815701001_33_dialog_content = "Projeto paisagístico? Que termo complicado...",
  str_homestory_815701001_34_dialog_content = "Vice tem muito conhecimento sobre desenho de engenharia, então ela me deu muitos conselhos quando projetamos o Cloud Gardens.",
  str_homestory_815701001_35_dialog_content = "Gabriel, Nikinis e Jola sabem muito sobre plantas...",
  str_homestory_815701001_36_dialog_content = "Pedi-lhes conselhos sobre quais plantas ficam bem em jardins.",
  str_homestory_815701001_37_dialog_content = "É um esforço conjunto que Cloud Gardens tenha a aparência que tem hoje.",
  str_homestory_815701001_38_dialog_content = "Esforço conjunto...",
  str_homestory_815701001_39_dialog_content = "Exatamente! Além disso, não se considere um \"estranho\", Sanae.",
  str_homestory_815701001_40_dialog_content = "Você se tornou um de nós desde o momento em que chegou aqui!",
  str_homestory_815701001_41_dialog_content = "Ahh... Ahh...",
  str_homestory_815701001_42_dialog_content = "Ah, por favor, não chore. Eu não quis te culpar...",
  str_homestory_815701001_43_dialog_content = "Você é realmente uma boa pessoa, Sr. Navegador...",
  str_homestory_815701001_44_dialog_content = "Eu também... farei minhas contribuições.",
  str_homestory_815701001_45_dialog_content = "Tive uma ideia! Deixe-me cuidar deste \"Canteiro de flores de amor<sprite=emo_aixin size=60 />\" de agora em diante!",
  str_homestory_815601001_0_dialog_content = "Eu não posso acreditar em meus olhos!",
  str_homestory_815601001_1_dialog_content = "Nina acabou de montar um cavalo de balanço?",
  str_homestory_815601001_2_dialog_content = "Um cavalo de balanço?",
  str_homestory_815601001_3_dialog_content = "Achei que você odiasse aqueles brinquedos.",
  str_homestory_815601001_4_dialog_content = "Eu também não disse que gostava...",
  str_homestory_815601001_5_dialog_content = "Eu estava cansado de andar e precisava de um lugar para descansar.",
  str_homestory_815601001_6_dialog_content = "Jamais me interessaria por uma coisa dessas.",
  str_homestory_815601001_7_dialog_content = "Bom ponto...",
  str_homestory_815601001_8_dialog_content = "O ponto não deveria ser \"estava cansado de andar e não tinha onde descansar\"?",
  str_homestory_815601001_9_option_content = "Desculpar-se",
  str_homestory_815601001_10_dialog_content = "Oh, sinto muito!",
  str_homestory_815601001_11_dialog_content = "Devo colocar mais alguns bancos de pedra por perto?",
  str_homestory_815601001_12_dialog_content = "Banco de pedra? Hahaha, você deve estar brincando, certo?",
  str_homestory_815601001_13_dialog_content = "Ninguém vai realmente sentar em algo tão difícil, certo?",
  str_homestory_815601001_14_dialog_content = "Se ele gosta de você...",
  str_homestory_815601001_15_dialog_content = "Atenciosamente, podemos projetar alguns assentos de visitantes bonitos e confortáveis para você.",
  str_homestory_815601001_16_dialog_content = "Contanto que você me diga o que é tão divertido sobre essa coisa de madeira...",
  str_homestory_815601001_17_option_content = "Pergunte sobre o humor dela",
  str_homestory_815601001_18_dialog_content = "Parece que você esteve em muitos lugares hoje, Nina.",
  str_homestory_815601001_19_dialog_content = "Gostaria de saber se meu lugar lhe serve bem, senhorita?",
  str_homestory_815601001_20_dialog_content = "Agora que você perguntou, não me culpe por ser dura.",
  str_homestory_815601001_21_dialog_content = "Este lugar está no meio do nada!",
  str_homestory_815601001_22_dialog_content = "Não posso discutir com isso...",
  str_homestory_815601001_23_dialog_content = "Mas a paisagem aqui é muito bonita. Posso adicioná-lo à minha lista de desejos de férias.",
  str_homestory_815601001_24_dialog_content = "Você deve saber que meus comentários podem influenciar muitas pessoas se forem publicados no jornal Umbraton.",
  str_homestory_815601001_25_dialog_content = "Desde que você me explique o que há de tão interessante nessa coisa de madeira...",
  str_homestory_815601001_26_dialog_content = "Eu pensei que você não estava interessado em cavalos de balanço.",
  str_homestory_815601001_27_dialog_content = "... Eu mudei de ideia.",
  str_homestory_815601001_28_dialog_content = "Saber o que todo mundo gosta é parte do meu trabalho.",
  str_homestory_815601001_29_dialog_content = "Esses blocos instáveis de madeira obviamente balançarão quando você tentar se sentar neles.",
  str_homestory_815601001_30_dialog_content = "Então você nunca andou em um cavalo de balanço?",
  str_homestory_815601001_31_dialog_content = "Como isso é possível?",
  str_homestory_815601001_32_dialog_content = "Mas... toda a experiência de montar um cavalo de balanço é essa sensação de balanço.",
  str_homestory_815601001_33_dialog_content = "Ah, entendo... Não entenda errado! Eu já sabia daquilo!",
  str_homestory_815601001_34_dialog_content = "Foi apenas, apenas um teste para você.",
  str_homestory_815601001_35_option_content = "Acredite nela",
  str_homestory_815601001_36_dialog_content = "Então devo ter passado...",
  str_homestory_815601001_37_dialog_content = "Sim! Você é mais inteligente do que parece, PlayerName. Haha.",
  str_homestory_815601001_38_option_content = "Não acredite nela",
  str_homestory_815601001_39_dialog_content = "Eu não compro.",
  str_homestory_815601001_40_dialog_content = "PlayerName é tão tolo! Hum.",
  str_homestory_815601001_41_dialog_content = "...",
  str_homestory_815601001_42_dialog_content = "Mas...",
  str_homestory_815601001_43_dialog_content = "Por que alguém montaria cavalos de madeira em vez de cavalos de verdade?",
  str_homestory_815601001_44_dialog_content = "não sei ao certo...",
  str_homestory_815601001_45_dialog_content = "Mas os cavalos de balanço oferecem a sua própria diversão e são muito mais seguros...",
  str_homestory_815601001_46_dialog_content = "E acho que nem todo mundo pode andar em cavalos de verdade.",
  str_homestory_815601001_47_dialog_content = "Quer dizer... Eles năo podem comprar os verdadeiros?<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "Temo que algumas pessoas não possam nem comprar um cavalo de balanço.",
  str_homestory_815601001_49_dialog_content = "...",
  str_homestory_815601001_50_dialog_content = "... Já tomei minha decisão!",
  str_homestory_815601001_51_dialog_content = "Do quê?",
  str_homestory_815601001_52_dialog_content = "Eu quero aprender design de carpintaria e fazer cavalos de balanço mais interessantes...",
  str_homestory_815601001_53_dialog_content = "E enviá-los para as crianças que precisam deles!",
  str_homestory_810401001_0_dialog_content = "Alvorecer?",
  str_homestory_810401001_1_dialog_content = "Esses passos...",
  str_homestory_810401001_2_dialog_content = "Poderia ser PlayerName?",
  str_homestory_810401001_3_dialog_content = "Ah! Você pode reconhecer meus passos?",
  str_homestory_810401001_4_dialog_content = "Sim!<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "Há muito mais sons diferentes aqui do que no Colossus...",
  str_homestory_810401001_6_dialog_content = "Mas ainda posso escolher aqueles feitos por pessoas conhecidas.",
  str_homestory_810401001_7_dialog_content = "Curti PlayerName e Eva. Vocês têm um jeito especial de andar.",
  str_homestory_810401001_8_dialog_content = "Um jeito especial de andar...",
  str_homestory_810401001_9_option_content = "Pergunte sobre o meu",
  str_homestory_810401001_10_dialog_content = "Você está sempre com pressa, mas depois se torna cauteloso ao se aproximar de mim.",
  str_homestory_810401001_11_dialog_content = "Posso não deixar claro para você...",
  str_homestory_810401001_12_dialog_content = "De qualquer forma, eu só sei que este é você!",
  str_homestory_810401001_13_dialog_content = "Ah! Mais uma coisa...",
  str_homestory_810401001_14_dialog_content = "Quando você chega perto, eu me sinto feliz.",
  str_homestory_810401001_15_dialog_content = "Este sentimento feliz também me diz que PlayerName está vindo.",
  str_homestory_810401001_16_option_content = "Pergunte sobre Eva",
  str_homestory_810401001_17_dialog_content = "Eva tem passos muito fofos!",
  str_homestory_810401001_18_dialog_content = "... Bonito ... passos?",
  str_homestory_810401001_19_dialog_content = "Sim! Tudo sobre Eva é fofo<sprite=emo_aixin size=60 />.",
  str_homestory_810401001_20_dialog_content = "Err...",
  str_homestory_810401001_21_dialog_content = "Bem, deixe-me colocar desta forma. O físico de Eve é muito especial...",
  str_homestory_810401001_22_dialog_content = "Ela quase não faz barulho quando anda.",
  str_homestory_810401001_23_dialog_content = "Mas quando Eve se aproxima, eu me sinto feliz.",
  str_homestory_810401001_24_dialog_content = "Este sentimento feliz me diz que Eva está chegando.",
  str_homestory_810401001_25_dialog_content = "Então é isso...",
  str_homestory_810401001_26_dialog_content = "Você é incrível!",
  str_homestory_810401001_27_dialog_content = "Acho que porque não posso ver, minha audição se tornou muito aguçada.",
  str_homestory_810401001_28_dialog_content = "Ah! A propósito...",
  str_homestory_810401001_29_dialog_content = "Que tal Sinsa?",
  str_homestory_810401001_30_dialog_content = "Acredito que você esteja familiarizado com ele. Como soam os passos de Sinsa?",
  str_homestory_810401001_31_dialog_content = "Bem, eu tenho uma maneira mais fácil de reconhecê-lo.",
  str_homestory_810401001_32_dialog_content = "O que foi?",
  str_homestory_810401001_33_dialog_content = "Ele é fedido.",
  str_homestory_810401001_34_dialog_content = "...?",
  str_homestory_810401001_35_dialog_content = "Ele está em constante movimento... Acho que transpira muito.",
  str_homestory_810401001_36_dialog_content = "Entendo...",
  str_homestory_810401001_37_dialog_content = "Ele definitivamente não é o homem mais fedorento de Rediesel Wrench...",
  str_homestory_810401001_38_dialog_content = "Mas ele é certamente mais fedido do que você e Eve.",
  str_homestory_810401001_39_dialog_content = "Estou feliz que você não cheira como ele, Navegador.",
  str_homestory_810401001_40_dialog_content = "Er... Obrigado...",
  str_homestory_810401001_41_dialog_content = "Mas por que... Por que não consigo notar o cheiro de Sinsa?",
  str_homestory_810401001_42_dialog_content = "Você não pode?",
  str_homestory_810401001_43_dialog_content = "Estou tão chateado por Eve passar muito tempo com ele...<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "... que eu inventei aquele odor?",
  str_homestory_810401001_45_dialog_content = "... Deve ser isso!",
  str_homestory_810401001_46_dialog_content = "... Qualquer que seja! Tenho certeza que ele é muito fedido.",
  str_homestory_810401001_47_dialog_content = "Fedorento, fedorento Sinsa<sprite=emo_kulou size=60 />!",
  str_homestory_809001001_0_dialog_content = "Bárbara?",
  str_homestory_809001001_1_dialog_content = "O amor é apenas uma bela mentira? ♪",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />O verdadeiro amor só surge quando o combustível acaba. ♪",
  str_homestory_809001001_3_dialog_content = "Ei, ei. O único amor. ♪",
  str_homestory_809001001_4_dialog_content = "Você está praticando seu novo single?",
  str_homestory_809001001_5_dialog_content = "Heheh, novo single? Não!",
  str_homestory_809001001_6_dialog_content = "Estou me preparando para um novo álbum!",
  str_homestory_809001001_7_option_content = "Um álbum?",
  str_homestory_809001001_8_dialog_content = "Um álbum é um disco com muitas músicas incluídas?",
  str_homestory_809001001_9_dialog_content = "Isso mesmo.",
  str_homestory_809001001_10_option_content = "Melhor que o da Regina?",
  str_homestory_809001001_11_dialog_content = "Uh-uh! É claro!",
  str_homestory_809001001_12_dialog_content = "Eu tenho que dar o meu melhor absoluto para as vendas deste álbum!",
  str_homestory_809001001_13_dialog_content = "Você é realmente trabalhador.",
  str_homestory_809001001_14_dialog_content = "Certamente. Afinal, novos gêneros musicais estão surgindo em todos os lugares...",
  str_homestory_809001001_15_dialog_content = "Eu não posso ficar para trás!",
  str_homestory_809001001_16_dialog_content = "Você está preocupado em perder popularidade e apoio?",
  str_homestory_809001001_17_dialog_content = "Perdendo popularidade e apoio? Nunca!",
  str_homestory_809001001_18_dialog_content = "Adoro ver diferentes tipos de música e músicos florescerem juntos.",
  str_homestory_809001001_19_dialog_content = "Então o que você quer dizer com \"não pode ficar para trás\"?",
  str_homestory_809001001_20_dialog_content = "Isso significa apenas que devo trabalhar mais<sprite=emo_yinfu size=60 />.",
  str_homestory_809001001_21_dialog_content = "Eu preciso progredir junto com novos artistas e trazer mais músicas incríveis para todos!",
  str_homestory_809001001_22_dialog_content = "Eu odeio ficar para trás!",
  str_homestory_809001001_23_dialog_content = "Isso é inspirador!",
  str_homestory_809001001_24_dialog_content = "Hmm... Não estou muito preocupado com minha popularidade.",
  str_homestory_809001001_25_dialog_content = "Mas se os fãs que conheço bem me deixaram por outros cantores...",
  str_homestory_809001001_26_dialog_content = "Eu ainda me sentiria um pouco frustrado!",
  str_homestory_809001001_27_dialog_content = "Outros cantores... Você está falando da Regina?",
  str_homestory_809001001_28_dialog_content = "PlayerName... Isso é muito grosseiro de sua parte!",
  str_homestory_809001001_29_dialog_content = "Você se importa com a música de Regina, não é?",
  str_homestory_809001001_30_dialog_content = "Como devo colocar?",
  str_homestory_809001001_31_dialog_content = "Seria uma mentira se eu dissesse que não me importo<sprite=emo_tanqi size=60 />...",
  str_homestory_809001001_32_dialog_content = "Er... É seguro dizer que...",
  str_homestory_809001001_33_dialog_content = "Estou ouvindo a música dela para promover a diversidade.",
  str_homestory_809001001_34_dialog_content = "Hmm... Ela pode não ter tantos fãs quanto eu, mas seus apoiadores são muito leais.",
  str_homestory_809001001_35_dialog_content = "Os músicos falam com a qualidade de suas músicas, mas estou bastante curioso...",
  str_homestory_809001001_36_dialog_content = "Como ela está mantendo seus fãs por perto?",
  str_homestory_809001001_37_dialog_content = "Por que não perguntar a Regina se você realmente quer saber?",
  str_homestory_809001001_38_dialog_content = "Hmm...",
  str_homestory_809001001_39_dialog_content = "Acho que vou seguir seu conselho, PlayerName...",
  str_homestory_809001001_40_dialog_content = "Fazer uma pergunta a ela não é grande coisa!",
  str_homestory_809001001_41_dialog_content = "Hmm... Em pelo menos 20 anos<sprite=emo_emo size=60 />!",
  str_homestory_809001001_42_dialog_content = "... Melhor apenas dizer que você nunca vai perguntar a ela!",
  str_homestory_807001001_0_dialog_content = "Leona...",
  str_homestory_807001001_1_dialog_content = "Ei, garoto.",
  str_homestory_807001001_2_dialog_content = "O que foi?",
  str_homestory_807001001_3_dialog_content = "Desculpe, eu realmente não tenho tempo agora.",
  str_homestory_807001001_4_dialog_content = "Como você pode ver, estou ocupado aliviando minhas emoções negativas.",
  str_homestory_807001001_5_dialog_content = "Ah! Eu não sabia que socar sacos de areia é algo que pode ajudar.",
  str_homestory_807001001_6_dialog_content = "Muito eficaz<sprite=emo_baiyan size=60 />.",
  str_homestory_807001001_7_dialog_content = "Você nunca ouviu?",
  str_homestory_807001001_8_dialog_content = "O exercício é uma boa maneira de combater as emoções negativas.",
  str_homestory_807001001_9_dialog_content = "Eu ouvi isso antes.",
  str_homestory_807001001_10_dialog_content = "Falando de suas emoções negativas...",
  str_homestory_807001001_11_option_content = "Qual é a causa?",
  str_homestory_807001001_12_dialog_content = "Sem causa específica.",
  str_homestory_807001001_13_option_content = "Você se sente melhor agora?",
  str_homestory_807001001_14_dialog_content = "É, mais ou menos.",
  str_homestory_807001001_15_dialog_content = "Você pode ver as emoções negativas como um nó dentro do seu corpo.",
  str_homestory_807001001_16_dialog_content = "Um nó? Como um nó em uma corda?",
  str_homestory_807001001_17_dialog_content = "Tipo de.",
  str_homestory_807001001_18_dialog_content = "Quando você percebe que está de mau humor...",
  str_homestory_807001001_19_dialog_content = "Você precisa fazer algo que você gosta para se livrar disso.",
  str_homestory_807001001_20_dialog_content = "Qualquer coisa que relaxe você faria.",
  str_homestory_807001001_21_dialog_content = "Para mim, esta é a melhor maneira de relaxar. Isso me faz sentir como se estivesse em uma batalha.",
  str_homestory_807001001_22_dialog_content = "Quando sentimentos negativos se enraízam em seu coração, esse nó fica cada vez mais difícil de desatar.",
  str_homestory_807001001_23_dialog_content = "Pode até se tornar uma ameaça à sua saúde.",
  str_homestory_807001001_24_dialog_content = "Levei muito tempo para aprender isso.",
  str_homestory_807001001_25_dialog_content = "Quando seu coração está cego pelo ódio...",
  str_homestory_807001001_26_dialog_content = "... Desculpe. eu discordo...",
  str_homestory_807001001_27_dialog_content = "Huh... você está absolutamente certo.",
  str_homestory_807001001_28_dialog_content = "Experimente da próxima vez.",
  str_homestory_807001001_29_dialog_content = "Sem problemas!",
  str_homestory_807001001_30_dialog_content = "Talvez Sharona estivesse aqui socando sacos de areia pelo mesmo motivo da última vez.",
  str_homestory_807001001_31_dialog_content = "Você quer dizer Sharona?",
  str_homestory_807001001_32_dialog_content = "Sharona deu um soco nesse saco de areia?",
  str_homestory_807001001_33_dialog_content = "Ah? Estou brincando!",
  str_homestory_807001001_34_dialog_content = "(Ah oh... eu provavelmente não deveria ter dito isso...)",
  str_homestory_807001001_35_dialog_content = "...",
  str_homestory_807001001_36_dialog_content = "Leona, qual é o problema?",
  str_homestory_807001001_37_dialog_content = "Heheh. Estou fazendo a mesma coisa que minha querida irmã novamente.",
  str_homestory_807001001_38_dialog_content = "Para não queimar este lugar <sprite=emo_nuhuo size=60 />baixa...",
  str_homestory_807001001_39_dialog_content = "Eu provavelmente deveria ir para Umbraton imediatamente.",
  str_homestory_807001001_40_dialog_content = "Tchau, garoto.",
  str_homestory_807001001_41_dialog_content = "H-Hum...",
  str_homestory_807001001_42_dialog_content = "Vejo você em breve...",
  str_homestory_811501001_0_dialog_content = "Naroxel!",
  str_homestory_811501001_1_dialog_content = "Caro PlayerName.",
  str_homestory_811501001_2_dialog_content = "Deve ser a força da natureza que nos guiou aqui mais uma vez.",
  str_homestory_811501001_3_dialog_content = "Você está conversando com Olive e Palm?",
  str_homestory_811501001_4_dialog_content = "É!",
  str_homestory_811501001_5_dialog_content = "Estou surpreso que você ainda se lembre dos nomes deles.",
  str_homestory_811501001_6_dialog_content = "Eles estão muito felizes.",
  str_homestory_811501001_7_dialog_content = "Não é nada...",
  str_homestory_811501001_8_dialog_content = "Estou cheio de emoções vendo o Eraveil subir novamente<sprite=emo_pugongying size=60 />.",
  str_homestory_811501001_9_dialog_content = "Cloud Gardens é realmente próspero e bonito agora.",
  str_homestory_811501001_10_dialog_content = "Graças à benção da natureza e seu trabalho duro, PlayerName.",
  str_homestory_811501001_11_dialog_content = "No entanto... estou um pouco preocupado com você.",
  str_homestory_811501001_12_dialog_content = "Você está bem depois do que aconteceu ultimamente?",
  str_homestory_811501001_13_option_content = "Aceno com a cabeça",
  str_homestory_811501001_14_dialog_content = "Estou feliz em compartilhar este lugar com todos vocês.",
  str_homestory_811501001_15_dialog_content = "Mas às vezes me sinto estressado por causa das altas expectativas.",
  str_homestory_811501001_16_option_content = "Agite a cabeça",
  str_homestory_811501001_17_dialog_content = "não estou de mau humor...",
  str_homestory_811501001_18_dialog_content = "Mas me sinto ansiosa e estressada.",
  str_homestory_811501001_19_dialog_content = "Entendi.",
  str_homestory_811501001_20_dialog_content = "Você gostaria de relaxar um pouco comigo?",
  str_homestory_811501001_21_dialog_content = "OK.",
  str_homestory_811501001_22_dialog_content = "Vamos tentar este exercício de respiração.",
  str_homestory_811501001_23_dialog_content = "Exercício de respiração?",
  str_homestory_811501001_24_dialog_content = "Sim.",
  str_homestory_811501001_25_dialog_content = "Isso irá ajudá-lo a equilibrar a energia dentro de seu corpo.",
  str_homestory_811501001_26_dialog_content = "Para simplificar...",
  str_homestory_811501001_27_dialog_content = "Mantém nossa energia interior fluindo.",
  str_homestory_811501001_28_dialog_content = "Entendido! Começaremos?",
  str_homestory_811501001_29_dialog_content = "Claro.",
  str_homestory_811501001_30_dialog_content = "Relaxe os ombros. Respire fundo.",
  str_homestory_811501001_31_dialog_content = "Muito bom. Agora... segure seu nariz.",
  str_homestory_811501001_32_dialog_content = "(Segure o nariz... Hmm...)",
  str_homestory_811501001_33_dialog_content = "Pressione a asa direita do nariz e inspire pela narina esquerda.",
  str_homestory_811501001_34_dialog_content = "Em seguida, pressione a asa esquerda do nariz e expire pela narina direita...",
  str_homestory_811501001_35_dialog_content = "(Inalar exalar...)",
  str_homestory_811501001_36_dialog_content = "Bem desse jeito. Ajuste lentamente sua respiração.",
  str_homestory_811501001_37_dialog_content = "Inspire e expire em equilíbrio...",
  str_homestory_811501001_38_dialog_content = "Em breve sentiremos nosso corpo e mente relaxados através deste exercício de respiração.",
  str_homestory_811501001_39_dialog_content = "Sim... Eu me sinto muito calmo agora.",
  str_homestory_811501001_40_dialog_content = "na verdade estou com um pouco de sono<sprite=emo_kun size=60 />...",
  str_homestory_811501001_41_dialog_content = "Hehehe.",
  str_homestory_811501001_42_dialog_content = "Este exercício de respiração pode nos trazer um alívio e um bom sono.",
  str_homestory_811501001_43_dialog_content = "Sinta-se à vontade para tentar novamente antes de dormir.",
  str_homestory_811501001_44_dialog_content = "Você pode se sentir ainda melhor se seus olhos estiverem fechados durante este exercício.",
  str_homestory_811501001_45_dialog_content = "Hmm. Vou tentar me lembrar disso.",
  str_homestory_811501001_46_dialog_content = "Obrigado, Naroxel!",
  str_homestory_803302001_0_dialog_content = "Olá, Vice.",
  str_homestory_803302001_1_dialog_content = "PlayerName! Você está livre no momento?",
  str_homestory_803302001_2_dialog_content = "Claro. O que você precisa?",
  str_homestory_803302001_3_dialog_content = "Enquanto caminhava pela margem do rio, notei algo na água.",
  str_homestory_803302001_4_dialog_content = "Tentei agarrá-lo, mas não consegui. Parecia uma espécie de planta.",
  str_homestory_803302001_5_dialog_content = "Se quiser, pode ir conferir.",
  str_homestory_803302001_6_dialog_content = "Claro, sem problemas.",
  str_homestory_803303001_0_dialog_content = "O que está fazendo?",
  str_homestory_803303001_1_dialog_content = "Estou pensando em como posso pescar aquela coisa de lá...",
  str_homestory_803303001_2_dialog_content = "O que foi?",
  str_homestory_803303001_3_dialog_content = "Há algo peculiar no rio que despertou minha curiosidade<sprite=emo_sikao size=60 />.",
  str_homestory_803303001_4_dialog_content = "Mas eu não consigo, não importa o quanto eu tente... e minhas mãos estão doloridas agora.",
  str_homestory_803303001_5_dialog_content = "Você pode me ajudar? Está ali.",
  str_homestory_803303001_6_dialog_content = "Ok, vou dar uma chance.",
  str_homestory_803304001_0_dialog_content = "Me procurando?",
  str_homestory_803304001_1_dialog_content = "Ei, como você sabia que eu estava procurando por você?",
  str_homestory_803304001_2_dialog_content = "Achei algo interessante!<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "Não outra aranha gigante ou grilo dançando, certo?",
  str_homestory_803304001_4_dialog_content = "Não, é um modelo para móveis novos!",
  str_homestory_803304001_5_dialog_content = "Mas está debaixo d'água e difícil de desenterrar.",
  str_homestory_803304001_6_dialog_content = "Bem, deixe comigo. Eu sou bom em coisas assim.",
  str_homestory_803304001_7_dialog_content = "Está ali! Deixe-me te mostrar!",
  str_homestory_809301001_0_dialog_content = "Aquele olhar em seus olhos...",
  str_homestory_809301001_1_dialog_content = "Posso te ajudar?",
  str_homestory_809301001_2_dialog_content = "Você cresceu desde a última vez que nos encontramos. Você sabia que eu queria algo de você.",
  str_homestory_809301001_3_dialog_content = "Eu apenas senti o cabelo se arrepiar nas minhas costas como se estivesse sendo observado...",
  str_homestory_809301001_4_dialog_content = "Olhei para cima e encontrei você me encarando.",
  str_homestory_809301001_5_dialog_content = "\"Olhou para cima\"? Acho que você não cresceu tanto quanto eu pensava.",
  str_homestory_809301001_6_option_content = "Eu cresci!",
  str_homestory_809301001_7_dialog_content = "Sim? Como é que eu não poderia dizer? Quer ir ao meu laboratório?",
  str_homestory_809301001_8_dialog_content = "Posso abrir-te para ver se os teus ossos cresceram.",
  str_homestory_809301001_9_option_content = "Tudo bem...",
  str_homestory_809301001_10_dialog_content = "Desistir já? Eu deveria ajudá-lo. Quer ir ao meu laboratório?",
  str_homestory_809301001_11_dialog_content = "Posso abri-lo e ver se seus ossos ainda podem crescer.",
  str_homestory_809301001_12_dialog_content = "U-hum, isso não será necessário...",
  str_homestory_809301001_13_dialog_content = "Não se preocupe. Depois da minha dissecação, farei um plano para você crescer mais alto.",
  str_homestory_809301001_14_dialog_content = "Está bem. Vamos deixar para a natureza por enquanto.",
  str_homestory_809301001_15_dialog_content = "Natureza? Você está de brincadeira?",
  str_homestory_809301001_16_dialog_content = "Posso dizer que muitas das árvores em Cloud Gardens foram geneticamente modificadas.",
  str_homestory_809301001_17_dialog_content = "E isso foi feito por...",
  str_homestory_809301001_18_dialog_content = "Emendar as sementes de diferentes plantas em variedades novas e únicas.",
  str_homestory_809301001_19_dialog_content = "Você poderia dizer isso só de olhar?",
  str_homestory_809301001_20_dialog_content = "Você esqueceu que sou um oficial de tecnologia da Illumina especializado em biotecnologia?",
  str_homestory_809301001_21_dialog_content = "Fiz mais experimentos de bioengenharia como esse do que posso contar.",
  str_homestory_809301001_22_dialog_content = "Mas eu não esperava que você tivesse um talento especial para esse tipo de tecnologia.",
  str_homestory_809301001_23_dialog_content = "Eu estava apenas brincando, então não é nada de especial.",
  str_homestory_809301001_24_dialog_content = "Sim, eu posso dizer.",
  str_homestory_809301001_25_dialog_content = "...",
  str_homestory_809301001_26_dialog_content = "Você não pode ter esse sucesso sem falhar noventa e nove vezes antes.",
  str_homestory_809301001_27_dialog_content = "Isso é o que eu percebi de todo o meu esforço. Como por você...",
  str_homestory_809301001_28_dialog_content = "Para obter essa semente ultra-rara, você precisa fazer isso e aquilo.",
  str_homestory_809301001_29_dialog_content = "\"Isso e aquilo\"? O que você quer dizer?",
  str_homestory_809301001_30_dialog_content = "É difícil para você ficar sem uma base científica. Conversamos depois.",
  str_homestory_809301001_31_dialog_content = "Bem, podemos fazê-lo agora.",
  str_homestory_809301001_32_dialog_content = "Agora? Deixe-me fechar os olhos primeiro.",
  str_homestory_809301001_33_dialog_content = "...",
  str_homestory_809301001_34_dialog_content = "Oh, espere, eu quase esqueci o que eu queria te perguntar.",
  str_homestory_809301001_35_dialog_content = "Você pode mudar meu quarto para um dormitório com muitas garotas bonitas?",
  str_homestory_809301001_36_option_content = "Concordo",
  str_homestory_809301001_37_dialog_content = "Eu posso, mas você deve discutir isso com todos primeiro.",
  str_homestory_809301001_38_option_content = "Rejeitar",
  str_homestory_809301001_39_dialog_content = "Não infrinjo o direito de ninguém de viver onde quiser.",
  str_homestory_809301001_40_dialog_content = "Mas tudo bem se você pudesse resolver isso com eles.",
  str_homestory_809301001_41_dialog_content = "Isso soa como problema.",
  str_homestory_809301001_42_dialog_content = "Embora valha a pena tentar. Se não, 100 tentativas.",
  str_homestory_809301001_43_dialog_content = "(Ficando com a mesma atitude para isso também?)",
  str_homestory_815702001_0_dialog_content = "O que você tá olhando?",
  str_homestory_815702001_1_dialog_content = "Ahhhhhhhhhh!",
  str_homestory_815702001_2_dialog_content = "Desculpe, eu assustei você de novo?",
  str_homestory_815702001_3_dialog_content = "(Mas por que eu disse \"de novo\"?)",
  str_homestory_815702001_4_dialog_content = "Não, eu estava apenas no fundo do meu pensamento.",
  str_homestory_815702001_5_dialog_content = "Então eu não te vi aqui.",
  str_homestory_815702001_6_dialog_content = "Eu que deveria me desculpar.",
  str_homestory_815702001_7_dialog_content = "Está tudo bem, então não se preocupe.",
  str_homestory_815702001_8_dialog_content = "Você acabou de vir do rio, certo? Não me diga que você estava pensando em...",
  str_homestory_815702001_9_option_content = "Pescaria?",
  str_homestory_815702001_10_dialog_content = "Pesca... Isso não requer equipamentos caros?",
  str_homestory_815702001_11_dialog_content = "Esse pensamento, uh, nunca passou pela minha cabeça...",
  str_homestory_815702001_12_option_content = "Natação?",
  str_homestory_815702001_13_dialog_content = "Nadar... Você não tem que usar um terno colante para isso?",
  str_homestory_815702001_14_dialog_content = "Eu me sentiria um pouco envergonhado.",
  str_homestory_815702001_15_dialog_content = "Na verdade, eu estava pensando...",
  str_homestory_815702001_16_dialog_content = "Os fazendeiros de Eraveil trabalharam tanto quanto os de Cloud Island?",
  str_homestory_815702001_17_dialog_content = "Também não tenho certeza, mas acho que é Eraveil ou Cloud Island...",
  str_homestory_815702001_18_dialog_content = "Eles ficam todos em êxtase quando é uma colheita abundante.",
  str_homestory_815702001_19_dialog_content = "Então, o que trouxe isso?",
  str_homestory_815702001_20_dialog_content = "Bem, acabei de encontrar um objeto brilhante na beira do rio que parecia uma moeda<sprite=emo_baiyebi size=60 />.",
  str_homestory_815702001_21_dialog_content = "Moedas significam comércio, comércio significa comida e comida significa... agricultor!",
  str_homestory_815702001_22_dialog_content = "Você junta tudo assim?",
  str_homestory_815702001_23_dialog_content = "Ah, por favor, não fique chateado!",
  str_homestory_815702001_24_dialog_content = "Nunca tive a intenção de ficar com a moeda para mim.",
  str_homestory_815702001_25_dialog_content = "Eu vou te dar a moeda agora...",
  str_homestory_815702001_26_dialog_content = "Está tudo bem, vá com calma.",
  str_homestory_815702001_27_dialog_content = "Deixa eu ver onde coloquei...",
  str_homestory_815702001_28_dialog_content = "Foi-se...",
  str_homestory_815702001_29_dialog_content = "Ah!",
  str_homestory_815702001_30_dialog_content = "O que foi?",
  str_homestory_815702001_31_dialog_content = "Lembro-me de ouvir um respingo quando saí da margem do rio mais cedo.",
  str_homestory_815702001_32_dialog_content = "Devo tê-lo deixado cair acidentalmente na água!",
  str_homestory_815702001_33_dialog_content = "Está tudo bem. Eu vou pescar.",
  str_homestory_815702001_34_dialog_content = "Ah, você vai? R-Sério? Obrigada!",
  str_homestory_815602001_0_dialog_content = "O que você está procurando?",
  str_homestory_815602001_1_dialog_content = "Ei, venha aqui!",
  str_homestory_815602001_2_dialog_content = "Nina?",
  str_homestory_815602001_3_dialog_content = "Se não estou errado, você estava procurando por algo.",
  str_homestory_815602001_4_dialog_content = "Sim.",
  str_homestory_815602001_5_dialog_content = "Você viu uma coisinha redonda?",
  str_homestory_815602001_6_dialog_content = "Você pode ser mais preciso?",
  str_homestory_815602001_7_dialog_content = "Bem... Aqui está a coisa.",
  str_homestory_815602001_8_dialog_content = "Eu nunca tinha visto algo com um padrão assim...",
  str_homestory_815602001_9_dialog_content = "É por isso que eu apertei com força na minha mão!",
  str_homestory_815602001_10_dialog_content = "Mas... escorregou da minha mão e caiu na água quando afrouxei o aperto...",
  str_homestory_815602001_11_dialog_content = "Espere, por que eu sinto que você está falando sobre—",
  str_homestory_815602001_12_dialog_content = "Espere, deixe-me terminar.",
  str_homestory_815602001_13_dialog_content = "Então descobri um padrão estranho na palma da minha mão!",
  str_homestory_815602001_14_option_content = "Lumina mutante?!",
  str_homestory_815602001_15_dialog_content = "Você tem lido muitos romances de fantasia?",
  str_homestory_815602001_16_option_content = "Você vai se transformar?!",
  str_homestory_815602001_17_dialog_content = "Do que diabos você está falando?",
  str_homestory_815602001_18_dialog_content = "É porque aquele objeto tinha uma forma e um padrão únicos!",
  str_homestory_815602001_19_dialog_content = "Quando o segurei na palma da mão, ficou impresso na minha pele.",
  str_homestory_815602001_20_dialog_content = "Este padrão é um pouco esteticamente agradável...",
  str_homestory_815602001_21_dialog_content = "Pense nisso, se eu fosse desenhar uma peça de roupa com base nesse padrão...",
  str_homestory_815602001_22_dialog_content = "Eu preciso encontrar essa moeda!",
  str_homestory_815602001_23_dialog_content = "Eu sabia que era uma moeda!",
  str_homestory_815602001_24_dialog_content = "Eu ajudo.",
  str_homestory_815602001_25_dialog_content = "T-Obrigado — Ei, espere!<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "Desde que encontrei a moeda em Cloud Gardens... tecnicamente ela pertence a você, certo?",
  str_homestory_815602001_27_dialog_content = "Então, se eu pegasse emprestado de você e estudasse...",
  str_homestory_815602001_28_dialog_content = "Não é um problema. Mas precisamos encontrá-lo primeiro.",
  str_homestory_815602001_29_dialog_content = "Estou surpreso que você concordou com isso tão rapidamente.",
  str_homestory_815602001_30_dialog_content = "Ahem... Não é como se eu realmente QUERIA estudá-lo...",
  str_homestory_815602001_31_dialog_content = "É apenas uma inspiração para o design de roupas, você sabe!",
  str_homestory_815602001_32_dialog_content = "Você sabe, certo?",
  str_homestory_815602001_33_dialog_content = "Eu sei.",
  str_homestory_815602001_34_dialog_content = "Tsc, isso é bom.",
  str_homestory_812601001_0_dialog_content = "O que você pensa sobre?",
  str_homestory_812601001_1_dialog_content = "Bethel?",
  str_homestory_812601001_2_dialog_content = "Parece que você está pensando muito em alguma coisa...",
  str_homestory_812601001_3_dialog_content = "Silêncio...<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "Acabei de lidar com todas aquelas declarações da Guilda. Estou no meio de fazer algumas ponderações.",
  str_homestory_812601001_5_dialog_content = "Sobre o que?",
  str_homestory_812601001_6_dialog_content = "Minha última obra de ficção!",
  str_homestory_812601001_7_dialog_content = "Talvez eu devesse passar por isso com você.",
  str_homestory_812601001_8_dialog_content = "Claro, se eu puder ajudar.",
  str_homestory_812601001_9_dialog_content = "Certo... Escute. Assim é a história...",
  str_homestory_812601001_10_dialog_content = "Os protagonistas masculino e feminino chegam a um rio...",
  str_homestory_812601001_11_dialog_content = "E de repente, o lenço da protagonista feminina cai na água!",
  str_homestory_812601001_12_dialog_content = "Então aqui está a pergunta: o protagonista feminino deve recuperá-lo ou o masculino deve liderar?",
  str_homestory_812601001_13_option_content = "A protagonista feminina",
  str_homestory_812601001_14_dialog_content = "Hmm...",
  str_homestory_812601001_15_dialog_content = "Claro, isso vai mostrar que ela é uma mulher muito independente e capaz.",
  str_homestory_812601001_16_option_content = "O protagonista masculino",
  str_homestory_812601001_17_dialog_content = "Hmm...",
  str_homestory_812601001_18_dialog_content = "Isso vai realmente levar a história adiante, e eles podem começar a falar sobre o lenço!",
  str_homestory_812601001_19_dialog_content = "Tudo bem. Eu entendi!",
  str_homestory_812601001_20_dialog_content = "É assim que vou escrever!<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "O que fez você conceber um enredo como esse?",
  str_homestory_812601001_22_dialog_content = "Porque eu vi algo cair na água agora mesmo.",
  str_homestory_812601001_23_dialog_content = "Isso me fez pensar que seria uma boa premissa...",
  str_homestory_812601001_24_dialog_content = "Espere o que? O que caiu na água?",
  str_homestory_812601001_25_dialog_content = "Eu não peguei uma boa olhada. Era algo pequeno e redondo.<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "Pequeno e redondo...",
  str_homestory_812601001_27_dialog_content = "Eu sei o que é isso.",
  str_homestory_816401001_0_dialog_content = "Carleen?",
  str_homestory_816401001_1_dialog_content = "PlayerName?",
  str_homestory_816401001_2_dialog_content = "O que você está fazendo, Carleen?",
  str_homestory_816401001_3_dialog_content = "Estou pensando.",
  str_homestory_816401001_4_dialog_content = "Está tudo bem? Você parece meio... para baixo.",
  str_homestory_816401001_5_dialog_content = "Baixa? Nós iremos...",
  str_homestory_816401001_6_dialog_content = "Porque Lumopolis foi atingida por vários desastres naturais recentemente.",
  str_homestory_816401001_7_dialog_content = "Sinto muito por ouvir isso...",
  str_homestory_816401001_8_dialog_content = "Como está a cidade agora? Há algo que eu possa fazer para ajudar?",
  str_homestory_816401001_9_dialog_content = "Obrigado por perguntar, PlayerName.",
  str_homestory_816401001_10_dialog_content = "A contagem de baixas e as perdas de ativos estão sendo tratadas oficialmente.",
  str_homestory_816401001_11_dialog_content = "Além de devolver os corpos dos mortos para suas famílias...",
  str_homestory_816401001_12_dialog_content = "Eu realmente não sei o que mais podemos fazer para aliviar a dor deles.",
  str_homestory_816401001_13_dialog_content = "Eu sei como você deve se sentir, Carleen.",
  str_homestory_816401001_14_dialog_content = "Ufa... <sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "Minha mente está muito mais clara agora que contei a você o que estava me incomodando.",
  str_homestory_816401001_16_dialog_content = "Você está pensando em como evitar esses desastres daqui para frente?",
  str_homestory_816401001_17_dialog_content = "Não.",
  str_homestory_816401001_18_dialog_content = "Diante de desastres naturais, somos apenas formigas.",
  str_homestory_816401001_19_dialog_content = "Estou apenas orando sozinho, e para reafirmar algo para mim mesmo...",
  str_homestory_816401001_20_option_content = "Sua fé?",
  str_homestory_816401001_21_dialog_content = "Bom...",
  str_homestory_816401001_22_option_content = "A eficácia das orações?",
  str_homestory_816401001_23_dialog_content = "Como devo colocar isso?",
  str_homestory_816401001_24_dialog_content = "Só quero confirmar que as orações ainda são capazes de fornecer o consolo de que preciso desesperadamente.",
  str_homestory_816401001_25_dialog_content = "Entendo...",
  str_homestory_816401001_26_dialog_content = "Muitas vezes tememos as coisas imprevisíveis que não podemos controlar.",
  str_homestory_816401001_27_dialog_content = "Mas não há nada que possamos fazer além de vê-los se desenrolarem.",
  str_homestory_816401001_28_dialog_content = "E é por isso que você se sente impotente, certo?",
  str_homestory_816401001_29_dialog_content = "Correto.",
  str_homestory_816401001_30_dialog_content = "Eu rezo sempre que me sinto derrotado.",
  str_homestory_816401001_31_dialog_content = "E também me pergunto o que é que as orações realmente me dão.",
  str_homestory_816401001_32_dialog_content = "E depois de muito pensar, concluí que é apoio espiritual, e...",
  str_homestory_816401001_33_dialog_content = "A motivação para continuar.",
  str_homestory_816401001_34_dialog_content = "De fato.",
  str_homestory_816401001_35_dialog_content = "Tenho certeza de que suas orações o ajudarão nesses tempos difíceis.",
  str_homestory_816401001_36_dialog_content = "E eu finalmente entendi uma coisa.",
  str_homestory_816401001_37_dialog_content = "Por que temos a tendência de fazer divindades com tantos elementos da natureza?",
  str_homestory_816401001_38_dialog_content = "Porque temos muitas perguntas sobre este mundo e poucas respostas.",
  str_homestory_816401001_39_dialog_content = "As orações são na verdade um compromisso. <sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "Eles não resolvem nenhum problema ou fornecem qualquer resposta.",
  str_homestory_816401001_41_dialog_content = "Mas eles trazem paz interior e ajudam você a se reerguer.",
  str_homestory_816401001_42_dialog_content = "Verdade... eles fornecem muito suporte.",
  str_homestory_816401001_43_dialog_content = "Talvez eu devesse tentar essa coisa de oração da próxima vez.",
  str_homestory_816401001_44_dialog_content = "Estou ansioso para falar com você sobre isso.",
  str_homestory_811101001_0_dialog_content = "Beryl...",
  str_homestory_811101001_1_dialog_content = "...",
  str_homestory_811101001_2_dialog_content = "Beryl!",
  str_homestory_811101001_3_dialog_content = "Hum? E aí?",
  str_homestory_811101001_4_dialog_content = "Você está desorientado, olhando para o rio. Algo está errado?",
  str_homestory_811101001_5_dialog_content = "Oh, você estava preocupado comigo?",
  str_homestory_811101001_6_option_content = "Sim.",
  str_homestory_811101001_7_dialog_content = "Então você acha que eu estou infeliz porque eu estive perto do rio? <sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "Bem, não é bem isso...",
  str_homestory_811101001_9_dialog_content = "Eu estava apenas dando um passeio pelo rio. Quero dizer, o tempo está bom hoje, certo?",
  str_homestory_811101001_10_dialog_content = "O olhar em seu rosto é estranho.",
  str_homestory_811101001_11_option_content = "Não muito.",
  str_homestory_811101001_12_dialog_content = "Eu só não sabia o que você estava fazendo, porque você está aqui há muito tempo.",
  str_homestory_811101001_13_dialog_content = "Quando desço ao rio, geralmente ando ou pesco, mas não fico parada.",
  str_homestory_811101001_14_dialog_content = "Então... o que você estava fazendo?",
  str_homestory_811101001_15_dialog_content = "Eu estava pensando sobre meus cristais e Cloud Gardens.",
  str_homestory_811101001_16_dialog_content = "Seus cristais...",
  str_homestory_811101001_17_dialog_content = "Sim, Vice disse que você tem se estressado com o desenvolvimento de Cloud Gardens.",
  str_homestory_811101001_18_dialog_content = "E sobre como você não tem muito dinheiro <sprite=emo_baiyebi size=60 />, então eu estava pensando em como torná-lo rico.",
  str_homestory_811101001_19_dialog_content = "E comecei a pensar no meu poder, os cristais.",
  str_homestory_811101001_20_dialog_content = "Se eu transformar as pedras em Cloud Gardens em cristais, então vendê-las para os joalheiros em Umbration...",
  str_homestory_811101001_21_dialog_content = "Você pode fazer isso?",
  str_homestory_811101001_22_dialog_content = "Sim, ouvi dizer que você pode quebrá-los e vender os fragmentos de cristal por uma bela quantia.",
  str_homestory_811101001_23_dialog_content = "S-Sério?",
  str_homestory_811101001_24_dialog_content = "Não, na verdade não.",
  str_homestory_811101001_25_dialog_content = "Uau! Vejo que você aprendeu a fazer piadas!",
  str_homestory_811101001_26_dialog_content = "Talvez eu tenha mudado depois de vir aqui. Afinal, é um lugar muito relaxante.",
  str_homestory_811101001_27_dialog_content = "Especialmente quando olho para os peixes no rio.",
  str_homestory_811101001_28_dialog_content = "Se você quiser ver os peixes, por que não ir até a Fonte da Esperança?",
  str_homestory_811101001_29_dialog_content = "Deve haver muitos lá, e alguns são muito bonitos também.",
  str_homestory_811101001_30_dialog_content = "Aqui... só consigo ver os bem pequenos.",
  str_homestory_811101001_31_dialog_content = "Esses são os que eu tenho observado.",
  str_homestory_811101001_32_dialog_content = "Especialmente a maneira como eles vagam pelas algas, ou a maneira como descansam nas rochas.",
  str_homestory_811101001_33_dialog_content = "É muito relaxante como eles se misturam com o ambiente.",
  str_homestory_811101001_34_dialog_content = "Sua atenção aos detalhes é realmente algo...",
  str_homestory_811101001_35_dialog_content = "Eu não posso acreditar que seus olhos são capazes de segui-los enquanto eles atravessam a água.",
  str_homestory_811101001_36_dialog_content = "Eles não estão nadando o tempo todo. Na verdade, eles passam muito tempo descansando no fundo do rio.",
  str_homestory_811101001_37_dialog_content = "Alguns chegam até a entrar nas fendas entre as rochas e apenas colocam a cabeça para fora.",
  str_homestory_811101001_38_dialog_content = "Alguns seguem as algas quando balançam na água. É tão... libertador.",
  str_homestory_811101001_39_dialog_content = "Eu vejo. Você não está olhando para o peixe, Beryl. Você está realmente olhando como eles vivem.",
  str_homestory_811101001_40_dialog_content = "Como eles vivem?",
  str_homestory_811101001_41_dialog_content = "Como eles não estão presos a nada e vivem vidas despreocupadas.",
  str_homestory_811101001_42_dialog_content = "Sim, nunca senti isso em nenhum outro lugar.",
  str_homestory_811101001_43_dialog_content = "Só me ocorreu depois que cheguei a Cloud Gardens e os vi no rio.",
  str_homestory_811101001_44_dialog_content = "Isso é por causa do charme deste lugar?",
  str_homestory_811101001_45_dialog_content = "Não o charme, mas a forma como relaxa.",
  str_homestory_811101001_46_dialog_content = "Sim, relaxado <sprite=emo_pugongying size=60 />...",
  str_homestory_816501001_0_dialog_content = "Ciel...",
  str_homestory_816501001_1_dialog_content = "Ei! Tem algum trabalho para mim?",
  str_homestory_816501001_2_option_content = "Isso.",
  str_homestory_816501001_3_dialog_content = "O que eles são? Como está o pagamento?",
  str_homestory_816501001_4_dialog_content = "Não tenho certeza se eles são adequados para você... Eles estão construindo tarefas de decoração...",
  str_homestory_816501001_5_dialog_content = "O que seria um desperdício de seus talentos.",
  str_homestory_816501001_6_option_content = "Não.",
  str_homestory_816501001_7_dialog_content = "Você realmente não tem nada?",
  str_homestory_816501001_8_dialog_content = "Cloud Gardens não tem muitos trabalhos para começar, e os Chubbs fazem a maioria deles.",
  str_homestory_816501001_9_dialog_content = "Alguma coisa em maior escala então? Como escavar túneis ou cavar montanhas.",
  str_homestory_816501001_10_dialog_content = "Meu mecha é feito para essas coisas, você sabe. <sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "Não pense que eu tenho nada agora. Por que de repente você está procurando emprego, a propósito? Você não quer aproveitar sua pausa ao máximo?",
  str_homestory_816501001_12_dialog_content = "Não posso fazer pausas porque preciso de dinheiro.",
  str_homestory_816501001_13_dialog_content = "Dinheiro? Ouvi Illumina racionando-o. Existe algo que você quer comprar?",
  str_homestory_816501001_14_dialog_content = "Eu... eu quero uma calculadora mecânica. Eu vi um uma vez no Laboratório de Pesquisa.",
  str_homestory_816501001_15_dialog_content = "Por que você não constrói um? Você tem tempo para enquanto estiver aqui.",
  str_homestory_816501001_16_dialog_content = "Não, porque eles têm muitas peças fora do padrão e é muito complicado.",
  str_homestory_816501001_17_dialog_content = "Levaria muito tempo se eu mesmo tivesse que fazer as peças.",
  str_homestory_816501001_18_dialog_content = "E custaria muito dinheiro para fazê-los.",
  str_homestory_816501001_19_dialog_content = "Mas eu realmente quero um, então estou procurando qualquer trabalho paralelo que eu possa assumir.",
  str_homestory_816501001_20_dialog_content = "Falando nisso, o que de repente o levou a querer obter um?",
  str_homestory_816501001_21_dialog_content = "Porque acho que há algo errado com o projeto. Há um lugar onde os cálculos não batem, mesmo depois de várias tentativas.",
  str_homestory_816501001_22_dialog_content = "O cálculo é muito complicado e eu fiz o meu melhor, mas uma máquina nunca estaria errada.",
  str_homestory_816501001_23_dialog_content = "Então você quer verificar os números.",
  str_homestory_816501001_24_dialog_content = "Sim! Recentemente construí um mecha dinâmico de acordo com este plano...",
  str_homestory_816501001_25_dialog_content = "Mas por causa de um erro, o mecha quebrou e quase queimou o projeto.",
  str_homestory_816501001_26_dialog_content = "Salvei-o do edifício em chamas, mas...",
  str_homestory_816501001_27_dialog_content = "Isso simplesmente não está funcionando, e acho que é porque posso estar perdendo uma parte do projeto. <sprite=emo_daomei size=60 />",
  str_homestory_816501001_28_dialog_content = "Algumas partes do mecha dinâmico construído de acordo com os planos atuais não estão funcionando conforme o esperado.",
  str_homestory_816501001_29_dialog_content = "Logicamente, se faltar uma peça no projeto, você não deve conseguir construir o mecha, certo?",
  str_homestory_816501001_30_dialog_content = "De um modo geral, sim.",
  str_homestory_816501001_31_dialog_content = "Então, poderia ser um problema de perspectiva?",
  str_homestory_816501001_32_dialog_content = "Por exemplo, eu pensei que uma das conexões do Colossus não parecia certa, mas não consegui consertá-la mesmo depois de tentar por muito tempo.",
  str_homestory_816501001_33_dialog_content = "Então veio um Firefly e imediatamente viu o problema.",
  str_homestory_816501001_34_dialog_content = "Perspectiva...",
  str_homestory_816501001_35_dialog_content = "Eu entendi! É como o <sprite=emo_baiyebi size=60 /> moeda!",
  str_homestory_816501001_36_dialog_content = "Que moeda?",
  str_homestory_816501001_37_dialog_content = "Eu vi uma moeda no rio ontem. Bem, poderia ter sido uma tampa de garrafa ou apenas um pedaço de metal.",
  str_homestory_816501001_38_dialog_content = "De qualquer forma, isso não é importante. O importante é que ele estava quicando no rio sozinho!",
  str_homestory_816501001_39_dialog_content = "Pensando bem, a superfície estava calma, mas talvez houvesse uma corrente de água embaixo...",
  str_homestory_816501001_40_dialog_content = "Ah, eu vejo. Talvez as fórmulas estivessem apenas sugerindo a direção que o design deveria tomar.",
  str_homestory_816501001_41_dialog_content = "Espere, você disse que viu uma moeda no rio?",
  str_homestory_816501001_42_dialog_content = "Hum? Certo, sim. De qualquer forma, vou projetar o mecha novamente. Vê você!",
  str_homestory_816501001_43_dialog_content = "Tá bom...",
  str_homestory_810001001_0_dialog_content = "O que está em sua mente?",
  str_homestory_810001001_1_dialog_content = "Sikare?",
  str_homestory_810001001_2_dialog_content = "Oi, Bola de Neve. Apenas quem eu estava procurando.",
  str_homestory_810001001_3_dialog_content = "O que foi?",
  str_homestory_810001001_4_dialog_content = "O que você acha do Cloud Gardens?",
  str_homestory_810001001_5_dialog_content = "Huh? Essa é a minha fala. Agora que você está me perguntando, eu preciso de um momento...",
  str_homestory_810001001_6_option_content = "Um lar.",
  str_homestory_810001001_7_dialog_content = "Esta é, naturalmente, a minha casa.",
  str_homestory_810001001_8_option_content = "Um lugar para descansar.",
  str_homestory_810001001_9_dialog_content = "Um ótimo lugar para fazer uma pausa.",
  str_homestory_810001001_10_dialog_content = "Entendo...",
  str_homestory_810001001_11_dialog_content = "Você não acha que é como uma prisão também?",
  str_homestory_810001001_12_dialog_content = "Como a Cripta Estrelada que eu guardo.",
  str_homestory_810001001_13_dialog_content = "Eu não estou seguindo você.",
  str_homestory_810001001_14_dialog_content = "É muito confortável aqui. É tão confortável que faz você não querer pensar em outras coisas.",
  str_homestory_810001001_15_dialog_content = "Eu sinto que outros já disseram isso para mim também.",
  str_homestory_810001001_16_dialog_content = "É uma espécie de conforto que está relacionado com o ditado do Astra que todos conhecem:",
  str_homestory_810001001_17_dialog_content = "A lâmina mais ameaçadora é uma cama confortável, onde muitos heróis desapareceram.",
  str_homestory_810001001_18_dialog_content = "As pessoas esquecem seus deveres quando estão confortáveis, especialmente cabeças-duras que só veem o que está à sua frente <sprite=emo_wuyu size=60 />.",
  str_homestory_810001001_19_dialog_content = "O que te fez pensar nisso afinal?",
  str_homestory_810001001_20_dialog_content = "Eu estava no rio ontem e vi algumas ervas daninhas flutuando na água.",
  str_homestory_810001001_21_dialog_content = "E pode ter havido um pedaço de metal que estava quicando na superfície da água com as ervas daninhas.",
  str_homestory_810001001_22_dialog_content = "Acho que agora entendi seu ponto.",
  str_homestory_810001001_23_dialog_content = "Se você pode pensar em uma analogia como esta, então é muito óbvio que você não é aquele pedaço de metal.",
  str_homestory_810001001_24_dialog_content = "Afinal, nós controlamos quais ações tomamos individualmente, não é?",
  str_homestory_810001001_25_dialog_content = "Eu sabia que não estava errado sobre você, Bola de Neve. Você é diferente daqueles outros cabeças-duras.",
  str_homestory_816601001_0_dialog_content = "Nada mal...",
  str_homestory_816601001_1_dialog_content = "Parece que você está de bom humor hoje.",
  str_homestory_816601001_2_dialog_content = "Presumo que você finalmente se estabeleceu aqui?",
  str_homestory_816601001_3_dialog_content = "Não tente adivinhar o que um extrozoologista está pensando!",
  str_homestory_816601001_4_dialog_content = "nem falei nada... <sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "Mas suas ações demonstraram que você está de bom humor.",
  str_homestory_816601001_6_dialog_content = "Hã?",
  str_homestory_816601001_7_dialog_content = "Acho que não.",
  str_homestory_816601001_8_dialog_content = "Bem... tudo bem. Acontece que tenho algumas perguntas para você.",
  str_homestory_816601001_9_dialog_content = "Perguntas?",
  str_homestory_816601001_10_dialog_content = "Pergunte, e verei se respondo.",
  str_homestory_816601001_11_dialog_content = "O que os cães <sprite=emo_goutou size=60 /> fazem quando estão felizes?",
  str_homestory_816601001_12_dialog_content = "Você nem sabe disso?",
  str_homestory_816601001_13_dialog_content = "Quando estão felizes, o que é muito comum, abanam o rabo. É óbvio também.",
  str_homestory_816601001_14_dialog_content = "Que tal gatos <sprite=emo_baimao size=60 />?",
  str_homestory_816601001_15_dialog_content = "Isso também é fácil.",
  str_homestory_816601001_16_dialog_content = "Eles são muito cautelosos, mas se você puder fazê-los felizes...",
  str_homestory_816601001_17_dialog_content = "Eles vão se aproximar de você e começar a ronronar.",
  str_homestory_816601001_18_dialog_content = "Que tal uma fera maravilhosa como Kyllo?",
  str_homestory_816601001_19_dialog_content = "É realmente muito óbvio quando Kyllo está feliz.",
  str_homestory_816601001_20_dialog_content = "Eu posso dizer como Kyllo está se sentindo de olhos fechados, na verdade!",
  str_homestory_816601001_21_dialog_content = "Bem, animais maravilhosos ou não...",
  str_homestory_816601001_22_dialog_content = "Acho que os animais mostram isso quando estão felizes.",
  str_homestory_816601001_23_dialog_content = "... Por que tenho a sensação de que você tem outras intenções com essas perguntas?",
  str_homestory_816601001_24_dialog_content = "Não mesmo!",
  str_homestory_816601001_25_dialog_content = "Eu só queria ver se minhas observações sobre você estavam corretas.",
  str_homestory_816601001_26_dialog_content = "De mim?",
  str_homestory_816601001_27_dialog_content = "Eu sou um extrozoólogo, e geralmente sou eu quem observa...",
  str_homestory_816601001_28_dialog_content = "Então por que você está me observando?",
  str_homestory_816601001_29_dialog_content = "Pode ser...",
  str_homestory_816601001_30_option_content = "Por curiosidade.",
  str_homestory_816601001_31_dialog_content = "Você mostra muito mais emoções do que eu, então estou muito intrigado.",
  str_homestory_816601001_32_option_content = "Boredom",
  str_homestory_816601001_33_dialog_content = "Você é uma criança muito interessante, então senti vontade de observar seu comportamento.",
  str_homestory_816601001_34_dialog_content = "E baseado no que eu vi...",
  str_homestory_816601001_35_dialog_content = "Suas orelhas de coelho se animam quando você está feliz.",
  str_homestory_816601001_36_dialog_content = "Ahhh! <sprite=emo_hanshui size=60 /> N-Não, por favor, não olhe para os meus ouvidos...",
  str_homestory_816601001_37_dialog_content = "...",
  str_homestory_816601001_38_dialog_content = "Espera!",
  str_homestory_816601001_39_dialog_content = "Meus ouvidos estão sempre em pé!",
  str_homestory_816601001_40_dialog_content = "Ao cobri-los agora, você admitiu que está de bom humor.",
  str_homestory_816601001_41_dialog_content = "Então você me enganou, PlayerName!",
  str_homestory_816601001_42_dialog_content = "Desculpe.",
  str_homestory_816601001_43_dialog_content = "Para mostrar que estou me desculpando, vou descer os slides com você.",
  str_homestory_816601001_44_dialog_content = "Isso soa bem.",
  str_homestory_816701001_0_dialog_content = "Tá dormindo?",
  str_homestory_816701001_1_dialog_content = "Uma boa pergunta.",
  str_homestory_816701001_2_dialog_content = "Se o vento é como o mundo respira...",
  str_homestory_816701001_3_dialog_content = "Então o mundo provavelmente está à deriva em direção à terra dos sonhos agora <sprite=emo_kun size=60 />.",
  str_homestory_816701001_4_dialog_content = "Ah, então você está acordado.",
  str_homestory_816701001_5_dialog_content = "Achei que você tinha adormecido na espreguiçadeira.",
  str_homestory_816701001_6_dialog_content = "O oceano é como um tirano que nunca acorda.",
  str_homestory_816701001_7_dialog_content = "Se você tem o prazer de sentir as rajadas, como lâminas, roçando seu rosto no oceano...",
  str_homestory_816701001_8_dialog_content = "Jeno?",
  str_homestory_816701001_9_dialog_content = "Sim, buscador de adivinhação?",
  str_homestory_816701001_10_dialog_content = "Não sei se entendi o que você acabou de dizer.",
  str_homestory_816701001_11_dialog_content = "Na verdade, eu sei que não entendi nada.",
  str_homestory_816701001_12_dialog_content = "As palavras não pertencem mais à garganta que as formou quando saem da boca.",
  str_homestory_816701001_13_dialog_content = "E então eles são interpretados pelo cérebro que os recebe assim que entram nos ouvidos de outra pessoa.",
  str_homestory_816701001_14_dialog_content = "Este mundo é um enorme festival de fantasias.",
  str_homestory_816701001_15_dialog_content = "Pelo menos é o que eu sempre pensei.",
  str_homestory_816701001_16_option_content = "(Não entendendo nada disso)",
  str_homestory_816701001_17_dialog_content = "Isso é profundo. Eu realmente não sei do que você está falando.",
  str_homestory_816701001_18_option_content = "(Entendido)",
  str_homestory_816701001_19_dialog_content = "Você acha que as pessoas nunca vão se entender de verdade.",
  str_homestory_816701001_20_dialog_content = "Meu caro ouvinte.",
  str_homestory_816701001_21_dialog_content = "Não importa, pois só precisamos desfrutar.",
  str_homestory_816701001_22_dialog_content = "Aham. Eu de alguma forma acho...",
  str_homestory_816701001_23_dialog_content = "Que às vezes você nem sabe do que está falando.",
  str_homestory_816701001_24_dialog_content = "Talvez às vezes eu não tenha as palavras certas.",
  str_homestory_816701001_25_dialog_content = "Mas minha magia nunca decepcionará ninguém <sprite=emo_mojing size=60 />.",
  str_homestory_816701001_26_dialog_content = "Isso é verdade.",
  str_homestory_816701001_27_dialog_content = "Hum? Espere!",
  str_homestory_816701001_28_dialog_content = "Você não criou uma ilusão para me enganar, não é?",
  str_homestory_816701001_29_dialog_content = "Na verdade, você dormiu na espreguiçadeira o tempo todo!",
  str_homestory_816701001_30_dialog_content = "Ah, você me pegou?",
  str_homestory_816701001_31_dialog_content = "Eu sabia!",
  str_homestory_816701001_32_dialog_content = "Espere, eu não terminei.",
  str_homestory_816701001_33_dialog_content = "Você está certo sobre uma coisa: há alguém dormindo na espreguiçadeira.",
  str_homestory_816701001_34_dialog_content = "Mas...",
  str_homestory_816701001_35_dialog_content = "Como você sabe que não é... você?",
  str_homestory_816701001_36_dialog_content = "Não pode ser!",
  str_homestory_816701001_37_dialog_content = "Porque eu vi você dormindo de longe!",
  str_homestory_816701001_38_dialog_content = "Você se lembra do que estava acontecendo antes disso, então?",
  str_homestory_816701001_39_dialog_content = "Eu era...",
  str_homestory_816701001_40_dialog_content = "Espere, o que eu estava fazendo?",
  str_homestory_816701001_41_dialog_content = "Hahahah.",
  str_homestory_816701001_42_dialog_content = "Você me hipnotizou sem eu saber?",
  str_homestory_816701001_43_dialog_content = "Por favor, me acorde... <sprite=emo_tanqi size=60 />",
  str_homestory_816701001_44_dialog_content = "Isso é fácil. Basta tirar uma soneca na espreguiçadeira.",
  str_homestory_816701001_45_dialog_content = "Tá bom...",
  str_homestory_816801001_0_dialog_content = "O que está fazendo?",
  str_homestory_816801001_1_dialog_content = "Olha Você aqui, PlayerName.",
  str_homestory_816801001_2_dialog_content = "Esse lugar parece bem legal! Principalmente aquela coisa ali...",
  str_homestory_816801001_3_dialog_content = "Ele toca música quando você toca <sprite=emo_yinfu size=60 />!",
  str_homestory_816801001_4_dialog_content = "Oh sim? Fico feliz em ouvir isso.",
  str_homestory_816801001_5_dialog_content = "Achei que poderia ocupar muito espaço...",
  str_homestory_816801001_6_dialog_content = "E que ninguém gostaria.",
  str_homestory_816801001_7_dialog_content = "Gostei!",
  str_homestory_816801001_8_dialog_content = "Não, eu adoro!",
  str_homestory_816801001_9_dialog_content = "Você vai me mostrar como usá-lo?",
  str_homestory_816801001_10_dialog_content = "Também não estou muito familiarizado com isso.",
  str_homestory_816801001_11_dialog_content = "Existe manual ou algo assim?",
  str_homestory_816801001_12_dialog_content = "Na verdade não...",
  str_homestory_816801001_13_dialog_content = "Então vamos ter que descobrir por conta própria?",
  str_homestory_816801001_14_dialog_content = "Parece mais divertido assim, no entanto.",
  str_homestory_816801001_15_dialog_content = "Não sabia que você gostava tanto de música.",
  str_homestory_816801001_16_dialog_content = "Eu amo coisas bonitas. E...",
  str_homestory_816801001_17_dialog_content = "Se eu pudesse aprender a usá-lo, então implementá-lo em minhas performances...",
  str_homestory_816801001_18_dialog_content = "Isso tornaria nosso ato de abertura mais agradável!",
  str_homestory_816801001_19_dialog_content = "Você está sempre pensando no circo.",
  str_homestory_816801001_20_dialog_content = "Você deve realmente amar o que faz.",
  str_homestory_816801001_21_dialog_content = "Honestamente, eu nunca pensei muito nisso <sprite=emo_wuzui size=60 />.",
  str_homestory_816801001_22_dialog_content = "Eu sempre acreditei que nasci para proteger a Esmeralda.",
  str_homestory_816801001_23_dialog_content = "Eu faço isso reparando e mantendo-o quando está encaixado ...",
  str_homestory_816801001_24_dialog_content = "E atirar em qualquer um a bordo com intenções nefastas com meu Aqua Blaster.",
  str_homestory_816801001_25_dialog_content = "Atuando com o circo para que mais conheçam a Esmeralda...",
  str_homestory_816801001_26_dialog_content = "é outra maneira de protegê-lo.",
  str_homestory_816801001_27_dialog_content = "Então é isso...",
  str_homestory_816801001_28_dialog_content = "A proteção vem em muitas formas e formas.",
  str_homestory_816801001_29_dialog_content = "Por exemplo, você faz um ótimo trabalho protegendo Cloud Gardens.",
  str_homestory_816801001_30_dialog_content = "Mas você pode querer limpar o fundo do rio em breve.",
  str_homestory_816801001_31_dialog_content = "Quando eu estava enchendo o blaster com água agora mesmo...",
  str_homestory_816801001_32_dialog_content = "Encontrei algo brilhante no fundo do rio.",
  str_homestory_816801001_33_dialog_content = "Algo brilhante...?",
  str_homestory_816801001_34_dialog_content = "Falando do rio, você quer se refrescar?",
  str_homestory_816801001_35_option_content = "Muitíssimo!",
  str_homestory_816801001_36_dialog_content = "Eu estava trabalhando, e estava muito quente.",
  str_homestory_816801001_37_dialog_content = "Isso é fácil.",
  str_homestory_816801001_38_dialog_content = "Toma essa!",
  str_homestory_816801001_39_dialog_content = "O quê?!",
  str_homestory_816801001_40_option_content = "Na verdade não...",
  str_homestory_816801001_41_dialog_content = "Você não vai me explodir com a pistola de água, vai?",
  str_homestory_816801001_42_dialog_content = "O quê mais?",
  str_homestory_816801001_43_dialog_content = "Eu estou bem, realmente.",
  str_homestory_816801001_44_dialog_content = "eu vou estar apenas pelo rio <sprite=emo_pugongying size=60 />!",
  str_homestory_801602001_0_dialog_content = "Kafka?",
  str_homestory_801602001_1_dialog_content = "Ah!",
  str_homestory_801602001_2_dialog_content = "Você me assustou, PlayerName.",
  str_homestory_801602001_3_dialog_content = "Me desculpe por isso.",
  str_homestory_801602001_4_dialog_content = "O que foi?",
  str_homestory_801602001_5_option_content = "Bom...",
  str_homestory_801602001_6_dialog_content = "Acabei de notar que você está aqui há um tempo.",
  str_homestory_801602001_7_dialog_content = "E eu estava com medo que você tivesse uma insolação.",
  str_homestory_801602001_8_dialog_content = "Não se preocupe, só estou guardando algo.",
  str_homestory_801602001_9_option_content = "Tô bem.",
  str_homestory_801602001_10_dialog_content = "Acabei de notar que você está aqui há um tempo.",
  str_homestory_801602001_11_dialog_content = "Então, eu estava curioso para saber o que você está fazendo.",
  str_homestory_801602001_12_dialog_content = "Claramente, estou guardando alguma coisa.",
  str_homestory_801602001_13_dialog_content = "Guardando alguma coisa?",
  str_homestory_801602001_14_dialog_content = "Obrigado, mas Cloud Gardens é muito seguro...",
  str_homestory_801602001_15_dialog_content = "Você não precisa ficar tão alarmado.",
  str_homestory_801602001_16_dialog_content = "Eu não estou fazendo isso para Cloud Gardens. É para...",
  str_homestory_801602001_17_dialog_content = "Um grupo de coelhos.",
  str_homestory_801602001_18_dialog_content = "Coelhinhos? Onde eles estão?",
  str_homestory_801602001_19_dialog_content = "Eles estão de volta em suas tocas",
  str_homestory_801602001_20_dialog_content = "Não se preocupe, você nunca vai encontrá-los.",
  str_homestory_801602001_21_dialog_content = "Eu não sou inimigo deles...",
  str_homestory_801602001_22_dialog_content = "Você realmente gosta de bichos, não é?",
  str_homestory_801602001_23_dialog_content = "D-eu?",
  str_homestory_801602001_24_dialog_content = "Só não quero que eles vão a algum lugar que não deveriam.",
  str_homestory_801602001_25_dialog_content = "Você é quase como um... pastor.",
  str_homestory_801602001_26_dialog_content = "Com seu cachorro grande <sprite=emo_goutou size=60 />, conduzindo os animais para um lugar seguro...",
  str_homestory_801602001_27_dialog_content = "Pastor? Não definitivamente NÃO.",
  str_homestory_801602001_28_dialog_content = "A propósito, vi algo brilhante no fundo do rio.",
  str_homestory_801602001_29_dialog_content = "Você vai descobrir o que é?",
  str_homestory_801602001_30_dialog_content = "Não deixe isso assustar as criaturas da área.",
  str_homestory_801602001_31_dialog_content = "Beleza!",
  str_homestory_817001001_0_dialog_content = "Que rara ocasião...",
  str_homestory_817001001_1_dialog_content = "Quem está aí?!",
  str_homestory_817001001_2_dialog_content = "Sou eu, PlayerName...",
  str_homestory_817001001_3_dialog_content = "Desculpe, fico nervoso quando ouço passos parando de repente.",
  str_homestory_817001001_4_dialog_content = "Relaxe, é muito seguro em Cloud Gardens.",
  str_homestory_817001001_5_dialog_content = "Sim, eu ouvi um tempo atrás",
  str_homestory_817001001_6_dialog_content = "que o celestita que apareceu do nada construiu um requintado refúgio em Eraveil.",
  str_homestory_817001001_7_dialog_content = "Eu não teria acreditado se não tivesse visto por mim mesmo.",
  str_homestory_817001001_8_dialog_content = "Não esperava tais habilidades de gerenciamento de alguém tão jovem quanto você.",
  str_homestory_817001001_9_option_content = "Reconhecer",
  str_homestory_817001001_10_dialog_content = "Agradeço pelo elogio.",
  str_homestory_817001001_11_dialog_content = "Não humilde, eu vejo.",
  str_homestory_817001001_12_dialog_content = "Ainda assim, eu gosto da coragem em você.",
  str_homestory_817001001_13_option_content = "Negar",
  str_homestory_817001001_14_dialog_content = "Na verdade, meus amigos me ajudaram muito.",
  str_homestory_817001001_15_dialog_content = "É mesmo?",
  str_homestory_817001001_16_dialog_content = "É raro ver jovens com tanta humildade.",
  str_homestory_817001001_17_dialog_content = "Não é à toa que Cloud Gardens consegue manter sua serenidade e paz.",
  str_homestory_817001001_18_dialog_content = "Sem assédio de Eclipsites, sem guerras de gangues.",
  str_homestory_817001001_19_dialog_content = "Quando penso nisso, não tive a chance de aproveitar o sol quente na minha pele",
  str_homestory_817001001_20_dialog_content = "no que parece uma vida inteira.",
  str_homestory_817001001_21_dialog_content = "É por isso que você deve tentar relaxar.",
  str_homestory_817001001_22_dialog_content = "Relaxar?",
  str_homestory_817001001_23_dialog_content = "Você sabe, eu só agora estou percebendo que",
  str_homestory_817001001_24_dialog_content = "ficar alerta tornou-se uma segunda natureza para mim.",
  str_homestory_817001001_25_dialog_content = "Mesmo que eu tenha saído da Euphoria...",
  str_homestory_817001001_26_dialog_content = "meus velhos hábitos ficaram comigo.",
  str_homestory_817001001_27_dialog_content = "Está olhando para todos aqueles próximos de um ponto de vista...",
  str_homestory_817001001_28_dialog_content = "um hábito que você manteve desde o seu tempo em Euphoria também?",
  str_homestory_817001001_29_dialog_content = "Entendo, manter o controle sobre seus convidados deve ser um de seus deveres como líder deste lugar.",
  str_homestory_817001001_30_dialog_content = "Acho que não posso subestimar você.",
  str_homestory_817001001_31_dialog_content = "Não, não foi isso que eu quis dizer.",
  str_homestory_817001001_32_dialog_content = "Acabei de ver você na torre de vigia.",
  str_homestory_817001001_33_dialog_content = "Relaxe, não estou tentando começar nada.",
  str_homestory_817001001_34_dialog_content = "Eu costumava gostar de ficar de pé, observando todos os acontecimentos de Euphoria se desenrolarem diante de mim.",
  str_homestory_817001001_35_dialog_content = "Normalmente, você veria...",
  str_homestory_817001001_36_dialog_content = "uma miríade de ganância e desejo se acumulando sob as densas nuvens de chuva.",
  str_homestory_817001001_37_dialog_content = "Mas não aqui.",
  str_homestory_817001001_38_dialog_content = "É tranquilo até onde meus olhos podem ver.",
  str_homestory_817001001_39_dialog_content = "Eu tenho um pedido, PlayerName.",
  str_homestory_817001001_40_dialog_content = "Apenas deixe-me saber o que você precisa.",
  str_homestory_817001001_41_dialog_content = "Posso trazer as crianças da igreja comigo da próxima vez?",
  str_homestory_817001001_42_dialog_content = "Claro!",
  str_homestory_817001001_43_dialog_content = "Ah, e outra coisa...",
  str_homestory_817001001_44_dialog_content = "Vi algo perto do rio que pode lhe interessar.",
  str_homestory_817001001_45_dialog_content = "Ele ainda deve estar lá se você for agora.",
  str_homestory_817001001_46_dialog_content = "Sério? Vou dar uma olhada!",
  str_homestory_817101001_0_dialog_content = "Casta?",
  str_homestory_817101001_1_dialog_content = "Ei, é você.",
  str_homestory_817101001_2_dialog_content = "Como você está se instalando em Cloud Gardens?",
  str_homestory_817101001_3_dialog_content = "Nada bem.",
  str_homestory_817101001_4_dialog_content = "Oh? Oque parece ser o problema?",
  str_homestory_817101001_5_dialog_content = "vou corrigir!",
  str_homestory_817101001_6_dialog_content = "Por um lado, o nevoeiro aqui...",
  str_homestory_817101001_7_dialog_content = "sempre parece se dissipar.",
  str_homestory_817101001_8_dialog_content = "A luz do sol incessante faz meus olhos ficarem secos.",
  str_homestory_817101001_9_dialog_content = "E não há bandidos ou hooligans procurando encrenca.",
  str_homestory_817101001_10_dialog_content = "Não estou fazendo nenhum treino decente neste lugar tranquilo.",
  str_homestory_817101001_11_dialog_content = "Se isso continuar, minha precisão vai se deteriorar<sprite=emo_daomei size=60 />.",
  str_homestory_817101001_12_option_content = "Desculpar-se",
  str_homestory_817101001_13_dialog_content = "Me desculpe por isso!",
  str_homestory_817101001_14_dialog_content = "A vida deve ser chata para você aqui.",
  str_homestory_817101001_15_option_content = "Suspiro em resignação",
  str_homestory_817101001_16_dialog_content = "Mas...",
  str_homestory_817101001_17_dialog_content = "Não posso fazer nada quanto a isso...",
  str_homestory_817101001_18_dialog_content = "Você não pode dizer que estou tentando elogiá-lo?",
  str_homestory_817101001_19_dialog_content = "Hã?",
  str_homestory_817101001_20_dialog_content = "Já me acostumei com a vida nas favelas...",
  str_homestory_817101001_21_dialog_content = "que não sei o que fazer em um lugar realmente seguro e confortável.",
  str_homestory_817101001_22_dialog_content = "O que é meio divertido, honestamente.",
  str_homestory_817101001_23_dialog_content = "Bem, na verdade há muitas coisas interessantes para fazer aqui!",
  str_homestory_817101001_24_dialog_content = "Sim, eu tenho descoberto isso ultimamente.",
  str_homestory_817101001_25_dialog_content = "Este outdoor é intrigante com a forma como as cores e as imagens se juntam...",
  str_homestory_817101001_26_dialog_content = "Deve ser um anúncio de cassino, certo?",
  str_homestory_817101001_27_dialog_content = "...",
  str_homestory_817101001_28_dialog_content = "Qual é a sua expressão<sprite=emo_baiyan size=60 />?",
  str_homestory_817101001_29_dialog_content = "Eu só quero ganhar algumas lembranças para as crianças da igreja.",
  str_homestory_817101001_30_dialog_content = "Não vou quebrar seu banco nem nada.",
  str_homestory_817101001_31_dialog_content = "Uh, isso é apenas para mostrar.",
  str_homestory_817101001_32_dialog_content = "Não temos cassinos aqui...",
  str_homestory_817101001_33_dialog_content = "O quê?",
  str_homestory_817101001_34_dialog_content = "Que tal pescar em vez disso?",
  str_homestory_817101001_35_dialog_content = "Pescaria?",
  str_homestory_817101001_36_dialog_content = "Você sabe, lançando isca e esperando o peixe morder.",
  str_homestory_817101001_37_dialog_content = "É um bom teste de sorte!",
  str_homestory_817101001_38_dialog_content = "Bem, qualquer teste de sorte é algo que não posso deixar passar!",
  str_homestory_817101001_39_dialog_content = "Ah, quase esqueci...",
  str_homestory_817101001_40_dialog_content = "Você é abençoado por Lady Luck<sprite=emo_dianzan size=60 />!",
  str_homestory_817101001_41_dialog_content = "Vejo que hoje é um mau dia para os peixes...",
  str_homestory_813001001_0_dialog_content = "Parece legal, não é?",
  str_homestory_813001001_1_dialog_content = "Hã?",
  str_homestory_813001001_2_dialog_content = "Aham…",
  str_homestory_813001001_3_dialog_content = "Ah, é você.",
  str_homestory_813001001_4_dialog_content = "Não seja tão barulhento da próxima vez. Você está tentando me assustar até a morte?",
  str_homestory_813001001_5_dialog_content = "Não diga que eu nunca te avisei!",
  str_homestory_813001001_6_dialog_content = "Se você dá a alguém um ataque cardíaco...",
  str_homestory_813001001_7_dialog_content = "Isso pode ser uma sentença de prisão perpétua!",
  str_homestory_813001001_8_dialog_content = "Obrigado pelo aviso...",
  str_homestory_813001001_9_dialog_content = "Agora que você sabe, você precisava de mim para alguma coisa?",
  str_homestory_813001001_10_dialog_content = "Cloud Gardens precisa das minhas habilidades de julgamento?",
  str_homestory_813001001_11_dialog_content = "Não, de jeito nenhum.",
  str_homestory_813001001_12_dialog_content = "Eu vi você ponderando e gesticulando diante desta estátua...",
  str_homestory_813001001_13_dialog_content = "Então eu estava apenas curioso.",
  str_homestory_813001001_14_dialog_content = "Gesticular? Quem estava gesticulando?",
  str_homestory_813001001_15_dialog_content = "O boato é contra a lei.",
  str_homestory_813001001_16_dialog_content = "De acordo com o Código de Reputação de Lumopolis, aqueles que caluniam os outros...",
  str_homestory_813001001_17_dialog_content = "será condenado a 100 dias de prisão ou multado em um milhão de Nightium.",
  str_homestory_813001001_18_dialog_content = "O quê?",
  str_homestory_813001001_19_option_content = "Refutar",
  str_homestory_813001001_20_dialog_content = "Mas estamos em Cloud Gardens, não em Lumopolis!",
  str_homestory_813001001_21_dialog_content = "PP-Absurdo!",
  str_homestory_813001001_22_dialog_content = "Como você pode tolerar não ter nenhum tipo de lei em Cloud Gardens?",
  str_homestory_813001001_23_option_content = "Cumprir",
  str_homestory_813001001_24_dialog_content = "Acho que me enganei então...",
  str_homestory_813001001_25_dialog_content = "Você tem que ter mais cuidado, PlayerName.",
  str_homestory_813001001_26_dialog_content = "Ou você estará cercado pela sordidez.",
  str_homestory_813001001_27_dialog_content = "Isso seria a queda de seu domínio!",
  str_homestory_813001001_28_dialog_content = "Certo...",
  str_homestory_813001001_29_dialog_content = "Dizer...",
  str_homestory_813001001_30_dialog_content = "Que tal você me dar a estátua?",
  str_homestory_813001001_31_dialog_content = "E vamos esquecer a coisa toda.",
  str_homestory_813001001_32_dialog_content = "O que? Mas...",
  str_homestory_813001001_33_dialog_content = "A estátua é muito importante para mim.",
  str_homestory_813001001_34_dialog_content = "Representa um certo antepassado celestita.",
  str_homestory_813001001_35_dialog_content = "As terras sem lei são realmente incompreensíveis.",
  str_homestory_813001001_36_dialog_content = "Se você realmente gosta da estátua...",
  str_homestory_813001001_37_dialog_content = "Posso fazer uma réplica para você com lama.",
  str_homestory_813001001_38_dialog_content = "Bom...",
  str_homestory_813001001_39_dialog_content = "Essa é uma solução<sprite=emo_woshou size=60 />.",
  str_homestory_813001001_40_dialog_content = "Só não me deixe esperando.",
  str_homestory_812101001_0_dialog_content = "Paloma?",
  str_homestory_812101001_1_dialog_content = "Ah, é você.",
  str_homestory_812101001_2_dialog_content = "Perdoe-me...",
  str_homestory_812101001_3_dialog_content = "Eu te acordei?",
  str_homestory_812101001_4_dialog_content = "Você sabe melhor do que fingir que se importa quando fala comigo.",
  str_homestory_812101001_5_dialog_content = "Apenas cuspa.",
  str_homestory_812101001_6_dialog_content = "Você quer saber como eu gosto de Cloud Gardens até agora, certo?",
  str_homestory_812101001_7_option_content = "Negar",
  str_homestory_812101001_8_dialog_content = "Na verdade não...",
  str_homestory_812101001_9_dialog_content = "Só queria dizer olá.",
  str_homestory_812101001_10_option_content = "Admitem",
  str_homestory_812101001_11_dialog_content = "Você tem razão...",
  str_homestory_812101001_12_dialog_content = "Eu me importo com sua opinião.",
  str_homestory_812101001_13_dialog_content = "Quer você admita ou não, eu vou dizer isso...",
  str_homestory_812101001_14_dialog_content = "...",
  str_homestory_812101001_15_dialog_content = "Eu não odeio o lugar.",
  str_homestory_812101001_16_dialog_content = "Isso é ótimo!",
  str_homestory_812101001_17_dialog_content = "Achei que você fosse desmontar...",
  str_homestory_812101001_18_dialog_content = "O que você disse?",
  str_homestory_812101001_19_dialog_content = "Ah, quero dizer...",
  str_homestory_812101001_20_dialog_content = "Esperava uma crítica construtiva sua!",
  str_homestory_812101001_21_dialog_content = "Não é que eu não tenha nada a dizer.",
  str_homestory_812101001_22_dialog_content = "Mas como você é bom com desenvolvimento, construção e gerenciamento...",
  str_homestory_812101001_23_dialog_content = "Você está interessado em expulsar os nobres de Lumopolis e assumir Azurita?",
  str_homestory_812101001_24_dialog_content = "O quê?!",
  str_homestory_812101001_25_dialog_content = "Eu nunca sequer considerei algo assim.",
  str_homestory_812101001_26_dialog_content = "Já conheci muitos que diziam uma coisa e faziam o contrário...",
  str_homestory_812101001_27_dialog_content = "Um muitas vezes.",
  str_homestory_812101001_28_dialog_content = "Eu... estou apenas tentando proteger minha própria casa.",
  str_homestory_812101001_29_dialog_content = "Eu presumo que aqueles em Lumopolis sintam o mesmo sobre sua casa também.",
  str_homestory_812101001_30_dialog_content = "Lar?",
  str_homestory_812101001_31_dialog_content = "Eu sou alguém que foi expulso de sua casa.",
  str_homestory_812101001_32_dialog_content = "\"Lar\" há muito se tornou uma palavra sem sentido para mim.",
  str_homestory_812101001_33_dialog_content = "Lembre-se de Paloma, você ainda tem Cloud Gardens.",
  str_homestory_812101001_34_dialog_content = "Se você gostaria...",
  str_homestory_812101001_35_dialog_content = "você pode tratar Cloud Gardens como sua casa!",
  str_homestory_812101001_36_dialog_content = "Então você não acha que mais ninguém vai tentar tirar isso de você?",
  str_homestory_812101001_37_dialog_content = "Só chegou onde está hoje graças a todos os meus amigos.",
  str_homestory_812101001_38_dialog_content = "É por isso que quero que Cloud Gardens seja um porto seguro para todos.",
  str_homestory_812101001_39_dialog_content = "Oh, Caelestite, você com certeza é incrivelmente ingênuo.<sprite=emo_baiyan size=60 />",
  str_homestory_812101001_40_dialog_content = "Pode ser...",
  str_homestory_812101001_41_dialog_content = "Posso adicionar uma definição para \"casa\" no meu dicionário.",
  str_homestory_812101001_42_dialog_content = "Qual seria...",
  str_homestory_812101001_43_dialog_content = "Jardins da Nuvem.",
  str_homestory_812001001_0_dialog_content = "Aí está você, Hedy.",
  str_homestory_812001001_1_dialog_content = "Argh...",
  str_homestory_812001001_2_dialog_content = "O que há de errado, Hedy?",
  str_homestory_812001001_3_dialog_content = "Avante, Noite Branca...",
  str_homestory_812001001_4_dialog_content = "Essa máquina continua rosnando maldosamente para mim!",
  str_homestory_812001001_5_dialog_content = "Diga-me, é uma relíquia maligna da Antiga Era, PlayerName?",
  str_homestory_812001001_6_dialog_content = "Se isso continuar...",
  str_homestory_812001001_7_dialog_content = "Vou ter que invocar o Cavaleiro da Luz para destruí-lo<sprite=emo_shengqi size=60 />.",
  str_homestory_812001001_8_option_content = "Console",
  str_homestory_812001001_9_dialog_content = "Não se preocupe, Hedy.",
  str_homestory_812001001_10_dialog_content = "É apenas uma máquina de sorvete.",
  str_homestory_812001001_11_option_content = "Desculpar-se",
  str_homestory_812001001_12_dialog_content = "Desculpe, esqueci de te dizer.",
  str_homestory_812001001_13_dialog_content = "Esta é uma máquina de sorvete!",
  str_homestory_812001001_14_dialog_content = "Uma... máquina de sorvete?<sprite=emo_wuzui size=60 />",
  str_homestory_812001001_15_dialog_content = "Sim. Basta colocar um copo em cima e pressionar o botão.",
  str_homestory_812001001_16_dialog_content = "Em seguida, a máquina fará um delicioso sorvete.",
  str_homestory_812001001_17_dialog_content = "Na verdade, eu, uh, já imaginei que era uma máquina de sorvete pelos flocos de neve nela.",
  str_homestory_812001001_18_dialog_content = "Mas não saiu nenhum sorvete...",
  str_homestory_812001001_19_dialog_content = "Então pensei que poderia ser uma criação diabólica disfarçada de máquina de sorvete.",
  str_homestory_812001001_20_dialog_content = "Acabou o sorvete de novo?",
  str_homestory_812001001_21_dialog_content = "\"Novamente\"?",
  str_homestory_812001001_22_dialog_content = "Bem, o sorvete que faz é tão bom...",
  str_homestory_812001001_23_dialog_content = "Se você não chegar cedo o suficiente, você não terá nenhum.",
  str_homestory_812001001_24_dialog_content = "Tem sido muito mais legal nos últimos dias, pensei que menos pessoas o usariam.",
  str_homestory_812001001_25_dialog_content = "Mas acho que ainda é muito popular.",
  str_homestory_812001001_26_dialog_content = "Que sabor você gosta, Hedy?",
  str_homestory_812001001_27_dialog_content = "Vou buscar os ingredientes para isso.",
  str_homestory_812001001_28_dialog_content = "Meu sabor de sorvete favorito...",
  str_homestory_812001001_29_dialog_content = "Sim, o que você gosta?",
  str_homestory_812001001_30_dialog_content = "Baunilha, chocolate, matcha, laranja, feijão vermelho...",
  str_homestory_812001001_31_dialog_content = "Eu amo todos eles!",
  str_homestory_812001001_32_dialog_content = "Tantos sabores, eu vejo...",
  str_homestory_812001001_33_dialog_content = "Você nunca tomou sorvete antes? Estes são todos os sabores básicos...",
  str_homestory_812001001_34_dialog_content = "O-o que você quer dizer?",
  str_homestory_812001001_35_dialog_content = "Claro que já tomei sorvete antes!",
  str_homestory_812001001_36_dialog_content = "Eu só acho que todos os sabores que você mencionou eram muito simples.",
  str_homestory_812001001_37_dialog_content = "Eu só tive sorvete com sabor de \"tomo antigo\" antes.",
  str_homestory_812001001_38_dialog_content = "Mas não acho que a máquina possa fazer isso.<sprite=emo_emo size=60 />",
  str_homestory_812001001_39_dialog_content = "\"Tomos antigos\" com sabor?!",
  str_homestory_812001001_40_dialog_content = "Não posso dizer que já tive isso, nunca.",
  str_homestory_812001001_41_dialog_content = "Mas vou tentar achar a receita!",
  str_homestory_812001001_42_dialog_content = "Ah, está tudo bem...",
  str_homestory_812001001_43_dialog_content = "Por quê?",
  str_homestory_812001001_44_dialog_content = "Eu gostaria de saber como...",
  str_homestory_812001001_45_dialog_content = "sabor de sorvete de baunilha, chocolate, matcha, laranja e feijão vermelho.",
  str_homestory_806801001_0_dialog_content = "Wendy?",
  str_homestory_806801001_1_dialog_content = "O que você está fazendo?",
  str_homestory_806801001_2_dialog_content = "Ah é você, PlayerName.",
  str_homestory_806801001_3_dialog_content = "Estou procurando um lugar para praticar vôo vertical.",
  str_homestory_806801001_4_dialog_content = "Voo vertical?",
  str_homestory_806801001_5_dialog_content = "Sim, voando para cima e para baixo.",
  str_homestory_806801001_6_dialog_content = "É o teste final de habilidades de vôo.",
  str_homestory_806801001_7_dialog_content = "Sabe, eu sempre fico com medo de que você caia voando tão alto.",
  str_homestory_806801001_8_dialog_content = "Seriamente?",
  str_homestory_806801001_9_dialog_content = "Relaxe, é moleza para mim.",
  str_homestory_806801001_10_dialog_content = "Ou você esqueceu que eu sou o míssil furacão do deserto<sprite=emo_mojing size=60 />?",
  str_homestory_806801001_11_option_content = "Esquecido",
  str_homestory_806801001_12_dialog_content = "Então vou reiterar!",
  str_homestory_806801001_13_option_content = "Não se esqueça",
  str_homestory_806801001_14_dialog_content = "Como eu poderia esquecer um apelido tão impressionante?",
  str_homestory_806801001_15_dialog_content = "Vou reiterar tudo, apenas no caso!",
  str_homestory_806801001_16_dialog_content = "Eu sou Wendy, o míssil do furacão do deserto!",
  str_homestory_806801001_17_dialog_content = "Velocidade é minha marca registrada, e ousadia é meu nome do meio!",
  str_homestory_806801001_18_dialog_content = "Ok, ok, entendi.",
  str_homestory_806801001_19_dialog_content = "Dito isso, por que praticar o voo vertical?",
  str_homestory_806801001_20_dialog_content = "Para fins de entrega, é claro!",
  str_homestory_806801001_21_dialog_content = "Entregar uma carta?",
  str_homestory_806801001_22_dialog_content = "Você já viu a coisa com os longos tentáculos, PlayerName?",
  str_homestory_806801001_23_dialog_content = "Você quer dizer o balão de água-viva?",
  str_homestory_806801001_24_dialog_content = "Eu não me importo com o que é.",
  str_homestory_806801001_25_dialog_content = "Se um cliente quiser que uma carta seja entregue, eles a receberão 100% garantida.",
  str_homestory_806801001_26_dialog_content = "Então você conhece o balão, PlayerName?",
  str_homestory_806801001_27_dialog_content = "Quer dizer, eu conheço o mobiliário... então eu acho?",
  str_homestory_806801001_28_dialog_content = "O nome do balão é Kleken?",
  str_homestory_806801001_29_dialog_content = "Bem, se o correio for endereçado a Kleken...",
  str_homestory_806801001_30_dialog_content = "Deve haver uma confusão, porque Kleken não é um balão.",
  str_homestory_806801001_31_dialog_content = "O que?! Sério?",
  str_homestory_806801001_32_dialog_content = "O remetente disse que Kleken tem muitos tentáculos longos e lisos.",
  str_homestory_806801001_33_dialog_content = "E muitas vezes ele usa uma cartola preta.",
  str_homestory_806801001_34_dialog_content = "Há um chapéu no balão?",
  str_homestory_806801001_35_dialog_content = "Bem, em qualquer caso, balões de água-viva não são o recipiente que você está procurando.",
  str_homestory_806801001_36_dialog_content = "Oh não, eu vou estabelecer um novo recorde pessoal para o maior tempo de entrega.",
  str_homestory_806801001_37_dialog_content = "Tenho que correr.",
  str_homestory_806801001_38_dialog_content = "Mesmo que eu visse algo brilhante no rio e quisesse dar uma olhada...",
  str_homestory_806801001_39_dialog_content = "Tenho uma entrega para fazer!<sprite=emo_dianzan size=60 />",
  str_homestory_817201001_0_dialog_content = "Oi, Lilica...",
  str_homestory_817201001_1_dialog_content = "Venha conferir, PlayerName!",
  str_homestory_817201001_2_dialog_content = "O que foi?",
  str_homestory_817201001_3_dialog_content = "Olha, esse brinquedo é muito divertido!",
  str_homestory_817201001_4_dialog_content = "Então, tudo o que você precisa fazer é bater nele com um bastão até que ele exploda com uma explosão de confete!<sprite=emo_caitiao size=60 />",
  str_homestory_817201001_5_dialog_content = "Às vezes, os doces também podem aparecer!",
  str_homestory_817201001_6_dialog_content = "Acho que nunca vi um brinquedo assim.",
  str_homestory_817201001_7_dialog_content = "Bem, isso faz sentido, já que as Bonecas Windelion são ornamentos tradicionais exclusivos do Eraveil.",
  str_homestory_817201001_8_dialog_content = "Você definitivamente não vai encontrá-los em nenhum outro lugar.",
  str_homestory_817201001_9_dialog_content = "Bonecos Windelion? Ornamentos tradicionais de Eraveil...",
  str_homestory_817201001_10_dialog_content = "Agora que você mencionou, acho que me lembro vagamente disso!",
  str_homestory_817201001_11_dialog_content = "Eles não têm um festival onde eles enchem um pote de barro com sementes de antemão...",
  str_homestory_817201001_12_dialog_content = "e quebrá-lo no próprio dia?",
  str_homestory_817201001_13_dialog_content = "Só então eles podem receber a bênção da natureza para uma colheita abundante naquele ano!",
  str_homestory_817201001_14_dialog_content = "Não é?",
  str_homestory_817201001_15_dialog_content = "Uau, Lilica! Eu não tenho ideia de que você conhece as tradições de Eraveil tão bem!",
  str_homestory_817201001_16_dialog_content = "Hehe, eu não iria tão longe, sabe?",
  str_homestory_817201001_17_dialog_content = "Certa vez, fiz o papel de um professor de história em um filme.",
  str_homestory_817201001_18_dialog_content = "Não foi um papel especial nem nada – eu nem consegui um close! Mas eu precisava continuar dando palestras em segundo plano.",
  str_homestory_817201001_19_dialog_content = "Lembro que o roteiro que me deram tocou em Eraveil e suas tradições!",
  str_homestory_817201001_20_dialog_content = "Uau! Acontece que existem filmes assim por aí?",
  str_homestory_817201001_21_dialog_content = "Qual é o nome do filme?",
  str_homestory_817201001_22_dialog_content = "*Limpa a garganta* De qualquer forma, minhas falas eram apenas parte do ruído de fundo, nada mais.",
  str_homestory_817201001_23_dialog_content = "Duvido que você consiga entender o que eu estava dizendo no filme...",
  str_homestory_817201001_24_option_content = "(Sentir-se desapontado)",
  str_homestory_817201001_25_dialog_content = "Tudo bem, então...",
  str_homestory_817201001_26_dialog_content = "Por um segundo, pensei que poderia assistir a um filme sobre Eraveil.",
  str_homestory_817201001_27_dialog_content = "Vamos, não pareça tão derrotado, PlayerName! Você já se esqueceu de quem eu sou?",
  str_homestory_817201001_28_option_content = "(Sentir-se animado)",
  str_homestory_817201001_29_dialog_content = "Mesmo que fosse apenas ruído de fundo, para Eraveil ser mencionado em um filme...",
  str_homestory_817201001_30_dialog_content = "Só de saber isso me deixa incrivelmente feliz!",
  str_homestory_817201001_31_dialog_content = "Realmente não é grande coisa, PlayerName... Além disso, você já esqueceu quem eu sou?",
  str_homestory_817201001_32_dialog_content = "Eu sou o diretor de cinema mais brilhante e promissor do nosso tempo! Lembrar?",
  str_homestory_817201001_33_dialog_content = "Por que eu não...",
  str_homestory_817201001_34_dialog_content = "filmar um filme inteiramente dedicado a Eraveil?",
  str_homestory_817201001_35_dialog_content = "Eh? Tudo bem?",
  str_homestory_817201001_36_dialog_content = "Claro, pode contar comigo!",
  str_homestory_817201001_37_dialog_content = "Isso seria incrível! Você já tem algo em mente, Lilica?",
  str_homestory_817201001_38_dialog_content = "Hum... vamos ver...<sprite=emo_sikao size=60 />",
  str_homestory_817201001_39_dialog_content = "Ah! Eu tenho!",
  str_homestory_817201001_40_dialog_content = "Que tal um filme de dança que acontece em Eraveil... comigo como a estrela!",
  str_homestory_817201001_41_dialog_content = "Hã?",
  str_homestory_817201001_42_dialog_content = "Isso ainda será um filme sobre Eraveil?",
  str_homestory_817201001_43_dialog_content = "Por que não?",
  str_homestory_817201001_44_dialog_content = "Ugh, isso com certeza é uma dor de cabeça...",
  str_homestory_817201001_45_dialog_content = "Tudo bem, e se em vez de mim... VOCÊ estrelou o filme de dança que acontece em Eraveil! Eh? Eh??",
  str_homestory_817201001_46_dialog_content = "Eu... acho que ninguém iria querer assistir isso...",
  str_homestory_817301001_0_dialog_content = "Minos...",
  str_homestory_817301001_1_dialog_content = "Bom dia, navegador<sprite=emo_mojing size=60 />.",
  str_homestory_817301001_2_dialog_content = "Olá, Minos.",
  str_homestory_817301001_3_dialog_content = "Há algo que eu possa fazer por você hoje, Navegador?",
  str_homestory_817301001_4_option_content = "(Confirme)",
  str_homestory_817301001_5_dialog_content = "Er... Bem, na verdade há algo que eu queria te perguntar, Minos.",
  str_homestory_817301001_6_dialog_content = "Por todos os meios, senhor.",
  str_homestory_817301001_7_dialog_content = "Espero que você possa relaxar um pouco quando estiver aqui em Cloud Gardens...",
  str_homestory_817301001_8_dialog_content = "Não há necessidade de você ser tão cortês e reverente, sabe?",
  str_homestory_817301001_9_option_content = "(Negar)",
  str_homestory_817301001_10_dialog_content = "N-Na verdade não, não...",
  str_homestory_817301001_11_dialog_content = "Eu sempre me sinto tão à vontade quando você está aqui em Cloud Gardens, Minos.",
  str_homestory_817301001_12_dialog_content = "Mas eu realmente espero que você possa relaxar um pouco enquanto está aqui...",
  str_homestory_817301001_13_dialog_content = "Afinal, eu convidei você para ser meu convidado em Cloud Gardens.",
  str_homestory_817301001_14_dialog_content = "Você tem razão, sim.",
  str_homestory_817301001_15_dialog_content = "Como seu convidado, certamente é rude de minha parte privá-lo do prazer de receber convidados.",
  str_homestory_817301001_16_dialog_content = "Tomei nota do seu pedido, senhor.",
  str_homestory_817301001_17_dialog_content = "Agora, por favor, permita-me alguns momentos para me moldar no convidado perfeito.",
  str_homestory_817301001_18_dialog_content = "Você não precisa se esforçar para ser perfeito, sabe?",
  str_homestory_817301001_19_dialog_content = "Um convidado imperfeito, então?",
  str_homestory_817301001_20_dialog_content = "Isso parece um desafio.",
  str_homestory_817301001_21_dialog_content = "Hehehe... Você está pensando demais, Minos. De qualquer forma...",
  str_homestory_817301001_22_dialog_content = "Acabei de ver essas velas acesas assim que você levanta a mão.",
  str_homestory_817301001_23_dialog_content = "Isso é simplesmente incrível! Como você fez isso, Minos?",
  str_homestory_817301001_24_dialog_content = "Você tem habilidades de observação tão aguçadas, senhor.",
  str_homestory_817301001_25_dialog_content = "Eu estava terminando o treinamento deles quando você chegou.",
  str_homestory_817301001_26_dialog_content = "Você estava... treinando velas?",
  str_homestory_817301001_27_dialog_content = "De fato. É uma técnica conhecida apenas por mordomos veteranos que dedicaram anos a prestar serviço...",
  str_homestory_817301001_28_dialog_content = "Não importa quão caro um móvel possa ser, ou quão delicado um ornamento possa parecer...",
  str_homestory_817301001_29_dialog_content = "Com a técnica certa, todos podem ser treinados para melhor servir os outros dentro de seus respectivos espaços.",
  str_homestory_817301001_30_dialog_content = "Pegue essas velas, por exemplo.",
  str_homestory_817301001_31_dialog_content = "Têm um mecanismo que lhes permite acender e apagar automaticamente.",
  str_homestory_817301001_32_dialog_content = "Deixadas desmarcadas, essas velas simplesmente serão ativadas e desativadas aleatoriamente, sem a menor aparência de ordem.",
  str_homestory_817301001_33_dialog_content = "Mas não se preocupe. Ao abordá-los na ordem adequada...",
  str_homestory_817301001_34_dialog_content = "Eles agora se iluminarão alegremente em sua presença.",
  str_homestory_817301001_35_dialog_content = "Th-Isso é incrível...",
  str_homestory_817301001_36_dialog_content = "Ah! Me desculpe...",
  str_homestory_817301001_37_dialog_content = "Como seu convidado, eu não deveria estar fazendo coisas como treinar seus móveis...",
  str_homestory_817301001_38_dialog_content = "Sem problemas.",
  str_homestory_817301001_39_dialog_content = "Se não fosse por você, eu nunca saberia que poderia fazer isso com essas velas!",
  str_homestory_817301001_40_dialog_content = "Obrigado por ignorar meu delito.",
  str_homestory_817301001_41_dialog_content = "Embora eu não possa deixar de me sentir grata pelo meu erro...",
  str_homestory_817301001_42_dialog_content = "Por causa disso, assumi perfeitamente o papel de um convidado imperfeito.",
  str_homestory_817301001_43_dialog_content = "Mas eu só espero que meu desempenho<sprite=emo_baimao size=60 /> foi do seu agrado, Navigator.",
  str_homestory_815901001_0_dialog_content = "Oi, Sadi!",
  str_homestory_815901001_1_dialog_content = "Ah é você. Não me diga que alguém mandou você me procurar?",
  str_homestory_815901001_2_dialog_content = "Nah, eu fui atraído pela música<sprite=emo_yinfu size=60 /> mais cedo.",
  str_homestory_815901001_3_dialog_content = "Aquele ritmo cativante e batidas emocionantes...",
  str_homestory_815901001_4_dialog_content = "Eu simplesmente não posso deixar de dançar ao som da música!",
  str_homestory_815901001_5_dialog_content = "Parece que você caiu no charme irresistível do hip-hop!",
  str_homestory_815901001_6_dialog_content = "Mas é perfeitamente normal, pois quem não gosta de hip-hop?",
  str_homestory_815901001_7_dialog_content = "Então isso é hip-hop...?",
  str_homestory_815901001_8_dialog_content = "Não me diga que você nunca ouviu falar disso antes, PlayerName?",
  str_homestory_815901001_9_option_content = "(Confirme)",
  str_homestory_815901001_10_dialog_content = "Eu realmente não ouço muito hip-hop, então não posso dizer que entendo muito bem.",
  str_homestory_815901001_11_option_content = "(Negar)",
  str_homestory_815901001_12_dialog_content = "De jeito nenhum, eu amo todos os tipos de música!",
  str_homestory_815901001_13_dialog_content = "Mas as únicas músicas de hip-hop que ouvi são seus raps...",
  str_homestory_815901001_14_dialog_content = "Por isso não entendo muito do gênero.",
  str_homestory_815901001_15_dialog_content = "É também por isso que eu não poderia dizer que era hip-hop imediatamente.",
  str_homestory_815901001_16_dialog_content = "Isso é uma verdadeira vergonha. Não é à toa que eu pensei que algo estava faltando quando cheguei aqui.",
  str_homestory_815901001_17_dialog_content = "Assim que vi este tambor mais cedo, percebi de repente que este lugar precisa de um pouco de hip-hop!",
  str_homestory_815901001_18_dialog_content = "Eu nunca soube que um único tambor pode fazer batidas tão emocionantes...",
  str_homestory_815901001_19_dialog_content = "Parece que você está completamente hipnotizado por isso, PlayerName.",
  str_homestory_815901001_20_dialog_content = "Acho que um fanfarrão como eu não tem escolha a não ser te dar uma mão.",
  str_homestory_815901001_21_dialog_content = "Me dê uma ajuda?",
  str_homestory_815901001_22_dialog_content = "Isso mesmo! Eu vou te ensinar a tocar esse tambor da maneira certa!",
  str_homestory_815901001_23_dialog_content = "Dessa forma, você pode ouvir batidas doces de hip-hop sempre que quiser!",
  str_homestory_815901001_24_dialog_content = "Eh? Espere, se eu te ensinar como fazer isso...",
  str_homestory_815901001_25_dialog_content = "Isso não significa que todos em Cloud Gardens vão ouvir as batidas de hip-hop que você faz?!",
  str_homestory_815901001_26_dialog_content = "Eu não posso acreditar que vou começar a tendência do hip-hop no Astra!",
  str_homestory_815901001_27_dialog_content = "S-Desculpe interromper, Sadie...",
  str_homestory_815901001_28_dialog_content = "Mas sou apenas um iniciante quando se trata de hip-hop ou bateria.",
  str_homestory_815901001_29_dialog_content = "Eu não acho que me ensinar será uma tarefa fácil.",
  str_homestory_815901001_30_dialog_content = "Ah, não se preocupe com isso! Afinal, o melhor aluno é aquele que está ansioso para aprender<sprite=emo_dianzan size=60 />!",
  str_homestory_815901001_31_dialog_content = "Agora, os dois aspectos mais importantes do hip-hop são o ritmo e a batida.",
  str_homestory_815901001_32_dialog_content = "O ritmo virá naturalmente enquanto você estiver tocando na batida.",
  str_homestory_815901001_33_dialog_content = "Agora, imagine-se como a baqueta e traga o ritmo dentro do seu coração.",
  str_homestory_815901001_34_dialog_content = "Afinal, o melhor hip-hop vem sempre direto do coração!",
  str_homestory_815901001_35_dialog_content = "Então você está dizendo que eu serei capaz de me apresentar como você se eu seguir meu coração?",
  str_homestory_815901001_36_dialog_content = "Absolutamente! Por que você não tenta?",
  str_homestory_815901001_37_dialog_content = "Apenas fique na batida e continue tocando bateria. A música vai fluir por conta própria!",
  str_homestory_815901001_38_dialog_content = "J-Continue tocando bateria, hein...",
  str_homestory_815901001_39_dialog_content = "Você não quer ajudar mais pessoas a perceberem o quão incrível o hip-hop é?",
  str_homestory_815901001_40_dialog_content = "Claro que sim, mas estou realmente esgotado agora.",
  str_homestory_815901001_41_dialog_content = "Eu acho que você ainda tem um longo caminho a percorrer antes de se tornar um superstar do hip-hop, PlayerName.",
  str_homestory_815901001_42_dialog_content = "Vamos chamá-lo por hoje, sim?",
  str_homestory_815901001_43_dialog_content = "Th-Obrigado...",
  str_homestory_807901001_0_dialog_content = "Michenny...",
  str_homestory_807901001_1_dialog_content = "Michenny?",
  str_homestory_807901001_2_dialog_content = "Olá, PlayerName.",
  str_homestory_807901001_3_dialog_content = "Heheh... Você também está aqui para apreciar a decoração?",
  str_homestory_807901001_4_dialog_content = "Como um cobrador de impostos de mente lógica, a palavra \"apreciar\" é muito sentimental.",
  str_homestory_807901001_5_dialog_content = "Estou aqui simplesmente para avaliar o valor deste item, nada mais.",
  str_homestory_807901001_6_dialog_content = "Ah... Isso não é Lumopolis, sabe? Acho que até você pode relaxar de vez em quando, Michenny<sprite=emo_sikao size=60 />.",
  str_homestory_807901001_7_dialog_content = "Exercitar o pensamento racional não é uma questão trivial.",
  str_homestory_807901001_8_dialog_content = "Especialmente quando o objetivo é tornar-se um estudioso de primeira linha no campo das leis tributárias.",
  str_homestory_807901001_9_dialog_content = "Não tenho intenção de desperdiçar anos de experiência acadêmica apenas para afrouxar, mesmo que por um momento.",
  str_homestory_807901001_10_dialog_content = "Isso não quer dizer que eu não tenha tempo livre, no entanto. Se precisar, posso ajudá-lo com os impostos do Cloud Gardens no meu tempo livre.",
  str_homestory_807901001_11_dialog_content = "Acho que não temos problemas fiscais em Cloud Gardens por enquanto...",
  str_homestory_807901001_12_dialog_content = "Seu tom é suave e você parece incerto. Isso é cerca de um imposto de 10 Nightium<sprite=emo_baiyebi size=60 /> longe de determinado.",
  str_homestory_807901001_13_dialog_content = "Parece que você rejeitou totalmente o meu serviço.",
  str_homestory_807901001_14_option_content = "Concordo",
  str_homestory_807901001_15_dialog_content = "Não é que eu queira recusar você, Michenny. É só que... Cloud Gardens não pode pagar um cobrador de impostos como você.",
  str_homestory_807901001_16_dialog_content = "Ah, menos Nightium como sempre, eu vejo.",
  str_homestory_807901001_17_dialog_content = "Você não precisa se preocupar com isso. Posso fornecer-lhe aconselhamento fiscal especializado, gratuitamente.",
  str_homestory_807901001_18_dialog_content = "Afinal, avaliar adequadamente o valor de Cloud Gardens me fornecerá uma medida de valor emocional também.",
  str_homestory_807901001_19_option_content = "Negar",
  str_homestory_807901001_20_dialog_content = "N-De jeito nenhum!",
  str_homestory_807901001_21_dialog_content = "Se Cloud Gardens precisar de um cobrador de impostos, você será a primeira pessoa para quem ligarei, Michenny!",
  str_homestory_807901001_22_dialog_content = "Os impostos devem existir onde quer que a terra seja administrada e as transações ocorram.",
  str_homestory_807901001_23_dialog_content = "Como você depositou tanta confiança em mim, continuarei avaliando o valor do Cloud Gardens.",
  str_homestory_807901001_24_dialog_content = "S-Claro...",
  str_homestory_807901001_25_dialog_content = "Voltando ao assunto em questão, me conta... O quanto você sabe sobre essa peça de decoração?",
  str_homestory_807901001_26_dialog_content = "Preciso de mais informações para fazer uma avaliação justa.",
  str_homestory_807901001_27_dialog_content = "Chama-se ninho de Windelion.",
  str_homestory_807901001_28_dialog_content = "Mesmo que essas cascas de ovos gigantes sejam apenas enfeites para nós, muitos animais<sprite=emo_gezitou size=60 /> gostaria de usá-los para botar ovos.",
  str_homestory_807901001_29_dialog_content = "Hum. Não geram valor econômico direto e ocupam espaço.",
  str_homestory_807901001_30_dialog_content = "Além disso, as criaturas que eles nutrem eventualmente começarão a consumir os recursos alimentares de Cloud Gardens.",
  str_homestory_807901001_31_dialog_content = "Minha conclusão é que este objeto e as pequenas criaturas que nele residem não têm nenhum valor.",
  str_homestory_807901001_32_dialog_content = "Pelo contrário, eles são um fardo econômico para Cloud Gardens.",
  str_homestory_807901001_33_dialog_content = "B-Mas dentro dos ovos estão criaturas vivas!",
  str_homestory_807901001_34_dialog_content = "Como você poderia avaliar o valor de suas vidas usando a lógica?",
  str_homestory_807901001_35_dialog_content = "Se você me perguntar, suas vidas não têm preço.",
  str_homestory_807901001_36_dialog_content = "Inestimável, você diz?",
  str_homestory_807901001_37_dialog_content = "Espere... Já entendi!",
  str_homestory_807901001_38_dialog_content = "Como você gostaria de cuidar deste Windelion Nest, Michenny?",
  str_homestory_807901001_39_dialog_content = "Muito bem. O que eu preciso fazer?",
  str_homestory_807901001_40_dialog_content = "Apenas espere aqui até que esses carinhas eclodam, e cuide deles até que eles cresçam!",
  str_homestory_807901001_41_dialog_content = "Posso lhe emprestar um livro que ensina tudo sobre como cuidar dos animais.",
  str_homestory_807901001_42_dialog_content = "Um livro didático seria muito útil, sim.",
  str_homestory_807901001_43_dialog_content = "Deixe para mim. Prometo que não vou decepcioná-lo.",
  str_homestory_817601001_0_dialog_content = "Bereta!",
  str_homestory_817601001_1_dialog_content = "O que você está fazendo, Beretta?",
  str_homestory_817601001_2_dialog_content = "Oh Olá PlayerName!",
  str_homestory_817601001_3_dialog_content = "Estou me exercitando.",
  str_homestory_817601001_4_dialog_content = "Quando passei por aqui, pensei ter visto Lady Raphael.",
  str_homestory_817601001_5_dialog_content = "Então parei para mais uma olhada...",
  str_homestory_817601001_6_dialog_content = "e notei sua foto neste cartão!",
  str_homestory_817601001_7_dialog_content = "Ah, esse é o cartão postal que todos me enviaram antes!",
  str_homestory_817601001_8_dialog_content = "Algumas das outras são lembranças que trouxe de novos lugares.",
  str_homestory_817601001_9_dialog_content = "Acho que esta foi tirada quando Raphael arrastou Michael em uma longa viagem.",
  str_homestory_817601001_10_dialog_content = "Eu queria saber por que Michael parecia tão chateado!<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "Você parece bastante popular.",
  str_homestory_817601001_12_dialog_content = "Você tem muito aqui... Até vi um com a assinatura de Lady Hedy.",
  str_homestory_817601001_13_dialog_content = "Ei, esta é uma foto de paisagem do Deserto de Rediesel?",
  str_homestory_817601001_14_dialog_content = "Isso é.",
  str_homestory_817601001_15_dialog_content = "Este é um souvenir da visita à Rediesel Wrench.",
  str_homestory_817601001_16_option_content = "E este é de Northland...",
  str_homestory_817601001_17_dialog_content = "Nossa, deserto e neve... Espetacular!",
  str_homestory_817601001_18_option_content = "E essa é da praia...",
  str_homestory_817601001_19_dialog_content = "Nossa, deserto e praia... Espetacular!",
  str_homestory_817601001_20_dialog_content = "Estou com tanta inveja por você ter ido a tantos lugares, PlayerName!",
  str_homestory_817601001_21_dialog_content = "Você não viaja, Beretta?",
  str_homestory_817601001_22_dialog_content = "Não, porque no meu trabalho, nunca consigo relaxar completamente, mesmo quando estou fora do trabalho.",
  str_homestory_817601001_23_dialog_content = "Afinal, os pacientes não param de adoecer ou se machucar só porque você está de férias.",
  str_homestory_817601001_24_dialog_content = "Mesmo quando vou viajar, é para dar assistência médica.",
  str_homestory_817601001_25_dialog_content = "Realmente é difícil ser médico...",
  str_homestory_817601001_26_dialog_content = "Está difícil.",
  str_homestory_817601001_27_dialog_content = "Mas quando penso em como posso aliviar a dor de alguém ou até mesmo salvar uma vida...",
  str_homestory_817601001_28_dialog_content = "Não é mais difícil!",
  str_homestory_817601001_29_dialog_content = "Sem falar que tenho que trabalhar mais para melhorar.",
  str_homestory_817601001_30_dialog_content = "Dessa forma, posso formar minha própria equipe médica itinerante para tratar pacientes em todo o continente.",
  str_homestory_817601001_31_dialog_content = "Então, não só poderei ajudar mais pessoas, mas também ver paisagens que nunca vi antes!",
  str_homestory_817601001_32_dialog_content = "Dois pássaros com uma pedra!<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "Estou impressionada, Beretta!",
  str_homestory_817601001_34_dialog_content = "Você tem um certo brilho quando fala do seu trabalho!",
  str_homestory_817601001_35_dialog_content = "Hahaha, mas ainda tenho um longo caminho pela frente!",
  str_homestory_817601001_36_dialog_content = "Meu objetivo é ser um grande médico como Lady Raphael ou Mr. John.",
  str_homestory_817601001_37_dialog_content = "Mas ainda tenho muito a aprender.",
  str_homestory_817601001_38_dialog_content = "Não apenas na medicina, mas também na resistência física e mental.",
  str_homestory_817601001_39_dialog_content = "Quando o Dr. John me operou, ele ficou na mesa de operação por três dias inteiros!",
  str_homestory_817601001_40_dialog_content = "Isso é impossível para mim fazer agora.",
  str_homestory_817601001_41_dialog_content = "Ah, melhor eu parar de falar e retomar meu treinamento!",
  str_homestory_817601001_42_dialog_content = "Tchau, PlayerName.",
  str_homestory_817601001_43_dialog_content = "Enviarei cartões-postais quando começar a tratar as pessoas!",
  str_homestory_817601001_44_dialog_content = "Heh, ainda com pressa, como sempre.",
  str_homestory_817601001_45_dialog_content = "Aguardo ansiosamente por esse dia. Você consegue, Beretta.",
  str_homestory_817501001_0_dialog_content = "Axélia?",
  str_homestory_817501001_1_dialog_content = "Olá, Axélia.",
  str_homestory_817501001_2_dialog_content = "Olá, PlayerName.",
  str_homestory_817501001_3_dialog_content = "Sentindo-se melhor ultimamente?",
  str_homestory_817501001_4_dialog_content = "Vejo você frequentemente em Cloud Gardens.",
  str_homestory_817501001_5_dialog_content = "Sim<sprite=emo_chidai size=60 />... assim que terminar de explorar Cloud Gardens, devo retornar à câmara de estase.",
  str_homestory_817501001_6_dialog_content = "Mas há muitas coisas aqui que acho fascinantes.",
  str_homestory_817501001_7_dialog_content = "Tal como este tambor que você costuma visitar?",
  str_homestory_817501001_8_dialog_content = "*Tosse*",
  str_homestory_817501001_9_dialog_content = "Você tem me observado, PlayerName?",
  str_homestory_817501001_10_option_content = "Claro que não!",
  str_homestory_817501001_11_dialog_content = "Os Cubos estão sempre com você, então nenhum contratempo deve ocorrer.",
  str_homestory_817501001_12_dialog_content = "Mas sinto que devo estar atento à sua condição.",
  str_homestory_817501001_13_dialog_content = "Obrigado por se importar.",
  str_homestory_817501001_14_option_content = "Não",
  str_homestory_817501001_15_dialog_content = "É que toda vez que te vejo, você está sempre rondando o tambor.",
  str_homestory_817501001_16_dialog_content = "Hum...",
  str_homestory_817501001_17_dialog_content = "Eu tenho uma certa curiosidade sobre esses tambores.",
  str_homestory_817501001_18_dialog_content = "Certo, lembro que você se interessava por música.",
  str_homestory_817501001_19_dialog_content = "Mas há uma razão para você gostar de techno?",
  str_homestory_817501001_20_dialog_content = "Razão...",
  str_homestory_817501001_21_dialog_content = "Talvez seja porque música assim não tem letra. <sprite=emo_sikao size=60 />",
  str_homestory_817501001_22_dialog_content = "Letra da música?",
  str_homestory_817501001_23_dialog_content = "Sim.",
  str_homestory_817501001_24_dialog_content = "Sem letras, os ouvintes têm mais espaço para a imaginação.",
  str_homestory_817501001_25_dialog_content = "Eles podem simplesmente se entregar ao ritmo da música sem precisar investir muito de suas emoções em algum tipo de história.",
  str_homestory_817501001_26_dialog_content = "Essa é uma resposta muito parecida com Axelia.",
  str_homestory_817501001_27_dialog_content = "Mesmo que o Pai zombasse do pensamento, acho que comparado a outras músicas...",
  str_homestory_817501001_28_dialog_content = "Techno simboliza a fusão racional de criatividade e notas musicais diretas.",
  str_homestory_817501001_29_dialog_content = "Você sabe, faz sentido quando você coloca dessa maneira.",
  str_homestory_817501001_30_dialog_content = "Esse tipo de música não parece evocar emoções fortes em mim...",
  str_homestory_817501001_31_dialog_content = "Sim.",
  str_homestory_817501001_32_dialog_content = "Então...",
  str_homestory_817501001_33_dialog_content = "Você fica perto da bateria porque a música techno geralmente tem batidas de bateria?",
  str_homestory_817501001_34_dialog_content = "Ou você está tentando incorporar sons de bateria no ritmo?",
  str_homestory_817501001_35_dialog_content = "Eu só quero ouvir mais seus sons.",
  str_homestory_817501001_36_dialog_content = "Mas você me deu uma ideia.",
  str_homestory_817501001_37_dialog_content = "Vou continuar a visitar no futuro.",
  str_homestory_817501001_38_dialog_content = "Claro! Deixe-me saber se há mais alguma coisa que você precisa.",
  str_homestory_817501001_39_dialog_content = "Obrigada, PlayerName.",
  str_homestory_805401001_0_dialog_content = "Nadine?",
  str_homestory_805401001_1_dialog_content = "PlayerName!",
  str_homestory_805401001_2_dialog_content = "Por que você está aqui sozinho?",
  str_homestory_805401001_3_dialog_content = "Por que você não está dentro dos dormitórios com os outros, ou pescando em algum lugar próximo?",
  str_homestory_805401001_4_dialog_content = "Porque eu tenho que terminar meu trabalho!",
  str_homestory_805401001_5_dialog_content = "Seu emprego?",
  str_homestory_805401001_6_dialog_content = "Isso mesmo. Como o primeiro Nightwatch de Cloud Gardens...",
  str_homestory_805401001_7_dialog_content = "é meu dever estar vigilante durante cada turno!",
  str_homestory_805401001_8_dialog_content = "Ei, espere um minuto—",
  str_homestory_805401001_9_dialog_content = "Não me lembro de ter pedido para você ser o Nightwatch para Cloud Gardens <sprite=emo_yueliang size=60 />.",
  str_homestory_805401001_10_dialog_content = "Você me convidou para sair em Cloud Gardens.",
  str_homestory_805401001_11_dialog_content = "Você forneceu hospedagem, comida e tantas coisas divertidas...",
  str_homestory_805401001_12_dialog_content = "Estou incrivelmente feliz!",
  str_homestory_805401001_13_dialog_content = "Nunca pensei que seria amigo íntimo de uma celebridade como você.",
  str_homestory_805401001_14_dialog_content = "Muito menos sair de Lumopolis para algum lugar tão remoto quanto Cloud Gardens.",
  str_homestory_805401001_15_dialog_content = "Mas não tenho dinheiro nem habilidades especiais... Não sei como retribuir.",
  str_homestory_805401001_16_dialog_content = "Parece que tudo o que sei é ser um Nightwatch.",
  str_homestory_805401001_17_dialog_content = "Então decidi que é assim que vou mostrar minha gratidão a você, PlayerName!",
  str_homestory_805401001_18_option_content = "agradeça a ela",
  str_homestory_805401001_19_dialog_content = "Obrigado, Nadine. Toca-me ouvir-te dizer isso.",
  str_homestory_805401001_20_dialog_content = "Mas não posso ter meus convidados trabalhando aqui para mim.",
  str_homestory_805401001_21_option_content = "Consolá-la",
  str_homestory_805401001_22_dialog_content = "Sua felicidade é o melhor retorno para mim!",
  str_homestory_805401001_23_dialog_content = "Você realmente não precisa se esforçar tanto.",
  str_homestory_805401001_24_dialog_content = "Não se preocupe, estou acostumado. Não é difícil para mim.",
  str_homestory_805401001_25_dialog_content = "Além do mais...",
  str_homestory_805401001_26_dialog_content = "Cloud Gardens é lindo!",
  str_homestory_805401001_27_dialog_content = "E você sempre obtém móveis que se adaptam às nossas preferências…",
  str_homestory_805401001_28_dialog_content = "Aos poucos, comecei a me sentir em casa aqui.",
  str_homestory_805401001_29_dialog_content = "Já que estamos em casa, não precisa ser tão formal comigo.",
  str_homestory_805401001_30_dialog_content = "Não fique preso em suas dívidas não pagas.",
  str_homestory_805401001_31_dialog_content = "Bem, tenho um senso de dever aqui porque penso nisso como um lar.",
  str_homestory_805401001_32_dialog_content = "Quero proteger Cloud Gardens, nosso lar, de todo mal!",
  str_homestory_805401001_33_dialog_content = "Para mim, isso não é apenas um trabalho.",
  str_homestory_805401001_34_dialog_content = "É um instinto e um dever!",
  str_homestory_805401001_35_dialog_content = "Ah, Nadine...",
  str_homestory_805401001_36_dialog_content = "Obrigado, suponho.",
  str_homestory_805401001_37_dialog_content = "Vou tentar compensá-lo por isso de alguma forma.",
  str_homestory_805401001_38_dialog_content = "O quê?!",
  str_homestory_817801001_0_dialog_content = "Olá, Vic.",
  str_homestory_817801001_1_dialog_content = "Não é todo dia que vemos você se aventurando ao ar livre!",
  str_homestory_817801001_2_dialog_content = "Não está com vontade de deitar na cama bebendo hoje?<sprite=emo_kun size=60 />",
  str_homestory_817801001_3_dialog_content = "Uau, isso é realmente o que você pensa de mim?",
  str_homestory_817801001_4_dialog_content = "Isso dói... Eu sou um extrozoologista mestre, você sabe...",
  str_homestory_817801001_5_dialog_content = "Sempre que estou no meu quarto, geralmente estou separando materiais ou trabalhando em meu novo livro.",
  str_homestory_817801001_6_dialog_content = "Sempre penso em assuntos importantes — só que beber ajuda a expandir minha mente!",
  str_homestory_817801001_7_dialog_content = "Oh sim? Então, como vai seu novo livro?",
  str_homestory_817801001_8_dialog_content = "Ahem... Eu digo, o ambiente aqui realmente está melhorando a cada dia.",
  str_homestory_817801001_9_dialog_content = "Bem, essa é uma maneira de mudar de assunto.",
  str_homestory_817801001_10_dialog_content = "Não, não, você sabe o que eu tenho feito aqui?",
  str_homestory_817801001_11_dialog_content = "Hmm ... Além de andar em transe?",
  str_homestory_817801001_12_dialog_content = "...",
  str_homestory_817801001_13_dialog_content = "Estou investigando as espécies e quantidades de formas de vida em sua floresta.",
  str_homestory_817801001_14_dialog_content = "Por que você está fazendo isso?",
  str_homestory_817801001_15_dialog_content = "Não subestime o significado desta informação!",
  str_homestory_817801001_16_dialog_content = "Pode revelar fenômenos de grande importância.",
  str_homestory_817801001_17_dialog_content = "Por exemplo, ele nos dirá quais tipos de formas de vida são adequados para o ambiente aqui,",
  str_homestory_817801001_18_dialog_content = "as interações simbióticas entre os animais e plantas aqui, e assim por diante.",
  str_homestory_817801001_19_dialog_content = "Quer saber, acabou de me ocorrer<sprite=emo_wuzui size=60 />—",
  str_homestory_817801001_20_dialog_content = "Este lugar é perfeito para investigação e pesquisa!",
  str_homestory_817801001_21_dialog_content = "Pretendo apresentar algumas feras maravilhosas aqui.",
  str_homestory_817801001_22_dialog_content = "Assim, meu livro terá mais...",
  str_homestory_817801001_23_dialog_content = "Espere... Você quer fazer o quê?",
  str_homestory_817801001_24_dialog_content = "Huh? Reunir informações e escrevê-las no meu livro...?",
  str_homestory_817801001_25_dialog_content = "Não, quero dizer a outra coisa.",
  str_homestory_817801001_26_dialog_content = "Você quer criar animais maravilhosos na floresta?",
  str_homestory_817801001_27_dialog_content = "Eu já te dei tantos quartos para você, isso não é suficiente!?",
  str_homestory_817801001_28_dialog_content = "Como é que em qualquer lugar remotamente perto da mesma coisa?",
  str_homestory_817801001_29_dialog_content = "O cenário interno artificial não pode ser comparado aos ambientes reais do mundo exterior.",
  str_homestory_817801001_30_dialog_content = "O comportamento animal só pode ser observado em seu estado mais verdadeiro quando o sujeito está em seu habitat natural.",
  str_homestory_817801001_31_dialog_content = "Esse não é o meu ponto!",
  str_homestory_817801001_32_dialog_content = "Você já trouxe tantos animais maravilhosos para o Colosso; Já recebi muitas reclamações dos outros, sabe!",
  str_homestory_817801001_33_dialog_content = "Sem mencionar que você não me encontrou uma solução para os constantes gritos maravilhosos da fera que acordam todo mundo de manhã cedo.",
  str_homestory_817801001_34_dialog_content = "E você nunca consegue limpar todas as fezes e cabelos que eles deixam por toda parte.",
  str_homestory_817801001_35_dialog_content = "Agora você quer criar ainda mais problemas para mim!?",
  str_homestory_817801001_36_dialog_content = "Você é tão frio, PlayerName.",
  str_homestory_817801001_37_dialog_content = "Como você pode achar isso problemático?",
  str_homestory_817801001_38_dialog_content = "Pense na contribuição que isso fará para organizações de bestas maravilhosas em todo o continente!",
  str_homestory_817801001_39_dialog_content = "Você está sendo ridícula!<sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "Você não tem permissão para trazer sua destruição extrozoológica para esta floresta, e ponto final.",
  str_homestory_817801001_41_dialog_content = "As pastagens, vales e rios também estão fora dos limites!",
  str_homestory_817801001_42_dialog_content = "Suspiro... Tudo bem.",
  str_homestory_817801001_43_dialog_content = "Realmente, os jovens de hoje não têm paciência com os mais velhos.",
  str_homestory_817701001_0_dialog_content = "Goldie!",
  str_homestory_817701001_1_dialog_content = "Ah, finalmente encontrei você, Goldie! <sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "PlayerName, Acabei de cantar minha nova música no palco.",
  str_homestory_817701001_3_dialog_content = "Estou tão nervoso. Gostaria de saber se todos gostaram...",
  str_homestory_817701001_4_dialog_content = "O que você pensou disso?",
  str_homestory_817701001_5_dialog_content = "Parecia incrível!",
  str_homestory_817701001_6_dialog_content = "Tenho certeza que todos amaram!",
  str_homestory_817701001_7_dialog_content = "Heehe... Obrigado. Acho que posso ficar tranquilo agora.",
  str_homestory_817701001_8_dialog_content = "Para ser honesto, há algo em minha mente agora.",
  str_homestory_817701001_9_dialog_content = "Eu estava esperando que você pudesse me dar alguns conselhos.",
  str_homestory_817701001_10_dialog_content = "E aí? Eu raramente vejo você em conflito.",
  str_homestory_817701001_11_dialog_content = "É sobre o primeiro single do meu novo álbum...",
  str_homestory_817701001_12_dialog_content = "Há uma música escrita no meu estilo habitual, cheia de sol <sprite=emo_taiyang size=60 /> e positividade.",
  str_homestory_817701001_13_dialog_content = "Depois, há esse outro som mais legal <sprite=emo_mojing size=60 /> música que estou pensando em substituí-la, na tentativa de tentar algo novo.",
  str_homestory_817701001_14_dialog_content = "Você acha que eu preciso substituí-lo, PlayerName?",
  str_homestory_817701001_15_option_content = "Você deveria fazê-lo.",
  str_homestory_817701001_16_dialog_content = "É bom experimentar um novo estilo de vez em quando!",
  str_homestory_817701001_17_option_content = "Não há necessidade de substituí-lo.",
  str_homestory_817701001_18_dialog_content = "Certo, posso lidar com meu estilo familiar com muito mais confiança!",
  str_homestory_817701001_19_dialog_content = "Porém, tudo depende do tema do álbum como um todo, certo?",
  str_homestory_817701001_20_dialog_content = "Certo! O tema do novo álbum é \"Growing Pains\".",
  str_homestory_817701001_21_dialog_content = "A empresa gastou uma fortuna para publicar este álbum!",
  str_homestory_817701001_22_dialog_content = "O que seu agente pensa?",
  str_homestory_817701001_23_dialog_content = "Meu agente diz que não preciso mudar nada.",
  str_homestory_817701001_24_dialog_content = "Porque alguns dos meus fãs podem não ser receptivos a um novo estilo...",
  str_homestory_817701001_25_dialog_content = "É uma sugestão um tanto conservadora.",
  str_homestory_817701001_26_dialog_content = "Mas acho que seus fãs preferem que você seja fiel a si mesmo.",
  str_homestory_817701001_27_dialog_content = "Quer você mude ou não, seus fãs vão apoiá-lo como sempre fizeram!",
  str_homestory_817701001_28_dialog_content = "Então, você também pode seguir seu coração.",
  str_homestory_817701001_29_dialog_content = "Escolha um estilo que você realmente goste.",
  str_homestory_817701001_30_dialog_content = "Vamos!",
  str_homestory_817701001_31_dialog_content = "Isso resolve! eu vou escolher—",
  str_homestory_817701001_32_dialog_content = "Você vai escolher—",
  str_homestory_817701001_33_dialog_content = "Minha canção de sol positiva!",
  str_homestory_817701001_34_dialog_content = "Hã?",
  str_homestory_817701001_35_dialog_content = "Porque isso é quem eu realmente sou!",
  str_homestory_817701001_36_dialog_content = "É o que mais me convém!",
  str_homestory_817701001_37_dialog_content = "Acho que seu agente conhece você, afinal...",
  str_homestory_818001001_0_dialog_content = "Brandy?",
  str_homestory_818001001_1_dialog_content = "Hum...? Devo colocar este bastão de luz aqui? Isso é estranho?",
  str_homestory_818001001_2_dialog_content = "O que está fazendo?",
  str_homestory_818001001_3_dialog_content = "Ei! Você chegou bem na hora!",
  str_homestory_818001001_4_dialog_content = "Ajude-me a dar uma olhada. Devo colocar este bastão de luz à esquerda ou à direita?",
  str_homestory_818001001_5_option_content = "A esquerda.",
  str_homestory_818001001_6_dialog_content = "Ficaria melhor à direita.",
  str_homestory_818001001_7_option_content = "É tudo a mesma coisa.",
  str_homestory_818001001_8_dialog_content = "Você tem razão. Vou colocá-lo à direita.",
  str_homestory_818001001_9_dialog_content = "...",
  str_homestory_818001001_10_dialog_content = "Por que você está fazendo isso?",
  str_homestory_818001001_11_dialog_content = "Estou tirando fotos para o meu artigo \"Goldie Takes Cloud Gardens By Storm\".",
  str_homestory_818001001_12_dialog_content = "No momento, estou tirando fotos das mercadorias dos fãs de Goldie.",
  str_homestory_818001001_13_dialog_content = "São bastões de luz, letreiros de néon, adesivos, mini cartões de retrato...",
  str_homestory_818001001_14_dialog_content = "Tem até uma camiseta com o rosto de Goldie. É tão fofo!",
  str_homestory_818001001_15_dialog_content = "Pensando bem. Eu sinto que ainda estou faltando um estande Goldie em tamanho real.",
  str_homestory_818001001_16_dialog_content = "Eu só preciso colocar minhas mãos em um e esgueirar-se de volta para o meu quarto... <sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "Oh não! Não deveria haver um estande Goldie em tamanho real por aqui em algum lugar!?",
  str_homestory_818001001_18_dialog_content = "Poderia ter sido roubado por algum fã de mente suja?",
  str_homestory_818001001_19_dialog_content = "Droga! Como alguém poderia fazer uma coisa dessas?",
  str_homestory_818001001_20_dialog_content = "Você acabou de dizer que era exatamente o que queria fazer...",
  str_homestory_818001001_21_dialog_content = "Esqueça. Vou tirar essas fotos primeiro.",
  str_homestory_818001001_22_dialog_content = "Ela está bem ao seu lado, por que você precisa tirar fotos de produtos?",
  str_homestory_818001001_23_dialog_content = "Eu não acho que você está fazendo isso da maneira certa.",
  str_homestory_818001001_24_dialog_content = "Você não entende - esta é uma maneira de adicionar um grau de contraste. Ele pode expressar totalmente...",
  str_homestory_818001001_25_dialog_content = "Eh? Espere um segundo!",
  str_homestory_818001001_26_dialog_content = "O que houve?",
  str_homestory_818001001_27_dialog_content = "Aquele amontoado de sombras das árvores está atingindo o letreiro de néon no ponto certo.",
  str_homestory_818001001_28_dialog_content = "Luzes e sombras dançando no tabuleiro, animando a cena com a silhueta das árvores.",
  str_homestory_818001001_29_dialog_content = "Este é o momento perfeito para tirar algumas fotos!",
  str_homestory_818001001_30_dialog_content = "Que tiro! Nunca vi uma foto tão perfeita antes!",
  str_homestory_818001001_31_dialog_content = "Esta é exatamente a foto que meu artigo de notícias precisa!",
  str_homestory_818001001_32_dialog_content = "Acho que sua reportagem precisa de uma foto da Goldie real...",
  str_homestory_818001001_33_dialog_content = "Terminei! Vou voltar e revelar essas fotos.",
  str_homestory_818001001_34_dialog_content = "A propósito, lembro-me de ter visto algo na água a caminho daqui. Você deveria ir dar uma olhada.",
  str_homestory_818001001_35_dialog_content = "Você não está me ouvindo de jeito nenhum, está...",
  str_homestory_818101001_0_dialog_content = "Zhong Xu?",
  str_homestory_818101001_1_dialog_content = "O que você tá olhando?",
  str_homestory_818101001_2_dialog_content = "Confira a estante.",
  str_homestory_818101001_3_dialog_content = "O que há de tão especial nisso? <sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "Espere, eu vejo Yixin!",
  str_homestory_818101001_5_dialog_content = "Ele rastejou para a prateleira enquanto eu não estava prestando atenção.",
  str_homestory_818101001_6_dialog_content = "Que gato travesso!",
  str_homestory_818101001_7_dialog_content = "Yimeng e Yinuo também estão lá.",
  str_homestory_818101001_8_dialog_content = "Eles gostam tanto assim da prateleira?",
  str_homestory_818101001_9_dialog_content = "Provavelmente porque gostam de lugares escuros e estreitos.",
  str_homestory_818101001_10_dialog_content = "Isso faz sentido. A prateleira é em camadas e muito escura por dentro.",
  str_homestory_818101001_11_dialog_content = "Isso poderia servir como um novo tipo de torre de gato, talvez?",
  str_homestory_818101001_12_dialog_content = "Parece lógico.",
  str_homestory_818101001_13_dialog_content = "Vou conseguir um artesão para modelar um depois disso.",
  str_homestory_818101001_14_dialog_content = "Absolutamente, você é bem-vindo a qualquer momento!",
  str_homestory_818101001_15_dialog_content = "Nunca pensei que a prateleira pudesse ser usada dessa maneira.",
  str_homestory_818101001_16_dialog_content = "Obrigado.",
  str_homestory_818101001_17_dialog_content = "Isso irá incomodá-lo?",
  str_homestory_818101001_18_option_content = "Não mesmo!",
  str_homestory_818101001_19_option_content = "Um pouco.",
  str_homestory_818101001_20_dialog_content = "Sinto muito, vou me certificar de falar com eles sobre isso.",
  str_homestory_818101001_21_dialog_content = "Agora a questão é... como vamos tirá-los?",
  str_homestory_818101001_22_dialog_content = "Eles estão dormindo tão profundamente.",
  str_homestory_818101001_23_dialog_content = "Normalmente eles vêm quando eu chamo seus nomes, mas eles não estão muito receptivos hoje.",
  str_homestory_818101001_24_dialog_content = "Talvez seja porque eles te conhecem muito bem.",
  str_homestory_818101001_25_dialog_content = "O que você quer dizer? <sprite=emo_wuzui size=60 />",
  str_homestory_818101001_26_dialog_content = "Normalmente você chama seus nomes quando precisa que eles façam alguma coisa.",
  str_homestory_818101001_27_dialog_content = "Hoje, você está apenas tentando tirá-los da prateleira.",
  str_homestory_818101001_28_dialog_content = "Então eles escolheram ignorá-lo.",
  str_homestory_818101001_29_dialog_content = "Esses gatos são muito espertos!",
  str_homestory_818101001_30_dialog_content = "... Esta prateleira parece ter um poder muito mais potente do que eu imaginava.",
  str_homestory_818101001_31_dialog_content = "Devo preparar uma réplica para eles.",
  str_homestory_818101001_32_dialog_content = "O que você vai fazer com os gatos?",
  str_homestory_818101001_33_dialog_content = "Vou esperar que eles acordem, suponho.",
  str_homestory_818101001_34_dialog_content = "Uma vitória retumbante para os gatos!",
  str_homestory_818101001_35_dialog_content = "Que vista maravilhosa, no entanto.",
  str_homestory_818101001_36_dialog_content = "Aqueles que não sabem o que está acontecendo provavelmente pensam que Zhong Xu está refletindo sobre algo filosófico novamente...",
  str_homestory_818301001_0_dialog_content = "Liqing?",
  str_homestory_818301001_1_dialog_content = "Para onde foi...?",
  str_homestory_818301001_2_dialog_content = "O que você está fazendo?",
  str_homestory_818301001_3_dialog_content = "H-Olá, PlayerName.",
  str_homestory_818301001_4_dialog_content = "Estou procurando por Tinytail. Você o viu?",
  str_homestory_818301001_5_dialog_content = "Não, o que está acontecendo?",
  str_homestory_818301001_6_dialog_content = "Ele está relaxando de novo, é isso que está acontecendo! <sprite=emo_shengqi size=60 />",
  str_homestory_818301001_7_dialog_content = "Levei-o ao jardim para colher algumas ervas.",
  str_homestory_818301001_8_dialog_content = "E então ele se foi, assim mesmo!",
  str_homestory_818301001_9_dialog_content = "Existem ervas em Cloud Gardens?",
  str_homestory_818301001_10_dialog_content = "De nada.",
  str_homestory_818301001_11_dialog_content = "Boas ervas geralmente são encontradas onde você menos espera.",
  str_homestory_818301001_12_dialog_content = "Você só precisa de um par de bons olhos. <sprite=emo_mojing size=60 />",
  str_homestory_818301001_13_dialog_content = "Isso soa totalmente como algo que você diria.",
  str_homestory_818301001_14_dialog_content = "Aliás...",
  str_homestory_818301001_15_option_content = "Há quanto tempo você está procurando por ele?",
  str_homestory_818301001_16_dialog_content = "Hum, bem, cerca de trinta minutos...",
  str_homestory_818301001_17_dialog_content = "Isso é muito tempo.",
  str_homestory_818301001_18_dialog_content = "Na verdade, talvez... apenas dez minutos?",
  str_homestory_818301001_19_option_content = "Que ervas você estava colhendo?",
  str_homestory_818301001_20_dialog_content = "Hum, j-só... ervas?",
  str_homestory_818301001_21_dialog_content = "Por que você continua gaguejando?",
  str_homestory_818301001_22_dialog_content = "Não estou!",
  str_homestory_818301001_23_dialog_content = "Pode ser isso...",
  str_homestory_818301001_24_dialog_content = "Você estava relaxando também?",
  str_homestory_818301001_25_dialog_content = "NN-Não. Não é possivel. Sem chance.",
  str_homestory_818301001_26_dialog_content = "Eu vim com Tinytail para colher ervas!",
  str_homestory_818301001_27_dialog_content = "Mas...",
  str_homestory_818301001_28_dialog_content = "Mas...?",
  str_homestory_818301001_29_dialog_content = "Aqui é confortável demais...",
  str_homestory_818301001_30_dialog_content = "Talvez eu tenha <sprite=emo_kun size=60 /> tirei uma soneca. Apenas por um momento!",
  str_homestory_818301001_31_dialog_content = "E Tinytail tinha ido embora quando eu acordei.",
  str_homestory_818301001_32_dialog_content = "Haha, então vocês dois são preguiçosos, eu vejo.",
  str_homestory_818301001_33_dialog_content = "Não, eu não sou!",
  str_homestory_818201001_0_dialog_content = "O que está fazendo?",
  str_homestory_818201001_1_dialog_content = "Estou me deliciando com a sensação da respiração da água.",
  str_homestory_818201001_2_dialog_content = "Eu realmente não entendo, mas... parece legal.",
  str_homestory_818201001_3_dialog_content = "Você já sentiu a respiração aquática antes?",
  str_homestory_818201001_4_option_content = "Sim.",
  str_homestory_818201001_5_dialog_content = "Realmente? Qual é a sensação?",
  str_homestory_818201001_6_dialog_content = "Frio, refrescante, sacia a sede.",
  str_homestory_818201001_7_dialog_content = "Esse é o sabor, não o hálito.",
  str_homestory_818201001_8_option_content = "Não.",
  str_homestory_818201001_9_dialog_content = "Se você quer aprender, eu posso te ensinar.",
  str_homestory_818201001_10_dialog_content = "Tá bom.",
  str_homestory_818201001_11_dialog_content = "Vamos começar agora.",
  str_homestory_818201001_12_dialog_content = "Agora? Eu não tenho meu calção de banho...",
  str_homestory_818201001_13_dialog_content = "Podemos praticar os movimentos básicos em terra primeiro.",
  str_homestory_818201001_14_dialog_content = "Fique em pé, respire fundo e sinta a água fluindo.",
  str_homestory_818201001_15_dialog_content = "Isso não é muito difícil. Acho que posso fazer isso.",
  str_homestory_818201001_16_dialog_content = "*Inalar*",
  str_homestory_818201001_17_dialog_content = "*Expire*",
  str_homestory_818201001_18_dialog_content = "Quanto tempo eu tenho que ficar assim?",
  str_homestory_818201001_19_dialog_content = "10.000 horas.",
  str_homestory_818201001_20_dialog_content = "10.000 horas?!",
  str_homestory_818201001_21_dialog_content = "Leva 10.000 horas para se tornar extraordinário em alguma coisa.",
  str_homestory_818201001_22_dialog_content = "Eu sei, mas isso é meio monótono... <sprite=emo_xinsui size=60 />",
  str_homestory_818201001_23_dialog_content = "Você pode desistir agora se quiser.",
  str_homestory_818201001_24_dialog_content = "Há muitas coisas divertidas, mas o caminho para o sucesso geralmente não é divertido.",
  str_homestory_818201001_25_dialog_content = "Desculpe, vou trabalhar mais.",
  str_homestory_818201001_26_dialog_content = "Você passou por um treinamento semelhante para se tornar tão bom na água?",
  str_homestory_818201001_27_dialog_content = "Não, eu nasci com a habilidade.",
  str_homestory_818201001_28_dialog_content = "???",
  str_homestory_818201001_29_dialog_content = "Então você está apenas tentando me enganar para ficar aqui por 10.000 horas?",
  str_homestory_818201001_30_dialog_content = "Não, um ancião Lin me ensinou isso quando eu estava aprendendo a nadar.",
  str_homestory_818201001_31_dialog_content = "Mas nasci com a habilidade de ressoar com a água, então não precisei praticar.",
  str_homestory_818201001_32_dialog_content = "Bem, se um ancião Lin disse isso, provavelmente é verdade.",
  str_homestory_818201001_33_dialog_content = "Apenas continue de pé...",
  str_homestory_818201001_34_dialog_content = "Minhas pernas doem, deixe-me fazer uma pausa. <sprite=emo_tanqi size=60 />",
  str_homestory_818201001_35_dialog_content = "Então podemos parar por aqui.",
  str_homestory_818201001_36_dialog_content = "Huh? Mas o ancião Lin disse...",
  str_homestory_818201001_37_dialog_content = "O ancião não sabia nadar, então provavelmente inventou.",
  str_homestory_818201001_38_dialog_content = "!!!",
  str_homestory_818201001_39_dialog_content = "Eu considerei por um minuto. Não acho que você possa entrar em ressonância com a água, mesmo que fique em pé por 10.000 horas.",
  str_homestory_818201001_40_dialog_content = "Algumas coisas você só precisa nascer com elas. Você não pode forçá-los.",
  str_homestory_818201001_41_dialog_content = "Você deveria ter dito isso antes!",
  str_homestory_818201001_42_dialog_content = "Você estava tão concentrado que não quis interromper.",
  str_homestory_818201001_43_dialog_content = "Você...",
  str_homestory_818201001_44_dialog_content = "Ah... minhas pernas estão doendo...",
  str_homestory_818201001_45_dialog_content = "Eu carrego você nas costas.",
  str_homestory_818201001_46_dialog_content = "Não, está bem...",
  str_homestory_818201001_47_dialog_content = "Até mais tarde então.",
  str_homestory_818201001_48_dialog_content = "Um, espere, você pode por favor descer?",
  str_homestory_816001001_0_dialog_content = "Michael?",
  str_homestory_816001001_1_dialog_content = "O que você tá olhando?",
  str_homestory_816001001_2_dialog_content = "(Ah, PlayerName.)",
  str_homestory_816001001_3_dialog_content = "(Estou admirando o castiçal.)",
  str_homestory_816001001_4_dialog_content = "Você deve gostar muito. Você quer?",
  str_homestory_816001001_5_dialog_content = "(Não, por favor, permita-me pagar. Quanto é?)",
  str_homestory_816001001_6_dialog_content = "(1.000 Nightium são suficientes? <sprite=emo_baiyebi size=60 />)",
  str_homestory_816001001_7_dialog_content = "Não, você não precisa pagar tanto.",
  str_homestory_816001001_8_dialog_content = "Na verdade, não vou vendê-lo se você pagar.",
  str_homestory_816001001_9_dialog_content = "(Por quê?)",
  str_homestory_816001001_10_dialog_content = "Por que você parece tão abatido?",
  str_homestory_816001001_11_dialog_content = "Certo, você gosta de colecionar bugigangas, certo?",
  str_homestory_816001001_12_dialog_content = "Lembro-me de ver todos os tipos de coisas maravilhosas em seu quarto.",
  str_homestory_816001001_13_dialog_content = "(Meu hobby é estranho?)",
  str_homestory_816001001_14_option_content = "(Confirme)",
  str_homestory_816001001_15_dialog_content = "Muitas coisas pareciam quebradas, mas você as guarda mesmo assim.",
  str_homestory_816001001_16_dialog_content = "Acho que é... excêntrico.",
  str_homestory_816001001_17_option_content = "(Negar)",
  str_homestory_816001001_18_dialog_content = "Todo mundo tem seus hobbies, não acho estranho.",
  str_homestory_816001001_19_dialog_content = "Acho que você gosta de colecionar uma grande variedade de coisas.",
  str_homestory_816001001_20_dialog_content = "(Eu apenas os acho interessantes, então quero colecioná-los.)",
  str_homestory_816001001_21_dialog_content = "(Mas eu quero comprar o castiçal por outros motivos.)",
  str_homestory_816001001_22_dialog_content = "Que razão?",
  str_homestory_816001001_23_dialog_content = "(A vela é inflamável e temo que ela comece um incêndio.<sprite=emo_nuhuo size=60 />)",
  str_homestory_816001001_24_dialog_content = "(Muitos desastres começam como pequenos perigos inconseqüentes.)",
  str_homestory_816001001_25_dialog_content = "(É difícil de entender?)",
  str_homestory_816001001_26_dialog_content = "Não, na verdade não.",
  str_homestory_816001001_27_dialog_content = "Então você está preocupado com a minha segurança?",
  str_homestory_816001001_28_dialog_content = "(É meu dever proteger Lumopolis.)",
  str_homestory_816001001_29_dialog_content = "(Você me ajudou muito, então protegê-lo também é importante.)",
  str_homestory_816001001_30_dialog_content = "Você também me ajudou muito.",
  str_homestory_816001001_31_dialog_content = "Você não está dizendo isso apenas como desculpa para comprar o castiçal, está?",
  str_homestory_816001001_32_dialog_content = "(Claro que não!)",
  str_homestory_816001001_33_dialog_content = "(Você deve ser tratado com respeito.)",
  str_homestory_816001001_34_dialog_content = "Por que estás a corar?",
  str_homestory_816001001_35_dialog_content = "(É por causa... da luz das velas.)",
  str_homestory_816001001_36_dialog_content = "(A propósito, vi algo brilhante no rio.)",
  str_homestory_816001001_37_dialog_content = "(Assim como a luz de velas.)",
  str_homestory_816001001_38_dialog_content = "Você vive mudando de assunto...",
  str_homestory_818401001_0_dialog_content = "Olá, Jeriah.",
  str_homestory_818401001_1_dialog_content = "...",
  str_homestory_818401001_2_dialog_content = "Jeriah? Olá...?",
  str_homestory_818401001_3_dialog_content = "Hum? Ah, o pequeno celestita.",
  str_homestory_818401001_4_dialog_content = "O que você está fazendo? Você parece realmente focado.",
  str_homestory_818401001_5_dialog_content = "Certo... Eu estava apenas sonhando acordado.",
  str_homestory_818401001_6_dialog_content = "Sonhando acordado?",
  str_homestory_818401001_7_dialog_content = "Já lhe disse que já estive em ruínas perto daqui antes?",
  str_homestory_818401001_8_dialog_content = "Naquela época, você ainda não havia retornado.",
  str_homestory_818401001_9_dialog_content = "Havia apenas ruínas e eclipsites aqui <sprite=emo_kulou size=60 />.",
  str_homestory_818401001_10_dialog_content = "Cara, eu nem quero falar sobre quanto tempo e esforço levou para limpar este lugar!",
  str_homestory_818401001_11_dialog_content = "Certo. Isso não deve ter sido fácil.",
  str_homestory_818401001_12_dialog_content = "Falando nisso, queria te perguntar uma coisa.",
  str_homestory_818401001_13_dialog_content = "Você acha que renovar Cloud Gardens foi um esforço significativo?",
  str_homestory_818401001_14_dialog_content = "Está lindo agora, mas se for atacado, ou daqui a cem anos, quando você se for...",
  str_homestory_818401001_15_dialog_content = "tudo aqui poderia voltar às ruínas.",
  str_homestory_818401001_16_option_content = "Foi significativo.",
  str_homestory_818401001_17_dialog_content = "Pelo menos agora, podemos ter toda a diversão que quisermos aqui.",
  str_homestory_818401001_18_dialog_content = "Se algum inimigo vier, eu os expulsarei.",
  str_homestory_818401001_19_dialog_content = "Se não posso cuidar deste lugar, vou deixá-lo para alguém de confiança.",
  str_homestory_818401001_20_dialog_content = "Sempre haverá um jeito!",
  str_homestory_818401001_21_dialog_content = "Você certamente está otimista.",
  str_homestory_818401001_22_option_content = "Provavelmente não.",
  str_homestory_818401001_23_dialog_content = "Pode não ter sentido se nosso propósito fosse fazer com que Cloud Gardens existisse para sempre.",
  str_homestory_818401001_24_dialog_content = "Estou ciente dos limites das minhas habilidades...",
  str_homestory_818401001_25_dialog_content = "Mas pelo menos estamos felizes, por enquanto.",
  str_homestory_818401001_26_dialog_content = "Isso é o suficiente para mim!",
  str_homestory_818401001_27_dialog_content = "Essa ideia de viver no presente é louvável.",
  str_homestory_818401001_28_dialog_content = "Quando vim para Eraveil pela primeira vez, pensei que era um lugar muito triste.",
  str_homestory_818401001_29_dialog_content = "Louças viradas, portas entreabertas, pilhas de roupas bagunçadas...",
  str_homestory_818401001_30_dialog_content = "Eles me lembraram que antigamente pessoas comuns desfrutavam de uma vida feliz aqui.",
  str_homestory_818401001_31_dialog_content = "Aqueles dias... puf. como dentes-de-leão <sprite=emo_pugongying size=60 />, eles foram levados pelo vento.",
  str_homestory_818401001_32_dialog_content = "Certo...",
  str_homestory_818401001_33_dialog_content = "Mas dentes-de-leão carregam sementes de esperança para terras distantes.",
  str_homestory_818401001_34_dialog_content = "Tudo isso nunca poderia ser sem sentido!",
  str_homestory_818401001_35_dialog_content = "Verdadeiro. Você mesmo é como uma sementinha, volta para brotar novamente.",
  str_homestory_818401001_36_dialog_content = "Falar com você é sempre uma experiência única.",
  str_homestory_818401001_37_dialog_content = "Hehe, fico lisonjeado.",
  str_homestory_818401001_38_dialog_content = "Hmm... Em troca, deixe-me dizer-lhe algo em que você pode estar interessado.",
  str_homestory_818401001_39_dialog_content = "Quando eu estava no rio mais cedo, vi algo brilhando na água.",
  str_homestory_818401001_40_dialog_content = "Talvez você possa ir e dar uma olhada. Pense nisso como uma aventura!",
  str_homestory_818401001_41_dialog_content = "Parece interessante... Obrigado, Jeriah!",
  str_homestory_818501001_0_dialog_content = "O que foi?",
  str_homestory_818501001_1_dialog_content = "Acabei de sentar em uma daquelas xícaras de café giratórias e agora estou me sentindo um pouco tonto <sprite=emo_xuanyun size=60 />...",
  str_homestory_818501001_2_dialog_content = "Tonto? As máquinas precisam de ajustes?",
  str_homestory_818501001_3_dialog_content = "Lembro que a velocidade já estava definida para a configuração mais lenta. Vou dar uma olhada depois.",
  str_homestory_818501001_4_dialog_content = "Essas coisas são super perigosas! Por favor, seja cuidadoso!",
  str_homestory_818501001_5_dialog_content = "Perigoso?",
  str_homestory_818501001_6_dialog_content = "Essas coisas não são para crianças de quatro anos ou mais?",
  str_homestory_818501001_7_dialog_content = "Duvido que sejam adequados mesmo para crianças de vinte anos ou mais...",
  str_homestory_818501001_8_dialog_content = "Algumas pessoas simplesmente não conseguem se acostumar com a sensação de girar. É perfeitamente normal.",
  str_homestory_818501001_9_dialog_content = "Um bom descanso deve ajudar.",
  str_homestory_818501001_10_dialog_content = "OK. vou descansar. Ainda tenho que entregar cartas para o norte mais tarde...",
  str_homestory_818501001_11_dialog_content = "Espere. Norte Sul...",
  str_homestory_818501001_12_dialog_content = "Oh não! Não consigo mais distinguir minhas direções!",
  str_homestory_818501001_13_dialog_content = "Eu costumava ter tanto orgulho do meu senso de direção! Como isso pode ser!?",
  str_homestory_818501001_14_dialog_content = "*soluçando* <sprite=emo_daku size=60 />Se eu não consigo nem entregar cartas, o que seria da minha carreira?",
  str_homestory_818501001_15_dialog_content = "Uh, isso é um pouco dramático...",
  str_homestory_818501001_16_dialog_content = "PlayerName, você pode me dizer para que lado é o norte?",
  str_homestory_818501001_17_option_content = "Vá para esquerda",
  str_homestory_818501001_18_dialog_content = "É isso? Eu não posso dizer nada...",
  str_homestory_818501001_19_option_content = "eu também não faço ideia",
  str_homestory_818501001_20_dialog_content = "E-Até você...",
  str_homestory_818501001_21_dialog_content = "Vamos acabar presos aqui?",
  str_homestory_818501001_22_dialog_content = "???",
  str_homestory_818501001_23_dialog_content = "Conta como estar preso quando você ainda está em sua própria casa?",
  str_homestory_818501001_24_dialog_content = "Agora nem eu tenho certeza de onde estou...",
  str_homestory_818501001_25_dialog_content = "O código da Courier Union diz que devemos sempre manter um senso de direção.",
  str_homestory_818501001_26_dialog_content = "Muitos entregadores acabam em situações perigosas sem ter para onde correr só porque se perderam.",
  str_homestory_818501001_27_dialog_content = "Acho que esse tipo de coisa só acontece quando você está no deserto, como uma grande floresta.",
  str_homestory_818501001_28_dialog_content = "Estamos no Jardim das Nuvens! Você vê a porta?",
  str_homestory_818501001_29_dialog_content = "É bem ali. Basta dar alguns passos e você estará fora daqui.",
  str_homestory_818501001_30_dialog_content = "Mas e se eu for lá para o deserto e ficar tão tonto quanto estou agora?",
  str_homestory_818501001_31_dialog_content = "Existem xícaras de café no deserto?",
  str_homestory_818501001_32_dialog_content = "Ah, certo...",
  str_homestory_818501001_33_dialog_content = "E mesmo que existam, simplesmente não ande neles.",
  str_homestory_818501001_34_dialog_content = "Sim! Você é tão esperto!",
  str_homestory_818501001_35_dialog_content = "Ha, claro...",
  str_homestory_818501001_36_dialog_content = "Quando eu voltar, adicionarei uma nova regra ao código Courier Union—",
  str_homestory_818501001_37_dialog_content = "\"Se você encontrar xícaras de café girando no deserto, não se sente nelas!\"",
  str_homestory_818501001_38_dialog_content = "As chances de encontrar xícaras de café girando no deserto devem ser bem baixas...",
  str_homestory_818501001_39_dialog_content = "\"—Sabedoria cortesia do celestita.\"",
  str_homestory_818501001_40_dialog_content = "!!!",
  str_homestory_818501001_41_dialog_content = "Quanto você quer que eu pague para manter meu nome fora disso!?",
  str_homestory_818501001_42_dialog_content = "O que? Este é um conselho realmente útil! De qualquer forma, estou fora...",
  str_homestory_818501001_43_dialog_content = "Oh, ótimo... eu vou ser motivo de chacota do Courier Union...<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "Gabriel?",
  str_homestory_802901001_1_dialog_content = "O que pensa que está fazendo?",
  str_homestory_802901001_2_dialog_content = "Atualmente estou tirando uma soneca debaixo da árvore, <sprite=emo_kun size=60 />, apenas casualmente absorvendo a respiração da árvore.",
  str_homestory_802901001_3_dialog_content = "A respiração da árvore?",
  str_homestory_802901001_4_dialog_content = "Isso mesmo... As árvores também são seres vivos.",
  str_homestory_802901001_5_dialog_content = "Posso sentir o padrão de sua respiração constante. Pode sentir isso, PlayerName?",
  str_homestory_802901001_6_option_content = "Admitem",
  str_homestory_802901001_7_dialog_content = "Quando suas folhas tremem, parece que ela está respirando mais rápido.",
  str_homestory_802901001_8_dialog_content = "Acho que é só o vento...",
  str_homestory_802901001_9_option_content = "Negar",
  str_homestory_802901001_10_dialog_content = "Ah, não consigo sentir nada...",
  str_homestory_802901001_11_dialog_content = "Parece que você é o único com essa habilidade especial de sentir as plantas, Gabriel...",
  str_homestory_802901001_12_dialog_content = "Cada árvore é diferente, assim como cada pessoa.",
  str_homestory_802901001_13_dialog_content = "Contanto que você sinta com o coração... você pode conhecer o mundo interior deles.",
  str_homestory_802901001_14_dialog_content = "Por exemplo, a respiração desta árvore é bastante difícil... Parece estar um pouco doente...",
  str_homestory_802901001_15_dialog_content = "Acho que deve ser por isso que suas folhas estão um pouco amareladas em comparação com as outras árvores.",
  str_homestory_802901001_16_dialog_content = "Parece um pouco sem vida.",
  str_homestory_802901001_17_dialog_content = "As árvores por aqui estão realmente florescendo. Eles estão bloqueando a luz do sol... <sprite=emo_taiyang size=60 />",
  str_homestory_802901001_18_dialog_content = "Parece que este pequenino está com problemas para realizar a fotossíntese!",
  str_homestory_802901001_19_dialog_content = "Então, você acha que precisamos mover esta árvore para outro lugar?",
  str_homestory_802901001_20_dialog_content = "Não, as plantas têm suas próprias maneiras de fazer as coisas.",
  str_homestory_802901001_21_dialog_content = "Esta árvore não trabalhou duro o suficiente para crescer, então as outras árvores roubaram sua luz do sol...",
  str_homestory_802901001_22_dialog_content = "Ele precisa confiar em si mesmo para crescer e ficar mais forte... Não devemos estragá-lo demais!",
  str_homestory_802901001_23_dialog_content = "Entendo... Isso faz muito sentido, Gabriel!",
  str_homestory_802901001_24_dialog_content = "Heh, eu estava preocupado que poderia ser muito difícil para você entender, PlayerName...",
  str_homestory_802901001_25_dialog_content = "Eu entendo! Mas, o que realmente me surpreende é—",
  str_homestory_802901001_26_dialog_content = "Você geralmente parece que está sempre andando atordoado, Gabriel, mas hoje você parece tão sério.",
  str_homestory_802901001_27_dialog_content = "Acho mais correto dizer que sempre ajo de acordo com o que me cerca...",
  str_homestory_802901001_28_dialog_content = "As plantas também têm seus destinos...",
  str_homestory_802901001_29_dialog_content = "Destinos...?",
  str_homestory_802901001_30_dialog_content = "Certo. Encontrar você sob esta árvore faz parte do destino da árvore.",
  str_homestory_802901001_31_dialog_content = "Falando nisso, quando eu estava andando ao longo do rio agora, eu vi algo brilhando...",
  str_homestory_802901001_32_dialog_content = "Você poderia ver o que era?",
  str_homestory_802901001_33_dialog_content = "Bem, eu estava planejando parar na floresta para tirar uma soneca!",
  str_homestory_802901001_34_dialog_content = "O fato de eu não ter verificado o que havia no rio também fazia parte dos planos do destino!",
  str_homestory_802901001_35_dialog_content = "Acho que entendo o que você quer dizer sobre destino...",
  str_homestory_818901001_0_dialog_content = "O que você está fazendo, Leyn?",
  str_homestory_818901001_1_dialog_content = "Ei! Leyn!",
  str_homestory_818901001_2_dialog_content = "Licores de chocolate, centros frutados <sprite=emo_sikao size=60 />... Huh?",
  str_homestory_818901001_3_dialog_content = "Olá.",
  str_homestory_818901001_4_dialog_content = "O que você está olhando, Leyn? Você parece tão focado.",
  str_homestory_818901001_5_dialog_content = "Nada mesmo, acabei de ver esta caixa de chocolates.",
  str_homestory_818901001_6_dialog_content = "Esses são do Mooncrown Day.",
  str_homestory_818901001_7_dialog_content = "Se você quiser comê-los, Leyn, sirva-se!",
  str_homestory_818901001_8_dialog_content = "Não, eu não quero comê-los. Estou interessado apenas no processo de produção.",
  str_homestory_818901001_9_dialog_content = "Costumo fazer sobremesas de chocolate em casa também.",
  str_homestory_818901001_10_dialog_content = "Mas eu costumo usar apenas chocolate derretido para decoração.",
  str_homestory_818901001_11_dialog_content = "Eu não tinha percebido que as sobremesas haviam chegado tão longe em termos de arte.",
  str_homestory_818901001_12_dialog_content = "Eu digo, você gosta de chocolate?",
  str_homestory_818901001_13_option_content = "Gostei!",
  str_homestory_818901001_14_dialog_content = "Nesse caso, assim que eu aprender algumas novas técnicas, deixarei você tentar.",
  str_homestory_818901001_15_dialog_content = "É um pouco cedo para você estar bebendo licores de chocolate...",
  str_homestory_818901001_16_dialog_content = "Vou trazer alguns frutados, então.",
  str_homestory_818901001_17_option_content = "Não é um fã...",
  str_homestory_818901001_18_dialog_content = "Oh, que pena.",
  str_homestory_818901001_19_dialog_content = "Da próxima vez, deixe-me trazer-lhe algumas outras guloseimas.",
  str_homestory_818901001_20_dialog_content = "Se houver algo que você gostaria de comer, por favor me avise. A qualquer hora que você desejar.",
  str_homestory_818901001_21_dialog_content = "Doce! Obrigado, Leyn!",
  str_homestory_818901001_22_dialog_content = "Hum...",
  str_homestory_818901001_23_dialog_content = "Qual é o problema? Por que você ainda está olhando para aqueles chocolates?",
  str_homestory_818901001_24_dialog_content = "Você... realmente quer comer um pouco?",
  str_homestory_818901001_25_dialog_content = "Estou um pouco curioso sobre o sabor deles! <sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "Acho que vou comprar uma caixa para fazer mais pesquisas!",
  str_homestory_818901001_27_dialog_content = "Ei, por que você ainda está sendo tão educado?",
  str_homestory_818901001_28_dialog_content = "Se você quiser comê-los, apenas coma!",
  str_homestory_818901001_29_dialog_content = "Todo mundo precisa se dar ao luxo de vez em quando.",
  str_homestory_818901001_30_dialog_content = "Eu... Err...",
  str_homestory_818901001_31_dialog_content = "Obrigado por sua gentileza. Nesse caso, vou me ajudar...",
  str_homestory_818601001_0_dialog_content = "Tina?",
  str_homestory_818601001_1_dialog_content = "Por quê você está aqui?",
  str_homestory_818601001_2_dialog_content = "Olá, PlayerName!",
  str_homestory_818601001_3_dialog_content = "Esta cadeira é extremamente curiosa.",
  str_homestory_818601001_4_dialog_content = "Você quer dizer aquela cadeira de praia?",
  str_homestory_818601001_5_dialog_content = "Certo... Então, esta é uma cadeira de praia...",
  str_homestory_818601001_6_dialog_content = "Para dizer a verdade, não sei nada de beira-mar. Eu passo a maior parte do meu tempo no Lumopolis Hall of Justice.",
  str_homestory_818601001_7_dialog_content = "Você costuma ir à beira-mar, PlayerName?",
  str_homestory_818601001_8_option_content = "Eu vou o tempo todo.",
  str_homestory_818601001_9_dialog_content = "Costumo ir à beira-mar.",
  str_homestory_818601001_10_dialog_content = "A beira-mar é a melhor!",
  str_homestory_818601001_11_option_content = "Não muito.",
  str_homestory_818601001_12_dialog_content = "Na verdade, não, eu não vou muito.",
  str_homestory_818601001_13_dialog_content = "Mas a beira-mar é bem divertida. Tenho algumas boas lembranças do meu tempo na praia.",
  str_homestory_818601001_14_dialog_content = "Entendi!",
  str_homestory_818601001_15_dialog_content = "Se eu pudesse ir à praia com você, PlayerName, isso seria ótimo!",
  str_homestory_818601001_16_dialog_content = "Mas ainda tenho muitos casos para tratar no Tribunal de Justiça. Estou terrivelmente ocupado!",
  str_homestory_818601001_17_dialog_content = "Talvez tenhamos a chance de ir juntos no futuro.",
  str_homestory_818601001_18_dialog_content = "Mas os maiôs que todo mundo usa na praia... Tem certeza que está tudo bem com eles?",
  str_homestory_818601001_19_dialog_content = "Maiôs... Eu li sobre isso em um livro. eles são bem fraquinhos<sprite=emo_qunzi size=60 />, não são?",
  str_homestory_818601001_20_dialog_content = "Certo... O traje nobre de Lumopolis pode ser um pouco abafado demais para o litoral...",
  str_homestory_818601001_21_dialog_content = "Entendo perfeitamente que roupas diferentes devem ser usadas em ocasiões diferentes, mas não me importo nem um pouco com isso.",
  str_homestory_818601001_22_dialog_content = "No entanto, os anciãos podem me acusar de abandonar seu código de etiqueta. O mero pensamento de seus escárnios me dá calafrios...",
  str_homestory_818601001_23_dialog_content = "*tosse* Você não precisa pensar tão longe no futuro, Tina...",
  str_homestory_818601001_24_dialog_content = "Afinal, nem sabemos quando vamos poder ir à beira-mar...",
  str_homestory_818601001_25_dialog_content = "Tem razão!",
  str_homestory_818601001_26_dialog_content = "Então... Você quer experimentar aquela cadeira de praia, ou o quê?",
  str_homestory_818601001_27_dialog_content = "Sim! Eu quero tentar!",
  str_homestory_818601001_28_dialog_content = "Não é tão macio quanto minha poltrona reclinável especial, mas ainda é muito confortável!",
  str_homestory_818601001_29_dialog_content = "Este material torna ainda mais prático para a praia.",
  str_homestory_818601001_30_dialog_content = "Oi, Tininha! Você está me ouvindo?",
  str_homestory_818601001_31_dialog_content = "Ela está dormindo profundamente...",
  str_homestory_819001001_0_dialog_content = "Matthieu?",
  str_homestory_819001001_1_dialog_content = "Você chegou bem a tempo.",
  str_homestory_819001001_2_dialog_content = "Este antigo pavilhão restaurado não é muito pobre, nem muito pobre ... É o lugar perfeito para tomar uma xícara de chá e mergulhar em um bom livro.",
  str_homestory_819001001_3_dialog_content = "Mas ainda precisa de algo para torná-lo ainda mais perfeito—",
  str_homestory_819001001_4_dialog_content = "O que foi?",
  str_homestory_819001001_5_dialog_content = "É um pouco monótono no momento, você não diria?",
  str_homestory_819001001_6_option_content = "Acho que não.",
  str_homestory_819001001_7_option_content = "Eu poderia fazer com um pouco mais de decoração.",
  str_homestory_819001001_8_dialog_content = "Vou trazer algumas almofadas. Isso deve ser o suficiente, certo?",
  str_homestory_819001001_9_dialog_content = "Pretendo decorá-lo com flores e plantas raras, e jogos de chá de ouro e prata, para uso dos nobres a bordo.",
  str_homestory_819001001_10_dialog_content = "Flores e plantas raras, jogos de chá de ouro e prata... Não seria um pouco extravagante demais?",
  str_homestory_819001001_11_dialog_content = "Você está preocupado com o custo? <sprite=emo_baiyebi size=60 /> Você realmente é um celestita frugal, não é?",
  str_homestory_819001001_12_dialog_content = "Você não precisa se preocupar com o dinheiro. Eu cuidarei disso.",
  str_homestory_819001001_13_dialog_content = "Não é só o dinheiro. Obviamente, o fato de custar muito dinheiro é um problema em si.",
  str_homestory_819001001_14_dialog_content = "Mas desde que você pode cuidar disso, não é um problema. No entanto...",
  str_homestory_819001001_15_dialog_content = "O que você tá tentando dizer?",
  str_homestory_819001001_16_dialog_content = "Este é o Cloud Gardens, um lugar onde todos se esforçam ao máximo para viver juntos.",
  str_homestory_819001001_17_dialog_content = "Nem todo mundo está interessado em coisas como buquês de flores e louças de ouro e prata.",
  str_homestory_819001001_18_dialog_content = "Não quero torná-lo muito chique, nem quero fazer com que certos aurorianos se sintam desconfortáveis.",
  str_homestory_819001001_19_dialog_content = "Está pensando em quem ainda não aproveitou o dia a dia?",
  str_homestory_819001001_20_dialog_content = "Estar rodeado de flores, ouro e prata não constitui exatamente a vida cotidiana...",
  str_homestory_819001001_21_dialog_content = "De qualquer forma, enviarei alguém para começar o trabalho de decoração imediatamente.",
  str_homestory_819001001_22_dialog_content = "Espere um minuto... Eu estou no comando aqui - tenho a palavra final em todas as decisões.",
  str_homestory_819001001_23_dialog_content = "Se você quer continuar morando aqui conosco, você precisa aprender a conviver com pessoas diferentes.",
  str_homestory_819001001_24_dialog_content = "Hum? Por que palavras tão sérias de repente?",
  str_homestory_819001001_25_dialog_content = "Espere... Você está apenas... <size=45>imitando Schwab</size>!?",
  str_homestory_819001001_26_dialog_content = "Hum? O que você está falando?",
  str_homestory_819001001_27_dialog_content = "Ouvi dizer que Schwab também gosta de ler em pavilhões cheios de flores, e sempre tem grandes multidões de garotas se reunindo para ele quando ele o faz.",
  str_homestory_819001001_28_dialog_content = "Então, você está tentando fazer as garotas ficarem loucas por você também?",
  str_homestory_819001001_29_dialog_content = "Você quer ser tão popular quanto Schwab, então o está copiando.",
  str_homestory_819001001_30_dialog_content = "Entendo...",
  str_homestory_819001001_31_dialog_content = "O que!? Não olhe para mim assim, como se tivesse acabado de resolver um caso importante! <sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "Esse não é o caso! Por que eu iria querer ser qualquer coisa como aquele tolo?",
  str_homestory_819001001_33_dialog_content = "A palavra \"tolo\" soa como um insulto a princípio.",
  str_homestory_819001001_34_dialog_content = "Mas algumas pessoas usam isso para disfarçar sua afeição pelos outros.",
  str_homestory_819001001_35_dialog_content = "Estou começando a me sentir mal de repente...",
  str_homestory_819001001_36_dialog_content = "Eu sou um estudioso preeminente da Dawn Academy!",
  str_homestory_819001001_37_dialog_content = "Por que eu iria imitar um tolo que só se preocupa em manter sua imagem na frente de um bando de mulheres inconstantes!?",
  str_homestory_819001001_38_dialog_content = "Então, por que você precisa decorar o antigo pavilhão com flores e jogos de chá sofisticados?",
  str_homestory_819001001_39_dialog_content = "É apenas uma questão de minhas preferências como nobre, claro!",
  str_homestory_819001001_40_dialog_content = "Esqueça. Decore como quiser.",
  str_homestory_819001001_41_dialog_content = "Eu não me importo.",
  str_homestory_819001001_42_dialog_content = "(Protesto demais? Vendo como ele ficou confuso, ele claramente não pode ter sugerido tudo isso só porque queria um lugar para ler, pode?)",
  str_homestory_819101001_0_dialog_content = "Hati?",
  str_homestory_819101001_1_dialog_content = "O que você está fazendo?",
  str_homestory_819101001_2_dialog_content = "Oh, apenas conversando com um livro na estante.",
  str_homestory_819101001_3_dialog_content = "Uh... Como exatamente você fala com um livro?<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "Fácil! Você apenas faz uma pergunta e a resposta aparecerá em suas páginas! Às vezes, a resposta é tão verdadeira que fico arrepiado.",
  str_homestory_819101001_5_dialog_content = "Então o que você perguntou?",
  str_homestory_819101001_6_dialog_content = "Eu queria ouvir uma história, então pedi que me contasse uma.",
  str_homestory_819101001_7_dialog_content = "Que tipo de história? Foi assustador?",
  str_homestory_819101001_8_dialog_content = "Você não está com medo?",
  str_homestory_819101001_9_option_content = "Talvez um pouco...",
  str_homestory_819101001_10_dialog_content = "Mas ainda assim, estou curioso.",
  str_homestory_819101001_11_option_content = "Parou!",
  str_homestory_819101001_12_dialog_content = "Você está brincando? Como um cara durão como eu pode ter medo de um livro?",
  str_homestory_819101001_13_dialog_content = "A história que me contou agora há pouco foi mais ou menos assim...",
  str_homestory_819101001_14_dialog_content = "\"Em uma noite fria de inverno, você estava em frente a uma estante, lendo o Livro Onisciente...\"",
  str_homestory_819101001_15_dialog_content = "\"Quando, de repente, você notou algo se movendo atrás de você. Foi quando as palavras lentamente começaram a aparecer nas páginas...\"",
  str_homestory_819101001_16_dialog_content = "\"Não se vire. <size=45>Alguém</size> está atrás de você.\"",
  str_homestory_819101001_17_dialog_content = "\"Apesar do seu medo, você não pode deixar de se virar e olhar.\"",
  str_homestory_819101001_18_dialog_content = "Isso foi o máximo que consegui na história. Quando me virei para olhar, foi quando você entrou na sala.",
  str_homestory_819101001_19_dialog_content = "Hahaha! Parece um típico romance de suspense, mas com uma reviravolta na vida real. O que acontece depois?",
  str_homestory_819101001_20_dialog_content = "\"A pessoa atrás de você não é outro senão seu senhorio.\"",
  str_homestory_819101001_21_dialog_content = "\"Mas não precisa ter medo. Seu senhorio é fraco, e você pode mandá-lo voando com um único soco.\"",
  str_homestory_819101001_22_dialog_content = "Espere o que?! Agora você está apenas inventando coisas!",
  str_homestory_819101001_23_dialog_content = "Mas ainda assim, é quase assustador como a história é adequada! É por isso que não consigo largar essa história!",
  str_homestory_819101001_24_dialog_content = "\"Para se vingar do seu senhorio por assustá-lo, você decide dar-lhe um soco rápido.\"",
  str_homestory_819101001_25_dialog_content = "\"Infelizmente, seu soco leve o derruba no chão. Em retaliação, ele o chuta para fora de sua casa e para as ruas geladas, onde você pega um resfriado e morre.\"",
  str_homestory_819101001_26_dialog_content = "É assustador, hein? Oh, não se preocupe, Sr. Proprietário; Eu nunca sonharia em bater em você.",
  str_homestory_819101001_27_dialog_content = "E eu também não te expulsaria! Não, espere um segundo - não há como você me nocautear com um único soco!",
  str_homestory_819101001_28_dialog_content = "Quer tentar?",
  str_homestory_819101001_29_dialog_content = "Vamos fazê-lo!<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "Tudo bem, mas você pediu! Deixe-me apenas soltar meu pulso.",
  str_homestory_819101001_31_dialog_content = "Eu estava falando sobre aquele Livro Onisciente!",
  str_homestory_819101001_32_dialog_content = "Oh? Então, o que você quer perguntar?",
  str_homestory_819101001_33_dialog_content = "Pode realmente responder a qualquer pergunta?",
  str_homestory_819101001_34_dialog_content = "Você vê, eu estou um pouco em apuros agora. Vice me pediu para resolver as finanças do Colosso para o mês...",
  str_homestory_819101001_35_dialog_content = "Eu ouvi você mencionar algo sobre isso no refeitório, sim.",
  str_homestory_819101001_36_dialog_content = "Então foi a primeira coisa que perguntei, e ele respondeu:",
  str_homestory_819101001_37_dialog_content = "\"Sou apenas um livro. Não tenho bens, então não tenho como ajudá-lo a equilibrar suas finanças.\"",
  str_homestory_819101001_38_dialog_content = "Tch... E aqui pensei que poderia responder a qualquer pergunta!",
  str_homestory_819101001_39_dialog_content = "Não há necessidade de perguntar ao Livro Onisciente. Eu poderia responder a sua pergunta, sem problemas.",
  str_homestory_819101001_40_dialog_content = "Oh sério? Vamos ouvir então.",
  str_homestory_819101001_41_dialog_content = "As despesas do Colossus estão completamente fora de controle e você está à beira da falência. Eventualmente, você acabará nas ruas geladas, onde pegará um resfriado e morrerá.",
  str_homestory_819101001_42_dialog_content = "Não roube apenas do Livro Onisciente!",
  str_homestory_819101001_43_dialog_content = "Bem, é uma resposta bastante adequada, não acha?",
  str_homestory_819101001_44_dialog_content = "Não é o que você esperava? Boo-hoo...",
  str_homestory_817702001_0_dialog_content = "Ei, eu acho que ouvi Goldie cantoria!",
  str_homestory_817702001_1_dialog_content = "♪ La-la-laa! ♪",
  str_homestory_817702001_2_dialog_content = "Oh, PlayerName! Olá.",
  str_homestory_817702001_3_dialog_content = "Oi, Goldie!",
  str_homestory_817702001_4_dialog_content = "Desculpe, não estou te interrompendo, estou?",
  str_homestory_817702001_5_dialog_content = "De jeito nenhum, de jeito nenhum!",
  str_homestory_817702001_6_dialog_content = "Não pude deixar de começar a cantar quando vi o violino aqui!",
  str_homestory_817702001_7_dialog_content = "Para ser sincero, fiquei muito surpreso ao descobrir que você tinha um, PlayerName.",
  str_homestory_817702001_8_dialog_content = "Será que... Você se interessa por instrumentos?",
  str_homestory_817702001_9_option_content = "Eu sou!",
  str_homestory_817702001_10_dialog_content = "Claro! Eu amo instrumentos!",
  str_homestory_817702001_11_dialog_content = "Mas eu não posso jogar nenhum deles, então não é bem um hobby, heheh...",
  str_homestory_817702001_12_dialog_content = "Mas isso ainda é uma coisa maravilhosa!",
  str_homestory_817702001_13_dialog_content = "Parece que temos mais uma coisa em comum, PlayerName!",
  str_homestory_817702001_14_option_content = "Não muito.",
  str_homestory_817702001_15_dialog_content = "Bem, eu não chamaria isso de interesse, sério...",
  str_homestory_817702001_16_dialog_content = "Mas se eu aprender a tocar um instrumento, você será o primeiro a ouvir!",
  str_homestory_817702001_17_dialog_content = "Realmente? Heehee... Estou tão honrado! Obrigado!",
  str_homestory_817702001_18_dialog_content = "Devo mencionar algo, no entanto...",
  str_homestory_817702001_19_dialog_content = "Este não é apenas um violino comum.",
  str_homestory_817702001_20_dialog_content = "Na verdade, fazia parte da coleção de um detetive famoso!",
  str_homestory_817702001_21_dialog_content = "Um detetive?",
  str_homestory_817702001_22_dialog_content = "Isso mesmo! Aparentemente, esse detetive gostava muito de jogar sempre que não estava investigando casos.",
  str_homestory_817702001_23_dialog_content = "Eu realmente não sei muito mais sobre eles...",
  str_homestory_817702001_24_dialog_content = "Mas um detetive apaixonado pelas artes - isso soa romântico <sprite=emo_aixin size=60 />!",
  str_homestory_817702001_25_dialog_content = "Sim!",
  str_homestory_817702001_26_dialog_content = "Um detetive calmo e racional que passa as noites sozinho, tendo apenas um violino para lhe fazer companhia...",
  str_homestory_817702001_27_dialog_content = "Espere um minuto... É isso! Essa é a inspiração que eu precisava!",
  str_homestory_817702001_28_dialog_content = "Que inspiração?",
  str_homestory_817702001_29_dialog_content = "A inspiração para o meu <sprite=emo_yinfu size=60 /> nova música!",
  str_homestory_817702001_30_dialog_content = "Terei que encomendar novos figurinos e inventar uma nova coreografia também!",
  str_homestory_817702001_31_dialog_content = "Estou ficando tão animado só de pensar nisso!",
  str_homestory_817702001_32_dialog_content = "Um show de ídolos com tema de detetive, hein?",
  str_homestory_817702001_33_dialog_content = "Aposto que vai ser um grande sucesso!",
  str_homestory_817702001_34_dialog_content = "Se alguém pode fazer isso, é você Goldie!",
  str_homestory_817702001_35_dialog_content = "Heehee! Espero vê-lo na platéia quando chegar o dia!",
  str_homestory_811602001_0_dialog_content = "O que é Fleur fazendo lá?",
  str_homestory_811602001_1_dialog_content = "Ei, Fleur! O que você está fazendo?",
  str_homestory_811602001_2_dialog_content = "Aí, Navegador!",
  str_homestory_811602001_3_dialog_content = "Estou ajustando o enfeite.",
  str_homestory_811602001_4_dialog_content = "Peguei para brincar com ele agora...",
  str_homestory_811602001_5_dialog_content = "E estava fazendo um barulho estranho.",
  str_homestory_811602001_6_dialog_content = "Um barulho estranho?",
  str_homestory_811602001_7_dialog_content = "Isso mesmo. Talvez um dos parafusos esteja muito apertado, ou talvez só precise de um pouco de óleo...",
  str_homestory_811602001_8_dialog_content = "Esta roda continua fazendo um barulho horrível.",
  str_homestory_811602001_9_option_content = "Entendi!",
  str_homestory_811602001_10_dialog_content = "Agora que você mencionou, este enfeite parece um pouco estranho...",
  str_homestory_811602001_11_dialog_content = "Se está fazendo esse tipo de som, isso não significa que uma de suas partes está em mau estado?",
  str_homestory_811602001_12_dialog_content = "Isso mesmo!",
  str_homestory_811602001_13_dialog_content = "A maioria das pessoas tem dificuldade em entender isso, mas parece que você pode ter um talento especial para consertar máquinas.",
  str_homestory_811602001_14_dialog_content = "V-você acha? Hehehe...",
  str_homestory_811602001_15_option_content = "estou sem noção...",
  str_homestory_811602001_16_dialog_content = "Você acha...?",
  str_homestory_811602001_17_dialog_content = "Deixe isso para um especialista como você descobrir isso, Fleur. Eu sou desesperado quando se trata desse tipo de coisa.",
  str_homestory_811602001_18_dialog_content = "Entendo... Eu esperava falar com você sobre máquinas, mas acho que isso está fora de questão.",
  str_homestory_811602001_19_dialog_content = "Não se preocupe, ainda posso consertar isso sozinho.",
  str_homestory_811602001_20_dialog_content = "Hmm... Parece que eu estava certo. Esse parafuso está muito apertado...",
  str_homestory_811602001_21_dialog_content = "Pena que não tenho ferramentas para soltá-lo agora.",
  str_homestory_811602001_22_dialog_content = "Voltarei e consertarei assim que encontrar a ferramenta certa, ok?",
  str_homestory_811602001_23_dialog_content = "Coisa certa, Fleur. Obrigado novamente!",
  str_homestory_811602001_24_dialog_content = "Não mencione isso. Afinal, é apenas um pequeno parafuso.",
  str_homestory_811602001_25_dialog_content = "Ainda assim, um pequeno parafuso pode fazer toda a diferença quando se trata de máquinas, sabia?",
  str_homestory_811602001_26_dialog_content = "Ainda bem que é só um brinquedo, se fosse um carrinho de verdade...",
  str_homestory_811602001_27_dialog_content = "A roda já estaria quebrada! Hahaha!",
  str_homestory_811602001_28_dialog_content = "Sem brincadeiras. Pessoas normais como nós só sabem que algo precisa ser consertado quando finalmente quebra...",
  str_homestory_811602001_29_dialog_content = "Se ao menos todas as máquinas pudessem apontar seus problemas para nós como Soroz...",
  str_homestory_811602001_30_dialog_content = "Isso está certo?",
  str_homestory_811602001_31_dialog_content = "Se você me perguntar, as pessoas são muito mais difíceis de entender <sprite=emo_sikao size=60 />...",
  str_homestory_811602001_32_dialog_content = "Não me interpretem mal, conceder a cada máquina uma personalidade seria uma enorme conquista...",
  str_homestory_811602001_33_dialog_content = "Mas a última coisa de que preciso é que as máquinas mintam para mim enquanto estou trabalhando nelas!",
  str_homestory_811602001_34_dialog_content = "Heheh, é verdade.",
  str_homestory_811602001_35_dialog_content = "Se esse dia chegar, tenho certeza que você estará cheio de problemas.",
  str_homestory_808401001_0_dialog_content = "Você também gosta de enigmas, Istvan?",
  str_homestory_808401001_1_dialog_content = "Chegou bem na hora, meu jovem amigo.",
  str_homestory_808401001_2_dialog_content = "Diga-me, o que você acha dessa imagem?",
  str_homestory_808401001_3_dialog_content = "O que eu acho disso? Deixe-me ver...",
  str_homestory_808401001_4_option_content = "Parece um pouco desafiador.",
  str_homestory_808401001_5_dialog_content = "Acho que algumas dessas pistas parecem um pouco suspeitas <sprite=emo_sikao size=60 />.",
  str_homestory_808401001_6_dialog_content = "Aposto que poderia descobrir com um pouco mais de tempo!",
  str_homestory_808401001_7_option_content = "Não entendi.",
  str_homestory_808401001_8_dialog_content = "Er... eu não sou exatamente o melhor em resolver enigmas <sprite=emo_tanqi size=60 />.",
  str_homestory_808401001_9_dialog_content = "Eu não consigo entender isso de jeito nenhum...",
  str_homestory_808401001_10_dialog_content = "Entendi.",
  str_homestory_808401001_11_dialog_content = "Me desculpe. Você me fez uma pergunta primeiro, e eu respondi com outra pergunta.",
  str_homestory_808401001_12_dialog_content = "Acho que deveria ter lhe dado uma resposta verdadeira...",
  str_homestory_808401001_13_dialog_content = "Não, meu amigo. Não gosto nada de enigmas.",
  str_homestory_808401001_14_dialog_content = "Huh? Então por que você ainda está tentando descobrir?!",
  str_homestory_808401001_15_dialog_content = "Fique tranquilo, meu jovem amigo, há uma explicação perfeitamente razoável para isso.",
  str_homestory_808401001_16_dialog_content = "A julgar pelas suas próprias palavras, você assumiu que esta imagem era uma pista para um enigma.",
  str_homestory_808401001_17_dialog_content = "O que significa que você inadvertidamente o viu da perspectiva de um detetive.",
  str_homestory_808401001_18_dialog_content = "Er... Isso mesmo, eu acho?",
  str_homestory_808401001_19_dialog_content = "No entanto, existem muitos outros personagens envolvidos neste caso.",
  str_homestory_808401001_20_dialog_content = "O detetive, o perpetrador, a vítima...",
  str_homestory_808401001_21_dialog_content = "E, claro, o instigador.",
  str_homestory_808401001_22_dialog_content = "O instigador?",
  str_homestory_808401001_23_dialog_content = "De fato. Como um pastor, o instigador é responsável por tudo e se beneficia disso mais do que qualquer outra pessoa.",
  str_homestory_808401001_24_dialog_content = "Criando ovelhas cuidadosamente à mão, pastoreando-as com cães leais, protegendo-as de lobos famintos...",
  str_homestory_808401001_25_dialog_content = "Um bom pastor nunca entrega seu rebanho aos caprichos do destino.",
  str_homestory_808401001_26_dialog_content = "É por isso que, em vez de resolver o enigma, o instigador escolhe a resposta que mais o beneficia.",
  str_homestory_808401001_27_dialog_content = "I-Isso é terrivelmente complicado!",
  str_homestory_808401001_28_dialog_content = "Mas acho que entendo o que você está tentando dizer, Istvan...",
  str_homestory_808401001_29_dialog_content = "Para um líder como você, às vezes a verdade não é tão importante quanto o resultado final, certo?",
  str_homestory_808401001_30_dialog_content = "Suas habilidades de dedução estão mais aguçadas do que nunca.",
  str_homestory_808401001_31_dialog_content = "Embora você ainda seja jovem e suas possibilidades futuras sejam quase ilimitadas.",
  str_homestory_808401001_32_dialog_content = "Só espero que um Navegador como você aprenda a mover outras peças a seu favor.",
  str_homestory_808401001_33_dialog_content = "Entregar-se aos prazeres da mediocridade é muita ovelha, não pastores.",
  str_homestory_808401001_34_dialog_content = "Heheheh... Obrigado, mas acho que é um pouco cedo para eu pensar nessas coisas...",
  str_homestory_808401001_35_dialog_content = "... Talvez você esteja certo. Apressar essas coisas pode ser prejudicial em alguns casos.",
  str_homestory_808401001_36_dialog_content = "Nesse caso, por que não lhe ofereço uma tarefa mais adequada à sua idade?",
  str_homestory_808401001_37_dialog_content = "Enquanto eu estava perto do rio, notei uma moeda brilhante na água <sprite=emo_baiyebi size=60 />.",
  str_homestory_808401001_38_dialog_content = "Não pude ter certeza na época, mas há uma chance de que fosse uma bugiganga rara.",
  str_homestory_808401001_39_dialog_content = "Por que você não vai dar uma olhada?",
  str_homestory_808401001_40_dialog_content = "Claro! Obrigado, Istvan!",
  str_homestory_819301001_0_dialog_content = "Kristen?",
  str_homestory_819301001_1_dialog_content = "E aí, Kristen?",
  str_homestory_819301001_2_dialog_content = "Hmm-hmm-hmm! <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_3_dialog_content = "Oh nada, apenas ouvindo música!",
  str_homestory_819301001_4_dialog_content = "Seu toca-discos é tão bonito, então eu tive que experimentá-lo!",
  str_homestory_819301001_5_dialog_content = "Então, o que você acha?",
  str_homestory_819301001_6_dialog_content = "É incrivel! A qualidade do som é incrível... Você realmente escolheu um bom!",
  str_homestory_819301001_7_dialog_content = "Há quanto tempo você é um amante da música, PlayerName?",
  str_homestory_819301001_8_dialog_content = "Sempre gostei muito de música, mas tenho tendência a apanhar coisas interessantes durante as minhas viagens... Como este gira-discos!",
  str_homestory_819301001_9_dialog_content = "Embora eu tenha certeza de que não é nada comparado à sua própria coleção.",
  str_homestory_819301001_10_dialog_content = "Bem, a casa da minha família tem uma coleção bastante extensa de tocadores de música... Um deles é bem grande também!",
  str_homestory_819301001_11_dialog_content = "eu apostaria...",
  str_homestory_819301001_12_dialog_content = "É provavelmente tão alto quanto a entrada do Hall of Justice.",
  str_homestory_819301001_13_dialog_content = "O-O quê?!",
  str_homestory_819301001_14_dialog_content = "A entrada do Tribunal de Justiça... É enorme!",
  str_homestory_819301001_15_dialog_content = "Você provavelmente poderia realizar um concerto em algo tão grande!",
  str_homestory_819301001_16_dialog_content = "Meu pai é um daqueles nobres colecionadores, sabe? Às vezes fica um pouco fora de mão!",
  str_homestory_819301001_17_dialog_content = "Mas você é um nobre também, Kristen...",
  str_homestory_819301001_18_dialog_content = "Sim, mas meu pai e eu somos diferentes!",
  str_homestory_819301001_19_dialog_content = "Ou você realmente acha que eu sou como um daqueles velhos nobres enfadonhos?",
  str_homestory_819301001_20_option_content = "Você não está!",
  str_homestory_819301001_21_dialog_content = "Você está sempre à procura de coisas novas e populares.",
  str_homestory_819301001_22_dialog_content = "Como a música, por exemplo!",
  str_homestory_819301001_23_option_content = "Talvez um pouco...",
  str_homestory_819301001_24_dialog_content = "Quero dizer, você é muito bem-educado, assim como todos os nobres que conheci.",
  str_homestory_819301001_25_dialog_content = "Heehee! Você realmente pensa assim, PlayerName?",
  str_homestory_819301001_26_dialog_content = "Não posso dizer que discordo.",
  str_homestory_819301001_27_dialog_content = "Sim, meu nascimento me faz parte da nobreza e tudo...",
  str_homestory_819301001_28_dialog_content = "Mas no fundo do meu coração, quero viver minha própria vida, nos meus próprios termos!",
  str_homestory_819301001_29_dialog_content = "E essa nova música me deu a inspiração que preciso para continuar!",
  str_homestory_819301001_30_dialog_content = "Espera aí!",
  str_homestory_819301001_31_dialog_content = "V-Você vai se apresentar bem aqui, Kristen? Agora mesmo?!",
  str_homestory_819301001_32_dialog_content = "Isso mesmo! Essa música também é perfeita para atingir algumas notas bem altas! Laaaa— <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "H-Espere!",
  str_homestory_819301001_34_dialog_content = "Oh, você olharia a hora? Esqueci totalmente que tinha algo importante para fazer! Até mais!",
  str_homestory_819301001_35_dialog_content = "R-Agora?",
  str_homestory_819301001_36_dialog_content = "Sim! Mas vá em frente e divirta-se com o toca-discos! Tchau!",
  str_homestory_819201001_0_dialog_content = "Leo?",
  str_homestory_819201001_1_dialog_content = "Eu estava apenas procurando por uma lupa, e aqui está.",
  str_homestory_819201001_2_dialog_content = "Para que você vai usá-lo?",
  str_homestory_819201001_3_dialog_content = "Para olhar este mapa.",
  str_homestory_819201001_4_dialog_content = "Meus subordinados exploraram recentemente as posições de várias fortalezas militares ao longo da fronteira.",
  str_homestory_819201001_5_dialog_content = "Acabaram de desenhar este mapa hoje e o enviaram.",
  str_homestory_819201001_6_dialog_content = "Mas a caligrafia neste mapa é tão desalinhada e ridiculamente pequena. Está me dando dor de cabeça. <sprite=emo_xuanyun size=60 />",
  str_homestory_819201001_7_dialog_content = "Há muitas palavras escritas no mapa?",
  str_homestory_819201001_8_dialog_content = "Veja você mesmo.",
  str_homestory_819201001_9_dialog_content = "\"Exibição de exploração e análise de fortalezas militares a 80 quilômetros do crepúsculo...\"",
  str_homestory_819201001_10_dialog_content = "Há também uma segunda linha.",
  str_homestory_819201001_11_dialog_content = "\"... e informações detalhadas, como distribuição espacial, quantidade e características qualitativas e inter-relações\"",
  str_homestory_819201001_12_dialog_content = "Huff... huff... <sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "D-Os nomes de todos os mapas... são tão complicados?",
  str_homestory_819201001_14_dialog_content = "Mal consigo recuperar o fôlego depois de lê-lo de uma só vez.",
  str_homestory_819201001_15_dialog_content = "Claro que não precisa ser tão complicado, mas dessa vez o cartógrafo foi bem minucioso, então escreveu o máximo que pôde...",
  str_homestory_819201001_16_dialog_content = "Realmente não é necessário.",
  str_homestory_819201001_17_dialog_content = "Não é de admirar que tantos estrategistas carreguem uma lupa com eles.",
  str_homestory_819201001_18_dialog_content = "Se eles tiverem que confiar em um cartógrafo tão minucioso quanto esse cara, uma lupa é sua única esperança de conseguir ler seus mapas com clareza.",
  str_homestory_819201001_19_dialog_content = "(Mas mesmo depois de conseguir ler esse nome ridículo, você provavelmente ficaria ainda mais frustrado.)",
  str_homestory_819201001_20_dialog_content = "De fato, existem muitos líderes que gostam de usar lentes de aumento.",
  str_homestory_819201001_21_dialog_content = "Eles não apenas podem ampliar texto e imagens e auxiliar na observação, mas também podem ajudar a fazer fogueiras quando o sol está brilhando.",
  str_homestory_819201001_22_dialog_content = "Pode-se dizer que são ferramentas versáteis, essenciais para as tropas em marcha.",
  str_homestory_819201001_23_dialog_content = "No entanto, tenho minhas reservas quanto às lupas.",
  str_homestory_819201001_24_dialog_content = "Por quê?",
  str_homestory_819201001_25_dialog_content = "Você também é um comandante em batalha. Talvez você possa adivinhar o motivo?",
  str_homestory_819201001_26_option_content = "Eles dependem da luz.",
  str_homestory_819201001_27_dialog_content = "Eles são difíceis de usar à noite ou no escuro.",
  str_homestory_819201001_28_dialog_content = "Isso é realmente um problema, mas desde que uma fonte de luz esteja disponível, esse problema pode ser evitado.",
  str_homestory_819201001_29_option_content = "Eles podem limitar seu campo de visão.",
  str_homestory_819201001_30_dialog_content = "De fato.",
  str_homestory_819201001_31_dialog_content = "Uma lupa amplia uma área, permitindo que o observador veja os detalhes com mais precisão.",
  str_homestory_819201001_32_dialog_content = "Mas, ao mesmo tempo, o campo de visão do observador é limitado ao alcance da lupa.",
  str_homestory_819201001_33_dialog_content = "Isso torna a pessoa incapaz de observar o ambiente mais amplo que os cerca.",
  str_homestory_819201001_34_dialog_content = "Mas a guerra geralmente requer o envio de tropas de uma perspectiva mais ampla.",
  str_homestory_819201001_35_dialog_content = "Às vezes, evito deliberadamente usar uma lupa para evitar que meu campo de visão fique muito focado.",
  str_homestory_819201001_36_dialog_content = "Você realmente é um estrategista inspirador.",
  str_homestory_819201001_37_dialog_content = "É apenas um hábito pessoal. Por exemplo, não tenho escolha a não ser pedir uma lupa em nossa situação atual.",
  str_homestory_819201001_38_dialog_content = "Você pode usar a lupa aqui sempre que quiser.",
  str_homestory_819201001_39_dialog_content = "Mas certifique-se de colocá-lo de volta em sua caixa depois de terminar de usá-lo.",
  str_homestory_819201001_40_dialog_content = "Se for exposto à luz solar direta, pode causar um incêndio. <sprite=emo_nuhuo size=60 />",
  str_homestory_819201001_41_dialog_content = "Haha, é bom que você tenha um forte senso de conscientização sobre segurança contra incêndio.",
  str_homestory_819201001_42_dialog_content = "Afinal, trabalhei tanto para fazer deste um lugar que posso chamar de lar.",
  str_homestory_819201001_43_dialog_content = "Se todo o meu dinheiro for consumido pelas chamas... bem, todo o meu trabalho árduo terá sido em vão.",
  str_homestory_819901001_0_dialog_content = "Yingel?",
  str_homestory_819901001_1_dialog_content = "Oh, PlayerName. Estou prestes a experimentar este café.",
  str_homestory_819901001_2_dialog_content = "Você mesmo preparou?",
  str_homestory_819901001_3_dialog_content = "Isso mesmo.",
  str_homestory_819901001_4_dialog_content = "Eu vi esta linda caneca de café agora, então pensei em tentar preparar uma xícara eu mesmo.",
  str_homestory_819901001_5_dialog_content = "Cheira incrível! <sprite=emo_dianzan size=60 />",
  str_homestory_819901001_6_dialog_content = "Veja o padrão na superfície? Isso é o que eles chamam de latte art.",
  str_homestory_819901001_7_dialog_content = "Sim, eu vejo isso! É lindo!",
  str_homestory_819901001_8_dialog_content = "Esta forma parece... Aoha?",
  str_homestory_819901001_9_dialog_content = "Você pode dizer que é Aoha? Bem, suponho que não posso chamar essa tentativa de fracasso.",
  str_homestory_819901001_10_dialog_content = "Claro que não é um fracasso! É incrível!",
  str_homestory_819901001_11_dialog_content = "Como você fez isso, Yingel?",
  str_homestory_819901001_12_dialog_content = "Fazer um café com leite não é nada difícil e os ingredientes também são muito básicos.",
  str_homestory_819901001_13_dialog_content = "Em primeiro lugar, você precisa colocar uma xícara pequena de café expresso em uma xícara de café...",
  str_homestory_819901001_14_dialog_content = "Em seguida, faça espuma com um pouco de leite fresco e adicione-o ao café expresso.",
  str_homestory_819901001_15_dialog_content = "Ao adicionar a espuma, ajuste a forma movendo o copo de leite.",
  str_homestory_819901001_16_dialog_content = "E assim, você deve ter um café com leite com um belo padrão.",
  str_homestory_819901001_17_dialog_content = "Você faz parecer fácil, mas tenho certeza que não é tão simples quanto parece...",
  str_homestory_819901001_18_dialog_content = "A prática leva à perfeição. Apenas tente algumas vezes e você ficará bem.",
  str_homestory_819901001_19_dialog_content = "Sempre que me sinto cansado no trabalho, preparo um café com leite.",
  str_homestory_819901001_20_dialog_content = "Leite suave e café maduro são uma combinação perfeita.",
  str_homestory_819901001_21_dialog_content = "PlayerName, gostaria de experimentar?<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "Sim.",
  str_homestory_819901001_23_dialog_content = "Afinal, você mesmo fez este café.",
  str_homestory_819901001_24_option_content = "Não.",
  str_homestory_819901001_25_dialog_content = "Se eu tomar café agora, tenho medo de não conseguir dormir.",
  str_homestory_819901001_26_dialog_content = "Tem mais de dois terços de leite, então não vai te manter acordada.",
  str_homestory_819901001_27_dialog_content = "Realmente? Nesse caso, adoraria tentar.",
  str_homestory_819901001_28_dialog_content = "Como é?",
  str_homestory_819901001_29_dialog_content = "Eu dou dez de dez para o sabor!",
  str_homestory_819901001_30_dialog_content = "Se eu pudesse fazer um café com leite tão delicioso quanto este.",
  str_homestory_819901001_31_dialog_content = "Você deveria tentar fazer um - eu sei que você pode fazer isso.",
  str_homestory_819901001_32_dialog_content = "No entanto, parece que meu leite acabou...",
  str_homestory_819901001_33_dialog_content = "O que, já foi tudo?",
  str_homestory_819901001_34_dialog_content = "Eu estava com muita sede agora, então bebi tudo.",
  str_homestory_819901001_35_dialog_content = "Erm, Yingel... você não pode simplesmente engolir leite como se fosse água...",
  str_homestory_820001001_0_dialog_content = "É Anatoli olhando para aquela lâmpada ao ar livre?",
  str_homestory_820001001_1_dialog_content = "O que está fazendo, Anatoli?",
  str_homestory_820001001_2_dialog_content = "Estou observando esta lâmpada.",
  str_homestory_820001001_3_option_content = "Observando uma lâmpada?",
  str_homestory_820001001_4_dialog_content = "Eu descobri que ele permanece ligado, mesmo durante o dia.",
  str_homestory_820001001_5_dialog_content = "Embora a luz que emite seja muito menos radiante que a luz do sol, ela nunca se apaga.",
  str_homestory_820001001_6_dialog_content = "Alguém está constantemente adicionando óleo de lamparina a ele?",
  str_homestory_820001001_7_dialog_content = "Uh, eu não sei a resposta para isso também...",
  str_homestory_820001001_8_option_content = "Por quê?",
  str_homestory_820001001_9_dialog_content = "Porque está sempre ligado, dia e noite.",
  str_homestory_820001001_10_dialog_content = "Embora discreto durante o dia, ilumina a escuridão à noite. <sprite=emo_taiyang size=60 />",
  str_homestory_820001001_11_dialog_content = "Claro que não!",
  str_homestory_820001001_12_dialog_content = "É ótimo ter uma luz iluminando a estrada à noite!",
  str_homestory_820001001_13_dialog_content = "No entanto ... deixar a luz acesa durante o dia parece um desperdício.",
  str_homestory_820001001_14_dialog_content = "Sim ... certamente faz.",
  str_homestory_820001001_15_dialog_content = "Afinal, esta não é a Noite Eterna... Realmente não há necessidade de manter as luzes acesas o tempo todo.",
  str_homestory_820001001_16_dialog_content = "Então vou apagá-lo por enquanto e acendê-lo mais tarde à noite.",
  str_homestory_820001001_17_dialog_content = "Seria melhor se você o mantivesse.",
  str_homestory_820001001_18_dialog_content = "Huh? Por quê?",
  str_homestory_820001001_19_dialog_content = "Podemos não saber quem está adicionando óleo a esta lâmpada, mas eles devem ter seus motivos.",
  str_homestory_820001001_20_dialog_content = "Seria melhor se não atrapalhássemos a rotina deles.",
  str_homestory_820001001_21_dialog_content = "Você tem razão.",
  str_homestory_820001001_22_dialog_content = "Eu realmente quero saber quem é essa pessoa misteriosa!",
  str_homestory_820001001_23_dialog_content = "Bem, tente observar mais e talvez um dia você os encontre.",
  str_homestory_820001001_24_dialog_content = "Lembro-me de você ser um verdadeiro gênio quando se trata de raciocínio e análise...",
  str_homestory_820001001_25_dialog_content = "Você tem alguma ideia de quem pode ser o isqueiro misterioso?",
  str_homestory_820001001_26_dialog_content = "Eu tenho minhas especulações.",
  str_homestory_820001001_27_dialog_content = "Como qual?",
  str_homestory_820001001_28_dialog_content = "Deve ser alguém muito paciente, capaz de persistir em fazer algo por muito tempo.",
  str_homestory_820001001_29_dialog_content = "E devem ter boa memória, pois parecem nunca esquecer uma tarefa tão trivial.",
  str_homestory_820001001_30_dialog_content = "Por último, eles parecem gostar muito de objetos que emitem uma luz modesta.",
  str_homestory_820001001_31_dialog_content = "Sim, isso faz sentido...",
  str_homestory_820001001_32_dialog_content = "Na verdade, isso me lembra algumas pessoas.",
  str_homestory_820001001_33_dialog_content = "Espere, eu tenho isso!",
  str_homestory_820001001_34_dialog_content = "Você não está falando apenas de você?!",
  str_homestory_820001001_35_dialog_content = "Excelente dedução.",
  str_homestory_820001001_36_dialog_content = "Então, por que você mantém esta lâmpada acesa?",
  str_homestory_820001001_37_dialog_content = "É claramente de dia, então obviamente não há necessidade de usar uma lâmpada...",
  str_homestory_820001001_38_dialog_content = "Embora a mais leve centelha de chama possa parecer pouco visível à luz do sol, ainda há algo que só ela pode fazer.",
  str_homestory_820001001_39_dialog_content = "Isto é o que eu acredito.",
  str_homestory_802801001_0_dialog_content = "Eu conheço essa voz...",
  str_homestory_802801001_1_dialog_content = "Isso é Raphael!",
  str_homestory_802801001_2_dialog_content = "Whoosh! Whoosh! Whoosh!",
  str_homestory_802801001_3_dialog_content = "PlayerName! É maravilhoso ver você!",
  str_homestory_802801001_4_dialog_content = "Ei! Experimente minhas novas pílulas Brain Booster!",
  str_homestory_802801001_5_dialog_content = "Essas pequenas coisas podem instantaneamente enchê-lo de energia! Eles podem até permitir que você sinta a presença de um tesouro místico!",
  str_homestory_802801001_6_dialog_content = "Edição limitada! Não perca esta chance única na vida!",
  str_homestory_802801001_7_option_content = "Acho que não preciso disso, obrigado...",
  str_homestory_802801001_8_dialog_content = "Eu tenho procurado alto e baixo por um tempo agora, e finalmente encontrei você!",
  str_homestory_802801001_9_dialog_content = "Você não quer que meu pequeno experimento falhe, quer?",
  str_homestory_802801001_10_dialog_content = "Para ser sincero, não estava pensando nisso...",
  str_homestory_802801001_11_option_content = "Deixe-me dar-lhes uma chance!",
  str_homestory_802801001_12_dialog_content = "Ele Ele! Você está inesperadamente alegre hoje, PlayerName!",
  str_homestory_802801001_13_dialog_content = "Amanhã trago mais!",
  str_homestory_802801001_14_dialog_content = "Erm... Você realmente não tem mais nada para fazer esses dias?",
  str_homestory_802801001_15_dialog_content = "Abra a boca e diga, \"ah\"!",
  str_homestory_802801001_16_dialog_content = "E-Espere um minuto!",
  str_homestory_802801001_17_dialog_content = "Esse cheiro... Não é a louça do Vice?",
  str_homestory_802801001_18_dialog_content = "(Uh, aqueles queimados... <sprite=emo_hanshui size=60 />)",
  str_homestory_802801001_19_dialog_content = "Huh?! Você não confia em mim?",
  str_homestory_802801001_20_dialog_content = "Erm... O que quero dizer é... você vê...",
  str_homestory_802801001_21_dialog_content = "Eu entendo, eu entendo! Você gosta de companheiros de confiança em quem pode confiar, não é? PlayerName?",
  str_homestory_802801001_22_dialog_content = "Estou fazendo o meu melhor para me tornar um companheiro incomparavelmente confiável!",
  str_homestory_802801001_23_dialog_content = "Aquele que pode fazer pílulas Brain Booster—",
  str_homestory_802801001_24_dialog_content = "Hehe, mas eu realmente não deveria me gabar.",
  str_homestory_802801001_25_dialog_content = "(Ela é surpreendentemente otimista...)",
  str_homestory_802801001_26_dialog_content = "Que tal agora, Raphael- você pode ir em frente e fazer um pouco mais, e depois deixar Carleen experimente-os outro dia!",
  str_homestory_802801001_27_dialog_content = "Ela está sempre trabalhando tanto... Ela pode até gostar de alguns Brain Boosters.",
  str_homestory_802801001_28_dialog_content = "Huh? Carleen?",
  str_homestory_802801001_29_dialog_content = "Eu não acho!",
  str_homestory_802801001_30_dialog_content = "Como assim?",
  str_homestory_802801001_31_dialog_content = "Porque se eu levá-los para Carleen, eu sei que ela diria—",
  str_homestory_802801001_32_dialog_content = "\"Raphael! Não se atreva a tentar me dar mais do seu doce estranho - e não pergunte por quê.\"",
  str_homestory_802801001_33_dialog_content = "Por quê?",
  str_homestory_802801001_34_dialog_content = "Eu gostaria de saber! <sprite=emo_sikao size=60 /> Mas Carleen nem me deixa perguntar.",
  str_homestory_802801001_35_dialog_content = "Ah sim, e...",
  str_homestory_802801001_36_dialog_content = "Essas pílulas foram criadas especificamente para você e suas habilidades psíquicas, PlayerName!",
  str_homestory_802801001_37_dialog_content = "Tudo bem, eu entendo... Apenas me dê então!",
  str_homestory_802801001_38_dialog_content = "(Bom, se for só doce...)",
  str_homestory_802801001_39_dialog_content = "Ele Ele! Eu sabia que eles eram perfeitos para você, PlayerName!",
  str_homestory_802801001_40_dialog_content = "Então, como foi...? Como foi?! Você notou alguma mudança?",
  str_homestory_802801001_41_dialog_content = "Você viu algo brilhante? Como um tesouro?",
  str_homestory_802801001_42_dialog_content = "Minha visão parece mais clara e posso ver mais longe—",
  str_homestory_802801001_43_dialog_content = "No Rio! Há realmente algo brilhante no rio!",
  str_homestory_802801001_44_dialog_content = "Sim! No Rio! Eu sabia!",
  str_homestory_802801001_45_dialog_content = "Meu experimento com o Brain Booster foi um sucesso! <sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "O que está fazendo aqui?",
  str_homestory_820201001_1_dialog_content = "Olha Você aqui.",
  str_homestory_820201001_2_dialog_content = "Este trono foi criado especificamente para mim?",
  str_homestory_820201001_3_dialog_content = "Sim...",
  str_homestory_820201001_4_dialog_content = "Eu aprovo o pensamento.",
  str_homestory_820201001_5_dialog_content = "Embora não esteja no nível do trono genuíno nos Jardins de Lumopolis...",
  str_homestory_820201001_6_dialog_content = "No entanto, é suficientemente adequado para o meu status.",
  str_homestory_820201001_7_dialog_content = "Estou feliz por ter gostado!",
  str_homestory_820201001_8_dialog_content = "Há mais alguma coisa que você precisa?",
  str_homestory_820201001_9_dialog_content = "Que tal construir um novo palácio Lumopolis aqui? <sprite=emo_sikao size=60 />",
  str_homestory_820201001_10_dialog_content = "Como já temos um trono, podemos construir um palácio para acompanhá-lo.",
  str_homestory_820201001_11_dialog_content = "Você quer construir um palácio aqui?",
  str_homestory_820201001_12_dialog_content = "Acho que falta espaço...",
  str_homestory_820201001_13_dialog_content = "Hum, isso é verdade. Além de ser bruto, não é grande o suficiente.",
  str_homestory_820201001_14_dialog_content = "Que tal uma reforma financiada por mim?",
  str_homestory_820201001_15_option_content = "Tudo bem",
  str_homestory_820201001_16_dialog_content = "Eu aprecio o pensamento.",
  str_homestory_820201001_17_option_content = "Você poderia?",
  str_homestory_820201001_18_dialog_content = "Além de materiais, muita mão de obra também é necessária para a expansão.",
  str_homestory_820201001_19_dialog_content = "Não acho que o projeto se justifique se você aparecer de vez em quando.",
  str_homestory_820201001_20_dialog_content = "É trivial para mim.",
  str_homestory_820201001_21_dialog_content = "Mas podemos esquecer se você não quiser.",
  str_homestory_820201001_22_dialog_content = "Espera aí, acho que estou sentindo cheiro de alguma coisa... <sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "O que é? Um odor estranho?",
  str_homestory_820201001_24_dialog_content = "Eu não sinto cheiro de nada.",
  str_homestory_820201001_25_dialog_content = "É exatamente isso que está faltando.",
  str_homestory_820201001_26_dialog_content = "Você deve adicionar alguns aromas agradáveis para deixar o cheiro do ar mais limpo e organizado.",
  str_homestory_820201001_27_dialog_content = "Não me interesso muito por cheiros...",
  str_homestory_820201001_28_dialog_content = "Se o visitante não sente um ar de elegância ao chegar aqui...",
  str_homestory_820201001_29_dialog_content = "Isso é uma grave quebra de etiqueta!",
  str_homestory_820201001_30_dialog_content = "Nesse caso, vou colocar alguém nisso.",
  str_homestory_820201001_31_dialog_content = "Espero ver uma mudança quando eu visitar novamente.",
  str_homestory_820201001_32_dialog_content = "Claro...",
  str_homestory_820301001_0_dialog_content = "Jakine?",
  str_homestory_820301001_1_dialog_content = "Entendo...",
  str_homestory_820301001_2_dialog_content = "O que está fazendo?",
  str_homestory_820301001_3_dialog_content = "O que... Há quanto tempo está aqui?",
  str_homestory_820301001_4_dialog_content = "Você viu a leitura que acabei de fazer?",
  str_homestory_820301001_5_dialog_content = "Acabei de chegar aqui e não vi nada.",
  str_homestory_820301001_6_dialog_content = "Você estava fazendo uma leitura para algo muito particular?",
  str_homestory_820301001_7_dialog_content = "Me desculpe, vou sair agora.",
  str_homestory_820301001_8_dialog_content = "É para algo muito particular, porém...",
  str_homestory_820301001_9_dialog_content = "Tem a ver com você.",
  str_homestory_820301001_10_dialog_content = "Comigo?",
  str_homestory_820301001_11_dialog_content = "Sim. Eu ouvi a conversa que você teve com Vice.",
  str_homestory_820301001_12_dialog_content = "Você está tendo problemas financeiros ultimamente?",
  str_homestory_820301001_13_dialog_content = "Bem, é um pouco apertado.",
  str_homestory_820301001_14_dialog_content = "Eu estava preocupado, então fiz uma leitura para você.",
  str_homestory_820301001_15_dialog_content = "Se você não quer saber, vou manter o resultado em segredo.",
  str_homestory_820301001_16_dialog_content = "Eu não me importo. Então, qual é o resultado?",
  str_homestory_820301001_17_dialog_content = "Bem, sobre suas finanças no futuro...",
  str_homestory_820301001_18_dialog_content = "Espere, ainda não estou mentalmente pronto para uma má participação...",
  str_homestory_820301001_19_dialog_content = "Diz que você será super rico! Viva uma vida feliz e livre de estresse todos os dias! <sprite=emo_yaosu size=60 />",
  str_homestory_820301001_20_dialog_content = "Realmente? Vai ser realmente incrível?",
  str_homestory_820301001_21_dialog_content = "Você acredita nisso?",
  str_homestory_820301001_22_dialog_content = "Huh? Então você estava mentindo para mim?",
  str_homestory_820301001_23_dialog_content = "Apenas me responda, você acredita nisso?",
  str_homestory_820301001_24_option_content = "Eu faço",
  str_homestory_820301001_25_dialog_content = "Pode apostar! Essa é a melhor atitude a se ter!",
  str_homestory_820301001_26_option_content = "Eu não",
  str_homestory_820301001_27_dialog_content = "Por que não? Você está me deixando com raiva agora!",
  str_homestory_820301001_28_dialog_content = "O poder de acreditar é crítico!",
  str_homestory_820301001_29_dialog_content = "Quando você acredita em algo, é nessa direção que tudo se move.",
  str_homestory_820301001_30_dialog_content = "Mas o que isso tem a ver com adivinhação?",
  str_homestory_820301001_31_dialog_content = "Porque o objetivo da leitura é...",
  str_homestory_820301001_32_dialog_content = "Para aproveitar o presente!",
  str_homestory_820301001_33_dialog_content = "Hmm, parece que adivinhar é realmente uma conversa fiada...",
  str_homestory_820301001_34_dialog_content = "Isso porque a vida é uma longa estrada, afinal.",
  str_homestory_820301001_35_dialog_content = "E nesta estrada, há muitas bifurcações.",
  str_homestory_820301001_36_dialog_content = "O que significa que sua decisão afetará o caminho que você seguirá no futuro.",
  str_homestory_820301001_37_dialog_content = "Mas independentemente disso, eu vi um futuro brilhante para você <sprite=emo_taiyang size=60 />.",
  str_homestory_820301001_38_dialog_content = "Entendido.",
  str_homestory_820301001_39_dialog_content = "O futuro está cheio de variáveis, mas tudo depende do aqui e agora.",
  str_homestory_820301001_40_dialog_content = "Uau, muito bem colocado... Devo anotar no meu diário.",
  str_homestory_820301001_41_dialog_content = "Haha, de qualquer forma, essa conversa me fez sentir muito melhor.",
  str_homestory_809801001_0_dialog_content = "Cuscuta?",
  str_homestory_809801001_1_dialog_content = "O que está olhando, Cuscuta?",
  str_homestory_809801001_2_dialog_content = "flores <sprite=emo_huaduo size=60 />.",
  str_homestory_809801001_3_dialog_content = "Algumas das flores do mato dão as boas-vindas ao sol e outras se recusam a ser olhadas.",
  str_homestory_809801001_4_dialog_content = "Eu conheço um do último tipo chamado Black Tail. Você ouviu falar?",
  str_homestory_809801001_5_option_content = "Sim.",
  str_homestory_809801001_6_dialog_content = "Mas o que você quer dizer com \"recusou-se a ser olhado\"?",
  str_homestory_809801001_7_option_content = "Não.",
  str_homestory_809801001_8_dialog_content = "Que tipo de flor é?",
  str_homestory_809801001_9_dialog_content = "A Cauda Negra é muito rara.",
  str_homestory_809801001_10_dialog_content = "Suas pétalas são frágeis, de tons profundos e absorvem a luz do sol com facilidade<sprite=emo_taiyang size=60 />.",
  str_homestory_809801001_11_dialog_content = "Então, para evitar queimaduras, costuma se esconder embaixo das folhas.",
  str_homestory_809801001_12_dialog_content = "Por isso, recusou-se a ser olhado.",
  str_homestory_809801001_13_dialog_content = "Eu vejo o que você quer dizer...",
  str_homestory_809801001_14_dialog_content = "Você gosta muito de Black Tails, não é, Cuscuta?",
  str_homestory_809801001_15_dialog_content = "Como determino se faço ou não?",
  str_homestory_809801001_16_dialog_content = "Bem, tendo uma visão única sobre ele e entendendo como ele cresce...",
  str_homestory_809801001_17_dialog_content = "Eu acho que é apenas alguém interessado nisso como você descobriria, certo?",
  str_homestory_809801001_18_dialog_content = "Você acha...?",
  str_homestory_809801001_19_dialog_content = "Na verdade, Black Tails normalmente crescem em cadáveres.",
  str_homestory_809801001_20_dialog_content = "Corpos mortos?!",
  str_homestory_809801001_21_dialog_content = "Sim. Eu acredito...",
  str_homestory_809801001_22_dialog_content = "Bem aqui, em breve, você verá Black Tails.",
  str_homestory_809801001_23_dialog_content = "V-Você quer dizer... tem um cadáver... enterrado aqui embaixo?!",
  str_homestory_809801001_24_dialog_content = "Não se preocupe, eu já verifiquei.",
  str_homestory_809801001_25_dialog_content = "Estou me referindo a este meu corpo prestes a murchar.",
  str_homestory_809801001_26_dialog_content = "Oh, vou dormir em breve, o que significa que Black Tails aparecerá.",
  str_homestory_809801001_27_dialog_content = "N-Não, Cuscuta!",
  str_homestory_809801001_28_dialog_content = "Chubbs me disse que o solo em Cloud Gardens tem minerais especiais.",
  str_homestory_809801001_29_dialog_content = "S-Então não é incomum que Black Tails cresça.",
  str_homestory_809801001_30_dialog_content = "Talvez até flores coloridas sejam possíveis!",
  str_homestory_809801001_31_dialog_content = "Colorida...",
  str_homestory_809801001_32_dialog_content = "Isso é verdade? <sprite=emo_yundao size=60 />",
  str_homestory_809801001_33_dialog_content = "Sim. Então, que tal plantarmos flores coloridas juntos?",
  str_homestory_809801001_34_dialog_content = "Plantar junto... Isso é... trabalho?",
  str_homestory_809801001_35_dialog_content = "Bem, não exatamente...",
  str_homestory_809801001_36_dialog_content = "Você também gosta de flores, PlayerName?",
  str_homestory_809801001_37_dialog_content = "Pode-se dizer que sim.",
  str_homestory_809801001_38_dialog_content = "Sempre senti que não havia cor suficiente em Cloud Gardens.",
  str_homestory_809801001_39_dialog_content = "Você acabou de me lembrar que poderíamos plantar mais flores para adicionar cores!",
  str_homestory_809801001_40_dialog_content = "Então você está dizendo que adicionar cores deixará as pessoas mais felizes?",
  str_homestory_809801001_41_dialog_content = "Claro! Por que não procuramos flores coloridas?",
  str_homestory_809801001_42_dialog_content = "Claro, podemos fazer isso.",
  str_homestory_809801001_43_dialog_content = "Mas o colorido que você mencionou inclui o dourado?",
  str_homestory_809801001_44_dialog_content = "Está vendo aquela coisa brilhando em ouro no lago? Isso é uma flor?",
  str_homestory_820101001_0_dialog_content = "O que você está começando?",
  str_homestory_820101001_1_dialog_content = "Se...",
  str_homestory_820101001_2_dialog_content = "Eu te atrapalhei, Mia?",
  str_homestory_820101001_3_dialog_content = "N-Não. Estou apenas refletindo sobre algumas questões difíceis.",
  str_homestory_820101001_4_dialog_content = "Alguma coisa que eu possa te ajudar?",
  str_homestory_820101001_5_dialog_content = "Sim. Posso te fazer uma pergunta?",
  str_homestory_820101001_6_dialog_content = "Claro.",
  str_homestory_820101001_7_dialog_content = "Se você pudesse se lembrar de um dia para sempre, qual dia você escolheria?",
  str_homestory_820101001_8_dialog_content = "Para sempre, hein... Eu realmente não consigo pensar em um.",
  str_homestory_820101001_9_dialog_content = "Então é isso que está te incomodando.",
  str_homestory_820101001_10_dialog_content = "É porque eu vi a pergunta, então...",
  str_homestory_820101001_11_dialog_content = "Ok, deixe-me pensar.",
  str_homestory_820101001_12_option_content = "O Colosso reiniciando...",
  str_homestory_820101001_13_dialog_content = "Eu escolheria lembrar o dia em que o Colossus foi reiniciado com sucesso.",
  str_homestory_820101001_14_dialog_content = "Essa foi a primeira vez que vi a aparência do Astra.",
  str_homestory_820101001_15_dialog_content = "Talvez você possa até chamá-lo de começo da minha vida.",
  str_homestory_820101001_16_option_content = "A ascensão do Obelisco do Retorno...",
  str_homestory_820101001_17_dialog_content = "Eu escolheria lembrar o dia em que o Obelisco do Retorno surgiu...",
  str_homestory_820101001_18_dialog_content = "Meus poderes mentais foram aumentados para onde eu senti que podia ver todos os cantos do Astra.",
  str_homestory_820101001_19_dialog_content = "Essa sensação foi incrível.",
  str_homestory_820101001_20_dialog_content = "Isso soa como um dia incrível.",
  str_homestory_820101001_21_dialog_content = "Você pensou nisso rápido o suficiente, PlayerName",
  str_homestory_820101001_22_dialog_content = "Na verdade, antes da reinicialização do Colossus, todo dia era uma repetição do dia anterior a mim.",
  str_homestory_820101001_23_dialog_content = "Minha vida só se tornou animada até eu conhecer todo mundo.",
  str_homestory_820101001_24_dialog_content = "Portanto, agora aprecio isso para ter certeza de que tenho uma memória clara de seus rostos.",
  str_homestory_820101001_25_dialog_content = "E vou me esforçar para lembrar de tudo e preservá-lo para sempre.",
  str_homestory_820101001_26_dialog_content = "Ah... <sprite=emo_sikao size=60 />",
  str_homestory_820101001_27_dialog_content = "Que tal compartilhar seus pensamentos, Mia?",
  str_homestory_820101001_28_dialog_content = "Meus pensamentos...",
  str_homestory_820101001_29_dialog_content = "Desde que eu esqueci algumas memórias importantes até recentemente...",
  str_homestory_820101001_30_dialog_content = "Preocupo-me muito em perdê-los novamente, por isso quero retê-los todos...",
  str_homestory_820101001_31_dialog_content = "Mas é difícil escolher entre guardar as lembranças da minha mãe, irmã...",
  str_homestory_820101001_32_dialog_content = "Mia...",
  str_homestory_820101001_33_dialog_content = "Desculpe por trazer você para baixo comigo...",
  str_homestory_820101001_34_dialog_content = "Não, eu deveria estar me desculpando. Eu não deveria ter dito tudo isso.",
  str_homestory_820101001_35_dialog_content = "Tá tudo bem, PlayerName.",
  str_homestory_820101001_36_dialog_content = "Na verdade, estou aliviado com o que você disse.",
  str_homestory_820101001_37_dialog_content = "Sério?",
  str_homestory_820101001_38_dialog_content = "Sim, ao invés de se preocupar em esquecer o passado, é mais importante valorizar o presente <sprite=emo_yaosu size=60 />.",
  str_homestory_820401001_0_dialog_content = "Senhora Joshua?",
  str_homestory_820401001_1_dialog_content = "O que está fazendo?",
  str_homestory_820401001_2_dialog_content = "Olhar, PlayerName.",
  str_homestory_820401001_3_dialog_content = "Esta planta em vaso está crescendo muito bem!",
  str_homestory_820401001_4_dialog_content = "Estou tentando descobrir qual é a variedade.",
  str_homestory_820401001_5_dialog_content = "Eu vejo. Você já identificou?",
  str_homestory_820401001_6_dialog_content = "Infelizmente ainda não consegui...",
  str_homestory_820401001_7_dialog_content = "Você sabe que planta é essa?",
  str_homestory_820401001_8_option_content = "Aceno com a cabeça",
  str_homestory_820401001_9_dialog_content = "Comprei em Umbraton não faz muito tempo.",
  str_homestory_820401001_10_dialog_content = "Eu escolhi aleatoriamente o que estava disponível.",
  str_homestory_820401001_11_dialog_content = "Eu acredito que o vendedor chamou de ... planta de mansão?",
  str_homestory_820401001_12_dialog_content = "Sim, esse é o nome.",
  str_homestory_820401001_13_dialog_content = "O nome é bastante simples, mas você o manteve em ótima forma!",
  str_homestory_820401001_14_dialog_content = "Bem, o vendedor disse que poderia crescer muito exuberante se cuidada.",
  str_homestory_820401001_15_option_content = "Agite a cabeça",
  str_homestory_820401001_16_dialog_content = "Bem, eu também não tenho certeza.",
  str_homestory_820401001_17_dialog_content = "Só me lembro que o vendedor disse que é perene.",
  str_homestory_820401001_18_dialog_content = "Você pode criá-lo dentro de casa também.",
  str_homestory_820401001_19_dialog_content = "Parece ser uma variedade fácil de cuidar.",
  str_homestory_820401001_20_dialog_content = "Você tem muitas plantas verdes aqui, PlayerName.",
  str_homestory_820401001_21_dialog_content = "Já pensou em ter flores na mistura<sprite=emo_huaduo size=60 />?",
  str_homestory_820401001_22_dialog_content = "Assim o ambiente não ficará monótono.",
  str_homestory_820401001_23_dialog_content = "Ei, que ótima sugestão!",
  str_homestory_820401001_24_dialog_content = "Mas não sou muito boa com flores...",
  str_homestory_820401001_25_dialog_content = "É mais fácil para mim ficar apenas com plantas verdes.",
  str_homestory_820401001_26_dialog_content = "Eu plantaria flores diferentes no jardim quando estivesse em Lumopolis.",
  str_homestory_820401001_27_dialog_content = "Regar e podar nas horas vagas...",
  str_homestory_820401001_28_dialog_content = "Isso me faz sentir muito sereno por dentro.",
  str_homestory_820401001_29_dialog_content = "Eu não sabia que você gostava disso!",
  str_homestory_820401001_30_dialog_content = "Então, você vai me ensinar a cultivar flores, senhora Joshua?",
  str_homestory_820401001_31_dialog_content = "Claro que não!",
  str_homestory_820401001_32_dialog_content = "Cultivar flores não é difícil, mas exige paciência.",
  str_homestory_820401001_33_dialog_content = "As flores são muito delicadas em seu estágio inicial de crescimento.",
  str_homestory_820401001_34_dialog_content = "Você pode usar o vaso desta planta exatamente para isso.",
  str_homestory_820401001_35_dialog_content = "Depois de plantar as sementes, certifique-se de regar regularmente<sprite=emo_hanshui size=60 /> e espere que eles cresçam.",
  str_homestory_820401001_36_dialog_content = "Mas lembre-se de não regar demais.",
  str_homestory_820401001_37_dialog_content = "Ok, entendi. E então?",
  str_homestory_820401001_38_dialog_content = "Depois que as sementes brotarem, cuide delas por um mês.",
  str_homestory_820401001_39_dialog_content = "Nutra as mudas com mais nutrientes nesse ínterim!",
  str_homestory_820401001_40_dialog_content = "Quando vir mudas, transplante-as para um espaço maior.",
  str_homestory_820401001_41_dialog_content = "Então eu preciso movê-los, eu vejo...",
  str_homestory_820401001_42_dialog_content = "Sim. Quando você passa de uma criança a um jovem corajoso, PlayerName...",
  str_homestory_820401001_43_dialog_content = "Você também não se aventurou e ampliou seus horizontes em outro lugar?",
  str_homestory_820401001_44_dialog_content = "Isso faz parte do ciclo de crescimento.",
  str_homestory_820401001_45_dialog_content = "B-Bem, foi exatamente isso que aconteceu...",
  str_homestory_820401001_46_dialog_content = "Mas você está realmente me fazendo corar.",
  str_homestory_820401001_47_dialog_content = "Você é um garoto legal, PlayerName.",
  str_homestory_820501001_0_dialog_content = "Senhorita Branca?",
  str_homestory_820501001_1_dialog_content = "Eu vi que você estava com os olhos fechados. Você estava dormindo<sprite=emo_kun size=60 />?",
  str_homestory_820501001_2_dialog_content = "Não, eu estava meditando.",
  str_homestory_820501001_3_dialog_content = "Meditando?",
  str_homestory_820501001_4_dialog_content = "Sim. Você sabe o que é meditação?",
  str_homestory_820501001_5_option_content = "Um pouco",
  str_homestory_820501001_6_dialog_content = "Ouvi dizer que a meditação pode acalmar sua mente e curar traumas.",
  str_homestory_820501001_7_dialog_content = "Isso é correto, ele pode realmente fazer isso.",
  str_homestory_820501001_8_option_content = "Não",
  str_homestory_820501001_9_dialog_content = "A meditação é uma prática mental que pode acalmar sua mente e curar traumas.",
  str_homestory_820501001_10_dialog_content = "Você está tendo algum tipo de problema? Sentindo-se inquieto?",
  str_homestory_820501001_11_dialog_content = "Além de meditar sozinho, você também pode conversar com um amigo, como eu.",
  str_homestory_820501001_12_dialog_content = "Achei que você parecia bastante solitário.",
  str_homestory_820501001_13_dialog_content = "Eu aprecio o pensamento.",
  str_homestory_820501001_14_dialog_content = "Gosto da sua companhia, é claro, mas não posso lhe dizer o motivo da minha meditação.",
  str_homestory_820501001_15_dialog_content = "Em vez disso, não adiantaria nada se eu lhe dissesse, de qualquer maneira.",
  str_homestory_820501001_16_dialog_content = "É algo sério? Posso tentar ajudar...",
  str_homestory_820501001_17_dialog_content = "Heheh, ter um amigo como você pode ser de grande ajuda.",
  str_homestory_820501001_18_dialog_content = "Já que meu humor melhora sempre que te vejo.",
  str_homestory_820501001_19_dialog_content = "A meditação também é um segredo para parecer jovem.",
  str_homestory_820501001_20_dialog_content = "Parece jovem?",
  str_homestory_820501001_21_dialog_content = "Sim. Eu estava pensando em retardar o envelhecimento e manter minha aparência física.",
  str_homestory_820501001_22_dialog_content = "Você poderia fazer isso apenas meditando?",
  str_homestory_820501001_23_dialog_content = "Não subestime o poder dos pensamentos.",
  str_homestory_820501001_24_dialog_content = "Então, gostaria de experimentar?",
  str_homestory_820501001_25_dialog_content = "Isso pode me tornar um lutador forte e poderoso?",
  str_homestory_820501001_26_dialog_content = "É isso que você quer?",
  str_homestory_820501001_27_dialog_content = "Sim, então posso proteger melhor as pessoas e coisas que quero proteger.",
  str_homestory_820501001_28_dialog_content = "Eu aprovo muito esse pensamento, já que também tenho lutado para proteger.",
  str_homestory_820501001_29_dialog_content = "Mas permita-me lembrá-lo de que a proteção assume muitas formas.",
  str_homestory_820501001_30_dialog_content = "Tome-me, por exemplo. Mesmo como guia, estou defendendo Lumopolis de diferentes maneiras.",
  str_homestory_820501001_31_dialog_content = "Por que o lembrete? É porque não consigo manifestar o que desejo por meio da meditação?",
  str_homestory_820501001_32_dialog_content = "Realmente não sei se a meditação vai melhorar e aumentar a massa muscular.",
  str_homestory_820501001_33_dialog_content = "Você ainda pode tentar, no entanto.",
  str_homestory_820501001_34_dialog_content = "Bem, eu também acho que não...",
  str_homestory_807501001_0_dialog_content = "Odi?",
  str_homestory_807501001_1_dialog_content = "Não acredito que tem algo tão legal aqui!",
  str_homestory_807501001_2_dialog_content = "Onde está minha chave? Vou começar a desmontar as coisas!",
  str_homestory_807501001_3_dialog_content = "Espere, o que você está desmontando agora?",
  str_homestory_807501001_4_dialog_content = "A luz da rua. Por que?",
  str_homestory_807501001_5_option_content = "Você não pode fazer isso.",
  str_homestory_807501001_6_option_content = "A luz da rua está quebrada?",
  str_homestory_807501001_7_dialog_content = "Não, eu só quero desmontá-lo.",
  str_homestory_807501001_8_dialog_content = "Não posso fazer isso, então.<sprite=emo_shengqi size=60 />",
  str_homestory_807501001_9_dialog_content = "Por que você! Por que não posso? É apenas uma velha luz de rua!",
  str_homestory_807501001_10_dialog_content = "Não está quebrado, então por que você iria removê-lo?",
  str_homestory_807501001_11_dialog_content = "Para estudá-lo, é claro.",
  str_homestory_807501001_12_dialog_content = "Veja, esta luz é completamente diferente do resto.",
  str_homestory_807501001_13_dialog_content = "Uh, eu não vejo muita diferença em tudo.",
  str_homestory_807501001_14_dialog_content = "Posso dizer que tem engrenagens internas intrincadas e fiação externa.",
  str_homestory_807501001_15_dialog_content = "Eu não acho que é assim que as luzes da rua em Lumopolis funcionam...",
  str_homestory_807501001_16_dialog_content = "Eu te disse, você não entenderia.",
  str_homestory_807501001_17_dialog_content = "Não, você não me disse isso.",
  str_homestory_807501001_18_dialog_content = "Vejo que você ficou melhor em atrevimento.",
  str_homestory_807501001_19_dialog_content = "Ok, você decidiu manter essa luz, certo?",
  str_homestory_807501001_20_dialog_content = "Bem, então vamos a isso.",
  str_homestory_807501001_21_dialog_content = "E vamos ver se consigo fazer você funcionar mal!",
  str_homestory_807501001_22_dialog_content = "Não sou uma máquina, não posso funcionar mal!",
  str_homestory_807501001_23_dialog_content = "Seu cabo é a única coisa que vai funcionar mal.",
  str_homestory_807501001_24_dialog_content = "Você está me ameaçando?",
  str_homestory_807501001_25_dialog_content = "Só estou relatando os fatos...",
  str_homestory_807501001_26_dialog_content = "Não olhe para nós, técnicos. Você pode ser um celestita, mas eu ainda...",
  str_homestory_807501001_27_dialog_content = "???",
  str_homestory_807501001_28_dialog_content = "Ops, não sei com o que te ameaçar.<sprite=emo_sikao size=60 />",
  str_homestory_807501001_29_dialog_content = "Hahaha...",
  str_homestory_807501001_30_dialog_content = "Ei, ria de mim de novo e eu vou pedir reforços!",
  str_homestory_807501001_31_dialog_content = "Hahahahaha!",
  str_homestory_807501001_32_dialog_content = "Pare de rir, ou eu vou pegar Sinsa para vir!",
  str_homestory_807501001_33_dialog_content = "Tem certeza que Sinsa vai ficar do seu lado?",
  str_homestory_807501001_34_dialog_content = "Uh... Bem, não realmente...",
  str_homestory_807501001_35_dialog_content = "Então, você só quer estudar essa luz?",
  str_homestory_807501001_36_dialog_content = "Sim. Parece interessante o suficiente para quebrar e ver.",
  str_homestory_807501001_37_dialog_content = "Mas está funcionando muito bem agora, então o interior também deve estar bem.",
  str_homestory_807501001_38_dialog_content = "Por que você não espera até que não funcione? Então eu vou pedir-lhe para repará-lo.",
  str_homestory_807501001_39_dialog_content = "Isso não é uma má ideia. Consertar coisas é o que eu faço!",
  str_homestory_807501001_40_dialog_content = "Tudo bem, não vou desmontá-lo agora.",
  str_homestory_807501001_41_dialog_content = "Permita-me agradecer em nome da luz.",
  str_homestory_807501001_42_dialog_content = "Falando nisso, acabei de pegar um brilho na água. Pode ser algum tipo de coisa mecânica!",
  str_homestory_807501001_43_dialog_content = "Eu deveria retirá-lo e desmontá-lo!",
  str_homestory_807501001_44_dialog_content = "Uh, talvez eu devesse salvar o que quer que esteja na água...",
  str_homestory_820601001_0_dialog_content = "O que ela está fazendo?",
  str_homestory_820601001_1_dialog_content = "O que você tá olhando?<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "A vista daqui de cima é surpreendente!",
  str_homestory_820601001_3_dialog_content = "Você está procurando há um tempo. Tem certeza de que é apenas a vista?",
  str_homestory_820601001_4_dialog_content = "Não se preocupe com isso. Você tem interesse em trabalhar comigo?",
  str_homestory_820601001_5_dialog_content = "Sua aguçada percepção de Caelestite certamente me ajudará em futuras competições de negócios!",
  str_homestory_820601001_6_dialog_content = "Ajudar você? Competição?",
  str_homestory_820601001_7_dialog_content = "Dizem que \"Negócios são guerra\" e um talento como você é exatamente o que eu preciso!",
  str_homestory_820601001_8_dialog_content = "Estou oferecendo bônus de projeto e opções de ações. Então, você está dentro?",
  str_homestory_820601001_9_dialog_content = "Isso depende dos projetos e de quanto estoque—",
  str_homestory_820601001_10_dialog_content = "Espere, eu ainda não disse sim!",
  str_homestory_820601001_11_dialog_content = "Qual é a competição de negócios? E o que isso tem a ver com a vista daqui de cima?",
  str_homestory_820601001_12_dialog_content = "Na verdade, acabei de pensar em uma ideia de negócio maravilhosa... Não conte a ninguém.",
  str_homestory_820601001_13_dialog_content = "E-eu não vou.",
  str_homestory_820601001_14_dialog_content = "É uma incursão no mar azul!",
  str_homestory_820601001_15_option_content = "Mar azul?",
  str_homestory_820601001_16_dialog_content = "Oceano, como diz!",
  str_homestory_820601001_17_dialog_content = "Então, você quer entrar no ramo de transporte?",
  str_homestory_820601001_18_option_content = "Indústria de transporte marítimo?",
  str_homestory_820601001_19_dialog_content = "Não!",
  str_homestory_820601001_20_dialog_content = "Mar azul é uma metáfora, uma comparação!",
  str_homestory_820601001_21_dialog_content = "O que isso representa como metáfora?",
  str_homestory_820601001_22_dialog_content = "No mundo dos negócios, isso significa um território inexplorado, repleto de oportunidades!",
  str_homestory_820601001_23_dialog_content = "Mas o que isso tem a ver com você observando da torre de vigia?",
  str_homestory_820601001_24_dialog_content = "Percebi que as ilhas no mar ainda não foram realmente desenvolvidas!",
  str_homestory_820601001_25_dialog_content = "Seja literalmente ou figurativamente, é ambos mar azul!",
  str_homestory_820601001_26_dialog_content = "Se eu posso descobrir ilhas no oceano e transformá-las em resorts...",
  str_homestory_820601001_27_dialog_content = "Férias de verão, aventura, caça ao tesouro, esportes, natação, parque infantil...",
  str_homestory_820601001_28_dialog_content = "Eu poderia falar sem parar apenas sobre temas!",
  str_homestory_820601001_29_dialog_content = "Então você quer desenvolver ilhas? Alguma coisa específica agora mesmo?",
  str_homestory_820601001_30_dialog_content = "Nenhum candidato adequado ainda. É por isso que quero pegar um navio e procurar um.",
  str_homestory_820601001_31_dialog_content = "Por maior que seja o oceano, com certeza deve haver uma ilha desabitada em algum lugar!",
  str_homestory_820601001_32_dialog_content = "Só temos que vencer todos e obter a ilha, então podemos construí-la como quisermos!",
  str_homestory_820601001_33_dialog_content = "Nós? Eu também vou?",
  str_homestory_820601001_34_dialog_content = "Claro! Essa visão e audição incríveis que você tem serão muito úteis.",
  str_homestory_820601001_35_dialog_content = "Eu pareço incrível nessa descrição.",
  str_homestory_820601001_36_dialog_content = "Então, o primeiro passo é encontrar uma ilha adequada?",
  str_homestory_820601001_37_dialog_content = "Isso mesmo. Eu estava pensando se poderíamos ver mais longe se colocássemos a torre de vigia em um navio.",
  str_homestory_820601001_38_dialog_content = "E já que você está aqui, vamos negociar o preço.",
  str_homestory_820601001_39_dialog_content = "Não tenho intenção de vender isso...<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "Chamaremos isso de sua parte do dinheiro inicial, certo? Vejo que você está bastante interessado nesse empreendimento.",
  str_homestory_820601001_41_dialog_content = "Isso não foi o que eu quis dizer.",
  str_homestory_820601001_42_dialog_content = "Precisa de mais tempo para pensar? Sem problemas. Nenhum contrato foi elaborado ainda, então tudo é negociável antes de assinar na linha pontilhada.",
  str_homestory_820601001_43_dialog_content = "Vou montar os planos o mais rápido possível. Você só precisa se decidir rápido!",
  str_homestory_820601001_44_dialog_content = "...T-Tudo bem. Vejo você então.",
  str_homestory_820701001_0_dialog_content = "Ele está andando nele?",
  str_homestory_820701001_1_dialog_content = "Parece que você está se divertindo muito.",
  str_homestory_820701001_2_dialog_content = "Isso é muito moderno da sua parte pegar o novo transporte para os Jardins das Nuvens! Muito legal!",
  str_homestory_820701001_3_dialog_content = "Mas ouvi dizer que é melhor com duas pessoas.",
  str_homestory_820701001_4_dialog_content = "Ouvi dizer que jogar em dupla pode servir como uma espécie de teste, principalmente para casais...<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "Um teste?",
  str_homestory_820701001_6_dialog_content = "Duas pessoas que estão juntas entram e dão algumas voltas...",
  str_homestory_820701001_7_dialog_content = "E se eles ainda conseguirem perguntar como o outro está logo após descerem...",
  str_homestory_820701001_8_dialog_content = "Isso significa que o relacionamento é sólido. Caso contrário, tsc...",
  str_homestory_820701001_9_dialog_content = "Então por que você está andando nisso sozinho? Está se preparando para um teste futuro?",
  str_homestory_820701001_10_dialog_content = "Errado, amigo!",
  str_homestory_820701001_11_dialog_content = "É uma viagem tonta e nauseante, mas também muito emocionante.",
  str_homestory_820701001_12_dialog_content = "Empolgante o suficiente para me lembrar daqueles dias...",
  str_homestory_820701001_13_dialog_content = "Eu não acho que quero saber pelo que você passou, mas acho que é hora da história, mesmo assim.",
  str_homestory_820701001_14_dialog_content = "Eu costumava ser um caçador, especializado em perseguir certos bandidos.",
  str_homestory_820701001_15_dialog_content = "Você quer dizer como um xerife? Mas você não veio do Deserto Rediesel?",
  str_homestory_820701001_16_dialog_content = "Não poderia haver algo assim. Apenas gangues como Rediesel Wrench andam por aí pelo lugar.",
  str_homestory_820701001_17_dialog_content = "Eu fiz isso por conta própria, e é por isso que eu disse caçador e não xerife.",
  str_homestory_820701001_18_dialog_content = "Então, que tipo de vilões você enfrentou? Isso tem algo a ver com o seu passado?",
  str_homestory_820701001_19_dialog_content = "Ouvi dizer que uma aldeia no Vale Denuo foi saqueada há muito tempo. Será que estão relacionados?",
  str_homestory_820701001_20_dialog_content = "Por onde devo começar... Vamos começar com uma história.",
  str_homestory_820701001_21_dialog_content = "Fale.",
  str_homestory_820701001_22_dialog_content = "Era uma vez, um grande pescador com habilidades de pesca incomparáveis.",
  str_homestory_820701001_23_dialog_content = "O ponto é que, as redes que ele fez eram muito resistentes e apertadas, de modo que nenhum peixe pudesse escapar.",
  str_homestory_820701001_24_dialog_content = "Ele conseguia grandes pescarias sempre que ia ao mar, tornando-se assim rico.",
  str_homestory_820701001_25_dialog_content = "Mas então ele começou a pegar cada vez menos peixes...",
  str_homestory_820701001_26_dialog_content = "Acabou o peixe?",
  str_homestory_820701001_27_dialog_content = "Exatamente! As redes estavam tão apertadas que até os mais jovens não ficaram de fora.",
  str_homestory_820701001_28_dialog_content = "Então a população de peixes diminuiu até quase desaparecer, até que um dia...",
  str_homestory_820701001_29_dialog_content = "Eu vejo uma reviravolta na trama chegando.<sprite=emo_yaosu tamanho=60 />",
  str_homestory_820701001_30_dialog_content = "O filho do pescador viu um peixe lindo em um recife escondido!",
  str_homestory_820701001_31_dialog_content = "Seu tamanho indicava que era jovem, mas realmente belo.",
  str_homestory_820701001_32_dialog_content = "O filho não pôde evitar contar ao seu pai, o pescador, quando chegou em casa.",
  str_homestory_820701001_33_dialog_content = "Aposto que o pescador foi atrás dele imediatamente.",
  str_homestory_820701001_34_dialog_content = "Desta vez, ele trouxe a rede mais resistente e apertada que tinha, jurando capturar o peixe.",
  str_homestory_820701001_35_dialog_content = "Pois ele sabia que era um peixe de aquário valioso que poderia render muito bom dinheiro.",
  str_homestory_820701001_36_dialog_content = "Guiado por seu filho, ele chegou ao recife isolado...",
  str_homestory_820701001_37_dialog_content = "Aposto que foi quando os problemas começaram.",
  str_homestory_820701001_38_dialog_content = "Correto! Eles viram o peixe novamente, só que ainda maior e mais bonito!",
  str_homestory_820701001_39_dialog_content = "Foi um dos pais do peixe que o filho viu?",
  str_homestory_820701001_40_dialog_content = "Provavelmente.",
  str_homestory_820701001_41_dialog_content = "Quando o grande e belo peixe viu o barco, começou a mergulhar e desviar-se no recife.",
  str_homestory_820701001_42_dialog_content = "O pescador perseguiu-o em uma perseguição quente...",
  str_homestory_820701001_43_dialog_content = "Apenas para bater o barco no recife.",
  str_homestory_820701001_44_dialog_content = "O barco afundou. Tanto o pescador quanto o filho morreram.",
  str_homestory_820701001_45_dialog_content = "Oh...",
  str_homestory_820701001_46_dialog_content = "Então, quem é o vilão que você mencionou, já que o pescador e seu filho morreram na história?",
  str_homestory_820701001_47_dialog_content = "É por isso que é apenas uma história. Não leia muito nele.",
  str_homestory_820801001_0_dialog_content = "Ela está obcecada há muito tempo...",
  str_homestory_820801001_1_dialog_content = "O que tá fazendo?",
  str_homestory_820801001_2_dialog_content = "O quê? Ah, é você! Você me notou?!<sprite=emo_wuzui tamanho=60 />",
  str_homestory_820801001_3_dialog_content = "Isso é porque você está olhando para o monumento há um bom tempo. Seus olhos não estão cansados?",
  str_homestory_820801001_4_dialog_content = "Eu realmente sinto isso agora que você mencionou...",
  str_homestory_820801001_5_dialog_content = "Espere um segundo, o ponto é que você me notou!",
  str_homestory_820801001_6_dialog_content = "Será que este é o poder do monumento, fazendo com que os outros percebam aqueles que são insignificantes?",
  str_homestory_820801001_7_dialog_content = "Não, é realmente porque você está parado aqui há muito tempo.",
  str_homestory_820801001_8_dialog_content = "Confira as imagens nele! Você consegue descobrir o que elas significam, PlayerName?",
  str_homestory_820801001_9_dialog_content = "Na verdade não... Parece ser antigo.",
  str_homestory_820801001_10_dialog_content = "É tão velho que eu não acho que alguém consiga dizer o que deveria transmitir.",
  str_homestory_820801001_11_dialog_content = "Sério? Suspirar...",
  str_homestory_820801001_12_dialog_content = "Por que essa cara triste agora? Você parece meio pra baixo...",
  str_homestory_820801001_13_dialog_content = "Isso é porque estou refletindo sobre o futuro da Chave Rediesel.",
  str_homestory_820801001_14_option_content = "O que você quer dizer com futuro?",
  str_homestory_820801001_15_dialog_content = "Ainda não me decidi, mas sei que tem que ser um objetivo de longo prazo, não as brincadeiras que fazemos agora.",
  str_homestory_820801001_16_dialog_content = "Mas esse é o estilo Rediesel! Muitas pessoas se juntaram por causa disso.",
  str_homestory_820801001_17_dialog_content = "Verdade, mas ter planos sempre é bom! Ainda não consigo pensar em nenhum, mas precisamos ter um!",
  str_homestory_820801001_18_option_content = "Você não está pensando demais nisso?",
  str_homestory_820801001_19_dialog_content = "...",
  str_homestory_820801001_20_dialog_content = "Bopper?",
  str_homestory_820801001_21_dialog_content = "Eu não sei por quê, mas sinto que alguém precisa fazer isso!",
  str_homestory_820801001_22_dialog_content = "Sair e ficar à toa todos os dias com objetivos aleatórios em mente... Isso é pura falta de disciplina.",
  str_homestory_820801001_23_dialog_content = "Parece que você tem pensado seriamente nisso...",
  str_homestory_820801001_24_dialog_content = "Eu não acho que esteja na agenda do Sinsa.",
  str_homestory_820801001_25_dialog_content = "Entendo que, como chefe, ele só precisa ser o líder legal.",
  str_homestory_820801001_26_dialog_content = "Enquanto cabe a mim elaborar planos como estrategista.",
  str_homestory_820801001_27_dialog_content = "Mas o que isso tem a ver com os monumentos?",
  str_homestory_820801001_28_dialog_content = "Jogue na conta da espontaneidade!",
  str_homestory_820801001_29_dialog_content = "Ouvi dizer que há monumentos assim em Lumópolis, Federação Illumina e até mesmo em Northland.",
  str_homestory_820801001_30_dialog_content = "Construído para homenagear pessoas famosas, méritos ou façanhas!",
  str_homestory_820801001_31_dialog_content = "Mas nós da Rediesel Wrench não temos nada parecido...",
  str_homestory_820801001_32_dialog_content = "Além disso, não temos nosso próprio território como eles...",
  str_homestory_820801001_33_dialog_content = "Então, o que vai acontecer se o futuro der errado ou todo mundo se envolver em uma grande discussão e seguir caminhos separados?",
  str_homestory_820801001_34_dialog_content = "Isso realmente parece ser uma preocupação legítima.",
  str_homestory_820801001_35_dialog_content = "Veja!",
  str_homestory_820801001_36_dialog_content = "Mas você já pensou em como o monumento deve tomar forma?",
  str_homestory_820801001_37_dialog_content = "Forma?",
  str_homestory_820801001_38_dialog_content = "Não precisa necessariamente ser um monumento, apenas algo representativo da Chave Rediesel.",
  str_homestory_820801001_39_dialog_content = "Você quer dizer como...",
  str_homestory_820801001_40_dialog_content = "Grafite nos carros?",
  str_homestory_820801001_41_dialog_content = "Se for o seu estilo, você sempre pode perceber que é uma Chave Rediesel onde quer que esteja.",
  str_homestory_820801001_42_dialog_content = "Ou, se matássemos um verme da areia, podemos desenhar um com um X sobre ele.",
  str_homestory_820801001_43_dialog_content = "Sim, essa é uma ótima ideia!",
  str_homestory_820801001_44_dialog_content = "Sem falar que a Rediesel Wrench está cheia de incríveis artistas de grafite!",
  str_homestory_820801001_45_dialog_content = "Preciso descobrir o plano para o Grande Concurso de Grafite do Carro com Chave Rediesel!<sprite=emo_yaosu tamanho=60 />",
  str_homestory_820901001_0_dialog_content = "O que ela está olhando?",
  str_homestory_820901001_1_dialog_content = "Comandante Wrath... O que você está fazendo aqui?",
  str_homestory_820901001_2_dialog_content = "Não estou fazendo nada. Só vi algo realmente interessante.",
  str_homestory_820901001_3_dialog_content = "Então é assim que a Illumina faz recrutamento hoje em dia...",
  str_homestory_820901001_4_dialog_content = "Você não é o Grande Marechal? Por que parece que você está percebendo isso só agora...?",
  str_homestory_820901001_5_dialog_content = "Porque o Grande Marechal não é responsável por supervisionar a conscrição externa...",
  str_homestory_820901001_6_dialog_content = "É o que eu estou supondo... O que você acha?",
  str_homestory_820901001_7_option_content = "De fato.",
  str_homestory_820901001_8_dialog_content = "Eu não acho que o Grande Marechal realmente tenha tempo para coisas assim.",
  str_homestory_820901001_9_option_content = "Por que você está me perguntando?!",
  str_homestory_820901001_10_dialog_content = "Você é o Grande Marechal! Ainda assim, está tentando adivinhar quais são suas responsabilidades?",
  str_homestory_820901001_11_dialog_content = "A primeira coisa que fiz após me tornar Grande Marechal foi liderar uma expedição.",
  str_homestory_820901001_12_dialog_content = "Mas agora... É hora de analisar outros assuntos.",
  str_homestory_820901001_13_dialog_content = "Por exemplo—onde vocês encontraram essa coisa?",
  str_homestory_820901001_14_dialog_content = "Foi em Umbraton... Estávamos gravando um filme na época.",
  str_homestory_820901001_15_dialog_content = "Um filme? Entendi... <sprite=emo_sikao size=60 />",
  str_homestory_820901001_16_dialog_content = "O que vem à sua mente?",
  str_homestory_820901001_17_dialog_content = "Esses anúncios de recrutamento... Como eles esperam atrair os melhores e mais corajosos da nação para se alistar no exército com esse quadro patético?",
  str_homestory_820901001_18_dialog_content = "Enquanto estou no comando, quero tornar a Illumina mais forte do que nunca.",
  str_homestory_820901001_19_dialog_content = "E então?",
  str_homestory_820901001_20_dialog_content = "Que tal fazermos um filme sobre os soldados Illumina? Uma peça de propaganda para ajudar a recrutar a próxima geração de heróis desta nação...",
  str_homestory_820901001_21_option_content = "Você está falando sério agora?",
  str_homestory_820901001_22_dialog_content = "Mesmo quando você coloca dessa forma... Filmar um filme ainda não parece algo que a Illumina faria.",
  str_homestory_820901001_23_dialog_content = "É verdade que a abordagem da Illumina para a educação se inclina mais para a tecnologia e a arte da guerra do que para as próprias artes...",
  str_homestory_820901001_24_dialog_content = "Serei o primeiro a admitir isso.",
  str_homestory_820901001_25_dialog_content = "É por isso que eu quero que você atire nessa coisa.",
  str_homestory_820901001_26_option_content = "Vamos lá!",
  str_homestory_820901001_27_dialog_content = "Por mais empolgantes e inspiradores que possam ser todos esses slogans, eles nunca poderiam se comparar a um filme.",
  str_homestory_820901001_28_dialog_content = "Se pudéssemos mostrar ao mundo a bravura de um verdadeiro herói Illumina na tela grande, enviaríamos ondas de choque por todo o continente.",
  str_homestory_820901001_29_dialog_content = "Mal posso esperar para fazer isso acontecer!",
  str_homestory_820901001_30_dialog_content = "Bem, isso resolve tudo! Agora, essa questão do filme está totalmente em suas mãos. Eu vou levantar os fundos e preparar os salários de vocês.",
  str_homestory_820901001_31_dialog_content = "Mas... eu não sei a primeira coisa sobre fazer um filme!",
  str_homestory_820901001_32_dialog_content = "Achei que você fosse do tipo criativo, não? Lembro que você até escreveu alguns poemas naquela época.",
  str_homestory_820901001_33_dialog_content = "Escrever poesia e fazer um filme são duas coisas muito diferentes! Além disso, minha poesia nem é tão boa assim...",
  str_homestory_820901001_34_dialog_content = "Pelo que entendi, as artes são todas bastante interligadas, não são?",
  str_homestory_820901001_35_dialog_content = "Esse não é o problema aqui!",
  str_homestory_820901001_36_dialog_content = "Além disso, não há sequer um único cinema em toda a Illumina!",
  str_homestory_820901001_37_dialog_content = "Bem, temos salas de exibição, mas elas só abrem nos dias de descanso.",
  str_homestory_820901001_38_dialog_content = "Então as pessoas nem terão a chance de assistir aos filmes...",
  str_homestory_820901001_39_dialog_content = "A Illumina alista todos os seus próprios cidadãos de qualquer maneira. Uma campanha de recrutamento como essa é obviamente para possíveis recrutas fora da federação.",
  str_homestory_820901001_40_dialog_content = "Mas agora que você mencionou, deixar os Illuminans verem a federação através da lente do diretor pode aumentar o moral deles, talvez.",
  str_homestory_820901001_41_dialog_content = "E se for esse o caso... será realmente uma oportunidade rara. Então — vou ter que estrelar nessa coisa.",
  str_homestory_820901001_42_dialog_content = "Que tal descermos aqui e ver quem tem mais presença de tela, hein?",
  str_homestory_820901001_43_dialog_content = "Ei, se colocarmos alguns comandantes na tela, isso pode até acender uma pequena competição entre as legiões.",
  str_homestory_820901001_44_dialog_content = "Você está realmente se empolgando demais aqui...",
  str_homestory_820901001_45_dialog_content = "Ah sim, e você também pode atuar e dirigir essa coisa ao mesmo tempo.",
  str_homestory_820901001_46_dialog_content = "Como o único Celestita e diretor, você certamente deve ter um papel de destaque.",
  str_homestory_820901001_47_dialog_content = "Você não está me ouvindo mesmo, né? Talvez eu devesse apenas me render... <sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "Ah, certo. Acabei de pensar em um nome perfeito para este filme.",
  str_homestory_820901001_49_dialog_content = "\"Salvando o Celestita PlayerName\"... O que você diz?",
  str_homestory_821001001_0_dialog_content = "Joselyne está rezando em frente à bandeira...",
  str_homestory_821001001_1_dialog_content = "Joselyne?",
  str_homestory_821001001_2_dialog_content = "Não precisa ficar aí esperando todo esse tempo. Você poderia ter apenas me chamado.",
  str_homestory_821001001_3_dialog_content = "Eu tinha medo de te incomodar.",
  str_homestory_821001001_4_dialog_content = "O Deus da Luz não questiona nossa fé apenas porque nossas orações são interrompidas.",
  str_homestory_821001001_5_dialog_content = "E eu nunca ficaria com raiva por um motivo tão insignificante. Você precisa da minha ajuda com algo?",
  str_homestory_821001001_6_dialog_content = "Não, eu só vi você parado na frente desta bandeira e pensei em vir até aqui.",
  str_homestory_821001001_7_dialog_content = "Você estava rezando para esta bandeira agora há pouco?",
  str_homestory_821001001_8_dialog_content = "Orar? Bem, é verdade que se alguém ora através de um meio específico, suas orações serão ouvidas mais claramente.",
  str_homestory_821001001_9_option_content = "Um tamanho médio como esta bandeira?",
  str_homestory_821001001_10_dialog_content = "Umm. Acreditar no Deus da Luz sempre fez parte da vida convencional de Lumopolis...",
  str_homestory_821001001_11_dialog_content = "Então, acho que faz sentido usar a bandeira de Lumopolis como um meio para a oração.",
  str_homestory_821001001_12_option_content = "Você quer dizer como uma relíquia sagrada?",
  str_homestory_821001001_13_dialog_content = "Pelo que entendi, as pessoas que buscam comunhão com seu deus geralmente tentam fazê-lo usando relíquias sagradas, certo?",
  str_homestory_821001001_14_dialog_content = "Dessa forma, eles provavelmente podem se comunicar com o divino cara a cara. Parece super eficaz!",
  str_homestory_821001001_15_dialog_content = "Na verdade, qualquer objeto pode ser usado como meio para alcançar o mesmo efeito.",
  str_homestory_821001001_16_dialog_content = "A graça da Luz<sprite=emo_taiyang size=60 /> se espalha por toda a terra. Tudo o que existe sob o sol está conectado à luz de Deus.",
  str_homestory_821001001_17_dialog_content = "Costumo rezar para as flores de tomate ao cuidar da horta.",
  str_homestory_821001001_18_dialog_content = "Sério?",
  str_homestory_821001001_19_dialog_content = "No entanto, é importante selecionar assuntos adequados ao realizar orações específicas.",
  str_homestory_821001001_20_dialog_content = "Então, pelo que você orou quando estava olhando para a bandeira de Lumópolis?",
  str_homestory_821001001_21_dialog_content = "...",
  str_homestory_821001001_22_dialog_content = "Desculpe, estou apenas curioso.",
  str_homestory_821001001_23_dialog_content = "Se eu falei algo fora de hora, por favor, apenas me ignore, Joselyne.",
  str_homestory_821001001_24_dialog_content = "Não, não... Afinal, é meu dever espalhar a graça do Deus da Luz para todos.",
  str_homestory_821001001_25_dialog_content = "Quando se trata de fé, compartilharei tudo o que sei.",
  str_homestory_821001001_26_dialog_content = "Mas agora mesmo, eu...",
  str_homestory_821001001_27_dialog_content = "Você o quê...?",
  str_homestory_821001001_28_dialog_content = "Eu só queria dar uma olhada mais de perto na costura da bandeira.",
  str_homestory_821001001_29_dialog_content = "Lumopolis realmente brilha no campo da criação de itens relacionados à religião.",
  str_homestory_821001001_30_dialog_content = "Especialmente bandeiras como esta. Elas são faróis que guiam todos que as contemplam. Obviamente, elas devem ser adequadamente resistentes.",
  str_homestory_821001001_31_dialog_content = "Se eu conseguir encontrar uma maneira de melhorar minhas habilidades de costura, poderei fazer mais para ajudar as pessoas necessitadas lá.",
  str_homestory_821001001_32_dialog_content = "Hah, e agora não consigo tirar da cabeça essa imagem de você erguendo heroicamente uma bandeira no ar...",
  str_homestory_821001001_33_dialog_content = "Você não vai me ver levantando bandeiras. Não é tão fácil quanto parece, sabe?",
  str_homestory_821001001_34_dialog_content = "Embora os moradores locais tenham me rotulado como uma \"Santa\", estou longe de ser a líder espiritual que eles precisam.",
  str_homestory_821001001_35_dialog_content = "Por enquanto, preciso começar costurando a bandeira dos Cavaleiros Espinho de Ferro.",
  str_homestory_821001001_36_dialog_content = "Certo. Fazer uma bandeira decente que lidere a carga da batalha é tão importante quanto agitá-la. Eu também vou ajudar, se você quiser.",
  str_homestory_821001001_37_dialog_content = "Você também sabe costurar?",
  str_homestory_821001001_38_dialog_content = "Bem, eu aprendi alguns truques pequenos com o Soroz quando era criança...",
  str_homestory_821001001_39_dialog_content = "Vou te ensinar tudo o que aprendi. Isso também deve reforçar e melhorar minhas habilidades.",
  str_homestory_821001001_40_dialog_content = "Primeiro de tudo—traga todas as suas roupas para mim.",
  str_homestory_821001001_41_dialog_content = "A-Todos eles?",
  str_homestory_821001001_42_dialog_content = "A única maneira de dominar os fundamentos é através de prática extensiva.",
  str_homestory_821001001_43_dialog_content = "Falar e não agir só nos levará ainda mais para a escuridão, da qual nem mesmo o Deus da Luz poderá nos libertar.",
  str_homestory_821001001_44_dialog_content = "Acredito que você não seja esse tipo de Celestita, não é?",
  str_homestory_821001001_45_dialog_content = "Claro que não estou! Vou buscar essas roupas imediatamente!",
  str_homestory_821201001_0_dialog_content = "Antony?",
  str_homestory_821201001_1_dialog_content = "Antony, você está parado no Corredor Irregular há meia hora.",
  str_homestory_821201001_2_dialog_content = "Você está interessado nesta coisa?",
  str_homestory_821201001_3_dialog_content = "Ah... Olá, PlayerName.",
  str_homestory_821201001_4_dialog_content = "Para dizer a verdade, eu realmente estou bastante interessado nisso.",
  str_homestory_821201001_5_dialog_content = "A primeira vez que coloquei os olhos nisso, tive certeza de uma coisa—",
  str_homestory_821201001_6_dialog_content = "Não há como negar o valor dessa pesquisa!",
  str_homestory_821201001_7_dialog_content = "May Eu pergunto, de que tipo de criatura são esses ossos, na verdade?",
  str_homestory_821201001_8_dialog_content = "Agora essa é uma pergunta que até mesmo me deixou perplexo...",
  str_homestory_821201001_9_dialog_content = "No momento, o júri está indeciso sobre esse ponto específico. Há todos os tipos de opiniões sobre esses ossos.",
  str_homestory_821201001_10_dialog_content = "Na sua opinião pessoal, que tipo de ossos você diria que são?",
  str_homestory_821201001_11_dialog_content = "Confio no seu julgamento.",
  str_homestory_821201001_12_dialog_content = "Deixe-me pensar<sprite=emo_sikao size=60 />... Talvez eles estejam...",
  str_homestory_821201001_13_option_content = "Os ossos de um determinado animal.",
  str_homestory_821201001_14_dialog_content = "Ossos de animais?",
  str_homestory_821201001_15_dialog_content = "Já viajei para muitos lugares e nunca vi ossos como esses.",
  str_homestory_821201001_16_dialog_content = "Nesse caso, estes poderiam ser os restos de alguma criatura extinta!",
  str_homestory_821201001_17_dialog_content = "Sério...?",
  str_homestory_821201001_18_option_content = "É a caixa torácica de um Colosso.",
  str_homestory_821201001_19_dialog_content = "O quê?!",
  str_homestory_821201001_20_dialog_content = "Sério?",
  str_homestory_821201001_21_dialog_content = "Será que esses realmente são os ossos que foram usados para fazer um Colosso?!",
  str_homestory_821201001_22_dialog_content = "É apenas um palpite, só isso.",
  str_homestory_821201001_23_dialog_content = "Não, não, você é um Celestita! Você não pode estar errado!",
  str_homestory_821201001_24_dialog_content = "De qualquer forma, preciso estudar este Corredor Irregular com cuidado!",
  str_homestory_821201001_25_dialog_content = "Posso mover uma parte dele para o meu quarto para me ajudar na minha pesquisa?!",
  str_homestory_821201001_26_dialog_content = "Ei, você não vai mover nada para o seu quarto, tá bom?!",
  str_homestory_821201001_27_dialog_content = "Afinal, isso é propriedade pública...",
  str_homestory_821201001_28_dialog_content = "Dito isso, estou um pouco curioso para saber qual é a verdade, na verdade.",
  str_homestory_821201001_29_dialog_content = "Tudo bem, você pode realizar sua pesquisa aqui e, se precisar de uma mão, tenho certeza de que encontrará alguém disposto a ajudá-lo.",
  str_homestory_821201001_30_dialog_content = "Não esquenta!",
  str_homestory_821201001_31_dialog_content = "Eu sei que vou chegar ao fundo disso!<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "Zarya, o que você está fazendo?",
  str_homestory_821101001_1_dialog_content = "Oh, PlayerName, você tem alguma ideia do que é isso?",
  str_homestory_821101001_2_dialog_content = "Está escrito \"Carro do Detetive\" nele.",
  str_homestory_821101001_3_dialog_content = "O que é um... carro?",
  str_homestory_821101001_4_dialog_content = "Bem, basicamente, é um meio de transporte conveniente.",
  str_homestory_821101001_5_dialog_content = "Isso é um meio de transporte?",
  str_homestory_821101001_6_dialog_content = "As pessoas não usam mais carruagens...?",
  str_homestory_821101001_7_dialog_content = "Ainda usam carruagens em alguns lugares, mas você verá que pessoas ricas na maioria das áreas geralmente dirigem carros.",
  str_homestory_821101001_8_dialog_content = "Ai...",
  str_homestory_821101001_9_dialog_content = "Você se interessa por carruagens, Zarya?",
  str_homestory_821101001_10_dialog_content = "Estou interessado em ver como é algo que nunca vi antes.",
  str_homestory_821101001_11_dialog_content = "Você pode me levar para ver o verdadeiro negócio mais tarde?",
  str_homestory_821101001_12_option_content = "Claro.",
  str_homestory_821101001_13_dialog_content = "Mas você tem que prometer que vai sentar no banco de trás e se comportar.",
  str_homestory_821101001_14_dialog_content = "Em hipótese alguma você tem permissão para dirigir.",
  str_homestory_821101001_15_option_content = "Acho que não.",
  str_homestory_821101001_16_dialog_content = "Hã? Por que não...?<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "Sinto que você está sempre a poucos momentos de fazer algo incrivelmente perigoso.",
  str_homestory_821101001_18_dialog_content = "Como comandar uma carruagem, por exemplo.",
  str_homestory_821101001_19_dialog_content = "Impressionante, PlayerName.",
  str_homestory_821101001_20_dialog_content = "Como você sabia que eu queria andar nele?",
  str_homestory_821101001_21_dialog_content = "Carona?",
  str_homestory_821101001_22_dialog_content = "Você não disse que era um meio de transporte... como qualquer outra carruagem?",
  str_homestory_821101001_23_dialog_content = "Então deve ser o mesmo princípio, certo?",
  str_homestory_821101001_24_dialog_content = "Tudo que você precisa fazer é dar um pequeno toque com o chicote e ele te levará para onde você quer ir.",
  str_homestory_821101001_25_dialog_content = "Ou você precisa dar um comando?",
  str_homestory_821101001_26_dialog_content = "Não sou o melhor em controlar meus Luminatics, mas sei lidar com um cavalo!",
  str_homestory_821101001_27_dialog_content = "...",
  str_homestory_821101001_28_dialog_content = "Hã? O gato comeu sua língua?",
  str_homestory_821101001_29_dialog_content = "Tenho a impressão de que você realmente precisa atualizar seu conhecimento sobre o mundo moderno...",
  str_homestory_821101001_30_dialog_content = "Hã?",
  str_homestory_821301001_0_dialog_content = "No. 33?",
  str_homestory_821301001_1_dialog_content = "Você está planejando fazer um piquenique?",
  str_homestory_821301001_2_dialog_content = "Sim, como você pode ver.",
  str_homestory_821301001_3_dialog_content = "É por essa razão que estou fazendo os preparativos necessários.",
  str_homestory_821301001_4_dialog_content = "Não me diga que você está planejando ir sozinho?",
  str_homestory_821301001_5_dialog_content = "Parece que você está me entendendo errado.",
  str_homestory_821301001_6_dialog_content = "Naturalmente, vou convidar meus outros amigos aurorianos para se juntarem a mim.",
  str_homestory_821301001_7_dialog_content = "Isso inclui você, é claro.",
  str_homestory_821301001_8_dialog_content = "Seria uma honra.",
  str_homestory_821301001_9_dialog_content = "...",
  str_homestory_821301001_10_dialog_content = "Falando nisso, por que você não convida Vice e os outros?",
  str_homestory_821301001_11_dialog_content = "Estou realizando um trabalho importante de análise.",
  str_homestory_821301001_12_dialog_content = "Ao perguntar às pessoas ao meu redor, descobri os padrões de comida nos seus piqueniques anteriores.",
  str_homestory_821301001_13_dialog_content = "Com base na comida de piquenique recebida até agora dos meus amigos aurorianos, cheguei a uma conclusão chocante:",
  str_homestory_821301001_14_dialog_content = "Um excesso de calorias pode ter um efeito catastrófico na saúde de alguém.",
  str_homestory_821301001_15_dialog_content = "Hã?",
  str_homestory_821301001_16_dialog_content = "O que você acha, PlayerName?",
  str_homestory_821301001_17_option_content = "Você tem toda a razão.",
  str_homestory_821301001_18_dialog_content = "Se você estiver analisando isso apenas do ponto de vista nutricional, com certeza, esse tipo de comida tem calorias demais.",
  str_homestory_821301001_19_dialog_content = "Não é frequente você concordar tão plenamente com meu ponto de vista.",
  str_homestory_821301001_20_dialog_content = "Mas...",
  str_homestory_821301001_21_option_content = "Isso não é verdade.",
  str_homestory_821301001_22_dialog_content = "Em relação à sua afirmação \"isso não é verdade\", qual abordagem analítica você utilizou para chegar a essa conclusão?",
  str_homestory_821301001_23_dialog_content = "Considero o julgamento que compartilhei com você totalmente sólido.",
  str_homestory_821301001_24_dialog_content = "Quando vamos fazer um piquenique, nosso objetivo é naturalmente apenas relaxar e descontrair.",
  str_homestory_821301001_25_dialog_content = "Você não alcançará esse objetivo se gastar tempo se preocupando com as pequenas coisas.",
  str_homestory_821301001_26_dialog_content = "Preocupado com coisas pequenas? Quer desabafar?",
  str_homestory_821301001_27_dialog_content = "Eu sei que suas intenções são boas, No. 33, mas às vezes você precisa se soltar.",
  str_homestory_821301001_28_dialog_content = "Você pode ser rigoroso quando for hora de ser rigoroso e tente relaxar quando for hora de relaxar. Dessa forma, as pessoas vão gostar mais de você.",
  str_homestory_821301001_29_dialog_content = "Informação recebida. Analisando informações...",
  str_homestory_821301001_30_dialog_content = "Sim, eu sei.",
  str_homestory_821301001_31_dialog_content = "Então vou reajustar minhas receitas de piquenique.",
  str_homestory_821301001_32_dialog_content = "Por favor, aguarde o meu convite.",
  str_homestory_821401001_0_dialog_content = "Rebecca?",
  str_homestory_821401001_1_dialog_content = "Navegador...",
  str_homestory_821401001_2_dialog_content = "Quer sentar na cadeira suspensa?",
  str_homestory_821401001_3_dialog_content = "Não... Eu só sinto um pouco de nostalgia...",
  str_homestory_821401001_4_dialog_content = "No passado... costumava haver uma cadeira suspensa parecida no pátio da minha casa.",
  str_homestory_821401001_5_dialog_content = "Naquela época, minha irmã mais velha, Eleanor, e eu costumávamos brincar juntas na cadeira suspensa.",
  str_homestory_821401001_6_dialog_content = "Mas apenas duas pessoas podiam brincar nele, porque a cadeira suspensa era muito pequena e tinha espaço limitado...",
  str_homestory_821401001_7_dialog_content = "O que significava que um de nós sempre ficaria de fora...",
  str_homestory_821401001_8_dialog_content = "Sério? Então, como você decidiu quem ficaria de fora?",
  str_homestory_821401001_9_dialog_content = "Jogamos pedra-papel-tesoura.",
  str_homestory_821401001_10_dialog_content = "É estranho agora que penso nisso. Eu nunca perdi naquela época. Nem mesmo uma vez.",
  str_homestory_821401001_11_dialog_content = "Talvez eles já tenham discutido isso entre eles?",
  str_homestory_821401001_12_dialog_content = "Isso é possível. Para ser sincero, o relacionamento entre minha irmã mais velha e Eleanor... nunca foi muito bom...",
  str_homestory_821401001_13_dialog_content = "Lembro-me de uma época em que saí da cadeira suspensa para balançá-la...",
  str_homestory_821401001_14_dialog_content = "No final, minha irmã mais velha e Eleanor quase tiveram uma briga na cadeira suspensa.",
  str_homestory_821401001_15_dialog_content = "Eles quase quebraram isso também naquela vez...",
  str_homestory_821401001_16_dialog_content = "Parece que você realmente sente falta daqueles tempos <sprite=emo_sikao size=60 />.",
  str_homestory_821401001_17_dialog_content = "Gostaria de sentar nele?",
  str_homestory_821401001_18_dialog_content = "Hã? Eu? Bem...",
  str_homestory_821401001_19_dialog_content = "Acho que vou passar.",
  str_homestory_821401001_20_option_content = "Por quê?",
  str_homestory_821401001_21_option_content = "Experimente.",
  str_homestory_821401001_22_dialog_content = "Na verdade... meu veneno tem estado um pouco inquieto recentemente...",
  str_homestory_821401001_23_dialog_content = "Se eu acidentalmente cochilar enquanto estou sentado nele, tenho medo que o veneno se espalhe e destrua a cadeira suspensa.",
  str_homestory_821401001_24_dialog_content = "Então vou apenas dar uma olhada.",
  str_homestory_821401001_25_dialog_content = "Se eu ficar perto e fechar os olhos, parece que tudo voltou a ser como era no passado...",
  str_homestory_821401001_26_dialog_content = "Não se preocupe com isso. Estou aqui.",
  str_homestory_821401001_27_dialog_content = "Vou te acordar imediatamente se você adormecer.",
  str_homestory_821401001_28_dialog_content = "Isso causaria muito problema para você...?",
  str_homestory_821401001_29_dialog_content = "Vai ficar tudo bem.",
  str_homestory_821401001_30_dialog_content = "Hum... Você pode esperar um pouco mais por mim?",
  str_homestory_821401001_31_dialog_content = "Há alguns recados que preciso resolver na clínica. Vou aí imediatamente depois de terminar.",
  str_homestory_821401001_32_dialog_content = "Agradeço, Navegador!",
  str_homestory_821501001_0_dialog_content = "Isa?",
  str_homestory_821501001_1_dialog_content = "Ah, é você.",
  str_homestory_821501001_2_dialog_content = "Há algo de errado com este carro? Você não para de olhar para ele.",
  str_homestory_821501001_3_dialog_content = "Aha! Boa pergunta.",
  str_homestory_821501001_4_dialog_content = "Você não acha esse carro... super legal?",
  str_homestory_821501001_5_option_content = "Não muito.",
  str_homestory_821501001_6_dialog_content = "Acho que você pode dizer que é lindo.",
  str_homestory_821501001_7_option_content = "É verdade.",
  str_homestory_821501001_8_dialog_content = "De certa forma, pode ser considerado legal.",
  str_homestory_821501001_9_dialog_content = "De qualquer forma, esse carro é exatamente o meu estilo!",
  str_homestory_821501001_10_dialog_content = "Se eu dirigir este carro para buscar Rebecca...",
  str_homestory_821501001_11_dialog_content = "Ela com certeza vai ficar muito animada!",
  str_homestory_821501001_12_dialog_content = "Você está pensando em buscar Rebecca com este carro?",
  str_homestory_821501001_13_dialog_content = "Sim, Rebecca não está bem.",
  str_homestory_821501001_14_dialog_content = "Mas ela ainda precisa caminhar para o trabalho todos os dias. Você não acha que ela está sendo muito dura consigo mesma?",
  str_homestory_821501001_15_dialog_content = "Realmente parece difícil.",
  str_homestory_821501001_16_dialog_content = "Certo? Isso é o que eu cheguei após uma consideração cuidadosa.",
  str_homestory_821501001_17_dialog_content = "Rebecca sempre diz que eu não sei o que ela quer. Hehe, com certeza ela precisa dessa ferramenta de transporte desta vez.",
  str_homestory_821501001_18_dialog_content = "Mas... esse carro é chamativo demais. Rebecca não vai gostar.",
  str_homestory_821501001_19_dialog_content = "Não se preocupe. Eu entendo ela bem. Tenho certeza de que sei o que ela gosta.",
  str_homestory_821501001_20_dialog_content = "Rebecca ama flores. Olhe as flores por todo o carro. Não há como ela odiar isso.",
  str_homestory_821501001_21_dialog_content = "... Uh, então tenta?",
  str_homestory_821501001_22_dialog_content = "Ok, vou contar ao Rebecca agora.",
  str_homestory_821501001_23_dialog_content = "Ela ficaria encantada.",
  str_homestory_821501001_24_dialog_content = "Boa sorte.",
  str_homestory_821601001_0_dialog_content = "O que há de errado com essa máquina, Xuan Ji?",
  str_homestory_821601001_1_dialog_content = "Foi usado pelos celestitas no passado. Interessado?",
  str_homestory_821601001_2_dialog_content = "É um tear mecânico, certo?",
  str_homestory_821601001_3_dialog_content = "Sim. Há registros sobre isso no Soroz.",
  str_homestory_821601001_4_dialog_content = "Eraveil já utilizou tais máquinas para produzir tecidos, alcançando um estilo de vida autossuficiente.",
  str_homestory_821601001_5_dialog_content = "Provavelmente requer manutenção regular, mas não está em uso há muito tempo...",
  str_homestory_821601001_6_dialog_content = "Você quer usá-lo, Xuan Ji?",
  str_homestory_821601001_7_dialog_content = "Não muito.",
  str_homestory_821601001_8_dialog_content = "Isso apenas me parece nostálgico.",
  str_homestory_821601001_9_dialog_content = "Nostálgico?",
  str_homestory_821601001_10_dialog_content = "Isso me lembra as máquinas para fins educacionais que eu usava quando era pequeno.",
  str_homestory_821601001_11_dialog_content = "Os mestres começavam a treinar nós, jovens alunos, em modelos protótipos.",
  str_homestory_821601001_12_dialog_content = "Tear como este é comum. Você pode até chamá-lo de meu segundo professor.",
  str_homestory_821601001_13_dialog_content = "Não admira que você ache isso interessante.",
  str_homestory_821601001_14_dialog_content = "Além disso, protótipos geralmente são muito frágeis.",
  str_homestory_821601001_15_dialog_content = "É o caso do que me foi dado, com algumas estruturas idênticas também...",
  str_homestory_821601001_16_dialog_content = "Eles também fariam isso para nos fazer apreciar o artesanato.",
  str_homestory_821601001_17_dialog_content = "Eu adoraria cuidar dele também, mas ele quebrava mais vezes do que não!",
  str_homestory_821601001_18_option_content = "Porque você tentou ajustá-lo?",
  str_homestory_821601001_19_dialog_content = "Bingo.",
  str_homestory_821601001_20_option_content = "É tão frágil",
  str_homestory_821601001_21_dialog_content = "Não, é porque eu ajustei bastante...",
  str_homestory_821601001_22_dialog_content = "Então não durou até a minha formatura.",
  str_homestory_821601001_23_dialog_content = "Quando finalmente me tornei competente o suficiente, já estava além do conserto.",
  str_homestory_821601001_24_dialog_content = "Entendi.",
  str_homestory_821601001_25_dialog_content = "Então, quer que eu conserte esse tear?",
  str_homestory_821601001_26_dialog_content = "Para esta versão atual de mim, deve ser muito fácil.",
  str_homestory_821601001_27_dialog_content = "Posso até melhorar o design para que ele funcione e se mantenha da melhor forma possível.",
  str_homestory_821601001_28_dialog_content = "Ah<sprite=emo_sikao size=60 />, isso não será necessário, no entanto.",
  str_homestory_821601001_29_dialog_content = "Mesmo que fosse consertado, seria difícil encontrar os materiais para processá-lo.",
  str_homestory_821601001_30_dialog_content = "Sem falar que agora podemos facilmente conseguir tecidos bonitos e baratos nas lojas.",
  str_homestory_821601001_31_dialog_content = "Verdade, o mesmo em Longzhou.",
  str_homestory_821601001_32_dialog_content = "Para pessoas comuns, as guildas são mais importantes do que os artesãos atualmente.",
  str_homestory_821601001_33_dialog_content = "Isso é progresso, certo?",
  str_homestory_821601001_34_dialog_content = "Hmm, não posso refutar isso. Essa máquina já cumpriu seu propósito.",
  str_homestory_821601001_35_dialog_content = "Então, é melhor deixá-lo descansar em paz.",
  str_homestory_818702001_0_dialog_content = "Tianxian? Mestre Li?",
  str_homestory_818702001_1_dialog_content = "Como você conseguiu dormir em pé?",
  str_homestory_818702001_2_dialog_content = "Acorde e volte para o seu quarto.",
  str_homestory_818702001_3_dialog_content = "Ei!",
  str_homestory_818702001_4_dialog_content = "Eu estava lá no céu conversando com os anjos há pouco.",
  str_homestory_818702001_5_dialog_content = "Quão rápido eu caí de volta à terra...",
  str_homestory_818702001_6_dialog_content = "Acho que ainda tenho um longo caminho pela frente.",
  str_homestory_818702001_7_dialog_content = "Desisto. Você não percebeu?",
  str_homestory_818702001_8_dialog_content = "A coisa ao lado da qual você adormeceu e quase se apoiou...",
  str_homestory_818702001_9_dialog_content = "É um relógio.",
  str_homestory_818702001_10_dialog_content = "Inacreditável! Como você consegue dormir tão profundamente ao lado de um relógio tão grande...",
  str_homestory_818702001_11_dialog_content = "Pelo contrário, meu irmão.",
  str_homestory_818702001_12_dialog_content = "Até onde eu sei, muitas pessoas em Astra mantinham um despertador ao lado de seus travesseiros.",
  str_homestory_818702001_13_dialog_content = "No entanto, eu preferia o céu como meu cobertor, a terra como minha cama e um relógio de sol como meu despertador.",
  str_homestory_818702001_14_dialog_content = "Então, neste caso, estou me adaptando ao que os habitantes locais fazem.",
  str_homestory_818702001_15_dialog_content = "Mas eles fizeram isso para acordar a tempo, e você estava apenas tentando tirar uma soneca<sprite=emo_kun size=60 />!",
  str_homestory_818702001_16_dialog_content = "Você não sente o tempo passar rápido de jeito nenhum?",
  str_homestory_818702001_17_dialog_content = "É porque o tempo voa e a vida é curta que se deve aproveitar as oportunidades quando elas se apresentam.",
  str_homestory_818702001_18_dialog_content = "Você deve dormir sempre que sentir sono, não esperar até bocejar.",
  str_homestory_818702001_19_dialog_content = "Por que você não se inclina e tira um cochilo? Então você vai entender.",
  str_homestory_818702001_20_option_content = "Não.",
  str_homestory_818702001_21_dialog_content = "Ainda jovem e inexperiente, pelo que vejo.",
  str_homestory_818702001_22_dialog_content = "Já vi minha parte do mundo e nunca vou desistir de qualquer chance de tirar um cochilo.",
  str_homestory_818702001_23_option_content = "Vou tentar.",
  str_homestory_818702001_24_dialog_content = "Você finalmente se iluminou!",
  str_homestory_818702001_25_dialog_content = "Mas mesmo que eu vá ficar aqui, preciso me preparar.",
  str_homestory_818702001_26_dialog_content = "Preciso levar meu saco de dormir, cobertor de piquenique e tudo mais.",
  str_homestory_818702001_27_dialog_content = "Você com certeza sabe aproveitar a vida. Eu mal tenho algo para o conforto.",
  str_homestory_818702001_28_dialog_content = "Suspiro, acho que o relógio de sol é provavelmente o mais afortunado de todos.",
  str_homestory_818702001_29_dialog_content = "Serve ao mesmo propósito, seja em Longzhou ou Astra.",
  str_homestory_818702001_30_dialog_content = "Tem folga enquanto o sol não está brilhando.",
  str_homestory_818702001_31_dialog_content = "Você já foi tão longe a ponto de invejar uma pedra?",
  str_homestory_818702001_32_dialog_content = "Não subestime as rochas. Há até heróis lendários que surgiram das pedras!",
  str_homestory_818702001_33_dialog_content = "Infelizmente, eu só conseguia me transformar em uma pedra nos meus sonhos.",
  str_homestory_818702001_34_dialog_content = "Falando nisso, sinto que outra soneca está chegando.",
  str_homestory_818702001_35_dialog_content = "Ainda sem senso de urgência, pelo visto...",
  str_homestory_818702001_36_dialog_content = "Não leve tudo tão a sério, PlayerName.",
  str_homestory_818702001_37_dialog_content = "Qual é o problema em diminuir o ritmo no trabalho e parar para apreciar as coisas boas da vida?<sprite=emo_qingsong size=60 />",
  str_homestory_818702001_38_dialog_content = "Verdade... Esse é o Li Tianxian que eu conheço.",
  str_homestory_818802001_0_dialog_content = "Dantang?",
  str_homestory_818802001_1_dialog_content = "O artesanato desta pipa é bastante único.",
  str_homestory_818802001_2_dialog_content = "O padrão angular e o esquema de cores simples...",
  str_homestory_818802001_3_dialog_content = "É muito parecido com a variedade mais comum vista em Longzhou.",
  str_homestory_818802001_4_dialog_content = "Os Celestitas também preferem uma elegância semelhante? Isso é bastante raro.",
  str_homestory_818802001_5_option_content = "As pessoas em Longzhou gostam de empinar pipas?",
  str_homestory_818802001_6_dialog_content = "Claro que sim.",
  str_homestory_818802001_7_option_content = "Você já empinou pipa antes, Dantang?",
  str_homestory_818802001_8_dialog_content = "Sim, eu amo pipas muito.",
  str_homestory_818802001_9_dialog_content = "Em Longzhou, empinar pipas é uma das atividades favoritas das crianças.",
  str_homestory_818802001_10_dialog_content = "Quando eu era jovem, era um prazer raro empinar pipas com minhas irmãs.",
  str_homestory_818802001_11_dialog_content = "Naquela época, nossas pipas ficavam emaranhadas.",
  str_homestory_818802001_12_dialog_content = "Às vezes, isso até causava brigas.",
  str_homestory_818802001_13_dialog_content = "Embora sempre nos reconciliássemos no final,",
  str_homestory_818802001_14_dialog_content = "Que tipo de pipas você empinou, Dantang?",
  str_homestory_818802001_15_dialog_content = "Minhas pipas? Ah, eu já empinei muitas pipas.",
  str_homestory_818802001_16_dialog_content = "Minhas irmãs preferiam pipas em formas de aves, mas para mim eram flores.",
  str_homestory_818802001_17_dialog_content = "Não vi nenhuma pipa assim.",
  str_homestory_818802001_18_dialog_content = "Bem, as pipas em Longzhou variavam muito em estilo.",
  str_homestory_818802001_19_dialog_content = "Pegue o Reino Ye, por exemplo. Eles gostam de anexar aparelhos às pipas.",
  str_homestory_818802001_20_dialog_content = "O que faria cada parte se mover e dançar.",
  str_homestory_818802001_21_dialog_content = "Todas as pipas que eu empinava naquela época eram feitas pelos artesãos do palácio.",
  str_homestory_818802001_22_dialog_content = "Decorado luxuosamente com elegância real.",
  str_homestory_818802001_23_dialog_content = "Sinto muita falta disso... Eu adoraria empinar pipa novamente.",
  str_homestory_818802001_24_dialog_content = "Infelizmente, esta pipa aqui não se compara ao que você tinha, eu temo.",
  str_homestory_818802001_25_dialog_content = "Tudo bem. O que estou sentindo falta são os momentos despreocupados do passado.",
  str_homestory_818802001_26_dialog_content = "Empinar pipa é realmente incidental.",
  str_homestory_818802001_27_dialog_content = "Hmm, estou sem tarefas e recados para fazer.",
  str_homestory_818802001_28_dialog_content = "Posso tirar um descanso, e seria o momento perfeito para empinar essa pipa.",
  str_homestory_818802001_29_dialog_content = "Então, você gostaria de empinar pipa comigo?",
  str_homestory_818802001_30_dialog_content = "Não é divertido voar sozinho.",
  str_homestory_818802001_31_dialog_content = "Que pena que só temos um aqui...",
  str_homestory_818802001_32_dialog_content = "Isso não é um problema. Podemos revezar, ou eu posso fazer um sozinho.",
  str_homestory_822001001_0_dialog_content = "Vergil?",
  str_homestory_822001001_1_dialog_content = "Por que você continua encarando o espantalho, Vergil?",
  str_homestory_822001001_2_dialog_content = "Este espantalho...<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "E daí? Não me diga que este espantalho é uma antiguidade!",
  str_homestory_822001001_4_dialog_content = "À primeira vista, parece ser...",
  str_homestory_822001001_5_dialog_content = "Sério? O que há de especial no espantalho?",
  str_homestory_822001001_6_dialog_content = "Os acessórios nele... Eles podem ser antiguidades.",
  str_homestory_822001001_7_dialog_content = "Antiguidades? Sério?",
  str_homestory_822001001_8_dialog_content = "Sim. Este colete deve ser um lançamento limitado de uma marca Umbraton.",
  str_homestory_822001001_9_dialog_content = "Estava na moda cinquenta anos atrás.",
  str_homestory_822001001_10_dialog_content = "O maior destaque desta oferta limitada é...",
  str_homestory_822001001_11_dialog_content = "Seu padrão branco sobre preto eram listras brancas tingidas em tecido preto.",
  str_homestory_822001001_12_dialog_content = "Em vez do convencional, com listras pretas impressas em tecido branco.",
  str_homestory_822001001_13_dialog_content = "E tem um número costurado atrás da gola com linha de ouro.",
  str_homestory_822001001_14_dialog_content = "Eu vejo isso...<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "Além disso, se você olhar de perto, os olhos do espantalho são feitos de obsidiana.",
  str_homestory_822001001_16_dialog_content = "O polimento e a cor são ambos de qualidade de pedra preciosa.",
  str_homestory_822001001_17_dialog_content = "Os nobres de Lumópolis costumavam transformar tais gemas em botões décadas atrás.",
  str_homestory_822001001_18_dialog_content = "Esses dois não estão longe disso.",
  str_homestory_822001001_19_dialog_content = "Eu nem percebi até que você mencionou.",
  str_homestory_822001001_20_dialog_content = "Por fim, o tronco que sustenta o espantalho...",
  str_homestory_822001001_21_dialog_content = "Parece ser agarwood.",
  str_homestory_822001001_22_dialog_content = "Apesar de ser mais suave, você ainda pode sentir um leve aroma quando se aproxima.",
  str_homestory_822001001_23_dialog_content = "Cajados de Agarwood valem bastante.",
  str_homestory_822001001_24_dialog_content = "Uau, isso significa que este espantalho não tem preço?",
  str_homestory_822001001_25_dialog_content = "Bem, as antiguidades são julgadas pelo seu todo.",
  str_homestory_822001001_26_dialog_content = "Um conjunto completo seria inestimável, mas muito menos quando até mesmo um componente está faltando.",
  str_homestory_822001001_27_dialog_content = "E vice-versa, assim como este espantalho, uma compilação de objetos completamente não relacionados.",
  str_homestory_822001001_28_dialog_content = "Mesmo sob a perspectiva de uma obra de arte...",
  str_homestory_822001001_29_dialog_content = "É de terceira categoria no melhor dos casos, não vale nada agora.",
  str_homestory_822001001_30_dialog_content = "Que pena...<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "A menos...",
  str_homestory_822001001_32_dialog_content = "A menos que o quê?",
  str_homestory_822001001_33_dialog_content = "A menos que você o desmonte. Você deseja fazer isso?",
  str_homestory_822001001_34_dialog_content = "Bem não.",
  str_homestory_822001001_35_dialog_content = "Prefiro como está aqui para nós aproveitarmos como está.",
  str_homestory_822001001_36_dialog_content = "Eu sabia que você diria isso, PlayerName.",
  str_homestory_821901001_0_dialog_content = "O que foi?",
  str_homestory_821901001_1_dialog_content = "A maneira como você parece... Será que...",
  str_homestory_821901001_2_dialog_content = "Você deve gostar muito deste relógio, não é?",
  str_homestory_821901001_3_dialog_content = "É um estilo que eu nunca vi antes.",
  str_homestory_821901001_4_dialog_content = "É um relógio Celestita?",
  str_homestory_821901001_5_dialog_content = "Acredito que sim.",
  str_homestory_821901001_6_dialog_content = "Tudo em Soroz é Celestita.",
  str_homestory_821901001_7_dialog_content = "Não é uma máquina, mas usa o reflexo da luz solar.",
  str_homestory_821901001_8_dialog_content = "Um conceito tão maravilhoso...",
  str_homestory_821901001_9_dialog_content = "Poderia ser chamado de Arte Sombria.",
  str_homestory_821901001_10_dialog_content = "Você realmente gosta do relógio, eu vejo.",
  str_homestory_821901001_11_dialog_content = "Estou impressionado com o tempo passageiro.",
  str_homestory_821901001_12_dialog_content = "Portanto, também adoro colecionar relógios de diferentes marcas.",
  str_homestory_821901001_13_dialog_content = "O quê? Você quer dizer que existem muitos tipos de relógios no mundo lá fora?",
  str_homestory_821901001_14_dialog_content = "Os relógios em Lumópolis são clássicos e elegantes.",
  str_homestory_821901001_15_dialog_content = "Os relógios de Northland são simples e práticos.",
  str_homestory_821901001_16_dialog_content = "Os relógios do Deserto Rediesel estão cheios de truques e gadgets.",
  str_homestory_821901001_17_dialog_content = "E os relógios Umbraton são discretos, mas lindos.",
  str_homestory_821901001_18_dialog_content = "Entendi. Você certamente é um aficionado por coleções.",
  str_homestory_821901001_19_dialog_content = "Nunca pensei que um item comum pudesse ter tanto a oferecer.",
  str_homestory_821901001_20_dialog_content = "Você abriu meus olhos.",
  str_homestory_821901001_21_dialog_content = "Os relógios que mencionei são todos produtos dos tempos modernos.",
  str_homestory_821901001_22_dialog_content = "Enquanto o relógio Celestita me fez perceber a gravidade do passado.",
  str_homestory_821901001_23_dialog_content = "Esse sentimento é especial e único.",
  str_homestory_821901001_24_dialog_content = "Se é assim que você se sente...<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "Gostaria de dar isso a você.",
  str_homestory_821901001_26_dialog_content = "Por que você faria isso?",
  str_homestory_821901001_27_option_content = "Porque somos amigos.",
  str_homestory_821901001_28_dialog_content = "Por causa da amizade, é isso?",
  str_homestory_821901001_29_dialog_content = "Essa é uma declaração de sinceridade.",
  str_homestory_821901001_30_option_content = "Parece que você gosta muito disso.",
  str_homestory_821901001_31_dialog_content = "Mesmo assim, eu não quero simplesmente pegá-lo.",
  str_homestory_821901001_32_dialog_content = "Eu aprecio muito o pensamento, no entanto.",
  str_homestory_821901001_33_dialog_content = "Mas por que não deixamos simplesmente ficar em \"casa\"?",
  str_homestory_821901001_34_dialog_content = "Eu não entendo. Você não gosta?",
  str_homestory_821901001_35_dialog_content = "Eu tenho outros relógios aqui, então...",
  str_homestory_821901001_36_dialog_content = "Estou muito feliz em saber que você compartilharia qualquer coisa com um amigo.",
  str_homestory_821901001_37_dialog_content = "No entanto, acho que é para ser em nenhum outro lugar, senão aqui.",
  str_homestory_821901001_38_dialog_content = "O passado representa memórias, e as memórias consistem em história.",
  str_homestory_821901001_39_dialog_content = "Tudo que é Celestita está aqui, PlayerName.",
  str_homestory_821901001_40_dialog_content = "Tudo isso significa algo para você.",
  str_homestory_821901001_41_dialog_content = "Eu não quero levar nada disso embora.",
  str_homestory_821901001_42_dialog_content = "Istvan...",
  str_homestory_821901001_43_dialog_content = "Adeus, que a sombra vigie você.",
  str_homestory_821801001_0_dialog_content = "Senhora Sheol?",
  str_homestory_821801001_1_dialog_content = "Que bom te encontrar aqui! É um sinal de que algo bom vai acontecer hoje.",
  str_homestory_821801001_2_dialog_content = "Você não concordaria, PlayerName?",
  str_homestory_821801001_3_dialog_content = "Não é inesperado, Senhora Sheol. Você sabe que estamos nos Jardins das Nuvens, certo...",
  str_homestory_821801001_4_dialog_content = "Claro que eu faço.",
  str_homestory_821801001_5_dialog_content = "Mas você precisa dessas coincidências ocasionais, seja nos negócios ou na vida.",
  str_homestory_821801001_6_dialog_content = "Desculpa, ainda não entendi.",
  str_homestory_821801001_7_dialog_content = "Está bem. Deixa eu explicar.",
  str_homestory_821801001_8_dialog_content = "Por exemplo, você precisava renovar o Cloud Gardens e a Guilda Cloudrover...",
  str_homestory_821801001_9_dialog_content = "Acontece que eu tinha um plano para isso.",
  str_homestory_821801001_10_dialog_content = "Não seria isso uma coincidência?",
  str_homestory_821801001_11_dialog_content = "E com isso, você está dizendo...?",
  str_homestory_821801001_12_dialog_content = "Cloud Gardens é realmente especial, mas você não acha que os dormitórios são muito monótonos?",
  str_homestory_821801001_13_option_content = "Eles são?",
  str_homestory_821801001_14_dialog_content = "Claro, por que mais eu mencionaria isso?",
  str_homestory_821801001_15_dialog_content = "Provavelmente você está acostumado, então não sente dessa maneira.",
  str_homestory_821801001_16_dialog_content = "Mas eu acho que dormitórios simples simplesmente não combinam com Cloud Gardens.",
  str_homestory_821801001_17_option_content = "Eu também sinto o mesmo",
  str_homestory_821801001_18_dialog_content = "Eu sabia!",
  str_homestory_821801001_19_dialog_content = "Nesse caso, você não acha que algo deveria ser feito a respeito?",
  str_homestory_821801001_20_dialog_content = "Como reformá-los, por exemplo?",
  str_homestory_821801001_21_dialog_content = "O que eu quero dizer é, podemos tornar os dormitórios mais sofisticados.",
  str_homestory_821801001_22_dialog_content = "Mais sofisticado?",
  str_homestory_821801001_23_dialog_content = "Não é uma má ideia, mas o orçamento<sprite=emo_baiyebi size=60 /> está apertado...",
  str_homestory_821801001_24_dialog_content = "Não se preocupe! Você pode confiar o projeto à minha Guilda Cloudrover!",
  str_homestory_821801001_25_dialog_content = "Vou remodelar os dormitórios para combinar com a grandiosidade do Cloud Gardens de graça!",
  str_homestory_821801001_26_dialog_content = "De graça? Tudo isso?!",
  str_homestory_821801001_27_dialog_content = "Não tenho certeza sobre isso...",
  str_homestory_821801001_28_dialog_content = "Eu sei que somos amigos, mas isso está aproveitando demais de você, Senhora Sheol.",
  str_homestory_821801001_29_dialog_content = "Como você sabe, eu não faço negócios não lucrativos.",
  str_homestory_821801001_30_dialog_content = "Quando os dormitórios estiverem prontos, vamos transformar o Cloud Gardens em um resort hotel.",
  str_homestory_821801001_31_dialog_content = "Hotel resort?!",
  str_homestory_821801001_32_dialog_content = "Apenas relaxe e deixe tudo comigo.",
  str_homestory_821801001_33_dialog_content = "Ou deixe-me colocar desta forma, eu garanto que você estará contando dinheiro até ficar cansado disso!",
  str_homestory_821801001_34_dialog_content = "Contando dinheiro até ficar enjoado?!",
  str_homestory_821801001_35_dialog_content = "É este o projeto que você mencionou anteriormente?",
  str_homestory_821801001_36_dialog_content = "Esta é verdadeiramente uma proposta que eu não posso recusar<sprite=emo_aixin size=60 />!",
  str_homestory_821801001_37_dialog_content = "Perfeito, então está resolvido...",
  str_homestory_821801001_38_dialog_content = "Espere, Senhora Sheol!",
  str_homestory_821801001_39_dialog_content = "Desculpe, mas eu só quero manter o Cloud Gardens do jeito que está por enquanto.",
  str_homestory_821801001_40_dialog_content = "Não tenho certeza de como os habitantes de Cloud Gardens receberão a notícia...",
  str_homestory_821801001_41_dialog_content = "Então, se simplesmente nos apressarmos com o projeto imediatamente...",
  str_homestory_821801001_42_dialog_content = "Entendo. Eu compreendi.",
  str_homestory_821801001_43_dialog_content = "Isso significa que temos a oportunidade de tornar o turismo uma coisa no futuro, certo?",
  str_homestory_821801001_44_dialog_content = "Turismo?",
  str_homestory_821801001_45_dialog_content = "Então, estou ansioso para ouvir de você!",
  str_homestory_822101001_0_dialog_content = "Intrigado?",
  str_homestory_822101001_1_dialog_content = "Eu vi você olhando para isso o tempo todo, aparentemente muito animado.",
  str_homestory_822101001_2_dialog_content = "É isso<sprite=emo_sikao size=60 />...",
  str_homestory_822101001_3_dialog_content = "Uma lixeira capaz de classificar automaticamente o lixo reciclável?",
  str_homestory_822101001_4_dialog_content = "Uau! Como você sabia disso?!",
  str_homestory_822101001_5_dialog_content = "É uma lixeira no estilo Celestita, diferente do tipo comum.",
  str_homestory_822101001_6_dialog_content = "Mas ainda pensei que não seria tão facilmente reconhecível.",
  str_homestory_822101001_7_dialog_content = "Heh, está me subestimando novamente, não é?",
  str_homestory_822101001_8_dialog_content = "Vou elaborar sobre minha análise então.",
  str_homestory_822101001_9_dialog_content = "Primeiramente, eu invadi o programa de controle e dei uma olhada...",
  str_homestory_822101001_10_dialog_content = "O quê? Por que você faria isso com os móveis de outras pessoas?!",
  str_homestory_822101001_11_dialog_content = "Estava em outra linguagem de programação avançada e sucinta. Definitivamente uma obra-prima da alta tecnologia Caelestite!",
  str_homestory_822101001_12_dialog_content = "Mas em termos de funções, eu pude discernir suas semelhanças com as do sistema de auto-organização na Cafeteria Illumina.",
  str_homestory_822101001_13_dialog_content = "O que significa que essa coisa também tem a mesma função de categorização.",
  str_homestory_822101001_14_dialog_content = "Aliás, eu escrevi o programa para a Cafeteria Illumina.",
  str_homestory_822101001_15_dialog_content = "Ele poderia classificar e dispensar alimentos com base em seus níveis nutricionais!",
  str_homestory_822101001_16_dialog_content = "Agradável.",
  str_homestory_822101001_17_dialog_content = "Eu me pergunto se há algum ingrediente nutritivo que poderia diminuir o desejo de mexer nos móveis de um amigo.",
  str_homestory_822101001_18_dialog_content = ".... De qualquer forma, não é ruim para você associar \"separação\" com uma lixeira.",
  str_homestory_822101001_19_dialog_content = "Bem, há uma razão mais conclusiva para isso.",
  str_homestory_822101001_20_dialog_content = "Ah?",
  str_homestory_822101001_21_dialog_content = "Há uma grande imagem de lixo nela.",
  str_homestory_822101001_22_dialog_content = "...",
  str_homestory_822101001_23_dialog_content = "Simplesmente maravilhoso!",
  str_homestory_822101001_24_dialog_content = "A auto-organização não é realmente a melhor coisa desde o pão fatiado.",
  str_homestory_822101001_25_dialog_content = "Mas para embalar um sistema em um volume tão compacto...",
  str_homestory_822101001_26_dialog_content = "Com esses recursos de classificação tão detalhados no topo... Isso é algo que a tecnologia atual da Illumina só pode sonhar.",
  str_homestory_822101001_27_dialog_content = "Os Celestitas são realmente pessoas incríveis!",
  str_homestory_822101001_28_dialog_content = "Hã...",
  str_homestory_822101001_29_option_content = "Você acha mesmo?",
  str_homestory_822101001_30_dialog_content = "É apenas uma lixeira.",
  str_homestory_822101001_31_dialog_content = "\"Just a garbage bin\" é o que o tornou incrível.",
  str_homestory_822101001_32_option_content = "Eu não achei que você gostaria tanto de uma \"lixeira automática\".",
  str_homestory_822101001_33_dialog_content = "Isso até me deixou todo animado!",
  str_homestory_822101001_34_dialog_content = "Você deveria ser!",
  str_homestory_822101001_35_dialog_content = "Tecnologias de ponta são sempre aplicadas primeiro para usos militares.",
  str_homestory_822101001_36_dialog_content = "Apenas quando se tornarem mais prevalentes do que a sujeira é que poderão ser acessados pelas pessoas comuns.",
  str_homestory_822101001_37_dialog_content = "Neste caso, é apenas porque essa lixeira automática é uma lixeira...",
  str_homestory_822101001_38_dialog_content = "Isso mostra a grandeza da cultura celestita!",
  str_homestory_822101001_39_dialog_content = "Ah! Isso faz sentido, agora que penso nisso!",
  str_homestory_822101001_40_dialog_content = "Mesmo que ainda me incomode que você tenha hackeado o programa...",
  str_homestory_822101001_41_dialog_content = "Mas eu sempre aprendo algo conversando com você. Eu realmente quero dizer isso.",
  str_homestory_822101001_42_dialog_content = "Obrigado, Algol.",
  str_homestory_822101001_43_dialog_content = "Sem problemas! Embora eu prefira que você me dê permissão para desmontar a lixeira para um estudo minucioso...",
  str_homestory_822101001_44_dialog_content = "Esqueça isso!",
  str_homestory_822301001_0_dialog_content = "Esta estátua de pedra...",
  str_homestory_822301001_1_dialog_content = "Eu raramente vejo coisas assim na sua caverna, PlayerName.",
  str_homestory_822301001_2_dialog_content = "Essa estátua tem algum tipo de significado especial para você?",
  str_homestory_822301001_3_dialog_content = "Você adivinhou... É uma estátua de uma garota Celestita.",
  str_homestory_822301001_4_dialog_content = "Um Celestita... Um dos seus povos de muito tempo atrás, sim?",
  str_homestory_822301001_5_dialog_content = "Posso sentir o sopro do tempo vindo de cada rachadura e arranhão nesta estátua.",
  str_homestory_822301001_6_dialog_content = "Os contos dizem que ela era uma viajante, que visitou todos os marcos famosos do nosso continente.",
  str_homestory_822301001_7_dialog_content = "E você está certo, Chen'ni. Esta estátua é de muito tempo atrás...",
  str_homestory_822301001_8_dialog_content = "Seria perigoso para um Caelestite viajar pelo nosso mundo infestado de Eclipsitas <sprite=emo_kulou size=60 /> sozinho agora...",
  str_homestory_822301001_9_dialog_content = "Comigo ao seu lado, o que há para temer?",
  str_homestory_822301001_10_dialog_content = "Talvez um dia, uma estátua seja erguida em sua memória também?",
  str_homestory_822301001_11_dialog_content = "Hã? E-Eu?! De jeito nenhum, eu não sou nada de especial...",
  str_homestory_822301001_12_dialog_content = "Por que não? Por exemplo, e se houvesse uma severa seca no mundo, e eu invocasse uma chuva pesada para trazer salvação a todos...",
  str_homestory_822301001_13_dialog_content = "E depois, você me levou para comprar alguns melões açucarados...",
  str_homestory_822301001_14_dialog_content = "Então todos nos veriam juntos, e fariam estátuas de nós dois!",
  str_homestory_822301001_15_dialog_content = "Esse é um exemplo estranhamente específico, quase como se realmente tivesse acontecido em algum momento...",
  str_homestory_822301001_16_dialog_content = "Ou talvez um inverno, eu resgate trinta e oito pessoas de um naufrágio no mar de uma só vez!",
  str_homestory_822301001_17_dialog_content = "E uma vez que eles cheguem à costa, você acende fogueiras e fornece cobertores para eles sobreviverem ao frio rigoroso...",
  str_homestory_822301001_18_dialog_content = "Eles colocarão uma estátua sua bem ao lado da minha, e as pessoas acenderão incenso em nossa honra por gerações!",
  str_homestory_822301001_19_dialog_content = "...",
  str_homestory_822301001_20_dialog_content = "Qual é o problema? Essas histórias não parecem interessantes para você?",
  str_homestory_822301001_21_option_content = "Estão sim.",
  str_homestory_822301001_22_dialog_content = "Mas eles também parecem realmente tristes.",
  str_homestory_822301001_23_option_content = "É difícil dizer...",
  str_homestory_822301001_24_dialog_content = "Sinto que essa não é uma boa maneira de considerá-los.",
  str_homestory_822301001_25_dialog_content = "Principalmente porque eles não são apenas histórias, são?",
  str_homestory_822301001_26_dialog_content = "Quando eu estava em Longzhou, vi tantas estátuas suas em diferentes lugares.",
  str_homestory_822301001_27_dialog_content = "Imagino que você tenha ajudado inúmeras pessoas por toda Longzhou, deixando para trás lendas e histórias como as que você acabou de mencionar.",
  str_homestory_822301001_28_dialog_content = "Quanto às pessoas em suas histórias, como a que comprou melões de açúcar para você ou a que ajudou você a salvar aquelas pessoas...",
  str_homestory_822301001_29_dialog_content = "Provavelmente eles não fazem mais parte deste mundo... Você é o único que ainda restou.",
  str_homestory_822301001_30_dialog_content = "Você sente pena de mim, PlayerName?",
  str_homestory_822301001_31_dialog_content = "Sinto muito que você tenha que continuar se despedindo das pessoas ao seu redor...",
  str_homestory_822301001_32_dialog_content = "Está errado eu me sentir assim por uma deusa dragão?",
  str_homestory_822301001_33_dialog_content = "Como um ser de carne e osso, é perfeitamente natural que você se sinta assim.",
  str_homestory_822301001_34_dialog_content = "Eu também me sinto da mesma forma sobre você.",
  str_homestory_822301001_35_dialog_content = "O tempo é insondavelmente longo e leva tudo ao seu fim.",
  str_homestory_822301001_36_dialog_content = "Apesar da minha longevidade, até mesmo minha própria existência é apenas um piscar de olhos em comparação com o mundo.",
  str_homestory_822301001_37_dialog_content = "Mas a nossa natureza efêmera é precisamente o que torna nosso encontro precioso. Poder caminhar lado a lado é entrelaçar nossos destinos.",
  str_homestory_822301001_38_dialog_content = "Seria arrogante da minha parte ter pena dos mortais por suas curtas expectativas de vida.",
  str_homestory_822301001_39_dialog_content = "Isso faz sentido... Por algum motivo, meu humor está bem melhor agora.",
  str_homestory_822301001_40_dialog_content = "\"A amizade não teme o passar do tempo.\" Não é isso que eles dizem em Longzhou?",
  str_homestory_822301001_41_dialog_content = "Isso está exatamente correto! Você realmente tem aprendido muito ultimamente.",
  str_homestory_822301001_42_dialog_content = "O tempo pode ser cruel, mas também tem um lado bom.",
  str_homestory_822301001_43_dialog_content = "<sprite=emo_qingsong size=60 /> Heehee... Acho que não posso me dar ao luxo de desperdiçar meu tempo ficando parado em um lugar!",
  str_homestory_822301001_44_dialog_content = "Além disso, se não fosse pela passagem do tempo, nunca teríamos nos conhecido...",
  str_homestory_822301001_45_dialog_content = "E eu nunca teria conseguido passar tantos dias felizes aqui com todos.",
  str_homestory_822401001_0_dialog_content = "Luo Song?",
  str_homestory_822401001_1_dialog_content = "Você quer usar isso?",
  str_homestory_822401001_2_dialog_content = "Claro que eu faço! Afinal, é tão bem feito!",
  str_homestory_822401001_3_dialog_content = "Finalmente... Consegui?",
  str_homestory_822401001_4_dialog_content = "Sim! Apenas olhe como a expressão dele inspira um desejo de confronto!",
  str_homestory_822401001_5_dialog_content = "E a sua estrutura não é nem muito dura nem muito macia também!",
  str_homestory_822401001_6_dialog_content = "Não importa o quão forte você o acerte, ele sempre retorna à sua posição original...",
  str_homestory_822401001_7_dialog_content = "É a ferramenta de treinamento perfeita para os meus punhos!",
  str_homestory_822401001_8_option_content = "Sim, eu sei.",
  str_homestory_822401001_9_dialog_content = "Eu sabia<sprite=emo_guilian size=60 /> que você entenderia, PlayerName.",
  str_homestory_822401001_10_option_content = "Eu realmente não entendi...",
  str_homestory_822401001_11_dialog_content = "Eu realmente não consigo explicar <sprite=emo_sikao size=60 />. Suponho que você poderia chamar de intuição de guerreiro?",
  str_homestory_822401001_12_dialog_content = "Durante minhas viagens em Longzhou, submeti-me a um treinamento amargo todos os dias.",
  str_homestory_822401001_13_dialog_content = "Construção de força, meditação, boxe de sombra, você escolhe.",
  str_homestory_822401001_14_dialog_content = "Até um único dia sem treino pode fazer uma pessoa enferrujar.",
  str_homestory_822401001_15_dialog_content = "Mas o objetivo de treinar assim é fortalecer o corpo.",
  str_homestory_822401001_16_dialog_content = "Algumas pessoas se deixam levar pela parte \"amarga\" disso, e acabam se machucando como resultado.",
  str_homestory_822401001_17_dialog_content = "E isso derrota completamente o propósito.",
  str_homestory_822401001_18_dialog_content = "Isso mesmo!",
  str_homestory_822401001_19_dialog_content = "É como algumas pessoas que batem repetidamente em árvores ao praticar a técnica \"Iron Mountain Lean\".",
  str_homestory_822401001_20_dialog_content = "Devido ao alto risco de lesão pessoal, é uma maneira extremamente imprudente de praticar esse movimento.",
  str_homestory_822401001_21_dialog_content = "Entendi. Quanto mais você sabe, hein...",
  str_homestory_822401001_22_dialog_content = "Durante minhas viagens, também tive que usar árvores para treinar, já que não conseguia encontrar um método melhor.",
  str_homestory_822401001_23_dialog_content = "Talvez seja porque eu era jovem, mas mal senti qualquer dor ou desconforto.",
  str_homestory_822401001_24_dialog_content = "Mas depois, comecei a treinar Ah Ding e os outros.",
  str_homestory_822401001_25_dialog_content = "E rapidamente percebi que seguir minha rotina era uma maneira fácil de machucá-los.",
  str_homestory_822401001_26_dialog_content = "Também percebi que os métodos de treinamento e equipamentos que usei no passado eram muito rudimentares.",
  str_homestory_822401001_27_dialog_content = "É por isso que comecei a prestar mais atenção à segurança durante o treinamento, incluindo coisas como equipamentos de proteção.",
  str_homestory_822401001_28_dialog_content = "Até fiz equipamentos de treinamento personalizados apenas para Ah Ding e os outros demônios...",
  str_homestory_822401001_29_dialog_content = "Custou-me muito tempo e esforço para projetar equipamentos levando em conta suas necessidades.",
  str_homestory_822401001_30_dialog_content = "Especialmente aquelas colunas de flor de ameixa. Foram necessárias tantas tentativas para fazer algo que funcionasse com suas perninhas curtas e pequenas!",
  str_homestory_822401001_31_dialog_content = "Você é um cara bastante atencioso.",
  str_homestory_822401001_32_dialog_content = "É claro. Além disso, eu realmente não tenho nenhum hobby fora do treinamento.",
  str_homestory_822401001_33_dialog_content = "Então, naturalmente, vou fazer o que é melhor para o treinamento dos meus amigos também.",
  str_homestory_822401001_34_dialog_content = "Quando eu tiver um tempinho, com certeza vou desenhar algumas coisas para você também!",
  str_homestory_822501001_0_dialog_content = "Aquela lanterna ali...",
  str_homestory_822501001_1_dialog_content = "Você gosta dessa lanterna do tribunal, Tiare?",
  str_homestory_822501001_2_dialog_content = "Sinta-se à vontade para dar uma olhada mais de perto, se quiser.",
  str_homestory_822501001_3_dialog_content = "Esta é a distância perfeita, na verdade.",
  str_homestory_822501001_4_dialog_content = "Isso me lembra do farol em Northland daqui.",
  str_homestory_822501001_5_dialog_content = "Vejo o que você está dizendo, agora que você mencionou.",
  str_homestory_822501001_6_dialog_content = "Uma pena que seja apenas uma lanterna comum e não vigie as criaturas de Northland como um farol.",
  str_homestory_822501001_7_dialog_content = "...",
  str_homestory_822501001_8_dialog_content = "Costumava sentar no topo dos cedros e observar o farol quando era pequeno.",
  str_homestory_822501001_9_dialog_content = "Foi incrivelmente brilhante...",
  str_homestory_822501001_10_dialog_content = "Seu brilho poderia alcançar qualquer lugar, não importa quão escuro fosse e quanta neblina houvesse.",
  str_homestory_822501001_11_dialog_content = "A luz manteve a Floresta de Snowpine quieta e imóvel.",
  str_homestory_822501001_12_dialog_content = "Sem Eclipsitas gritando, sem Aurorianos berrando... A serenidade era inestimável.",
  str_homestory_822501001_13_dialog_content = "Apenas nós, os nortistas, temos esse farol especial.",
  str_homestory_822501001_14_dialog_content = "Posso perceber o quanto vocês apreciam e reverenciam isso.",
  str_homestory_822501001_15_dialog_content = "Na verdade, o que apreciamos e reverenciamos não é o farol...",
  str_homestory_822501001_16_dialog_content = "Uma vez, eu estava tão ocupado perseguindo uma presa astuta que não percebi o quão longe eu tinha ido.",
  str_homestory_822501001_17_dialog_content = "Até que os gritos dos Eclipsitas me assustaram! Naquela altura, eu estava muito longe de casa.",
  str_homestory_822501001_18_dialog_content = "Foi quando eu vi as luzes de um farol.",
  str_homestory_822501001_19_dialog_content = "Você ainda consegue ver isso tão longe de casa?",
  str_homestory_822501001_20_dialog_content = "Não, o que eu vi não era o farol que nos protegia.",
  str_homestory_822501001_21_dialog_content = "Mas um farol normal à beira-mar.",
  str_homestory_822501001_22_dialog_content = "Se transformaria em um esconderijo de Eclipsites após o anoitecer.",
  str_homestory_822501001_23_dialog_content = "Céus!",
  str_homestory_822501001_24_dialog_content = "Escondi-me na floresta, sem ousar me mover.",
  str_homestory_822501001_25_dialog_content = "A luz continuava passando por mim.",
  str_homestory_822501001_26_dialog_content = "Eu olhei enquanto os Eclipsitas se moviam por baixo.",
  str_homestory_822501001_27_dialog_content = "Você sabe o que eu percebi então?",
  str_homestory_822501001_28_dialog_content = "O quê?",
  str_homestory_822501001_29_dialog_content = "Aquele farol era exatamente o mesmo que o farol que eu apreciava e reverenciava.",
  str_homestory_822501001_30_dialog_content = "...",
  str_homestory_822501001_31_dialog_content = "Tinha o mesmo brilho que poderia penetrar a noite mais escura e a névoa mais densa...",
  str_homestory_822501001_32_dialog_content = "Mas não conseguiu me proteger. Durante toda a noite, se eu tivesse sequer se mexido...",
  str_homestory_822501001_33_dialog_content = "Os Eclipsitas teriam me rasgado em pedaços.",
  str_homestory_822501001_34_dialog_content = "Tiare...",
  str_homestory_822501001_35_dialog_content = "Finalmente entendi aquela noite.",
  str_homestory_822501001_36_dialog_content = "O próprio farol não era nada especial.",
  str_homestory_822501001_37_dialog_content = "Como esta lanterna comum que vemos, era apenas um prédio comum.",
  str_homestory_822501001_38_dialog_content = "Não teria sido nada se ninguém tivesse acendido, mantido e colocado determinação nisso.",
  str_homestory_822501001_39_dialog_content = "O que vinha protegendo os habitantes de Northland nunca foi o farol...",
  str_homestory_822501001_40_dialog_content = "Mas Queen Bethlehem.",
  str_homestory_822501001_41_dialog_content = "...",
  str_homestory_822501001_42_option_content = "A determinação de Sua Majestade é simplesmente inabalável.",
  str_homestory_822501001_43_dialog_content = "Mesmo sem o Farol, ela faria tudo o que pudesse para defender seu povo.",
  str_homestory_822501001_44_option_content = "Deve ter sido uma noite importante na sua vida.",
  str_homestory_822501001_45_dialog_content = "Naquela noite foi quando você forjou sua própria determinação.",
  str_homestory_822501001_46_dialog_content = "Isso mesmo.",
  str_homestory_822501001_47_dialog_content = "Mesmo que eu não possa se comparar à Sua Majestade, eu a seguirei até o amargo fim.",
  str_homestory_822501001_48_dialog_content = "Dediquei minha vida a defender e proteger meu povo, como ela.",
  str_homestory_822501001_49_dialog_content = "É assim que eu me sinto também.",
  str_homestory_822501001_50_dialog_content = "Especialmente a parte sobre \"não poder segurar uma vela para Sua Majestade.\"",
  str_homestory_822501001_51_dialog_content = "Haha, quem poderia segurar uma vela para ela de qualquer maneira?",
  str_homestory_822501001_52_dialog_content = "Mas, enquanto ela estiver lá, eu nunca me perderei.",
  str_homestory_822601001_0_dialog_content = "Ei...",
  str_homestory_822601001_1_dialog_content = "Você não acha que este cavalo de balanço é bastante interessante, Rachel?",
  str_homestory_822601001_2_dialog_content = "Eu sei que é um pouco infantil, mas é surpreendentemente divertido de montar.",
  str_homestory_822601001_3_dialog_content = "Quer tentar? Vá em frente!",
  str_homestory_822601001_4_dialog_content = "Eu prefiro que nao...",
  str_homestory_822601001_5_dialog_content = "Não importa o que você diga, eu sou muito velho para esse tipo de coisa.",
  str_homestory_822601001_6_dialog_content = "Quanto a você, eu não sabia que era um grande fã de cavalos de balanço.",
  str_homestory_822601001_7_dialog_content = "Eu-Eu não me chamaria de \"fã\" deles ou algo assim...",
  str_homestory_822601001_8_dialog_content = "(Eu pensei que ela estava apenas muito envergonhada para andar, mas agora meu segredo foi revelado!)",
  str_homestory_822601001_9_dialog_content = "Ainda assim, é um brinquedo muito bem feito.",
  str_homestory_822601001_10_dialog_content = "Quando você olha além de sua aparência simples, o design e o artesanato são ambos excelentes.",
  str_homestory_822601001_11_dialog_content = "Uma combinação poderosa de ergonomia e mecânica estrutural.",
  str_homestory_822601001_12_dialog_content = "Até eu estou um pouco cativado por isso.",
  str_homestory_822601001_13_dialog_content = "Uau... Eu nunca percebi nada disso por mim mesmo.",
  str_homestory_822601001_14_dialog_content = "Quer dizer que você consegue discernir todas essas coisas apenas olhando para algo?",
  str_homestory_822601001_15_dialog_content = "Sim. É uma habilidade básica para qualquer engenheiro.",
  str_homestory_822601001_16_dialog_content = "A habilidade de desenhar uma representação tridimensional de qualquer objeto com um único olhar é muito importante.",
  str_homestory_822601001_17_dialog_content = "Na verdade, eu tenho uma boa ideia de como replicar este cavalo de balanço agora.",
  str_homestory_822601001_18_dialog_content = "Isso me parece um superpoder...",
  str_homestory_822601001_19_dialog_content = "Tudo bem, então vou deixar você ficar com isso!",
  str_homestory_822601001_20_dialog_content = "Hã?",
  str_homestory_822601001_21_option_content = "Você pode levar para casa para fins de pesquisa.",
  str_homestory_822601001_22_dialog_content = "Eu entendo. Você quer que eu vá embora, para parar de te incomodar, certo?",
  str_homestory_822601001_23_dialog_content = "Não mesmo!",
  str_homestory_822601001_24_option_content = "Você parece gostar muito disso.",
  str_homestory_822601001_25_dialog_content = "Sim, mas eu gosto mais do seu Colossus do que qualquer outra coisa.",
  str_homestory_822601001_26_dialog_content = "Soroz não está na mesa!",
  str_homestory_822601001_27_dialog_content = "Hehe... Só brincando.",
  str_homestory_822601001_28_dialog_content = "Agradeço a oferta, mas...",
  str_homestory_822601001_29_dialog_content = "Quero fazer o presente da minha irmã com minhas próprias mãos.",
  str_homestory_822601001_30_dialog_content = "... Irmã?",
  str_homestory_822601001_31_dialog_content = "Sim. No momento em que vi este cavalo de balanço, decidi fazer um igual para minha irmãzinha.",
  str_homestory_822601001_32_dialog_content = "Nunca tive a oportunidade de brincar com brinquedos assim quando era criança, mas pelo menos minha irmã vai...",
  str_homestory_822601001_33_dialog_content = "Talvez seja apenas a minha maneira de compensar o meu próprio passado.",
  str_homestory_822601001_34_dialog_content = "Rachel...",
  str_homestory_822601001_35_dialog_content = "Eu estava falando sério agora mesmo.",
  str_homestory_822601001_36_dialog_content = "Este cavalo de balanço... É muito mais divertido do que você imagina!",
  str_homestory_822601001_37_dialog_content = "H-Huh?",
  str_homestory_822601001_38_dialog_content = "Então experimente! Você não pode fazer a réplica perfeita para sua irmã a menos que tenha experimentado o original por si mesmo, certo?",
  str_homestory_822601001_39_dialog_content = "Vamos, não seja tímido!",
  str_homestory_822601001_40_dialog_content = "Uh... Certo então... Mas só dessa vez.",
  str_homestory_822601001_41_dialog_content = "Aposto que você também vai ficar viciado nisso!",
  str_homestory_822701001_0_dialog_content = "Zeta?",
  str_homestory_822701001_1_dialog_content = "Que tipo de coisa é essa?",
  str_homestory_822701001_2_dialog_content = "Essas asas adoráveis, esse trabalho de especialista...",
  str_homestory_822701001_3_dialog_content = "Se você me perguntar, isso deve ser algum tipo de tesouro inestimável do passado distante.",
  str_homestory_822701001_4_dialog_content = "É uma Boneca de Windelion.",
  str_homestory_822701001_5_dialog_content = "Bem, se não é o Último Celestita! Você chegou na hora certa.",
  str_homestory_822701001_6_dialog_content = "Já que você conhece o nome, deve estar muito familiarizado com essa maravilhosa criação.",
  str_homestory_822701001_7_dialog_content = "É apenas uma decoração para Windelion.",
  str_homestory_822701001_8_dialog_content = "Windelion?",
  str_homestory_822701001_9_dialog_content = "É um feriado celestita. Alguém já me disse que é semelhante a como os aurorianos comemoram seus santos e o Deus da Luz.",
  str_homestory_822701001_10_dialog_content = "Santos? O Deus da Luz? Isso parece incrível!",
  str_homestory_822701001_11_dialog_content = "Eu não fazia ideia que este mundo tinha um feriado tão legal!",
  str_homestory_822701001_12_dialog_content = "Um amigo meu também aprendeu sobre Windelion através de livros.",
  str_homestory_822701001_13_dialog_content = "Para nós, Celestitas, é um feriado incrivelmente importante.",
  str_homestory_822701001_14_dialog_content = "Todos os anos no Windelion, agradecemos à natureza organizando uma grande festa.",
  str_homestory_822701001_15_dialog_content = "Ah... Isso não parece muito diferente de qualquer outro feriado.",
  str_homestory_822701001_16_dialog_content = "Ahem... De qualquer forma, esta boneca é apenas mais uma decoração usada para celebrar o Windelion.",
  str_homestory_822701001_17_dialog_content = "Enchemos a barriga da boneca com doces e desejos.",
  str_homestory_822701001_18_dialog_content = "Você disse... doce e desejos?",
  str_homestory_822701001_19_dialog_content = "Vamos lá então! Eu quero celebrar Windelion agora mesmo!",
  str_homestory_822701001_20_dialog_content = "Por que você ficou tão animado de repente?",
  str_homestory_822701001_21_dialog_content = "Eu também quero fazer uma Boneca Windelion!",
  str_homestory_822701001_22_option_content = "Você também pode fazê-los fora do período de férias, sabia?",
  str_homestory_822701001_23_dialog_content = "É mesmo? Então me mostre como fazer um.",
  str_homestory_822701001_24_option_content = "Claro, eu não vejo por que não.",
  str_homestory_822701001_25_dialog_content = "Sério? Você é o melhor!",
  str_homestory_822701001_26_dialog_content = "Heehee, e quando eu terminar, vou encher a barriga dele com minhas últimas obras-primas...",
  str_homestory_822701001_27_dialog_content = "Quando todos começam a se perguntar o que tem dentro...",
  str_homestory_822701001_28_dialog_content = "Bum! Pop! Whoosh! Um monte de fumaça e doces vão voar para fora!",
  str_homestory_822701001_29_dialog_content = "Ahn? Você não vai colocar bombas nele, vai?",
  str_homestory_822701001_30_dialog_content = "Sim, eu sou, mas não se preocupe! Eu vou usar apenas o suficiente para enviar doces voando em todas as direções!",
  str_homestory_822801001_0_dialog_content = "Batia",
  str_homestory_822801001_1_dialog_content = "Você finalmente veio para fora!",
  str_homestory_822801001_2_dialog_content = "Oh, oi...",
  str_homestory_822801001_3_dialog_content = "Posso ajudar?",
  str_homestory_822801001_4_dialog_content = "Não, é só que você continua passando o dia todo na sua tenda jogando jogos.",
  str_homestory_822801001_5_dialog_content = "Eu estava prestes a te dizer para sair e tomar um pouco de ar fresco.",
  str_homestory_822801001_6_dialog_content = "Ah... Ufa...",
  str_homestory_822801001_7_dialog_content = "Pronto, terminado. Até mais.",
  str_homestory_822801001_8_dialog_content = "E-Espere! Você deveria pelo menos dar uma volta antes de voltar para dentro, não acha?",
  str_homestory_822801001_9_dialog_content = "Ah, o ar livre...",
  str_homestory_822801001_10_dialog_content = "Por que você odeia tanto sair, Batia?",
  str_homestory_822801001_11_dialog_content = "Você... não gosta daqui?",
  str_homestory_822801001_12_dialog_content = "De maneira nenhuma! Não é que eu desgoste deste lugar ou algo assim...",
  str_homestory_822801001_13_dialog_content = "Na verdade, eu gosto muito mais do que as ruas de Umbraton!",
  str_homestory_822801001_14_dialog_content = "Ah... Então você esteve comparando este lugar com Umbraton o tempo todo...",
  str_homestory_822801001_15_dialog_content = "S-Desculpe, eu não quis dizer isso!",
  str_homestory_822801001_16_dialog_content = "E-Eu realmente só conheço as ruas de Umbraton...",
  str_homestory_822801001_17_dialog_content = "O que é ainda mais motivo para visitar lugares diferentes!",
  str_homestory_822801001_18_option_content = "Então, onde devemos ir?",
  str_homestory_822801001_19_dialog_content = "Pelo Rio.",
  str_homestory_822801001_20_dialog_content = "Poderíamos ir pescar em um dos rios próximos?",
  str_homestory_822801001_21_dialog_content = "Ah, então como uma versão da vida real do Mestre Pescador!",
  str_homestory_822801001_22_dialog_content = "Não tenho certeza se consigo pegar um peixe de verdade, embora...",
  str_homestory_822801001_23_dialog_content = "Hahaha, bem, as regras são um pouco diferentes daquelas nos seus jogos.",
  str_homestory_822801001_24_option_content = "A floresta.",
  str_homestory_822801001_25_dialog_content = "Vamos acampar na floresta. Podemos acender uma fogueira, procurar frutas silvestres e cozinhar ao ar livre!",
  str_homestory_822801001_26_dialog_content = "Ah, isso soa como um jogo de estilo gerencial.",
  str_homestory_822801001_27_dialog_content = "Traçando o desenvolvimento do nosso acampamento e seguindo diferentes processos de confecção para garantir a máxima eficiência...",
  str_homestory_822801001_28_dialog_content = "Acampar não dá pontos ou conquistas, você sabe.",
  str_homestory_822801001_29_dialog_content = "Ah, ok. Acho que posso tentar.",
  str_homestory_822801001_30_dialog_content = "Mas posso pelo menos levar minha barraca se formos sair?",
  str_homestory_822801001_31_dialog_content = "Se cansarmos, sempre podemos entrar e jogar jogos.",
  str_homestory_822801001_32_dialog_content = "Bom, acho que não faria mal.",
  str_homestory_822901001_0_dialog_content = "Senhora Victoria, por que você continua olhando para a cadeira pendurada?",
  str_homestory_822901001_1_dialog_content = "Há algo de errado com isso?",
  str_homestory_822901001_2_dialog_content = "Isso apenas me lembra de uma cadeira suspensa semelhante na Ordem Verdadeira.",
  str_homestory_822901001_3_dialog_content = "É a cadeira favorita deles.",
  str_homestory_822901001_4_dialog_content = "O que houve?",
  str_homestory_822901001_5_dialog_content = "Oito em cada dez vezes que passei por lá, eu veria Beryl encolhida lendo nele.",
  str_homestory_822901001_6_dialog_content = "Quanto aos outros dois, ela adormeceu em cima de um dos seus livros.",
  str_homestory_822901001_7_dialog_content = "Então ela pegou para si mesma!",
  str_homestory_822901001_8_dialog_content = "Às vezes, vejo Eicy andando em círculos.",
  str_homestory_822901001_9_dialog_content = "E ela está sempre murmurando coisas que a maioria das pessoas nunca entenderia, como...",
  str_homestory_822901001_10_dialog_content = "Seria um dispositivo de tortura perfeito com alguns espinhos de ferro adicionados ao assento e ao encosto!",
  str_homestory_822901001_11_dialog_content = "Você deve proteger bem aquela cadeira pendurada antes que ela coloque as mãos nela... E o Beryl também!",
  str_homestory_822901001_12_dialog_content = "Você não pode culpar Eicy por pensar dessa maneira.",
  str_homestory_822901001_13_dialog_content = "Realmente parecia um instrumento de tortura quando estava coberto com o sangue de Nails.",
  str_homestory_822901001_14_dialog_content = "Até mesmo Nails?!",
  str_homestory_822901001_15_dialog_content = "Você não pode culpar Nails por isso. É uma cadeira realmente confortável.",
  str_homestory_822901001_16_dialog_content = "Até nosso devoto asceta gostaria de sentar lá às vezes.",
  str_homestory_822901001_17_dialog_content = "...",
  str_homestory_822901001_18_dialog_content = "Então... Você é o único que não se sentou nele?",
  str_homestory_822901001_19_dialog_content = "Agora que penso nisso, você está certo.",
  str_homestory_822901001_20_dialog_content = "Talvez eu esteja evitando isso.",
  str_homestory_822901001_21_dialog_content = "Evitando... uma cadeira?",
  str_homestory_822901001_22_dialog_content = "É da antiga casa Varaki e já pertenceu ao meu pai.",
  str_homestory_822901001_23_dialog_content = "Eu não sei o que o Faust estava pensando quando ele me trouxe de volta.",
  str_homestory_822901001_24_dialog_content = "Vê-lo me lembra dos meus pais, minha infância e o destino impotente dos Varaki.",
  str_homestory_822901001_25_dialog_content = "Eu... não quero continuar lembrando de tudo isso.",
  str_homestory_822901001_26_dialog_content = "Faust deveria aprender a manter as mãos para si mesmo.",
  str_homestory_822901001_27_dialog_content = "Talvez ele estivesse tentando me lembrar que enfrentar o destino é uma parte da Verdade.",
  str_homestory_822901001_28_dialog_content = "A cadeira suspensa é uma lembrança da sua infância.",
  str_homestory_822901001_29_dialog_content = "Essas memórias podem ser dolorosas, mas também há alegria nelas, certo?",
  str_homestory_822901001_30_dialog_content = "Heh, eu acho. Pai uma vez me segurou em seus braços enquanto lia na cadeira de balanço. Essa é uma bela memória.",
  str_homestory_822901001_31_dialog_content = "No entanto, após vivenciar eventos recentes, eu finalmente entendo agora.",
  str_homestory_822901001_32_dialog_content = "A dor do passado só existe no meu coração.",
  str_homestory_822901001_33_dialog_content = "Se eu puder superar isso, então a cadeira suspensa não será mais do que uma cadeira suspensa.",
  str_homestory_822901001_34_dialog_content = "Como a sua sabedoria natural apontou.",
  str_homestory_822901001_35_dialog_content = "Não deveria encarar isso, deveria sentar confortavelmente nele.",
  str_homestory_822901001_36_dialog_content = "S-Sim! Era isso que eu estava tentando te dizer!",
  str_homestory_822901001_37_dialog_content = "Por favor, sente-se. Você é sempre bem-vindo para sentar na minha cadeira suspensa.",
  str_homestory_822901001_38_dialog_content = "Obrigado pela hospitalidade, PlayerName.",
  str_homestory_823001001_0_dialog_content = "Esta casa parece estranha, não parece?",
  str_homestory_823001001_1_dialog_content = "Mas as aparências enganam porque é muito confortável por dentro!",
  str_homestory_823001001_2_dialog_content = "Estranho? De jeito nenhum...",
  str_homestory_823001001_3_dialog_content = "Sua estrutura em forma de torre e a disposição das janelas fazem com que se pareça com um pequeno castelo.",
  str_homestory_823001001_4_dialog_content = "Se você permitir, gostaria de treinar aqui ocasionalmente.",
  str_homestory_823001001_5_dialog_content = "Sem problemas!",
  str_homestory_823001001_6_dialog_content = "Use o lugar sempre que quiser.",
  str_homestory_823001001_7_dialog_content = "Nenhum mesmo...",
  str_homestory_823001001_8_dialog_content = "Se você pode garantir que nenhum sangue será derramado aqui...",
  str_homestory_823001001_9_dialog_content = "Estou eternamente grato pela sua generosidade.",
  str_homestory_823001001_10_dialog_content = "A propósito, o Sr. Wilhelm está treinando em reclusão em um castelo, certo?",
  str_homestory_823001001_11_dialog_content = "Oh! S-Sim... Por que você mencionou meu mentor de repente?",
  str_homestory_823001001_12_dialog_content = "Eu estava apenas pensando... Você quer treinar em uma casa que parece um castelo...",
  str_homestory_823001001_13_dialog_content = "Devido à influência do Sr. Wilhelm?",
  str_homestory_823001001_14_dialog_content = "...",
  str_homestory_823001001_15_dialog_content = "Mentir é um pecado. Como você viu através das minhas intenções, só posso admitir.",
  str_homestory_823001001_16_dialog_content = "Eu tenho um pequeno desejo de... imitar meu mentor.",
  str_homestory_823001001_17_dialog_content = "Embora eu tenha prometido a ele que não faria isso.",
  str_homestory_823001001_18_dialog_content = "Um ser tão insignificante quanto eu tentando me tornar como meu mentor é um terrível pecado! Eu...",
  str_homestory_823001001_19_dialog_content = "Isso não é verdade! Não é muito normal ter o desejo de imitar alguém que você respeita?",
  str_homestory_823001001_20_dialog_content = "O que você tentou imitar?",
  str_homestory_823001001_21_dialog_content = "Eu...",
  str_homestory_823001001_22_dialog_content = "Tentei... deixar meu cabelo crescer.",
  str_homestory_823001001_23_dialog_content = "...",
  str_homestory_823001001_24_dialog_content = "Mas meu cabelo não parece ser adequado para isso. Um par de pardais pensou que minha cabeça era o ninho deles...",
  str_homestory_823001001_25_dialog_content = "Até o momento em que terminei de me arrepender, um pintinho já havia chocado na minha cabeça.",
  str_homestory_823001001_26_dialog_content = "Você realmente se arrependeu por muito tempo...",
  str_homestory_823001001_27_dialog_content = "Depois de cortar meu cabelo, tentei ficar acordado e ler durante a noite como meu mentor.",
  str_homestory_823001001_28_dialog_content = "Mas eu adormeci enquanto caminhava e rolei escada abaixo...",
  str_homestory_823001001_29_dialog_content = "Ei, ei!",
  str_homestory_823001001_30_dialog_content = "A espada do meu mentor, Fluxo Carmesim, é realmente legal.",
  str_homestory_823001001_31_dialog_content = "Mas meu mentor me parou quando tentei imitar o Fluxo Carmesim com meu próprio sangue.",
  str_homestory_823001001_32_dialog_content = "Ah! Ele deve ter dito para você simplesmente ser você mesmo, certo?",
  str_homestory_823001001_33_dialog_content = "Meu mentor me perguntou gentilmente, \"Nails, olhe para cima e me diga o que você vê.\"",
  str_homestory_823001001_34_dialog_content = "Eu respondi, \"O céu, Mentor. O Senhor da Verdade está nos observando de lá.\"",
  str_homestory_823001001_35_dialog_content = "Meu mentor perguntou, \"Você sabe por que podemos ver o céu?\"",
  str_homestory_823001001_36_dialog_content = "Eu respondi, \"Porque o Senhor o criou.\"",
  str_homestory_823001001_37_dialog_content = "Meu mentor disse, \"É porque seu Fluxo Carmesim acabou de cortar nosso teto.\"",
  str_homestory_823001001_38_dialog_content = "...",
  str_homestory_823001001_39_dialog_content = "Arrependi-me profundamente dos meus pecados.",
  str_homestory_823001001_40_dialog_content = "Então percebi que não tinha aprendido a coisa mais valiosa do meu mentor.",
  str_homestory_823001001_41_dialog_content = "Meu mentor nunca se desviou de suas crenças.",
  str_homestory_823001001_42_dialog_content = "E eu deveria fazer o mesmo. Eu deveria viver como nasci.",
  str_homestory_823001001_43_dialog_content = "Se você conseguiu chegar a essa conclusão a partir dessa série de desastres... Quero dizer, incidentes...",
  str_homestory_823001001_44_dialog_content = "Você deve ser muito perspicaz.",
  str_homestory_823001001_45_dialog_content = "Obrigado pelas palavras gentis, PlayerName.",
  str_homestory_823001001_46_dialog_content = "Em troca, estou sempre feliz em ouvir suas confissões neste pequeno castelo.",
  str_homestory_823001001_47_dialog_content = "Aham, vamos fazer isso assim que eu descobrir!",
  str_homestory_823101001_0_dialog_content = "Sr. Wilhelm, por que você está olhando para aquele pavilhão? Não há nada ali.",
  str_homestory_823101001_1_dialog_content = "Estou me perguntando se este seu pavilhão tem um quebra-cabeça enterrado abaixo dele.",
  str_homestory_823101001_2_dialog_content = "Um enigma? S-Sério...? O que te faz pensar isso?",
  str_homestory_823101001_3_dialog_content = "Um pavilhão solitário na natureza tem uma afinidade natural com aventura e quebra-cabeças.",
  str_homestory_823101001_4_dialog_content = "Coisas semelhantes ocorreram em muitas lendas.",
  str_homestory_823101001_5_dialog_content = "Inspirado por isso, uma vez propus uma questão para Victoria.",
  str_homestory_823101001_6_dialog_content = "N-No pavilhão?",
  str_homestory_823101001_7_dialog_content = "Comecei irritando ela...",
  str_homestory_823101001_8_dialog_content = "Por que você faria isso?!",
  str_homestory_823101001_9_dialog_content = "Era uma tarefa fácil, já que ela sempre teve um sentimento de hostilidade em relação a mim.",
  str_homestory_823101001_10_dialog_content = "Mas de como ela gritou \"Vá para o inferno! Demônio!\" e saiu correndo com os olhos injetados de sangue...",
  str_homestory_823101001_11_dialog_content = "Talvez eu tenha ido longe demais.",
  str_homestory_823101001_12_dialog_content = "Senhora Victoria era muito... animada naquela época, hein?",
  str_homestory_823101001_13_dialog_content = "Depois disso, eu deliberadamente deixei todos os tipos de pistas para fazê-la pensar que os Varaki tinham um tesouro ancestral.",
  str_homestory_823101001_14_dialog_content = "E se ela encontrasse, poderia me derrubar e retomar a posição de chefe da família.",
  str_homestory_823101001_15_dialog_content = "Você tem uma relação tão distorcida...",
  str_homestory_823101001_16_dialog_content = "Ela não decepcionou. Decifrou com sucesso as pistas e chegou à conclusão correta.",
  str_homestory_823101001_17_dialog_content = "A localização do tesouro ancestral foi inscrita no pavilhão no fundo do jardim.",
  str_homestory_823101001_18_dialog_content = "What happened next?",
  str_homestory_823101001_19_dialog_content = "Claro, localizar o pavilhão não foi o fim disso.",
  str_homestory_823101001_20_dialog_content = "Ela teve que resolver os enigmas esculpidos nas lajes de pedra do pavilhão e descobrir a verdadeira localização do tesouro.",
  str_homestory_823101001_21_dialog_content = "Devo mencionar que meu envelhecimento artificial das lajes de pedra foi impecável.",
  str_homestory_823101001_22_dialog_content = "...",
  str_homestory_823101001_23_dialog_content = "Então... Você que inventou esses enigmas? Quais eram eles?",
  str_homestory_823101001_24_dialog_content = "Eles não eram nada. Apenas algumas perguntas de conhecimento geral sobre história, mitos e fábulas, e alguns problemas de matemática.",
  str_homestory_823101001_25_dialog_content = "Ela só teria que estudar por uma semana para passar por tudo com facilidade.",
  str_homestory_823101001_26_dialog_content = "Tenho a sensação de que não acabou bem...",
  str_homestory_823101001_27_dialog_content = "Depende da maneira como você olha para isso. Ela teve sucesso, assim como eu pensei que teria.",
  str_homestory_823101001_28_dialog_content = "Mas eu realmente não consegui entender por que ela ficou tão brava depois de encontrar o tesouro...",
  str_homestory_823101001_29_dialog_content = "Deixe-me perguntar agora. O que você enterrou como tesouro?",
  str_homestory_823101001_30_dialog_content = "O mel favorito de Victoria. Um pote inteiro que foi colhido fresco naquele ano.",
  str_homestory_823101001_31_dialog_content = "É isso?!",
  str_homestory_823101001_32_dialog_content = "Isso não é suficiente? Estava claramente escrito em \"Como Lidar com Meninas Adolescentes Rebeldes\"—",
  str_homestory_823101001_33_dialog_content = "\"Prepare algo que ela goste. Você nunca pode errar com coisas doces.\"",
  str_homestory_823101001_34_dialog_content = "Eu realmente não entendo qual é o problema.",
  str_homestory_823101001_35_dialog_content = "Por que você simplesmente não deu a ela o mel?!",
  str_homestory_823101001_36_dialog_content = "Lembra como ela é hostil comigo?",
  str_homestory_823101001_37_dialog_content = "Provocar um ao outro não é muito chato, mas é realmente cansativo.",
  str_homestory_823101001_38_dialog_content = "Então, eu não me importei em distraí-la com outra coisa.",
  str_homestory_823101001_39_dialog_content = "Ela passou uma semana esforçando a mente e estudando história, fábulas e matemática, enquanto queimava de antecipação...",
  str_homestory_823101001_40_dialog_content = "Mas no final, tudo que ela encontrou foi um novo pote de mel. Não era diferente de você zombando dela por ter sido enganada...",
  str_homestory_823101001_41_dialog_content = "Você ainda não entende por que ela estava brava?",
  str_homestory_823101001_42_dialog_content = "Você tem razão.",
  str_homestory_823101001_43_dialog_content = "Mas isso não é motivo para derramar mel no meu assento antes da reunião dos chefes de família...",
  str_homestory_823101001_44_dialog_content = "Eu não tive escolha a não ser sentar no mel e agir como se nada estivesse errado durante toda a duração da reunião!",
  str_homestory_823101001_45_dialog_content = "O que você achou?",
  str_homestory_823101001_46_dialog_content = "Você mereceu isso.",
  str_homestory_823101001_47_dialog_content = "Você recebeu o que merecia.",
  str_homestory_823101001_48_dialog_content = "Tsc..."
}
return config
